INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u5-C1','math',4,1,'u5',2,'표와 그림그래프로 정리하기 — 조사한 것을 표로 정리하면 항목별 수와 합계를 알 수 있고, 그림그래프는 수를 그림의 크기와 개수로 나타내지만 견주려면 그림을 세어야 한다',ARRAY['4수04-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u5-C2','math',4,1,'u5',2,'막대그래프의 뜻 — 조사한 수량을 막대 모양으로 나타낸 그래프로, 막대의 길이만 보고 많고 적음을 한눈에 견줄 수 있다',ARRAY['4수04-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u5-C3','math',4,1,'u5',2,'막대그래프 읽기 — 가로·세로가 무엇을 나타내는지와 세로 눈금 한 칸의 크기를 먼저 확인하고 막대의 값을 읽으며, 수량은 막대의 길이로만 나타내 굵기와는 관계없고 막대를 가로로 눕혀도 같다',ARRAY['4수04-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u5-C4','math',4,1,'u5',3,'막대그래프 그리는 차례 — 제목, 가로와 세로에 나타낼 것, 단위, 눈금 한 칸의 크기를 정한 뒤 수량만큼 막대를 그리며, 막대의 굵기는 모두 같게 하고 제목은 마지막에 써도 된다',ARRAY['4수04-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u5-C5','math',4,1,'u5',3,'눈금과 막대의 칸 수 — 세로 눈금은 가장 큰 수까지 나타낼 수 있어야 하고, 막대의 칸 수는 수량을 눈금 한 칸의 크기로 나누어 정한다',ARRAY['4수04-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u5-C6','math',4,1,'u5',4,'눈금 한 칸의 크기 정하기 — 눈금 한 칸을 바꾸면 막대의 칸 수만 달라지고 나타내는 수는 그대로이며, 가장 큰 수를 담으면서 차이가 잘 드러나게 자료에 알맞게 정한다',ARRAY['4수04-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u5-C7','math',4,1,'u5',5,'바로 읽고 견주기 — 막대그래프에서 가장 많은 것과 가장 적은 것을 바로 찾고, 막대끼리 견주어 차와 몇 배인지를 알아낸다',ARRAY['4수04-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u5-C8','math',4,1,'u5',5,'판단하기와 그래프에 없는 것 — 그래프를 바탕으로 판단하되 까닭·앞날처럼 그래프에 없는 것은 지어내지 않고, 눈금 한 칸이 다른 그래프끼리는 길이만으로 견주지 않는다',ARRAY['4수04-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u5-C9','math',4,1,'u5',6,'자료 수집하기 — 주제, 항목, 방법을 차례로 정한 뒤 조사하며, 항목은 겹치지 않게 정하고 상황에 알맞은 방법을 고르며, 조사가 끝나면 합계가 인원과 같은지 확인한다',ARRAY['4수04-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u5-C10','math',4,1,'u5',7,'표에서 그래프로, 그래프에서 기사로 — 모은 자료를 표로 정리하고 막대그래프로 나타낸 뒤 해석하며, 표와 그래프의 값은 언제나 같아야 하고 기사에는 그래프에서 알 수 있는 사실만 쓴다',ARRAY['4수04-02']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u5-C11','math',4,1,'u5',8,'두 자료를 한 그래프에 — 두 자료는 막대의 색으로 구분하고 이름표(범례)로 어느 자료인지 읽으며, 묶는 방법을 바꿔도 나타내는 수는 그대로이다',ARRAY['4수04-02']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X01','math',4,'u5',ARRAY['M4-1-u5-C3','M4-1-u5-C4']::text[],'가로와 세로가 나타내는 것을 바꾸어 읽거나 엉뚱하게 정한다','가로·세로 이름 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X02','math',4,'u5',ARRAY['M4-1-u5-C3','M4-1-u5-C5','M4-1-u5-C6','M4-1-u5-C7']::text[],'세로 눈금 한 칸의 크기를 확인하지 않고 막대의 칸 수를 그대로 수로 읽는다','눈금 한 칸이 얼마인지 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X03','math',4,'u5',ARRAY['M4-1-u5-C2','M4-1-u5-C3','M4-1-u5-C4','M4-1-u5-C11']::text[],'막대의 굵기(폭)나 색으로 수량을 판단하거나 막대마다 굵기를 다르게 그린다','수량은 막대의 길이로만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X04','math',4,'u5',ARRAY['M4-1-u5-C1','M4-1-u5-C2']::text[],'표·그림그래프·막대그래프의 쓰임을 구별하지 못한다 — 수를 나타내는 방법이나 좋은 점을 섞는다','표는 수, 그림은 개수, 막대는 길이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X05','math',4,'u5',ARRAY['M4-1-u5-C5']::text[],'세로 눈금을 가장 큰 수보다 짧게 정해도 된다고 생각한다','가장 큰 수까지 담기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X06','math',4,'u5',ARRAY['M4-1-u5-C6']::text[],'눈금 한 칸의 크기를 바꾸면 막대가 나타내는 수도 달라진다고 생각한다','칸 수만 바뀌고 수는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X07','math',4,'u5',ARRAY['M4-1-u5-C6']::text[],'눈금 한 칸의 크기는 아무렇게나 정해도 된다고 생각한다 — 너무 크게 하면 차이가 안 보이고 너무 작게 하면 칸이 넘친다는 것을 놓친다','다 들어가면서 차이가 보이게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X09','math',4,'u5',ARRAY['M4-1-u5-C3','M4-1-u5-C7','M4-1-u5-C11']::text[],'차나 몇 배를 구할 때 다른 항목의 값을 쓰거나 차 대신 합을, 몇 배 대신 차를 구한다','묻는 두 항목으로 셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X10','math',4,'u5',ARRAY['M4-1-u5-C8']::text[],'눈금 한 칸의 크기가 다른 두 그래프의 막대를 길이만으로 견준다','눈금이 같은지 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X11','math',4,'u5',ARRAY['M4-1-u5-C8','M4-1-u5-C10','M4-1-u5-C11']::text[],'까닭·앞날·맛처럼 그래프에 없는 것을 그래프에서 알 수 있다고 하거나 기사에 지어 쓴다','그래프에 있는 사실만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X12','math',4,'u5',ARRAY['M4-1-u5-C8']::text[],'그래프가 아니라 자기 좋아하는 것이나 이름·길이 같은 엉뚱한 까닭으로 판단한다','그래프의 수로 판단') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X13','math',4,'u5',ARRAY['M4-1-u5-C9']::text[],'친구들에게 물어 답할 수 없거나 몇 가지 갈래로 나눌 수 없는 것을 조사 주제·항목으로 고른다','물어볼 수 있고 갈래로 나뉘는가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X14','math',4,'u5',ARRAY['M4-1-u5-C9']::text[],'항목을 서로 겹치게 정한다 — 한 사람이 어느 항목에 답할지 헷갈린다','항목끼리 겹치지 않게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X15','math',4,'u5',ARRAY['M4-1-u5-C9','M4-1-u5-C10']::text[],'합계가 인원과 달라도 괜찮다고 생각한다 — 두 번 답한 친구나 빠진 친구를 놓친다','합계 = 인원 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X16','math',4,'u5',ARRAY['M4-1-u5-C9']::text[],'상황을 생각하지 않고 조사 방법을 고르거나 방법마다 좋은 점을 섞는다','상황에 알맞은 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X17','math',4,'u5',ARRAY['M4-1-u5-C10']::text[],'표와 그래프의 값이 달라도 된다고 생각하거나 표를 그래프에 맞춰 고친다','그래프는 표를 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X18','math',4,'u5',ARRAY['M4-1-u5-C4','M4-1-u5-C9','M4-1-u5-C10']::text[],'자료 모으기·표·그래프·해석, 또는 그리는 걸음의 차례를 뒤섞는다','모으기→표→그래프→해석') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X19','math',4,'u5',ARRAY['M4-1-u5-C11']::text[],'두 자료를 나타낸 그래프에서 이름표(범례)를 보지 않아 두 자료를 바꾸어 읽는다','이름표로 색 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X20','math',4,'u5',ARRAY['M4-1-u5-C11']::text[],'두 자료를 묶는 방법을 바꾸면 나타내는 수가 달라진다고 생각한다','늘어놓는 차례만 바뀜') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u5-X21','math',4,'u5',ARRAY['M4-1-u5-C1','M4-1-u5-C2','M4-1-u5-C3','M4-1-u5-C4','M4-1-u5-C5','M4-1-u5-C6','M4-1-u5-C7','M4-1-u5-C8','M4-1-u5-C9','M4-1-u5-C10','M4-1-u5-C11']::text[],'묻는 말을 거꾸로 읽는다 — 아닌 것↔맞는 것, 잘못↔바르게, 많은↔적은','물음의 핵심 낱말에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_basic#1','math',4,1,'u5','L02','g4_1_math_u5_L02_basic','lesson_basic','M4-1-u5-C2',1,'mc','auto','조사한 수량을 막대 모양으로 나타낸 그래프를 무엇이라고 하나요?',ARRAY['M4-1-u5-X04']::text[],true,'{"seq":1,"concept":"M4-1-u5-C2","difficulty":1,"kind":"mc","stem":"조사한 수량을 막대 모양으로 나타낸 그래프를 무엇이라고 하나요?","options":[{"t":"막대그래프","correct":true},{"t":"그림그래프","mis":"M4-1-u5-X04"},{"t":"표","mis":"M4-1-u5-X04"},{"t":"수직선","mis":"M4-1-u5-X04"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"variant_rule":{"alt":[{"stem":"막대그래프에서 수량은 무엇으로 나타내나요?","options":[{"t":"막대의 길이","correct":true},{"t":"막대의 굵기","mis":"M4-1-u5-X03"},{"t":"막대의 색깔","mis":"M4-1-u5-X03"},{"t":"그림의 개수","mis":"M4-1-u5-X04"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"asset":null},{"stem":"막대그래프의 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"막대의 길이만 보고 많고 적음을 한눈에 견줄 수 있어요.","correct":true},{"t":"정확한 수를 조사하지 않아도 돼요.","mis":"M4-1-u5-X04"},{"t":"그림을 예쁘게 그릴 수 있어요.","mis":"M4-1-u5-X04"},{"t":"조사하지 않아도 결과를 알 수 있어요.","mis":"M4-1-u5-X11"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_basic#2','math',4,1,'u5','L02','g4_1_math_u5_L02_basic','lesson_basic','M4-1-u5-C3',1,'mc','auto','아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?',ARRAY['M4-1-u5-X01']::text[],true,'{"seq":2,"concept":"M4-1-u5-C3","difficulty":1,"kind":"mc","stem":"아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 체험, 세로: 학생 수","correct":true},{"t":"가로: 학생 수, 세로: 체험","mis":"M4-1-u5-X01"},{"t":"가로: 체험, 세로: 체험","mis":"M4-1-u5-X01"},{"t":"가로: 학생 수, 세로: 학생 수","mis":"M4-1-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 체험, 세로에는 학생 수를 명 단위로 나타냈어요.","가로: 체험, 세로: 학생 수예요."],"asset":{"type":"lgraph","mode":"bar","xs":["로봇","요리","방송","소방","과학"],"series":[{"vals":[6,10,7,8,2]}],"step":1,"ymax":11,"ylab":"(명)","title":"가고 싶은 체험별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 직업, 세로: 학생 수","correct":true},{"t":"가로: 학생 수, 세로: 직업","mis":"M4-1-u5-X01"},{"t":"가로: 직업, 세로: 직업","mis":"M4-1-u5-X01"},{"t":"가로: 학생 수, 세로: 학생 수","mis":"M4-1-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 직업, 세로에는 학생 수를 명 단위로 나타냈어요.","가로: 직업, 세로: 학생 수예요."],"asset":{"type":"lgraph","mode":"bar","xs":["요리사","경찰관","과학자","가수","의사"],"series":[{"vals":[7,8,4,3,9]}],"step":1,"ymax":10,"ylab":"(명)","title":"희망 직업별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 급식 메뉴, 세로: 학생 수","correct":true},{"t":"가로: 학생 수, 세로: 급식 메뉴","mis":"M4-1-u5-X01"},{"t":"가로: 급식 메뉴, 세로: 급식 메뉴","mis":"M4-1-u5-X01"},{"t":"가로: 학생 수, 세로: 학생 수","mis":"M4-1-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 급식 메뉴, 세로에는 학생 수를 명 단위로 나타냈어요.","가로: 급식 메뉴, 세로: 학생 수예요."],"asset":{"type":"lgraph","mode":"bar","xs":["카레","잡채","불고기","국수","김밥"],"series":[{"vals":[8,5,10,4,6]}],"step":1,"ymax":11,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_basic#3','math',4,1,'u5','L02','g4_1_math_u5_L02_basic','lesson_basic','M4-1-u5-C1',1,'sa','auto','조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u5-C1","difficulty":1,"kind":"sa","stem":"조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["34"],"explanation":["합계는 항목별 수를 모두 더한 것이에요.","6 + 9 + 12 + 4 + 3. = 34","합계는 34명이에요 — 모두 답했는지 확인할 수 있어요."],"asset":{"type":"picg","only":"table","head":"과일","cols":["사과","포도","딸기","귤","배"],"counts":[6,9,12,4,3],"vh":"학생 수","unit":"명","total":null,"title":"좋아하는 과일별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["합계는 항목별 수를 모두 더한 것이에요.","8 + 5 + 2 + 4 + 9. = 28","합계는 28명이에요 — 모두 답했는지 확인할 수 있어요."],"asset":{"type":"picg","only":"table","head":"운동","cols":["축구","피구","수영","야구","배구"],"counts":[8,5,2,4,9],"vh":"학생 수","unit":"명","total":null,"title":"좋아하는 운동별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["합계는 항목별 수를 모두 더한 것이에요.","9 + 12 + 7 + 10. = 38","합계는 38명이에요 — 모두 답했는지 확인할 수 있어요."],"asset":{"type":"picg","only":"table","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[9,12,7,10],"vh":"학생 수","unit":"명","total":null,"title":"좋아하는 계절별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
