INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_basic#5','math',4,1,'u5','L02','g4_1_math_u5_L02_basic','lesson_basic','M4-1-u5-C3',2,'sa','auto','김밥을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u5-C3","difficulty":2,"kind":"sa","stem":"김밥을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["세로 눈금 한 칸은 1명이에요.","김밥의 막대 끝을 따라 세로 눈금을 읽어요.","김밥을 좋아하는 학생은 3명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","만두"],"series":[{"vals":[4,3,9,7,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 간식별 학생 수"},"variant_rule":{"alt":[{"stem":"강아지를 기르고 싶은 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["세로 눈금 한 칸은 1명이에요.","강아지의 막대 끝을 따라 세로 눈금을 읽어요.","강아지를 기르고 싶은 학생은 5명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["강아지","고양이","토끼","햄스터","금붕어"],"series":[{"vals":[5,4,1,7,8]}],"step":1,"ymax":9,"ylab":"(명)","title":"기르고 싶은 동물별 학생 수"}},{"stem":"3반이 빌린 책은 몇 권인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["세로 눈금 한 칸은 10권이에요.","3반의 막대는 0에서 3칸이에요.","3 × 10 = 30 — 3반이 빌린 책은 30권이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["1반","2반","3반","4반","5반","6반"],"series":[{"vals":[80,140,30,150,120,100]}],"step":10,"ymax":160,"ylab":"(권)","title":"반별 빌린 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_basic#6','math',4,1,'u5','L02','g4_1_math_u5_L02_basic','lesson_basic','M4-1-u5-C1',2,'sa','auto','큰 그림은 5명, 작은 그림은 1명을 나타내는 그림그래프예요. 여름을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u5-C1","difficulty":2,"kind":"sa","stem":"큰 그림은 5명, 작은 그림은 1명을 나타내는 그림그래프예요. 여름을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["여름의 줄에는 큰 그림 1개와 작은 그림 1개가 있어요.","큰 그림 1개는 5명, 작은 그림 1개는 1명이에요.","5 + 1 = 6 — 6명이에요."],"asset":{"type":"picg","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[3,6,9,11],"units":[5,1],"icon":"🌸","unit":"명","vh":"학생 수","title":"좋아하는 계절별 학생 수"},"variant_rule":{"alt":[{"stem":"큰 그림은 5명, 작은 그림은 1명을 나타내는 그림그래프예요. 요리 체험을 고른 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["요리의 줄에는 큰 그림 1개와 작은 그림 1개가 있어요.","큰 그림 1개는 5명, 작은 그림 1개는 1명이에요.","5 + 1 = 6 — 6명이에요."],"asset":{"type":"picg","head":"체험","cols":["로봇","요리","방송","소방"],"counts":[11,6,12,13],"units":[5,1],"icon":"🚀","unit":"명","vh":"학생 수","title":"가고 싶은 체험별 학생 수"}},{"stem":"큰 그림은 5명, 작은 그림은 1명을 나타내는 그림그래프예요. 가수를 희망하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["가수의 줄에는 큰 그림 1개와 작은 그림 4개가 있어요.","큰 그림 1개는 5명, 작은 그림 4개는 4명이에요.","5 + 4 = 9 — 9명이에요."],"asset":{"type":"picg","head":"직업","cols":["요리사","경찰관","과학자","가수"],"counts":[3,7,8,9],"units":[5,1],"icon":"🧑","unit":"명","vh":"학생 수","title":"희망 직업별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_basic#7','math',4,1,'u5','L02','g4_1_math_u5_L02_basic','lesson_basic','M4-1-u5-C3',2,'mc','auto','「반별 빌린 책 수」에서 가장 많은 항목은 무엇인가요?',ARRAY['M4-1-u5-X21','M4-1-u5-X02']::text[],true,'{"seq":7,"concept":"M4-1-u5-C3","difficulty":2,"kind":"mc","stem":"「반별 빌린 책 수」에서 가장 많은 항목은 무엇인가요?","options":[{"t":"6반","correct":true},{"t":"5반","mis":"M4-1-u5-X21"},{"t":"1반","mis":"M4-1-u5-X02"},{"t":"2반","mis":"M4-1-u5-X02"}],"explanation":["한 그래프 안에서는 막대가 길수록 수가 많아요.","가장 긴 막대는 6반의 막대예요.","그래서 가장 많은 항목은 6반이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["1반","2반","3반","4반","5반","6반"],"series":[{"vals":[100,40,120,60,30,140]}],"step":10,"ymax":150,"ylab":"(권)","title":"반별 빌린 책 수"},"variant_rule":{"alt":[{"stem":"「농장별 토마토 생산량」에서 가장 적은 항목은 무엇인가요?","options":[{"t":"해 농장","correct":true},{"t":"별 농장","mis":"M4-1-u5-X21"},{"t":"달 농장","mis":"M4-1-u5-X02"},{"t":"숲 농장","mis":"M4-1-u5-X02"}],"explanation":["한 그래프 안에서는 막대가 길수록 수가 많아요.","가장 짧은 막대는 해 농장의 막대예요.","그래서 가장 적은 항목은 해 농장이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["해 농장","달 농장","별 농장","숲 농장","강 농장"],"series":[{"vals":[60,100,300,260,120]}],"step":20,"ymax":320,"ylab":"(kg)","title":"농장별 토마토 생산량"}},{"stem":"「마을별 나무 수」에서 가장 많은 항목은 무엇인가요?","options":[{"t":"라 마을","correct":true},{"t":"가 마을","mis":"M4-1-u5-X21"},{"t":"나 마을","mis":"M4-1-u5-X02"},{"t":"다 마을","mis":"M4-1-u5-X02"}],"explanation":["한 그래프 안에서는 막대가 길수록 수가 많아요.","가장 긴 막대는 라 마을의 막대예요.","그래서 가장 많은 항목은 라 마을이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을","마 마을"],"series":[{"vals":[25,60,45,75,30]}],"step":5,"ymax":80,"ylab":"(그루)","title":"마을별 나무 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_basic#8','math',4,1,'u5','L02','g4_1_math_u5_L02_basic','lesson_basic','M4-1-u5-C3',2,'ox','auto','막대가 굵을수록 더 많은 수를 나타내요.',ARRAY['M4-1-u5-X03']::text[],true,'{"seq":8,"concept":"M4-1-u5-C3","difficulty":2,"kind":"ox","stem":"막대가 굵을수록 더 많은 수를 나타내요.","answer":"X","reason_options":[{"t":"수량은 막대의 길이로만 나타내서","correct":true},{"t":"굵은 막대가 더 커 보여서","mis":"M4-1-u5-X03"}],"mis":"M4-1-u5-X03","explanation":["막대그래프에서 수량은 막대의 길이로만 나타내요.","굵기와 색은 수와 관계없고, 막대를 가로로 눕혀도 같아요.","세로 눈금 한 칸의 크기는 그래프마다 달라 먼저 확인해요."],"variant_rule":{"alt":[{"stem":"같은 자료를 막대의 굵기만 다르게 그려도 나타내는 수는 같아요.","answer":"O","reason_options":[{"t":"수량은 길이로 나타내고 굵기는 관계없어서","correct":true},{"t":"굵기가 다르면 수도 달라져서","mis":"M4-1-u5-X03"}],"explanation":["막대그래프에서 수량은 막대의 길이로만 나타내요.","굵기와 색은 수와 관계없고, 막대를 가로로 눕혀도 같아요.","세로 눈금 한 칸의 크기는 그래프마다 달라 먼저 확인해요."],"asset":null},{"stem":"막대를 가로로 눕혀 그려도 막대의 길이가 수량을 나타내요.","answer":"O","reason_options":[{"t":"눕혀도 길이로 수량을 나타내는 것은 같아서","correct":true},{"t":"눕히면 수량이 달라져서","mis":"M4-1-u5-X01"}],"explanation":["막대그래프에서 수량은 막대의 길이로만 나타내요.","굵기와 색은 수와 관계없고, 막대를 가로로 눕혀도 같아요.","세로 눈금 한 칸의 크기는 그래프마다 달라 먼저 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_basic#9','math',4,1,'u5','L02','g4_1_math_u5_L02_basic','lesson_basic','M4-1-u5-C1',2,'mc','auto','그림그래프는 수를 무엇으로 나타내나요?',ARRAY['M4-1-u5-X04']::text[],true,'{"seq":9,"concept":"M4-1-u5-C1","difficulty":2,"kind":"mc","stem":"그림그래프는 수를 무엇으로 나타내나요?","options":[{"t":"그림의 크기와 개수","correct":true},{"t":"막대의 길이","mis":"M4-1-u5-X04"},{"t":"글자의 색깔","mis":"M4-1-u5-X04"},{"t":"칸의 넓이","mis":"M4-1-u5-X04"}],"explanation":["표는 항목별 수와 합계를 정확히 보여 줘요.","그림그래프는 수를 그림의 크기와 개수로 나타내요.","그래서 그림그래프로 견주려면 그림을 하나하나 세어야 해요."],"variant_rule":{"alt":[{"stem":"그림그래프에서 두 항목을 견줄 때 번거로운 점은 무엇인가요?","options":[{"t":"그림을 하나하나 세어야 수를 알 수 있어요.","correct":true},{"t":"그림그래프에는 항목 이름을 쓸 수 없어요.","mis":"M4-1-u5-X04"},{"t":"그림그래프는 합계를 바꿔 버려요.","mis":"M4-1-u5-X04"},{"t":"그림그래프로는 수를 나타낼 수 없어요.","mis":"M4-1-u5-X04"}],"explanation":["표는 항목별 수와 합계를 정확히 보여 줘요.","그림그래프는 수를 그림의 크기와 개수로 나타내요.","그래서 그림그래프로 견주려면 그림을 하나하나 세어야 해요."],"asset":null},{"stem":"조사한 것을 표로 정리하면 좋은 점은 무엇인가요?","options":[{"t":"항목별 수와 합계를 정확히 알 수 있어요.","correct":true},{"t":"막대의 길이로 한눈에 견줄 수 있어요.","mis":"M4-1-u5-X04"},{"t":"그림의 크기로 수를 나타낼 수 있어요.","mis":"M4-1-u5-X04"},{"t":"조사를 다시 하지 않아도 앞날을 알 수 있어요.","mis":"M4-1-u5-X11"}],"explanation":["표는 항목별 수와 합계를 정확히 보여 줘요.","그림그래프는 수를 그림의 크기와 개수로 나타내요.","그래서 그림그래프로 견주려면 그림을 하나하나 세어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_basic#10','math',4,1,'u5','L02','g4_1_math_u5_L02_basic','lesson_basic','M4-1-u5-C3',3,'sa','auto','가장 많은 항목과 가장 적은 항목의 학생 수 차는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u5-C3","difficulty":3,"kind":"sa","stem":"가장 많은 항목과 가장 적은 항목의 학생 수 차는 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["가장 긴 막대는 로봇 13명, 가장 짧은 막대는 요리 3명이에요.","차는 큰 수에서 작은 수를 빼요.","13 − 3 = 10 — 10명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["로봇","요리","방송","소방","과학"],"series":[{"vals":[13,3,9,5,11]}],"step":1,"ymax":14,"ylab":"(명)","title":"가고 싶은 체험별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 가장 많은 항목과 가장 적은 항목의 학생 수 차는 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["가장 긴 막대는 요리사 9명, 가장 짧은 막대는 과학자 3명이에요.","차는 큰 수에서 작은 수를 빼요.","9 − 3 = 6 — 6명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["요리사","경찰관","과학자","가수","의사"],"series":[{"vals":[9,6,3,7,8]}],"step":1,"ymax":10,"ylab":"(명)","title":"희망 직업별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 가장 많은 항목과 가장 적은 항목의 학생 수 차는 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["가장 긴 막대는 국수 11명, 가장 짧은 막대는 김밥 5명이에요.","차는 큰 수에서 작은 수를 빼요.","11 − 5 = 6 — 6명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["카레","잡채","불고기","국수","김밥"],"series":[{"vals":[7,9,10,11,5]}],"step":1,"ymax":12,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_challenge#1','math',4,1,'u5','L02','g4_1_math_u5_L02_challenge','lesson_challenge','M4-1-u5-C1',2,'sa','auto','표에서 가수의 수가 지워졌어요. 합계가 26명일 때 가수를 희망하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u5-C1","difficulty":2,"kind":"sa","stem":"표에서 가수의 수가 지워졌어요. 합계가 26명일 때 가수를 희망하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["합계에서 나머지 항목의 수를 모두 빼면 돼요.","나머지의 합: 4 + 3 + 8 + 2 = 17.","26 − 17 = 9 — 9명이에요."],"asset":{"type":"picg","only":"table","head":"직업","cols":["요리사","경찰관","과학자","가수","의사"],"counts":[4,3,8,null,2],"vh":"학생 수","unit":"명","total":26,"title":"희망 직업별 학생 수"},"variant_rule":{"alt":[{"stem":"표에서 잡채의 수가 지워졌어요. 합계가 30명일 때 잡채를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["합계에서 나머지 항목의 수를 모두 빼면 돼요.","나머지의 합: 3 + 9 + 6 + 10 = 28.","30 − 28 = 2 — 2명이에요."],"asset":{"type":"picg","only":"table","head":"급식 메뉴","cols":["카레","잡채","불고기","국수","김밥"],"counts":[3,null,9,6,10],"vh":"학생 수","unit":"명","total":30,"title":"좋아하는 급식 메뉴별 학생 수"}},{"stem":"표에서 김밥의 수가 지워졌어요. 합계가 39명일 때 김밥을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["합계에서 나머지 항목의 수를 모두 빼면 돼요.","나머지의 합: 8 + 5 + 7 + 9 = 29.","39 − 29 = 10 — 10명이에요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","만두"],"counts":[8,null,5,7,9],"vh":"학생 수","unit":"명","total":39,"title":"좋아하는 간식별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_challenge#2','math',4,1,'u5','L02','g4_1_math_u5_L02_challenge','lesson_challenge','M4-1-u5-C3',2,'mc','auto','막대를 가로로 눕힌 막대그래프는 세로 막대그래프와 무엇이 달라졌나요?',ARRAY['M4-1-u5-X06','M4-1-u5-X03','M4-1-u5-X01']::text[],true,'{"seq":2,"concept":"M4-1-u5-C3","difficulty":2,"kind":"mc","stem":"막대를 가로로 눕힌 막대그래프는 세로 막대그래프와 무엇이 달라졌나요?","options":[{"t":"수량과 항목을 나타내는 자리가 서로 바뀌었어요.","correct":true},{"t":"수량이 모두 줄어들었어요.","mis":"M4-1-u5-X06"},{"t":"막대의 길이가 수량을 나타내지 않게 되었어요.","mis":"M4-1-u5-X03"},{"t":"항목의 개수가 달라졌어요.","mis":"M4-1-u5-X01"}],"explanation":["막대를 가로로 눕히면 항목은 세로에, 수량은 가로에 와요.","가로와 세로가 나타내는 것의 자리만 바뀌어요.","막대의 길이가 수량을 나타내는 것은 똑같아요."],"variant_rule":{"alt":[{"stem":"가로 막대그래프에서 항목의 이름은 어디에 쓰나요?","options":[{"t":"세로(왼쪽)에 써요.","correct":true},{"t":"가로(아래쪽)에 써요.","mis":"M4-1-u5-X01"},{"t":"막대의 끝에 써요.","mis":"M4-1-u5-X01"},{"t":"제목 옆에 써요.","mis":"M4-1-u5-X01"}],"explanation":["막대를 가로로 눕히면 항목은 세로에, 수량은 가로에 와요.","가로와 세로가 나타내는 것의 자리만 바뀌어요.","막대의 길이가 수량을 나타내는 것은 똑같아요."],"asset":null},{"stem":"가로 막대그래프에서 수량을 읽으려면 어느 눈금을 보나요?","options":[{"t":"가로 눈금","correct":true},{"t":"세로 눈금","mis":"M4-1-u5-X01"},{"t":"막대의 굵기","mis":"M4-1-u5-X03"},{"t":"막대의 색","mis":"M4-1-u5-X03"}],"explanation":["막대를 가로로 눕히면 항목은 세로에, 수량은 가로에 와요.","가로와 세로가 나타내는 것의 자리만 바뀌어요.","막대의 길이가 수량을 나타내는 것은 똑같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_challenge#3','math',4,1,'u5','L02','g4_1_math_u5_L02_challenge','lesson_challenge','M4-1-u5-C3',3,'mc','auto','가 마을의 나무는 몇 그루인가요?',ARRAY['M4-1-u5-X02']::text[],true,'{"seq":3,"concept":"M4-1-u5-C3","difficulty":3,"kind":"mc","stem":"가 마을의 나무는 몇 그루인가요?","options":[{"t":"15그루","correct":true},{"t":"3그루","mis":"M4-1-u5-X02"},{"t":"20그루","mis":"M4-1-u5-X02"},{"t":"10그루","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 5그루예요.","가 마을의 막대는 0에서 3칸이에요.","3 × 5 = 15 — 가 마을의 나무는 15그루예요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을","마 마을"],"series":[{"vals":[15,45,30,60,35]}],"step":5,"ymax":65,"ylab":"(그루)","title":"마을별 나무 수"},"variant_rule":{"alt":[{"stem":"2학년 우유 신청 학생은 몇 명인가요?","options":[{"t":"20명","correct":true},{"t":"4명","mis":"M4-1-u5-X02"},{"t":"25명","mis":"M4-1-u5-X02"},{"t":"15명","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 5명이에요.","2학년의 막대는 0에서 4칸이에요.","4 × 5 = 20 — 2학년 우유 신청 학생은 20명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["1학년","2학년","3학년","4학년","5학년","6학년"],"series":[{"vals":[25,20,70,35,80,55]}],"step":5,"ymax":85,"ylab":"(명)","title":"학년별 우유 신청 학생 수"}},{"stem":"3모둠이 모은 빈 병은 몇 개인가요?","options":[{"t":"18개","correct":true},{"t":"9개","mis":"M4-1-u5-X02"},{"t":"20개","mis":"M4-1-u5-X02"},{"t":"16개","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 2개예요.","3모둠의 막대는 0에서 9칸이에요.","9 × 2 = 18 — 3모둠이 모은 빈 병은 18개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠","5모둠"],"series":[{"vals":[28,12,18,24,26]}],"step":2,"ymax":30,"ylab":"(개)","title":"모둠별 모은 빈 병 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_challenge#4','math',4,1,'u5','L02','g4_1_math_u5_L02_challenge','lesson_challenge','M4-1-u5-C2',3,'error','auto','막대그래프에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u5-X03','M4-1-u5-X21']::text[],true,'{"seq":4,"concept":"M4-1-u5-C2","difficulty":3,"kind":"error","stem":"막대그래프에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「막대가 굵을수록 수가 많아.」","correct":true,"mis_target":"M4-1-u5-X03"},{"t":"시우 — 「막대그래프는 수량을 막대의 길이로 나타내.」","mis":"M4-1-u5-X21"},{"t":"은우 — 「가로와 세로가 무엇인지 먼저 봐야 해.」","mis":"M4-1-u5-X21"},{"t":"하랑 — 「표를 보면 합계를 알 수 있어.」","mis":"M4-1-u5-X21"}],"explanation":["막대그래프는 수량을 막대의 길이로 나타내요.","서윤의 말은 막대그래프의 성질과 맞지 않아요.","굵기는 관계없고, 눈금 한 칸은 그래프마다 달라 먼저 확인해요."],"variant_rule":{"alt":[{"stem":"막대그래프에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「세로 눈금 한 칸은 언제나 1이야.」","correct":true,"mis_target":"M4-1-u5-X02"},{"t":"은우 — 「가로와 세로가 무엇인지 먼저 봐야 해.」","mis":"M4-1-u5-X21"},{"t":"하랑 — 「표를 보면 합계를 알 수 있어.」","mis":"M4-1-u5-X21"},{"t":"지아 — 「눈금 한 칸이 얼마인지 먼저 확인해.」","mis":"M4-1-u5-X21"}],"explanation":["막대그래프는 수량을 막대의 길이로 나타내요.","시우의 말은 막대그래프의 성질과 맞지 않아요.","굵기는 관계없고, 눈금 한 칸은 그래프마다 달라 먼저 확인해요."],"asset":null},{"stem":"막대그래프에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「그림그래프는 세지 않아도 길이로 견줄 수 있어.」","correct":true,"mis_target":"M4-1-u5-X04"},{"t":"하랑 — 「표를 보면 합계를 알 수 있어.」","mis":"M4-1-u5-X21"},{"t":"지아 — 「눈금 한 칸이 얼마인지 먼저 확인해.」","mis":"M4-1-u5-X21"},{"t":"준서 — 「막대그래프는 수량을 막대의 길이로 나타내.」","mis":"M4-1-u5-X21"}],"explanation":["막대그래프는 수량을 막대의 길이로 나타내요.","은우의 말은 막대그래프의 성질과 맞지 않아요.","굵기는 관계없고, 눈금 한 칸은 그래프마다 달라 먼저 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_challenge#5','math',4,1,'u5','L02','g4_1_math_u5_L02_challenge','lesson_challenge','M4-1-u5-C1',3,'sa','auto','큰 그림은 10명, 작은 그림은 1명을 나타내는 그림그래프예요. 큰 그림 2개와 작은 그림 4개는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u5-C1","difficulty":3,"kind":"sa","stem":"큰 그림은 10명, 작은 그림은 1명을 나타내는 그림그래프예요. 큰 그림 2개와 작은 그림 4개는 몇 명인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["큰 그림 2개는 10 × 2 = 20.","작은 그림 4개는 1 × 4 = 4.","20 + 4 = 24 — 24명이에요."],"variant_rule":{"alt":[{"stem":"큰 그림은 5명, 작은 그림은 1명을 나타내는 그림그래프예요. 큰 그림 3개와 작은 그림 2개는 몇 명인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["큰 그림 3개는 5 × 3 = 15.","작은 그림 2개는 1 × 2 = 2.","15 + 2 = 17 — 17명이에요."],"asset":null},{"stem":"큰 그림은 10권, 작은 그림은 1권을 나타내는 그림그래프예요. 큰 그림 1개와 작은 그림 7개는 몇 권인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["큰 그림 1개는 10 × 1 = 10.","작은 그림 7개는 1 × 7 = 7.","10 + 7 = 17 — 17권이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_challenge#6','math',4,1,'u5','L02','g4_1_math_u5_L02_challenge','lesson_challenge','M4-1-u5-C3',3,'sa','auto','어느 막대그래프에서 세로 눈금 5칸이 5명을 나타내요. 세로 눈금 한 칸은 몇 명을 나타내나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u5-C3","difficulty":3,"kind":"sa","stem":"어느 막대그래프에서 세로 눈금 5칸이 5명을 나타내요. 세로 눈금 한 칸은 몇 명을 나타내나요? 숫자로 쓰세요.","answer":["1"],"explanation":["세로 눈금 5칸이 5명이에요.","한 칸은 5 ÷ 5로 구해요.","세로 눈금 한 칸은 1명이에요."],"variant_rule":{"alt":[{"stem":"어느 막대그래프에서 세로 눈금 5칸이 10명을 나타내요. 세로 눈금 한 칸은 몇 명을 나타내나요? 숫자로 쓰세요.","answer":["2"],"explanation":["세로 눈금 5칸이 10명이에요.","한 칸은 10 ÷ 5로 구해요.","세로 눈금 한 칸은 2명이에요."],"asset":null},{"stem":"어느 막대그래프에서 세로 눈금 5칸이 25그루를 나타내요. 세로 눈금 한 칸은 몇 그루를 나타내나요? 숫자로 쓰세요.","answer":["5"],"explanation":["세로 눈금 5칸이 25그루예요.","한 칸은 25 ÷ 5로 구해요.","세로 눈금 한 칸은 5그루예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_challenge#7','math',4,1,'u5','L02','g4_1_math_u5_L02_challenge','lesson_challenge','M4-1-u5-C2',3,'mc','auto','그림그래프와 막대그래프의 다른 점으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X04']::text[],true,'{"seq":7,"concept":"M4-1-u5-C2","difficulty":3,"kind":"mc","stem":"그림그래프와 막대그래프의 다른 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"수량을 그림그래프는 그림으로, 막대그래프는 막대의 길이로 나타내요.","correct":true},{"t":"그림그래프는 항목을 나타내지 않아요.","mis":"M4-1-u5-X04"},{"t":"막대그래프에는 제목이 없어요.","mis":"M4-1-u5-X04"},{"t":"두 그래프는 서로 다른 자료만 나타내요.","mis":"M4-1-u5-X04"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"variant_rule":{"alt":[{"stem":"그림그래프와 막대그래프의 같은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 항목별 수량을 나타내요.","correct":true},{"t":"둘 다 그림의 개수로 나타내요.","mis":"M4-1-u5-X04"},{"t":"둘 다 막대의 굵기로 나타내요.","mis":"M4-1-u5-X03"},{"t":"둘 다 합계만 나타내요.","mis":"M4-1-u5-X04"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"asset":null},{"stem":"그림을 세지 않고도 길이만 보고 많고 적음을 견줄 수 있는 것은 어느 것인가요?","options":[{"t":"막대그래프","correct":true},{"t":"그림그래프","mis":"M4-1-u5-X04"},{"t":"표","mis":"M4-1-u5-X04"},{"t":"말로 들은 조사 결과","mis":"M4-1-u5-X04"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_challenge#8','math',4,1,'u5','L02','g4_1_math_u5_L02_challenge','lesson_challenge','M4-1-u5-C3',4,'sa','auto','가장 많은 항목과 가장 적은 항목을 빼고, 나머지 항목의 학생 수를 모두 더하면 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u5-C3","difficulty":4,"kind":"sa","stem":"가장 많은 항목과 가장 적은 항목을 빼고, 나머지 항목의 학생 수를 모두 더하면 몇 명인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["가장 많은 것은 잡채, 가장 적은 것은 김밥이에요.","나머지는 카레, 불고기, 국수 — 5명, 7명, 6명.","5 + 7 + 6 = 18 — 18명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["카레","잡채","불고기","국수","김밥"],"series":[{"vals":[5,8,7,6,3]}],"step":1,"ymax":9,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 가장 많은 항목과 가장 적은 항목을 빼고, 나머지 항목의 학생 수를 모두 더하면 몇 명인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["가장 많은 것은 김밥, 가장 적은 것은 떡볶이예요.","나머지는 과일, 빵, 만두 — 7명, 8명, 9명.","7 + 8 + 9 = 24 — 24명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","만두"],"series":[{"vals":[5,12,7,8,9]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 가장 많은 항목과 가장 적은 항목을 빼고, 나머지 항목의 학생 수를 모두 더하면 몇 명인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["가장 많은 것은 강아지, 가장 적은 것은 햄스터예요.","나머지는 고양이, 토끼, 금붕어 — 3명, 5명, 6명.","3 + 5 + 6 = 14 — 14명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["강아지","고양이","토끼","햄스터","금붕어"],"series":[{"vals":[9,3,5,2,6]}],"step":1,"ymax":10,"ylab":"(명)","title":"기르고 싶은 동물별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_challenge#9','math',4,1,'u5','L02','g4_1_math_u5_L02_challenge','lesson_challenge','M4-1-u5-C3',4,'sa','auto','가장 많은 항목과 가장 적은 항목의 학생 수 차는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u5-C3","difficulty":4,"kind":"sa","stem":"가장 많은 항목과 가장 적은 항목의 학생 수 차는 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["가장 긴 막대는 김밥 12명, 가장 짧은 막대는 떡볶이 2명이에요.","차는 큰 수에서 작은 수를 빼요.","12 − 2 = 10 — 10명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","만두"],"series":[{"vals":[2,12,4,5,10]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 간식별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 가장 많은 항목과 가장 적은 항목의 학생 수 차는 몇 명인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["가장 긴 막대는 금붕어 11명, 가장 짧은 막대는 강아지 4명이에요.","차는 큰 수에서 작은 수를 빼요.","11 − 4 = 7 — 7명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["강아지","고양이","토끼","햄스터","금붕어"],"series":[{"vals":[4,9,8,7,11]}],"step":1,"ymax":12,"ylab":"(명)","title":"기르고 싶은 동물별 학생 수"}},{"stem":"가장 많은 항목과 가장 적은 항목의 빌린 책 수 차는 몇 권인가요? 숫자로 쓰세요.","answer":["130"],"explanation":["가장 긴 막대는 5반 160권, 가장 짧은 막대는 1반 30권이에요.","차는 큰 수에서 작은 수를 빼요.","160 − 30 = 130 — 130권이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["1반","2반","3반","4반","5반","6반"],"series":[{"vals":[30,130,90,120,160,60]}],"step":10,"ymax":170,"ylab":"(권)","title":"반별 빌린 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L02_challenge#10','math',4,1,'u5','L02','g4_1_math_u5_L02_challenge','lesson_challenge','M4-1-u5-C2',4,'essay','teacher','같은 「좋아하는 과일별 학생 수」를 그림그래프와 막대그래프로 나타냈어요. 사과와 포도 가운데 어느 쪽이 얼마나 더 많은지 견주기에 어느 그래프가 더 편리한지와 그 까닭을 쓰고, 친구가 「사과 막대가 더 굵으니 사과가 더 많아.」라고 했다면 무엇이 잘못인지도 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-1-u5-C2","difficulty":4,"kind":"essay","stem":"같은 「좋아하는 과일별 학생 수」를 그림그래프와 막대그래프로 나타냈어요. 사과와 포도 가운데 어느 쪽이 얼마나 더 많은지 견주기에 어느 그래프가 더 편리한지와 그 까닭을 쓰고, 친구가 「사과 막대가 더 굵으니 사과가 더 많아.」라고 했다면 무엇이 잘못인지도 써 보세요.","answer_guide":{"answer":"예: 막대그래프가 더 편리하다. 그림그래프는 그림을 하나하나 세어야 수를 알 수 있지만 막대그래프는 막대의 길이만 보고 많고 적음을 한눈에 견줄 수 있기 때문이다. 막대그래프에서 수량은 막대의 길이로만 나타내므로 굵기로 판단한 친구의 말은 잘못이다.","scoring_points":["막대그래프를 골랐는가","그림을 세어야 하는 불편과 길이로 한눈에 견주는 점을 썼는가","수량은 굵기가 아니라 길이로 나타낸다고 썼는가"]},"explanation":["그림그래프는 그림을 세어야 견줄 수 있어요.","막대그래프는 길이만 보면 돼요.","수량은 막대의 길이로만 나타내요 — 굵기와는 관계없어요."],"asset":{"type":"lgraph","mode":"bar","xs":["사과","포도","딸기","귤"],"series":[{"vals":[9,6,4,7]}],"step":1,"ymax":10,"ylab":"(명)","title":"좋아하는 과일별 학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_basic#1','math',4,1,'u5','L03','g4_1_math_u5_L03_basic','lesson_basic','M4-1-u5-C4',1,'mc','auto','막대그래프를 그리는 차례에서 눈금 한 칸의 크기를 정한 다음에 하는 일은 무엇인가요?',ARRAY['M4-1-u5-X18']::text[],true,'{"seq":1,"concept":"M4-1-u5-C4","difficulty":1,"kind":"mc","stem":"막대그래프를 그리는 차례에서 눈금 한 칸의 크기를 정한 다음에 하는 일은 무엇인가요?","options":[{"t":"수량만큼 막대를 그려요.","correct":true},{"t":"가로와 세로에 나타낼 것을 정해요.","mis":"M4-1-u5-X18"},{"t":"세로 눈금의 단위를 정해요.","mis":"M4-1-u5-X18"},{"t":"조사를 처음부터 다시 해요.","mis":"M4-1-u5-X18"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"variant_rule":{"alt":[{"stem":"막대그래프를 그리는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"제목 → 가로와 세로 → 단위 → 눈금의 크기 → 막대","correct":true},{"t":"막대 → 눈금의 크기 → 단위 → 가로와 세로 → 제목","mis":"M4-1-u5-X18"},{"t":"가로와 세로 → 막대 → 단위 → 눈금의 크기 → 제목","mis":"M4-1-u5-X18"},{"t":"눈금의 크기 → 막대 → 가로와 세로 → 단위 → 제목","mis":"M4-1-u5-X18"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"asset":null},{"stem":"막대그래프의 제목에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"맨 처음에 써도 되고 맨 마지막에 써도 돼요.","correct":true},{"t":"맨 처음에만 써야 해요.","mis":"M4-1-u5-X18"},{"t":"제목은 쓰지 않아도 돼요.","mis":"M4-1-u5-X04"},{"t":"막대마다 하나씩 써요.","mis":"M4-1-u5-X03"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_basic#2','math',4,1,'u5','L03','g4_1_math_u5_L03_basic','lesson_basic','M4-1-u5-C4',1,'mc','auto','표를 보고 세로 막대그래프로 나타내려고 해요. 가로와 세로에는 각각 무엇을 나타내야 하나요?',ARRAY['M4-1-u5-X01']::text[],true,'{"seq":2,"concept":"M4-1-u5-C4","difficulty":1,"kind":"mc","stem":"표를 보고 세로 막대그래프로 나타내려고 해요. 가로와 세로에는 각각 무엇을 나타내야 하나요?","options":[{"t":"가로: 체험, 세로: 학생 수","correct":true},{"t":"가로: 학생 수, 세로: 합계","mis":"M4-1-u5-X01"},{"t":"가로: 합계, 세로: 체험","mis":"M4-1-u5-X01"},{"t":"가로: 학생 수, 세로: 학생 수","mis":"M4-1-u5-X01"}],"explanation":["세로 막대그래프는 가로에 항목을 늘어놓고 막대를 위로 세워요.","항목은 체험, 수량은 학생 수예요.","가로: 체험, 세로: 학생 수예요."],"asset":{"type":"picg","only":"table","head":"체험","cols":["로봇","요리","방송","소방","과학"],"counts":[4,10,12,5,11],"vh":"학생 수","unit":"명","total":42,"title":"가고 싶은 체험별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 표를 보고 세로 막대그래프로 나타내려고 해요. 가로와 세로에는 각각 무엇을 나타내야 하나요?","options":[{"t":"가로: 직업, 세로: 학생 수","correct":true},{"t":"가로: 학생 수, 세로: 합계","mis":"M4-1-u5-X01"},{"t":"가로: 합계, 세로: 직업","mis":"M4-1-u5-X01"},{"t":"가로: 학생 수, 세로: 학생 수","mis":"M4-1-u5-X01"}],"explanation":["세로 막대그래프는 가로에 항목을 늘어놓고 막대를 위로 세워요.","항목은 직업, 수량은 학생 수예요.","가로: 직업, 세로: 학생 수예요."],"asset":{"type":"picg","only":"table","head":"직업","cols":["요리사","경찰관","과학자","가수","의사"],"counts":[7,3,10,1,5],"vh":"학생 수","unit":"명","total":26,"title":"희망 직업별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 표를 보고 세로 막대그래프로 나타내려고 해요. 가로와 세로에는 각각 무엇을 나타내야 하나요?","options":[{"t":"가로: 급식 메뉴, 세로: 학생 수","correct":true},{"t":"가로: 학생 수, 세로: 합계","mis":"M4-1-u5-X01"},{"t":"가로: 합계, 세로: 급식 메뉴","mis":"M4-1-u5-X01"},{"t":"가로: 학생 수, 세로: 학생 수","mis":"M4-1-u5-X01"}],"explanation":["세로 막대그래프는 가로에 항목을 늘어놓고 막대를 위로 세워요.","항목은 급식 메뉴, 수량은 학생 수예요.","가로: 급식 메뉴, 세로: 학생 수예요."],"asset":{"type":"picg","only":"table","head":"급식 메뉴","cols":["카레","잡채","불고기","국수","김밥"],"counts":[3,10,11,