INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_basic#3','math',4,1,'u5','L03','g4_1_math_u5_L03_basic','lesson_basic','M4-1-u5-C5',1,'sa','auto','표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 점까지 나타내어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u5-C5","difficulty":1,"kind":"sa","stem":"표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 점까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["175"],"explanation":["세로 눈금은 모든 막대를 그릴 수 있어야 해요.","표에서 가장 큰 수는 175점이에요.","그래서 세로 눈금은 적어도 175점까지 나타내요."],"asset":{"type":"picg","only":"table","head":"지역","cols":["가 지역","나 지역","다 지역","라 지역","마 지역"],"counts":[175,150,100,25,75],"vh":"문화유산 수","unit":"점","title":"지역별 문화유산 수"},"variant_rule":{"alt":[{"stem":"표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 명까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["세로 눈금은 모든 막대를 그릴 수 있어야 해요.","표에서 가장 큰 수는 9명이에요.","그래서 세로 눈금은 적어도 9명까지 나타내요."],"asset":{"type":"picg","only":"table","head":"과일","cols":["사과","포도","딸기","귤","배"],"counts":[9,3,4,8,7],"vh":"학생 수","unit":"명","title":"좋아하는 과일별 학생 수"}},{"stem":"표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 명까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["세로 눈금은 모든 막대를 그릴 수 있어야 해요.","표에서 가장 큰 수는 12명이에요.","그래서 세로 눈금은 적어도 12명까지 나타내요."],"asset":{"type":"picg","only":"table","head":"운동","cols":["축구","피구","수영","야구","배구"],"counts":[3,12,10,9,6],"vh":"학생 수","unit":"명","title":"좋아하는 운동별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_basic#4','math',4,1,'u5','L03','g4_1_math_u5_L03_basic','lesson_basic','M4-1-u5-C5',1,'sa','auto','세로 눈금 한 칸이 1명인 막대그래프에 7명을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u5-C5","difficulty":1,"kind":"sa","stem":"세로 눈금 한 칸이 1명인 막대그래프에 7명을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 칸이 1명이니 한 칸 올라갈 때마다 1씩 커져요.","막대의 칸 수는 7 ÷ 1로 구해요.","7 ÷ 1 = 7 — 7칸으로 그려요."],"variant_rule":{"alt":[{"stem":"세로 눈금 한 칸이 2명인 막대그래프에 12명을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 칸이 2명이니 한 칸 올라갈 때마다 2씩 커져요.","막대의 칸 수는 12 ÷ 2로 구해요.","12 ÷ 2 = 6 — 6칸으로 그려요."],"asset":null},{"stem":"세로 눈금 한 칸이 5그루인 막대그래프에 35그루를 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 칸이 5그루이니 한 칸 올라갈 때마다 5씩 커져요.","막대의 칸 수는 35 ÷ 5로 구해요.","35 ÷ 5 = 7 — 7칸으로 그려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_basic#5','math',4,1,'u5','L03','g4_1_math_u5_L03_basic','lesson_basic','M4-1-u5-C4',2,'mc','auto','막대그래프를 그릴 때 꼭 해야 하는 일이 아닌 것은 어느 것인가요?',ARRAY['M4-1-u5-X21']::text[],true,'{"seq":5,"concept":"M4-1-u5-C4","difficulty":2,"kind":"mc","stem":"막대그래프를 그릴 때 꼭 해야 하는 일이 아닌 것은 어느 것인가요?","options":[{"t":"막대마다 굵기를 다르게 하기","correct":true},{"t":"가로와 세로에 무엇을 나타낼지 정하기","mis":"M4-1-u5-X21"},{"t":"눈금 한 칸의 크기를 정하기","mis":"M4-1-u5-X21"},{"t":"수량에 맞게 막대의 길이를 정하기","mis":"M4-1-u5-X21"}],"explanation":["막대그래프는 가로·세로, 단위, 눈금 한 칸을 정하고 수량만큼 막대를 그려요.","「막대마다 굵기를 다르게 하기」는 꼭 해야 하는 일이 아니에요.","막대의 굵기는 모두 같게, 모든 항목을 빠짐없이 그려요."],"variant_rule":{"alt":[{"stem":"막대그래프를 그릴 때 꼭 해야 하는 일이 아닌 것은 어느 것인가요?","options":[{"t":"수가 가장 많은 막대만 색칠하기","correct":true},{"t":"눈금 한 칸의 크기를 정하기","mis":"M4-1-u5-X21"},{"t":"수량에 맞게 막대의 길이를 정하기","mis":"M4-1-u5-X21"},{"t":"세로 눈금의 단위를 정하기","mis":"M4-1-u5-X21"}],"explanation":["막대그래프는 가로·세로, 단위, 눈금 한 칸을 정하고 수량만큼 막대를 그려요.","「수가 가장 많은 막대만 색칠하기」는 꼭 해야 하는 일이 아니에요.","막대의 굵기는 모두 같게, 모든 항목을 빠짐없이 그려요."],"asset":null},{"stem":"막대그래프를 그릴 때 꼭 해야 하는 일이 아닌 것은 어느 것인가요?","options":[{"t":"막대 위에 그림을 그려 넣기","correct":true},{"t":"수량에 맞게 막대의 길이를 정하기","mis":"M4-1-u5-X21"},{"t":"세로 눈금의 단위를 정하기","mis":"M4-1-u5-X21"},{"t":"가로와 세로에 무엇을 나타낼지 정하기","mis":"M4-1-u5-X21"}],"explanation":["막대그래프는 가로·세로, 단위, 눈금 한 칸을 정하고 수량만큼 막대를 그려요.","「막대 위에 그림을 그려 넣기」는 꼭 해야 하는 일이 아니에요.","막대의 굵기는 모두 같게, 모든 항목을 빠짐없이 그려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_basic#6','math',4,1,'u5','L03','g4_1_math_u5_L03_basic','lesson_basic','M4-1-u5-C5',2,'mc','auto','표를 보고 막대그래프를 그리는데 세로 눈금을 11명까지만 그렸어요. 무엇이 문제인가요?',ARRAY['M4-1-u5-X04','M4-1-u5-X03','M4-1-u5-X05']::text[],true,'{"seq":6,"concept":"M4-1-u5-C5","difficulty":2,"kind":"mc","stem":"표를 보고 막대그래프를 그리는데 세로 눈금을 11명까지만 그렸어요. 무엇이 문제인가요?","options":[{"t":"11명보다 큰 수는 막대로 다 나타낼 수 없어요.","correct":true},{"t":"세로 눈금이 짧으면 제목을 쓸 수 없어요.","mis":"M4-1-u5-X04"},{"t":"막대의 굵기를 정할 수 없어요.","mis":"M4-1-u5-X03"},{"t":"문제가 없어요 — 눈금은 아무렇게나 정해도 돼요.","mis":"M4-1-u5-X05"}],"explanation":["세로 눈금은 가장 큰 수를 담을 수 있어야 해요.","표에서 가장 큰 수는 12명인데 눈금은 11명까지예요.","그래서 11명보다 큰 막대는 잘려서 그릴 수 없어요."],"asset":{"type":"picg","only":"table","head":"과일","cols":["사과","포도","딸기","귤","배"],"counts":[4,5,12,10,8],"vh":"학생 수","unit":"명","title":"좋아하는 과일별 학생 수"},"variant_rule":{"alt":[{"stem":"표를 보고 막대그래프를 그리는데 세로 눈금을 8명까지만 그렸어요. 무엇이 문제인가요?","options":[{"t":"8명보다 큰 수는 막대로 다 나타낼 수 없어요.","correct":true},{"t":"세로 눈금이 짧으면 제목을 쓸 수 없어요.","mis":"M4-1-u5-X04"},{"t":"막대의 굵기를 정할 수 없어요.","mis":"M4-1-u5-X03"},{"t":"문제가 없어요 — 눈금은 아무렇게나 정해도 돼요.","mis":"M4-1-u5-X05"}],"explanation":["세로 눈금은 가장 큰 수를 담을 수 있어야 해요.","표에서 가장 큰 수는 10명인데 눈금은 8명까지예요.","그래서 8명보다 큰 막대는 잘려서 그릴 수 없어요."],"asset":{"type":"picg","only":"table","head":"운동","cols":["축구","피구","수영","야구","배구"],"counts":[10,6,9,4,2],"vh":"학생 수","unit":"명","title":"좋아하는 운동별 학생 수"}},{"stem":"표를 보고 막대그래프를 그리는데 세로 눈금을 9명까지만 그렸어요. 무엇이 문제인가요?","options":[{"t":"9명보다 큰 수는 막대로 다 나타낼 수 없어요.","correct":true},{"t":"세로 눈금이 짧으면 제목을 쓸 수 없어요.","mis":"M4-1-u5-X04"},{"t":"막대의 굵기를 정할 수 없어요.","mis":"M4-1-u5-X03"},{"t":"문제가 없어요 — 눈금은 아무렇게나 정해도 돼요.","mis":"M4-1-u5-X05"}],"explanation":["세로 눈금은 가장 큰 수를 담을 수 있어야 해요.","표에서 가장 큰 수는 12명인데 눈금은 9명까지예요.","그래서 9명보다 큰 막대는 잘려서 그릴 수 없어요."],"asset":{"type":"picg","only":"table","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[12,9,7,8],"vh":"학생 수","unit":"명","title":"좋아하는 계절별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_basic#7','math',4,1,'u5','L03','g4_1_math_u5_L03_basic','lesson_basic','M4-1-u5-C4',2,'ox','auto','막대그래프를 그릴 때 막대의 굵기는 모두 같게 그려요.',ARRAY['M4-1-u5-X03']::text[],true,'{"seq":7,"concept":"M4-1-u5-C4","difficulty":2,"kind":"ox","stem":"막대그래프를 그릴 때 막대의 굵기는 모두 같게 그려요.","answer":"O","reason_options":[{"t":"수량은 길이로만 나타내므로 굵기를 같게 해야 헷갈리지 않아서","correct":true},{"t":"많은 항목은 더 굵게 그려야 해서","mis":"M4-1-u5-X03"}],"mis":"M4-1-u5-X03","explanation":["그리는 차례 — 제목, 가로와 세로, 단위, 눈금 한 칸의 크기, 막대.","막대는 수량 ÷ 한 칸만큼, 굵기는 모두 같게 그려요.","세로 눈금은 가장 큰 수까지 담을 수 있어야 해요."],"variant_rule":{"alt":[{"stem":"막대그래프의 제목은 맨 마지막에 써도 괜찮아요.","answer":"O","reason_options":[{"t":"제목은 처음이나 마지막에 쓸 수 있어서","correct":true},{"t":"제목은 반드시 맨 처음에만 써야 해서","mis":"M4-1-u5-X18"}],"explanation":["그리는 차례 — 제목, 가로와 세로, 단위, 눈금 한 칸의 크기, 막대.","막대는 수량 ÷ 한 칸만큼, 굵기는 모두 같게 그려요.","세로 눈금은 가장 큰 수까지 담을 수 있어야 해요."],"asset":null},{"stem":"막대를 그리기 전에 눈금 한 칸의 크기를 먼저 정해요.","answer":"O","reason_options":[{"t":"한 칸의 크기를 알아야 막대를 몇 칸으로 그릴지 정할 수 있어서","correct":true},{"t":"막대를 다 그린 뒤에 눈금을 정해도 되어서","mis":"M4-1-u5-X18"}],"explanation":["그리는 차례 — 제목, 가로와 세로, 단위, 눈금 한 칸의 크기, 막대.","막대는 수량 ÷ 한 칸만큼, 굵기는 모두 같게 그려요.","세로 눈금은 가장 큰 수까지 담을 수 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_basic#8','math',4,1,'u5','L03','g4_1_math_u5_L03_basic','lesson_basic','M4-1-u5-C5',2,'sa','auto','세로 눈금 한 칸이 10권인 막대그래프에 90권을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u5-C5","difficulty":2,"kind":"sa","stem":"세로 눈금 한 칸이 10권인 막대그래프에 90권을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 칸이 10권이니 한 칸 올라갈 때마다 10씩 커져요.","막대의 칸 수는 90 ÷ 10으로 구해요.","90 ÷ 10 = 9 — 9칸으로 그려요."],"variant_rule":{"alt":[{"stem":"세로 눈금 한 칸이 20 kg인 막대그래프에 160 kg을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 칸이 20 kg이니 한 칸 올라갈 때마다 20씩 커져요.","막대의 칸 수는 160 ÷ 20으로 구해요.","160 ÷ 20 = 8 — 8칸으로 그려요."],"asset":null},{"stem":"세로 눈금 한 칸이 25점인 막대그래프에 125점을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 칸이 25점이니 한 칸 올라갈 때마다 25씩 커져요.","막대의 칸 수는 125 ÷ 25로 구해요.","125 ÷ 25 = 5 — 5칸으로 그려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_basic#9','math',4,1,'u5','L03','g4_1_math_u5_L03_basic','lesson_basic','M4-1-u5-C4',2,'mc','auto','막대를 그릴 때 지켜야 할 것은 어느 것인가요?',ARRAY['M4-1-u5-X03','M4-1-u5-X02','M4-1-u5-X05']::text[],true,'{"seq":9,"concept":"M4-1-u5-C4","difficulty":2,"kind":"mc","stem":"막대를 그릴 때 지켜야 할 것은 어느 것인가요?","options":[{"t":"막대의 굵기를 모두 같게 그려요.","correct":true},{"t":"수가 많은 막대를 더 굵게 그려요.","mis":"M4-1-u5-X03"},{"t":"막대마다 눈금 한 칸을 다르게 해요.","mis":"M4-1-u5-X02"},{"t":"수가 적은 막대는 그리지 않아요.","mis":"M4-1-u5-X05"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"variant_rule":{"alt":[{"stem":"학생 수를 나타내는 막대그래프에서 세로 눈금의 단위로 알맞은 것은 어느 것인가요?","options":[{"t":"명","correct":true},{"t":"개","mis":"M4-1-u5-X01"},{"t":"권","mis":"M4-1-u5-X01"},{"t":"kg","mis":"M4-1-u5-X01"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"asset":null},{"stem":"가로에는 항목, 세로에는 학생 수를 나타내기로 정했어요. 그다음에 정할 것은 무엇인가요?","options":[{"t":"세로 눈금의 단위","correct":true},{"t":"막대마다 다른 굵기","mis":"M4-1-u5-X03"},{"t":"막대마다 다른 색","mis":"M4-1-u5-X03"},{"t":"신문 기사 제목","mis":"M4-1-u5-X18"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_basic#10','math',4,1,'u5','L03','g4_1_math_u5_L03_basic','lesson_basic','M4-1-u5-C5',3,'mc','auto','표의 내용은 「1반 70권, 2반 100권, 3반 50권, 4반 160권」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?',ARRAY['M4-1-u5-X02']::text[],true,'{"seq":10,"concept":"M4-1-u5-C5","difficulty":3,"kind":"mc","stem":"표의 내용은 「1반 70권, 2반 100권, 3반 50권, 4반 160권」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"4반","correct":true},{"t":"1반","mis":"M4-1-u5-X02"},{"t":"2반","mis":"M4-1-u5-X02"},{"t":"3반","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 10권이에요.","막대마다 표의 수와 견주어 봐요.","4반의 막대는 170권인데 표에서는 160권이에요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["1반","2반","3반","4반"],"series":[{"vals":[70,100,50,170]}],"step":10,"ymax":180,"ylab":"(권)","title":"반별 빌린 책 수"},"variant_rule":{"alt":[{"stem":"표의 내용은 「해 농장 200 kg, 달 농장 140 kg, 별 농장 80 kg, 숲 농장 280 kg」예요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"숲 농장","correct":true},{"t":"해 농장","mis":"M4-1-u5-X02"},{"t":"달 농장","mis":"M4-1-u5-X02"},{"t":"별 농장","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 20 kg이에요.","막대마다 표의 수와 견주어 봐요.","숲 농장의 막대는 300 kg인데 표에서는 280 kg이에요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["해 농장","달 농장","별 농장","숲 농장"],"series":[{"vals":[200,140,80,300]}],"step":20,"ymax":320,"ylab":"(kg)","title":"농장별 토마토 생산량"}},{"stem":"표의 내용은 「가 마을 55그루, 나 마을 25그루, 다 마을 20그루, 라 마을 30그루」예요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"다 마을","correct":true},{"t":"가 마을","mis":"M4-1-u5-X02"},{"t":"나 마을","mis":"M4-1-u5-X02"},{"t":"라 마을","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 5그루예요.","막대마다 표의 수와 견주어 봐요.","다 마을의 막대는 15그루인데 표에서는 20그루예요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을"],"series":[{"vals":[55,25,15,30]}],"step":5,"ymax":60,"ylab":"(그루)","title":"마을별 나무 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_challenge#1','math',4,1,'u5','L03','g4_1_math_u5_L03_challenge','lesson_challenge','M4-1-u5-C5',2,'mc','auto','표를 보고 막대그래프를 그리는데 세로 눈금을 10명까지만 그렸어요. 무엇이 문제인가요?',ARRAY['M4-1-u5-X04','M4-1-u5-X03','M4-1-u5-X05']::text[],true,'{"seq":1,"concept":"M4-1-u5-C5","difficulty":2,"kind":"mc","stem":"표를 보고 막대그래프를 그리는데 세로 눈금을 10명까지만 그렸어요. 무엇이 문제인가요?","options":[{"t":"10명보다 큰 수는 막대로 다 나타낼 수 없어요.","correct":true},{"t":"세로 눈금이 짧으면 제목을 쓸 수 없어요.","mis":"M4-1-u5-X04"},{"t":"막대의 굵기를 정할 수 없어요.","mis":"M4-1-u5-X03"},{"t":"문제가 없어요 — 눈금은 아무렇게나 정해도 돼요.","mis":"M4-1-u5-X05"}],"explanation":["세로 눈금은 가장 큰 수를 담을 수 있어야 해요.","표에서 가장 큰 수는 11명인데 눈금은 10명까지예요.","그래서 10명보다 큰 막대는 잘려서 그릴 수 없어요."],"asset":{"type":"picg","only":"table","head":"체험","cols":["로봇","요리","방송","소방","과학"],"counts":[8,9,10,11,2],"vh":"학생 수","unit":"명","title":"가고 싶은 체험별 학생 수"},"variant_rule":{"alt":[{"stem":"표를 보고 막대그래프를 그리는데 세로 눈금을 8명까지만 그렸어요. 무엇이 문제인가요?","options":[{"t":"8명보다 큰 수는 막대로 다 나타낼 수 없어요.","correct":true},{"t":"세로 눈금이 짧으면 제목을 쓸 수 없어요.","mis":"M4-1-u5-X04"},{"t":"막대의 굵기를 정할 수 없어요.","mis":"M4-1-u5-X03"},{"t":"문제가 없어요 — 눈금은 아무렇게나 정해도 돼요.","mis":"M4-1-u5-X05"}],"explanation":["세로 눈금은 가장 큰 수를 담을 수 있어야 해요.","표에서 가장 큰 수는 10명인데 눈금은 8명까지예요.","그래서 8명보다 큰 막대는 잘려서 그릴 수 없어요."],"asset":{"type":"picg","only":"table","head":"직업","cols":["요리사","경찰관","과학자","가수","의사"],"counts":[9,10,1,5,2],"vh":"학생 수","unit":"명","title":"희망 직업별 학생 수"}},{"stem":"표를 보고 막대그래프를 그리는데 세로 눈금을 7명까지만 그렸어요. 무엇이 문제인가요?","options":[{"t":"7명보다 큰 수는 막대로 다 나타낼 수 없어요.","correct":true},{"t":"세로 눈금이 짧으면 제목을 쓸 수 없어요.","mis":"M4-1-u5-X04"},{"t":"막대의 굵기를 정할 수 없어요.","mis":"M4-1-u5-X03"},{"t":"문제가 없어요 — 눈금은 아무렇게나 정해도 돼요.","mis":"M4-1-u5-X05"}],"explanation":["세로 눈금은 가장 큰 수를 담을 수 있어야 해요.","표에서 가장 큰 수는 10명인데 눈금은 7명까지예요.","그래서 7명보다 큰 막대는 잘려서 그릴 수 없어요."],"asset":{"type":"picg","only":"table","head":"급식 메뉴","cols":["카레","잡채","불고기","국수","김밥"],"counts":[10,9,6,3,8],"vh":"학생 수","unit":"명","title":"좋아하는 급식 메뉴별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_challenge#2','math',4,1,'u5','L03','g4_1_math_u5_L03_challenge','lesson_challenge','M4-1-u5-C4',2,'mc','auto','표를 보고 세로 막대그래프로 나타내려고 해요. 가로와 세로에는 각각 무엇을 나타내야 하나요?',ARRAY['M4-1-u5-X01']::text[],true,'{"seq":2,"concept":"M4-1-u5-C4","difficulty":2,"kind":"mc","stem":"표를 보고 세로 막대그래프로 나타내려고 해요. 가로와 세로에는 각각 무엇을 나타내야 하나요?","options":[{"t":"가로: 간식, 세로: 학생 수","correct":true},{"t":"가로: 학생 수, 세로: 합계","mis":"M4-1-u5-X01"},{"t":"가로: 합계, 세로: 간식","mis":"M4-1-u5-X01"},{"t":"가로: 학생 수, 세로: 학생 수","mis":"M4-1-u5-X01"}],"explanation":["세로 막대그래프는 가로에 항목을 늘어놓고 막대를 위로 세워요.","항목은 간식, 수량은 학생 수예요.","가로: 간식, 세로: 학생 수예요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","만두"],"counts":[8,9,5,12,11],"vh":"학생 수","unit":"명","total":45,"title":"좋아하는 간식별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 표를 보고 세로 막대그래프로 나타내려고 해요. 가로와 세로에는 각각 무엇을 나타내야 하나요?","options":[{"t":"가로: 동물, 세로: 학생 수","correct":true},{"t":"가로: 학생 수, 세로: 합계","mis":"M4-1-u5-X01"},{"t":"가로: 합계, 세로: 동물","mis":"M4-1-u5-X01"},{"t":"가로: 학생 수, 세로: 학생 수","mis":"M4-1-u5-X01"}],"explanation":["세로 막대그래프는 가로에 항목을 늘어놓고 막대를 위로 세워요.","항목은 동물, 수량은 학생 수예요.","가로: 동물, 세로: 학생 수예요."],"asset":{"type":"picg","only":"table","head":"동물","cols":["강아지","고양이","토끼","햄스터","금붕어"],"counts":[8,3,7,4,1],"vh":"학생 수","unit":"명","total":23,"title":"기르고 싶은 동물별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 표를 보고 세로 막대그래프로 나타내려고 해요. 가로와 세로에는 각각 무엇을 나타내야 하나요?","options":[{"t":"가로: 반, 세로: 빌린 책 수","correct":true},{"t":"가로: 빌린 책 수, 세로: 합계","mis":"M4-1-u5-X01"},{"t":"가로: 합계, 세로: 반","mis":"M4-1-u5-X01"},{"t":"가로: 빌린 책 수, 세로: 빌린 책 수","mis":"M4-1-u5-X01"}],"explanation":["세로 막대그래프는 가로에 항목을 늘어놓고 막대를 위로 세워요.","항목은 반, 수량은 빌린 책 수예요.","가로: 반, 세로: 빌린 책 수예요."],"asset":{"type":"picg","only":"table","head":"반","cols":["1반","2반","3반","4반","5반","6반"],"counts"