INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_challenge#3','math',4,1,'u5','L03','g4_1_math_u5_L03_challenge','lesson_challenge','M4-1-u5-C5',3,'mc','auto','표의 내용은 「1학년 85명, 2학년 70명, 3학년 60명, 4학년 90명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?',ARRAY['M4-1-u5-X02']::text[],true,'{"seq":3,"concept":"M4-1-u5-C5","difficulty":3,"kind":"mc","stem":"표의 내용은 「1학년 85명, 2학년 70명, 3학년 60명, 4학년 90명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"2학년","correct":true},{"t":"1학년","mis":"M4-1-u5-X02"},{"t":"3학년","mis":"M4-1-u5-X02"},{"t":"4학년","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 5명이에요.","막대마다 표의 수와 견주어 봐요.","2학년의 막대는 75명인데 표에서는 70명이에요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["1학년","2학년","3학년","4학년"],"series":[{"vals":[85,75,60,90]}],"step":5,"ymax":95,"ylab":"(명)","title":"학년별 우유 신청 학생 수"},"variant_rule":{"alt":[{"stem":"표의 내용은 「1모둠 6개, 2모둠 30개, 3모둠 22개, 4모둠 14개」예요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"3모둠","correct":true},{"t":"1모둠","mis":"M4-1-u5-X02"},{"t":"2모둠","mis":"M4-1-u5-X02"},{"t":"4모둠","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 2개예요.","막대마다 표의 수와 견주어 봐요.","3모둠의 막대는 24개인데 표에서는 22개예요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"vals":[6,30,24,14]}],"step":2,"ymax":32,"ylab":"(개)","title":"모둠별 모은 빈 병 수"}},{"stem":"표의 내용은 「가 지역 125점, 나 지역 25점, 다 지역 100점, 라 지역 75점」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"가 지역","correct":true},{"t":"나 지역","mis":"M4-1-u5-X02"},{"t":"다 지역","mis":"M4-1-u5-X02"},{"t":"라 지역","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 25점이에요.","막대마다 표의 수와 견주어 봐요.","가 지역의 막대는 150점인데 표에서는 125점이에요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 지역","나 지역","다 지역","라 지역"],"series":[{"vals":[150,25,100,75]}],"step":25,"ymax":175,"ylab":"(점)","title":"지역별 문화유산 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_challenge#4','math',4,1,'u5','L03','g4_1_math_u5_L03_challenge','lesson_challenge','M4-1-u5-C4',3,'error','auto','모둠 친구들이 막대그래프를 함께 그리며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u5-X03','M4-1-u5-X21']::text[],true,'{"seq":4,"concept":"M4-1-u5-C4","difficulty":3,"kind":"error","stem":"모둠 친구들이 막대그래프를 함께 그리며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「많은 항목은 막대를 더 굵게 그리자.」","correct":true,"mis_target":"M4-1-u5-X03"},{"t":"하랑 — 「가로에는 항목, 세로에는 수를 놓자.」","mis":"M4-1-u5-X21"},{"t":"지아 — 「막대의 굵기는 모두 같게 하자.」","mis":"M4-1-u5-X21"},{"t":"준서 — 「제목은 마지막에 써도 괜찮아.」","mis":"M4-1-u5-X21"}],"explanation":["막대그래프는 정한 차례대로 그려요.","은우의 말은 그리는 방법과 맞지 않아요.","막대는 수 ÷ 한 칸만큼, 굵기는 같게, 눈금은 가장 큰 수까지예요."],"variant_rule":{"alt":[{"stem":"모둠 친구들이 막대그래프를 함께 그리며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「눈금 한 칸이 5명이면 15명은 15칸이야.」","correct":true,"mis_target":"M4-1-u5-X08"},{"t":"지아 — 「막대의 굵기는 모두 같게 하자.」","mis":"M4-1-u5-X21"},{"t":"준서 — 「제목은 마지막에 써도 괜찮아.」","mis":"M4-1-u5-X21"},{"t":"민서 — 「눈금은 가장 큰 수까지 그리자.」","mis":"M4-1-u5-X21"}],"explanation":["막대그래프는 정한 차례대로 그려요.","하랑의 말은 그리는 방법과 맞지 않아요.","막대는 수 ÷ 한 칸만큼, 굵기는 같게, 눈금은 가장 큰 수까지예요."],"asset":null},{"stem":"모둠 친구들이 막대그래프를 함께 그리며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「가장 큰 수가 12인데 눈금은 10까지면 돼.」","correct":true,"mis_target":"M4-1-u5-X05"},{"t":"준서 — 「제목은 마지막에 써도 괜찮아.」","mis":"M4-1-u5-X21"},{"t":"민서 — 「눈금은 가장 큰 수까지 그리자.」","mis":"M4-1-u5-X21"},{"t":"도윤 — 「가로에는 항목, 세로에는 수를 놓자.」","mis":"M4-1-u5-X21"}],"explanation":["막대그래프는 정한 차례대로 그려요.","지아의 말은 그리는 방법과 맞지 않아요.","막대는 수 ÷ 한 칸만큼, 굵기는 같게, 눈금은 가장 큰 수까지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_challenge#5','math',4,1,'u5','L03','g4_1_math_u5_L03_challenge','lesson_challenge','M4-1-u5-C5',3,'sa','auto','표에서 나 마을의 나무는 15그루예요. 아래 막대그래프에 나 마을의 막대만 아직 그리지 못했어요. 몇 칸으로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u5-C5","difficulty":3,"kind":"sa","stem":"표에서 나 마을의 나무는 15그루예요. 아래 막대그래프에 나 마을의 막대만 아직 그리지 못했어요. 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["세로 눈금 한 칸은 5그루예요.","막대의 칸 수는 15 ÷ 5로 구해요.","15 ÷ 5 = 3 — 3칸으로 그려요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을","마 마을"],"series":[{"vals":[75,15,65,40,25]}],"step":5,"ymax":80,"ylab":"(그루)","title":"마을별 나무 수","hide":[[0,1]]},"variant_rule":{"alt":[{"stem":"표에서 5학년 우유 신청 학생은 55명이에요. 아래 막대그래프에 5학년의 막대만 아직 그리지 못했어요. 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["11"],"explanation":["세로 눈금 한 칸은 5명이에요.","막대의 칸 수는 55 ÷ 5로 구해요.","55 ÷ 5 = 11 — 11칸으로 그려요."],"asset":{"type":"lgraph","mode":"bar","xs":["1학년","2학년","3학년","4학년","5학년","6학년"],"series":[{"vals":[90,65,70,75,55,80]}],"step":5,"ymax":95,"ylab":"(명)","title":"학년별 우유 신청 학생 수","hide":[[0,4]]}},{"stem":"표에서 3모둠이 모은 빈 병은 20개예요. 아래 막대그래프에 3모둠의 막대만 아직 그리지 못했어요. 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["10"],"explanation":["세로 눈금 한 칸은 2개예요.","막대의 칸 수는 20 ÷ 2로 구해요.","20 ÷ 2 = 10 — 10칸으로 그려요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠","5모둠"],"series":[{"vals":[24,22,20,14,30]}],"step":2,"ymax":32,"ylab":"(개)","title":"모둠별 모은 빈 병 수","hide":[[0,2]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_challenge#6','math',4,1,'u5','L03','g4_1_math_u5_L03_challenge','lesson_challenge','M4-1-u5-C5',3,'ox','auto','세로 눈금은 표에서 가장 작은 수까지만 나타내면 돼요.',ARRAY['M4-1-u5-X05']::text[],true,'{"seq":6,"concept":"M4-1-u5-C5","difficulty":3,"kind":"ox","stem":"세로 눈금은 표에서 가장 작은 수까지만 나타내면 돼요.","answer":"X","reason_options":[{"t":"가장 큰 수까지 나타내야 모든 막대를 그릴 수 있어서","correct":true},{"t":"작은 수만 있으면 충분해서","mis":"M4-1-u5-X05"}],"mis":"M4-1-u5-X05","explanation":["그리는 차례 — 제목, 가로와 세로, 단위, 눈금 한 칸의 크기, 막대.","막대는 수량 ÷ 한 칸만큼, 굵기는 모두 같게 그려요.","세로 눈금은 가장 큰 수까지 담을 수 있어야 해요."],"variant_rule":{"alt":[{"stem":"눈금 한 칸이 2명일 때 10명은 10칸으로 그려요.","answer":"X","reason_options":[{"t":"10 ÷ 2 = 5이므로 5칸으로 그려야 해서","correct":true},{"t":"수와 칸 수는 언제나 같아서","mis":"M4-1-u5-X08"}],"explanation":["그리는 차례 — 제목, 가로와 세로, 단위, 눈금 한 칸의 크기, 막대.","막대는 수량 ÷ 한 칸만큼, 굵기는 모두 같게 그려요.","세로 눈금은 가장 큰 수까지 담을 수 있어야 해요."],"asset":null},{"stem":"학생 수가 적은 항목은 막대그래프에서 빼고 그려도 돼요.","answer":"X","reason_options":[{"t":"조사한 항목은 모두 빠짐없이 나타내야 해서","correct":true},{"t":"적은 수는 중요하지 않아서","mis":"M4-1-u5-X05"}],"explanation":["그리는 차례 — 제목, 가로와 세로, 단위, 눈금 한 칸의 크기, 막대.","막대는 수량 ÷ 한 칸만큼, 굵기는 모두 같게 그려요.","세로 눈금은 가장 큰 수까지 담을 수 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_challenge#7','math',4,1,'u5','L03','g4_1_math_u5_L03_challenge','lesson_challenge','M4-1-u5-C4',3,'mc','auto','막대그래프를 그릴 때 꼭 해야 하는 일이 아닌 것은 어느 것인가요?',ARRAY['M4-1-u5-X21']::text[],true,'{"seq":7,"concept":"M4-1-u5-C4","difficulty":3,"kind":"mc","stem":"막대그래프를 그릴 때 꼭 해야 하는 일이 아닌 것은 어느 것인가요?","options":[{"t":"수가 적은 막대는 빼고 그리기","correct":true},{"t":"세로 눈금의 단위를 정하기","mis":"M4-1-u5-X21"},{"t":"가로와 세로에 무엇을 나타낼지 정하기","mis":"M4-1-u5-X21"},{"t":"눈금 한 칸의 크기를 정하기","mis":"M4-1-u5-X21"}],"explanation":["막대그래프는 가로·세로, 단위, 눈금 한 칸을 정하고 수량만큼 막대를 그려요.","「수가 적은 막대는 빼고 그리기」는 꼭 해야 하는 일이 아니에요.","막대의 굵기는 모두 같게, 모든 항목을 빠짐없이 그려요."],"variant_rule":{"alt":[{"stem":"막대그래프를 그릴 때 꼭 해야 하는 일이 아닌 것은 어느 것인가요?","options":[{"t":"막대마다 굵기를 다르게 하기","correct":true},{"t":"가로와 세로에 무엇을 나타낼지 정하기","mis":"M4-1-u5-X21"},{"t":"눈금 한 칸의 크기를 정하기","mis":"M4-1-u5-X21"},{"t":"수량에 맞게 막대의 길이를 정하기","mis":"M4-1-u5-X21"}],"explanation":["막대그래프는 가로·세로, 단위, 눈금 한 칸을 정하고 수량만큼 막대를 그려요.","「막대마다 굵기를 다르게 하기」는 꼭 해야 하는 일이 아니에요.","막대의 굵기는 모두 같게, 모든 항목을 빠짐없이 그려요."],"asset":null},{"stem":"막대그래프를 그릴 때 꼭 해야 하는 일이 아닌 것은 어느 것인가요?","options":[{"t":"수가 가장 많은 막대만 색칠하기","correct":true},{"t":"눈금 한 칸의 크기를 정하기","mis":"M4-1-u5-X21"},{"t":"수량에 맞게 막대의 길이를 정하기","mis":"M4-1-u5-X21"},{"t":"세로 눈금의 단위를 정하기","mis":"M4-1-u5-X21"}],"explanation":["막대그래프는 가로·세로, 단위, 눈금 한 칸을 정하고 수량만큼 막대를 그려요.","「수가 가장 많은 막대만 색칠하기」는 꼭 해야 하는 일이 아니에요.","막대의 굵기는 모두 같게, 모든 항목을 빠짐없이 그려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_challenge#8','math',4,1,'u5','L03','g4_1_math_u5_L03_challenge','lesson_challenge','M4-1-u5-C5',4,'sa','auto','「반별 빌린 책 수」를 조사했더니 모두 600권이었어요. 표에서 5반의 수가 지워졌어요. 세로 눈금 한 칸이 10권인 막대그래프로 나타낼 때, 5반의 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u5-C5","difficulty":4,"kind":"sa","stem":"「반별 빌린 책 수」를 조사했더니 모두 600권이었어요. 표에서 5반의 수가 지워졌어요. 세로 눈금 한 칸이 10권인 막대그래프로 나타낼 때, 5반의 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["15"],"explanation":["5반의 수는 600 − (100 + 70 + 30 + 130 + 120) = 150.","막대의 칸 수는 150 ÷ 10으로 구해요.","150 ÷ 10 = 15 — 15칸이에요."],"asset":{"type":"picg","only":"table","head":"반","cols":["1반","2반","3반","4반","5반","6반"],"counts":[100,70,30,130,null,120],"vh":"빌린 책 수","unit":"권","total":600,"title":"반별 빌린 책 수"},"variant_rule":{"alt":[{"stem":"「농장별 토마토 생산량」을 조사했더니 모두 1220 kg이었어요. 표에서 숲 농장의 수가 지워졌어요. 세로 눈금 한 칸이 20 kg인 막대그래프로 나타낼 때, 숲 농장의 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["14"],"explanation":["숲 농장의 수는 1220 − (300 + 140 + 240 + 260) = 280.","막대의 칸 수는 280 ÷ 20으로 구해요.","280 ÷ 20 = 14 — 14칸이에요."],"asset":{"type":"picg","only":"table","head":"농장","cols":["해 농장","달 농장","별 농장","숲 농장","강 농장"],"counts":[300,140,240,null,260],"vh":"토마토 생산량","unit":"kg","total":1220,"title":"농장별 토마토 생산량"}},{"stem":"「마을별 나무 수」를 조사했더니 모두 210그루였어요. 표에서 마 마을의 수가 지워졌어요. 세로 눈금 한 칸이 5그루인 막대그래프로 나타낼 때, 마 마을의 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["마 마을의 수는 210 − (25 + 60 + 15 + 80) = 30.","막대의 칸 수는 30 ÷ 5로 구해요.","30 ÷ 5 = 6 — 6칸이에요."],"asset":{"type":"picg","only":"table","head":"마을","cols":["가 마을","나 마을","다 마을","라 마을","마 마을"],"counts":[25,60,15,80,null],"vh":"나무 수","unit":"그루","total":210,"title":"마을별 나무 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_challenge#9','math',4,1,'u5','L03','g4_1_math_u5_L03_challenge','lesson_challenge','M4-1-u5-C5',4,'sa','auto','가장 큰 수가 23명인 자료를 세로 눈금 한 칸이 2명인 막대그래프로 나타내려고 해요. 0부터 세로 눈금은 적어도 몇 칸이 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u5-C5","difficulty":4,"kind":"sa","stem":"가장 큰 수가 23명인 자료를 세로 눈금 한 칸이 2명인 막대그래프로 나타내려고 해요. 0부터 세로 눈금은 적어도 몇 칸이 있어야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["세로 눈금은 가장 큰 수 23명까지 담아야 해요.","11칸이면 22, 12칸이면 24까지 나타낼 수 있어요.","그래서 적어도 12칸이 있어야 해요."],"variant_rule":{"alt":[{"stem":"가장 큰 수가 72그루인 자료를 세로 눈금 한 칸이 5그루인 막대그래프로 나타내려고 해요. 0부터 세로 눈금은 적어도 몇 칸이 있어야 하나요? 숫자로 쓰세요.","answer":["15"],"explanation":["세로 눈금은 가장 큰 수 72그루까지 담아야 해요.","14칸이면 70, 15칸이면 75까지 나타낼 수 있어요.","그래서 적어도 15칸이 있어야 해요."],"asset":null},{"stem":"가장 큰 수가 154권인 자료를 세로 눈금 한 칸이 10권인 막대그래프로 나타내려고 해요. 0부터 세로 눈금은 적어도 몇 칸이 있어야 하나요? 숫자로 쓰세요.","answer":["16"],"explanation":["세로 눈금은 가장 큰 수 154권까지 담아야 해요.","15칸이면 150, 16칸이면 160까지 나타낼 수 있어요.","그래서 적어도 16칸이 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L03_challenge#10','math',4,1,'u5','L03','g4_1_math_u5_L03_challenge','lesson_challenge','M4-1-u5-C4',4,'essay','teacher','「좋아하는 계절별 학생 수」가 봄 9명, 여름 6명, 가을 12명, 겨울 4명이에요. 이 표를 세로 눈금 한 칸이 1명인 막대그래프로 나타내는 차례를 쓰고, 세로 눈금은 적어도 몇 명까지 있어야 하는지와 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-1-u5-C4","difficulty":4,"kind":"essay","stem":"「좋아하는 계절별 학생 수」가 봄 9명, 여름 6명, 가을 12명, 겨울 4명이에요. 이 표를 세로 눈금 한 칸이 1명인 막대그래프로 나타내는 차례를 쓰고, 세로 눈금은 적어도 몇 명까지 있어야 하는지와 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 제목을 쓰고, 가로에는 계절, 세로에는 학생 수를 나타내기로 정하고, 단위를 명으로 정한 뒤, 눈금 한 칸을 1명으로 정하고 계절마다 학생 수만큼 막대를 같은 굵기로 그린다. 가장 큰 수가 가을의 12명이므로 세로 눈금은 적어도 12명까지 있어야 한다. 그보다 짧으면 가을의 막대를 다 그릴 수 없다.","scoring_points":["제목·가로와 세로·단위·눈금·막대의 차례를 썼는가","세로 눈금이 적어도 12명까지라고 썼는가","가장 큰 수를 담아야 하는 까닭을 썼는가"]},"explanation":["그리는 차례 — 제목, 가로와 세로, 단위, 눈금 한 칸, 막대.","가장 큰 수는 가을 12명이에요.","세로 눈금이 12명보다 짧으면 가을의 막대가 잘려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_basic#1','math',4,1,'u5','L04','g4_1_math_u5_L04_basic','lesson_basic','M4-1-u5-C6',1,'mc','auto','눈금 한 칸의 크기를 바꾸면 무엇이 달라지나요?',ARRAY['M4-1-u5-X06']::text[],true,'{"seq":1,"concept":"M4-1-u5-C6","difficulty":1,"kind":"mc","stem":"눈금 한 칸의 크기를 바꾸면 무엇이 달라지나요?","options":[{"t":"막대의 칸 수는 달라지지만 나타내는 수는 그대로예요.","correct":true},{"t":"막대가 나타내는 수가 달라져요.","mis":"M4-1-u5-X06"},{"t":"항목의 개수가 달라져요.","mis":"M4-1-u5-X06"},{"t":"아무것도 달라지지 않아요.","mis":"M4-1-u5-X06"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"variant_rule":{"alt":[{"stem":"같은 자료에서 눈금 한 칸을 크게 하면 막대는 어떻게 되나요?","options":[{"t":"막대가 짧아져요.","correct":true},{"t":"막대가 길어져요.","mis":"M4-1-u5-X21"},{"t":"막대가 나타내는 수가 커져요.","mis":"M4-1-u5-X06"},{"t":"막대가 굵어져요.","mis":"M4-1-u5-X03"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"asset":null},{"stem":"같은 자료에서 눈금 한 칸을 작게 하면 막대는 어떻게 되나요?","options":[{"t":"막대가 길어져요.","correct":true},{"t":"막대가 짧아져요.","mis":"M4-1-u5-X21"},{"t":"막대가 나타내는 수가 작아져요.","mis":"M4-1-u5-X06"},{"t":"항목의 개수가 늘어나요.","mis":"M4-1-u5-X06"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_basic#2','math',4,1,'u5','L04','g4_1_math_u5_L04_basic','lesson_basic','M4-1-u5-C6',1,'sa','auto','눈금 한 칸이 1명인 막대그래프에서 10칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 2명인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u5-C6","difficulty":1,"kind":"sa","stem":"눈금 한 칸이 1명인 막대그래프에서 10칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 2명인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["5"],"explanation":["먼저 막대가 나타내는 수를 구해요: 10 × 1 = 10.","나타내는 수 10명은 눈금이 바뀌어도 그대로예요.","10 ÷ 2 = 5 — 5칸이 돼요."],"variant_rule":{"alt":[{"stem":"눈금 한 칸이 1명인 막대그래프에서 12칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 2명인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["6"],"explanation":["먼저 막대가 나타내는 수를 구해요: 12 × 1 = 12.","나타내는 수 12명은 눈금이 바뀌어도 그대로예요.","12 ÷ 2 = 6 — 6칸이 돼요."],"asset":null},{"stem":"눈금 한 칸이 5그루인 막대그래프에서 12칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 10그루인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["6"],"explanation":["먼저 막대가 나타내는 수를 구해요: 12 × 5 = 60.","나타내는 수 60그루는 눈금이 바뀌어도 그대로예요.","60 ÷ 10 = 6 — 6칸이 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_basic#3','math',4,1,'u5','L04','g4_1_math_u5_L04_basic','lesson_basic','M4-1-u5-C6',1,'sa','auto','표를 보고 눈금 한 칸을 20 kg으로 막대그래프를 그리려고 해요. 별 농장의 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u5-C6","difficulty":1,"kind":"sa","stem":"표를 보고 눈금 한 칸을 20 kg으로 막대그래프를 그리려고 해요. 별 농장의 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["별 농장의 토마토 생산량은 180 kg이에요.","한 칸이 20 kg이니 칸 수는 180 ÷ 20으로 구해요.","180 ÷ 20 = 9 — 9칸이에요."],"asset":{"type":"picg","only":"table","head":"농장","cols":["해 농장","달 농장","별 농장","숲 농장","강 농장"],"counts":[220,160,180,300,100],"vh":"토마토 생산량","unit":"kg","title":"농장별 토마토 생산량"},"variant_rule":{"alt":[{"stem":"표를 보고 눈금 한 칸을 5그루로 막대그래프를 그리려고 해요. 라 마을의 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["10"],"explanation":["라 마을의 나무는 50그루예요.","한 칸이 5그루이니 칸 수는 50 ÷ 5로 구해요.","50 ÷ 5 = 10 — 10칸이에요."],"asset":{"type":"picg","only":"table","head":"마을","cols":["가 마을","나 마을","다 마을","라 마을","마 마을"],"counts":[25,45,15,50,55],"vh":"나무 수","unit":"그루","title":"마을별 나무 수"}},{"stem":"표를 보고 눈금 한 칸을 5명으로 막대그래프를 그리려고 해요. 2학년의 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["2학년 우유 신청 학생은 20명이에요.","한 칸이 5명이니 칸 수는 20 ÷ 5로 구해요.","20 ÷ 5 = 4 — 4칸이에요."],"asset":{"type":"picg","only":"table","head":"학년","cols":["1학년","2학년","3학년","4학년","5학년","6학년"],"counts":[80,20,40,75,55,30],"vh":"학생 수","unit":"명","title":"학년별 우유 신청 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_basic#4','math',4,1,'u5','L04','g4_1_math_u5_L04_basic','lesson_basic','M4-1-u5-C6',1,'ox','auto','눈금 한 칸의 크기를 바꾸면 막대가 나타내는 수도 바뀌어요.',ARRAY['M4-1-u5-X06']::text[],true,'{"seq":4,"concept":"M4-1-u5-C6","difficulty":1,"kind":"ox","stem":"눈금 한 칸의 크기를 바꾸면 막대가 나타내는 수도 바뀌어요.","answer":"X","reason_options":[{"t":"칸 수만 달라지고 나타내는 수는 그대로라서","correct":true},{"t":"막대의 길이가 달라지니 수도 달라져서","mis":"M4-1-u5-X06"}],"mis":"M4-1-u5-X06","explanation":["눈금 한 칸을 바꾸면 막대의 칸 수만 달라져요.","나타내는 수는 그대로예요.","가장 큰 수를 담으면서 차이가 잘 보이게 한 칸을 정해요."],"variant_rule":{"alt":[{"stem":"같은 자료에서 눈금 한 칸을 2배로 하면 막대의 칸 수는 절반이 돼요.","answer":"O","reason_options":[{"t":"같은 수를 2배 큰 칸으로 나누니 칸 수가 절반이 되어서","correct":true},{"t":"칸 수도 2배가 되어서","mis":"M4-1-u5-X08"}],"explanation":["눈금 한 칸을 바꾸면 막대의 칸 수만 달라져요.","나타내는 수는 그대로예요.","가장 큰 수를 담으면서 차이가 잘 보이게 한 칸을 정해요."],"asset":null},{"stem":"눈금 한 칸은 언제나 될 수 있는 대로 작게 정하는 것이 좋아요.","answer":"X","reason_options":[{"t":"너무 작으면 칸이 넘쳐 다 그릴 수 없어서","correct":true},{"t":"작을수록 언제나 보기 좋아서","mis":"M4-1-u5-X07"}],"explanation":["눈금 한 칸을 바꾸면 막대의 칸 수만 달라져요.","나타내는 수는 그대로예요.","가장 큰 수를 담으면서 차이가 잘 보이게 한 칸을 정해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_basic#5','math',4,1,'u5','L04','g4_1_math_u5_L04_basic','lesson_basic','M4-1-u5-C6',2,'sa','auto','같은 자료를 가 그래프는 눈금 한 칸을 1명으로, 나 그래프는 2명으로 그렸어요. 가 그래프에서 어떤 막대가 8칸이라면, 나 그래프에서 이 막대가 나타내는 수는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u5-C6","difficulty":2,"kind":"sa","stem":"같은 자료를 가 그래프는 눈금 한 칸을 1명으로, 나 그래프는 2명으로 그렸어요. 가 그래프에서 어떤 막대가 8칸이라면, 나 그래프에서 이 막대가 나타내는 수는 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["가 그래프에서 이 막대는 8 × 1 = 8명이에요.","눈금 한 칸이 달라져도 막대가 나타내는 수는 그대로예요.","그래서 나 그래프에서도 8명이에요 — 칸 수만 4칸으로 달라져요."],"variant_rule":{"alt":[{"stem":"같은 자료를 가 그래프는 눈금 한 칸을 2명으로, 나 그래프는 1명으로 그렸어요. 가 그래프에서 어떤 막대가 6칸이라면, 나 그래프에서 이 막대가 나타내는 수는 몇 명인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["가 그래프에서 이 막대는 6 × 2 = 12명이에요.","눈금 한 칸이 달라져도 막대가 나타내는 수는 그대로예요.","그래서 나 그래프에서도 12명이에요 — 칸 수만 12칸으로 달라져요."],"asset":null},{"stem":"같은 자료를 가 그래프는 눈금 한 칸을 5그루로, 나 그래프는 10그루로 그렸어요. 가 그래프에서 어떤 막대가 9칸이라면, 나 그래프에서 이 막대가 나타내는 수는 몇 그루인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["가 그래프에서 이 막대는 9 × 5 = 45그루예요.","눈금 한 칸이 달라져도 막대가 나타내는 수는 그대로예요.","그래서 나 그래프에서도 45그루예요 — 칸 수만 4칸으로 달라져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_basic#6','math',4,1,'u5','L04','g4_1_math_u5_L04_basic','lesson_basic','M4-1-u5-C6',2,'mc','auto','표에서 가장 큰 수는 160권이에요. 눈금 한 칸의 크기로 가장 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X07']::text[],true,'{"seq":6,"concept":"M4-1-u5-C6","difficulty":2,"kind":"mc","stem":"표에서 가장 큰 수는 160권이에요. 눈금 한 칸의 크기로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"10권 — 16칸이면 다 들어가고 차이도 잘 보여요.","correct":true},{"t":"1권 — 칸을 160개나 그려야 해요.","mis":"M4-1-u5-X07"},{"t":"200권 — 모두 한 칸 안에 들어가요.","mis":"M4-1-u5-X07"},{"t":"눈금은 아무렇게나 정해도 괜찮아요.","mis":"M4-1-u5-X07"}],"explanation":["한 칸이 너무 작으면 칸이 너무 많아 다 그릴 수 없어요.","한 칸이 너무 크면 막대들이 다 비슷해 보여요.","10권 한 칸으로 하면 16칸에 다 들어가고 차이도 잘 보여요."],"asset":{"type":"picg","only":"table","head":"반","cols":["1반","2반","3반","4반","5반","6반"],"counts":[160,130,120,140,90,50],"vh":"빌린 책 수","unit":"권","title":"반별 빌린 책 수"},"variant_rule":{"alt":[{"stem":"표에서 가장 큰 수는 300 kg이에요. 눈금 한 칸의 크기로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"20 kg — 15칸이면 다 들어가고 차이도 잘 보여요.","correct":true},{"t":"1 kg — 칸을 300개나 그려야 해요.","mis":"M4-1-u5-X07"},{"t":"400 kg — 모두 한 칸 안에 들어가요.","mis":"M4-1-u5-X07"},{"t":"눈금은 아무렇게나 정해도 괜찮아요.","mis":"M4-1-u5-X07"}],"explanation":["한 칸이 너무 작으면 칸이 너무 많아 다 그릴 수 없어요.","한 칸이 너무 크면 막대들이 다 비슷해 보여요.","20 kg 한 칸으로 하면 15칸에 다 들어가고 차이도 잘 보여요."],"asset":{"type":"picg","only":"table","head":"농장","cols":["해 농장","달 농장","별 농장","숲 농장","강 농장"],"counts":[120,300,280,140,180],"vh":"토마토 생산량","unit":"kg","title":"농장별 토마토 생산량"}},{"stem":"표에서 가장 큰 수는 70그루예요. 눈금 한 칸의 크기로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"5그루 — 14칸이면 다 들어가고 차이도 잘 보여요.","correct":true},{"t":"1그루 — 칸을 70개나 그려야 해요.","mis":"M4-1-u5-X07"},{"t":"500그루 — 모두 한 칸 안에 들어가요.","mis":"M4-1-u5-X07"},{"t":"눈금은 아무렇게나 정해도 괜찮아요.","mis":"M4-1-u5-X07"}],"explanation":["한 칸이 너무 작으면 칸이 너무 많아 다 그릴 수 없어요.","한 칸이 너무 크면 막대들이 다 비슷해 보여요.","5그루 한 칸으로 하면 14칸에 다 들어가고 차이도 잘 보여요."],"asset":{"type":"picg","only":"table","head":"마을","cols":["가 마을","나 마을","다 마을","라 마을","마 마을"],"counts":[70,55,30,40,50],"vh":"나무 수","unit":"그루","title":"마을별 나무 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_basic#7','math',4,1,'u5','L04','g4_1_math_u5_L04_basic','lesson_basic','M4-1-u5-C6',2,'mc','auto','눈금 한 칸의 크기를 고르는 기준으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X07']::text[],true,'{"seq":7,"concept":"M4-1-u5-C6","difficulty":2,"kind":"mc","stem":"눈금 한 칸의 크기를 고르는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"가장 큰 수를 담으면서 차이가 잘 드러나게 해요.","correct":true},{"t":"언제나 한 칸을 1로 해요.","mis":"M4-1-u5-X07"},{"t":"한 칸을 될 수 있는 대로 크게 해요.","mis":"M4-1-u5-X07"},{"t":"아무렇게나 정해도 돼요.","mis":"M4-1-u5-X07"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"variant_rule":{"alt":[{"stem":"눈금 한 칸을 너무 크게 정하면 어떤 점이 불편한가요?","options":[{"t":"막대들이 다 비슷해 보여서 차이를 알아보기 어려워요.","correct":true},{"t":"가장 큰 수가 그래프 밖으로 넘쳐요.","mis":"M4-1-u5-X21"},{"t":"항목을 모두 쓸 수 없어요.","mis":"M4-1-u5-X07"},{"t":"제목을 쓸 자리가 없어져요.","mis":"M4-1-u5-X07"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"asset":null},{"stem":"가장 큰 수가 126인 자료를 눈금 한 칸 1로 그리면 어떤 점이 불편한가요?","options":[{"t":"칸을 126개나 그려야 해서 종이에 다 들어가지 않아요.","correct":true},{"t":"막대들이 다 비슷해 보여요.","mis":"M4-1-u5-X21"},{"t":"막대가 나타내는 수가 달라져요.","mis":"M4-1-u5-X06"},{"t":"불편한 점이 없어요.","mis":"M4-1-u5-X07"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_basic#8','math',4,1,'u5','L04','g4_1_math_u5_L04_basic','lesson_basic','M4-1-u5-C6',2,'sa','auto','눈금 한 칸이 10권인 막대그래프에서 12칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 20권인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u5-C6","difficulty":2,"kind":"sa","stem":"눈금 한 칸이 10권인 막대그래프에서 12칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 20권인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["6"],"explanation":["먼저 막대가 나타내는 수를 구해요: 12 × 10 = 120.","나타내는 수 120권은 눈금이 바뀌어도 그대로예요.","120 ÷ 20 = 6 — 6칸이 돼요."],"variant_rule":{"alt":[{"stem":"눈금 한 칸이 20 kg인 막대그래프에서 10칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 40 kg인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["5"],"explanation":["먼저 막대가 나타내는 수를 구해요: 10 × 20 = 200.","나타내는 수 200 kg은 눈금이 바뀌어도 그대로예요.","200 ÷ 40 = 5 — 5칸이 돼요."],"asset":null},{"stem":"눈금 한 칸이 25점인 막대그래프에서 6칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 50점인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 막대가 나타내는 수를 구해요: 6 × 25 = 150.","나타내는 수 150점은 눈금이 바뀌어도 그대로예요.","150 ÷ 50 = 3 — 3칸이 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_basic#9','math',4,1,'u5','L04','g4_1_math_u5_L04_basic','lesson_basic','M4-1-u5-C6',2,'sa','auto','세로 눈금 한 칸이 25점인 막대그래프예요. 다 지역의 문화유산은 몇 점인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u5-C6","difficulty":2,"kind":"sa","stem":"세로 눈금 한 칸이 25점인 막대그래프예요. 다 지역의 문화유산은 몇 점인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["세로 눈금 한 칸은 25점이에요.","다 지역의 막대는 0에서 1칸이에요.","1 × 25 = 25 — 25점이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 지역","나 지역","다 지역","라 지역","마 지역"],"series":[{"vals":[175,50,25,150,75]}],"step":25,"ymax":200,"ylab":"(점)","title":"지역별 문화유산 수"},"variant_rule":{"alt":[{"stem":"세로 눈금 한 칸이 10권인 막대그래프예요. 4반이 빌린 책은 몇 권인가요? 숫자로 쓰세요.","answer":["140"],"explanation":["세로 눈금 한 칸은 10권이에요.","4반의 막대는 0에서 14칸이에요.","14 × 10 = 140 — 140권이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["1반","2반","3반","4반","5반","6반"],"series":[{"vals":[120,100,40,140,80,110]}],"step":10,"ymax":150,"ylab":"(권)","title":"반별 빌린 책 수"}},{"stem":"세로 눈금 한 칸이 20 kg인 막대그래프예요. 해 농장의 토마토 생산량은 몇 kg인가요? 숫자로 쓰세요.","answer":["280"],"explanation":["세로 눈금 한 칸은 20 kg이에요.","해 농장의 막대는 0에서 14칸이에요.","14 × 20 = 280 — 280 kg이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["해 농장","달 농장","별 농장","숲 농장","강 농장"],"series":[{"vals":[280,80,240,300,140]}],"step":20,"ymax":320,"ylab":"(kg)","title":"농장별 토마토 생산량"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_basic#10','math',4,1,'u5','L04','g4_1_math_u5_L04_basic','lesson_basic','M4-1-u5-C6',3,'mc','auto','「모둠별 모은 빈 병 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 2개로 그렸어요, 나 그래프는 눈금 한 칸을 40개로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X07']::text[],true,'{"seq":10,"concept":"M4-1-u5-C6","difficulty":3,"kind":"mc","stem":"「모둠별 모은 빈 병 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 2개로 그렸어요, 나 그래프는 눈금 한 칸을 40개로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"가 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"나 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 40개면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 2개인 가 그래프가 차이를 알아보기 좋아요."],"variant_rule":{"alt":[{"stem":"「지역별 문화유산 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 250점으로 그렸어요, 나 그래프는 눈금 한 칸을 25점으로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"가 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 250점면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 25점인 나 그래프가 차이를 알아보기 좋아요."],"asset":null},{"stem":"「반별 빌린 책 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 10권으로 그렸어요, 나 그래프는 눈금 한 칸을 200권으로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"가 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"나 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 200권면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 10권인 가 그래프가 차이를 알아보기 좋아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_challenge#1','math',4,1,'u5','L04','g4_1_math_u5_L04_challenge','lesson_challenge','M4-1-u5-C6',2,'ox','auto','가장 큰 수가 크면 눈금 한 칸을 크게 정해야 할 때도 있어요.',ARRAY['M4-1-u5-X07']::text[],true,'{"seq":1,"concept":"M4-1-u5-C6","difficulty":2,"kind":"ox","stem":"가장 큰 수가 크면 눈금 한 칸을 크게 정해야 할 때도 있어요.","answer":"O","reason_options":[{"t":"가장 큰 수를 담을 수 있게 정해야 해서","correct":true},{"t":"눈금 한 칸은 언제나 1이어야 해서","mis":"M4-1-u5-X07"}],"mis":"M4-1-u5-X07","explanation":["눈금 한 칸을 바꾸면 막대의 칸 수만 달라져요.","나타내는 수는 그대로예요.","가장 큰 수를 담으면서 차이가 잘 보이게 한 칸을 정해요."],"variant_rule":{"alt":[{"stem":"눈금 한 칸을 너무 크게 하면 막대들의 차이가 잘 보이지 않아요.","answer":"O","reason_options":[{"t":"막대가 모두 짧아져 비슷해 보여서","correct":true},{"t":"막대가 길어져 다 넘쳐서","mis":"M4-1-u5-X21"}],"explanation":["눈금 한 칸을 바꾸면 막대의 칸 수만 달라져요.","나타내는 수는 그대로예요.","가장 큰 수를 담으면서 차이가 잘 보이게 한 칸을 정해요."],"asset":null},{"stem":"눈금 한 칸이 10인 그래프와 20인 그래프에서 같은 항목의 막대 길이가 다르면 수도 달라요.","answer":"X","reason_options":[{"t":"같은 자료라면 눈금만 달라 칸 수가 달라질 뿐이라서","correct":true},{"t":"막대가 짧은 쪽이 수가 더 적어서","mis":"M4-1-u5-X06"}],"explanation":["눈금 한 칸을 바꾸면 막대의 칸 수만 달라져요.","나타내는 수는 그대로예요.","가장 큰 수를 담으면서 차이가 잘 보이게 한 칸을 정해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_challenge#2','math',4,1,'u5','L04','g4_1_math_u5_L04_challenge','lesson_challenge','M4-1-u5-C6',2,'sa','auto','같은 자료를 가 그래프는 눈금 한 칸을 10권으로, 나 그래프는 20권으로 그렸어요. 가 그래프에서 어떤 막대가 7칸이라면, 나 그래프에서 이 막대가 나타내는 수는 몇 권인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u5-C6","difficulty":2,"kind":"sa","stem":"같은 자료를 가 그래프는 눈금 한 칸을 10권으로, 나 그래프는 20권으로 그렸어요. 가 그래프에서 어떤 막대가 7칸이라면, 나 그래프에서 이 막대가 나타내는 수는 몇 권인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["가 그래프에서 이 막대는 7 × 10 = 70권이에요.","눈금 한 칸이 달라져도 막대가 나타내는 수는 그대로예요.","그래서 나 그래프에서도 70권이에요 — 칸 수만 3칸으로 달라져요."],"variant_rule":{"alt":[{"stem":"같은 자료를 가 그래프는 눈금 한 칸을 20 kg으로, 나 그래프는 10 kg으로 그렸어요. 가 그래프에서 어떤 막대가 6칸이라면, 나 그래프에서 이 막대가 나타내는 수는 몇 kg인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["가 그래프에서 이 막대는 6 × 20 = 120 kg이에요.","눈금 한 칸이 달라져도 막대가 나타내는 수는 그대로예요.","그래서 나 그래프에서도 120 kg이에요 — 칸 수만 12칸으로 달라져요."],"asset":null},{"stem":"같은 자료를 가 그래프는 눈금 한 칸을 25점으로, 나 그래프는 50점으로 그렸어요. 가 그래프에서 어떤 막대가 4칸이라면, 나 그래프에서 이 막대가 나타내는 수는 몇 점인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["가 그래프에서 이 막대는 4 × 25 = 100점이에요.","눈금 한 칸이 달라져도 막대가 나타내는 수는 그대로예요.","그래서 나 그래프에서도 100점이에요 — 칸 수만 2칸으로 달라져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_challenge#3','math',4,1,'u5','L04','g4_1_math_u5_L04_challenge','lesson_challenge','M4-1-u5-C6',3,'mc','auto','표에서 가장 큰 수는 90명이에요. 눈금 한 칸의 크기로 가장 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X07']::text[],true,'{"seq":3,"concept":"M4-1-u5-C6","difficulty":3,"kind":"mc","stem":"표에서 가장 큰 수는 90명이에요. 눈금 한 칸의 크기로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"5명 — 18칸이면 다 들어가고 차이도 잘 보여요.","correct":true},{"t":"1명 — 칸을 90개나 그려야 해요.","mis":"M4-1-u5-X07"},{"t":"1000명 — 모두 한 칸 안에 들어가요.","mis":"M4-1-u5-X07"},{"t":"눈금은 아무렇게나 정해도 괜찮아요.","mis":"M4-1-u5-X07"}],"explanation":["한 칸이 너무 작으면 칸이 너무 많아 다 그릴 수 없어요.","한 칸이 너무 크면 막대들이 다 비슷해 보여요.","5명 한 칸으로 하면 18칸에 다 들어가고 차이도 잘 보여요."],"asset":{"type":"picg","only":"table","head":"학년","cols":["1학년","2학년","3학년","4학년","5학년","6학년"],"counts":[80,65,45,70,40,90],"vh":"학생 수","unit":"명","title":"학년별 우유 신청 학생 수"},"variant_rule":{"alt":[{"stem":"표에서 가장 큰 수는 175점이에요. 눈금 한 칸의 크기로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"25점 — 7칸이면 다 들어가고 차이도 잘 보여요.","correct":true},{"t":"1점 — 칸을 175개나 그려야 해요.","mis":"M4-1-u5-X07"},{"t":"200점 — 모두 한 칸 안에 들어가요.","mis":"M4-1-u5-X07"},{"t":"눈금은 아무렇게나 정해도 괜찮아요.","mis":"M4-1-u5-X07"}],"explanation":["한 칸이 너무 작으면 칸이 너무 많아 다 그릴 수 없어요.","한 칸이 너무 크면 막대들이 다 비슷해 보여요.","25점 한 칸으로 하면 7칸에 다 들어가고 차이도 잘 보여요."],"asset":{"type":"picg","only":"table","head":"지역","cols":["가 지역","나 지역","다 지역","라 지역","마 지역"],"counts":[25,175,50,100,75],"vh":"문화유산 수","unit":"점","title":"지역별 문화유산 수"}},{"stem":"표에서 가장 큰 수는 150권이에요. 눈금 한 칸의 크기로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"10권 — 15칸이면 다 들어가고 차이도 잘 보여요.","correct":true},{"t":"1권 — 칸을 150개나 그려야 해요.","mis":"M4-1-u5-X07"},{"t":"200권 — 모두 한 칸 안에 들어가요.","mis":"M4-1-u5-X07"},{"t":"눈금은 아무렇게나 정해도 괜찮아요.","mis":"M4-1-u5-X07"}],"explanation":["한 칸이 너무 작으면 칸이 너무 많아 다 그릴 수 없어요.","한 칸이 너무 크면 막대들이 다 비슷해 보여요.","10권 한 칸으로 하면 15칸에 다 들어가고 차이도 잘 보여요."],"asset":{"type":"picg","only":"table","head":"반","cols":["1반","2반","3반","4반","5반","6반"],"counts":[70,100,60,150,30,140],"vh":"빌린 책 수","unit":"권","title":"반별 빌린 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_challenge#4','math',4,1,'u5','L04','g4_1_math_u5_L04_challenge','lesson_challenge','M4-1-u5-C6',3,'error','auto','눈금 한 칸의 크기에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u5-X06','M4-1-u5-X21']::text[],true,'{"seq":4,"concept":"M4-1-u5-C6","difficulty":3,"kind":"error","stem":"눈금 한 칸의 크기에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「눈금 한 칸을 2명으로 바꿨더니 10명이 5명이 됐어.」","correct":true,"mis_target":"M4-1-u5-X06"},{"t":"준서 — 「눈금 한 칸이 크면 막대가 짧아져.」","mis":"M4-1-u5-X21"},{"t":"민서 — 「눈금을 바꿔도 수는 그대로야.」","mis":"M4-1-u5-X21"},{"t":"도윤 — 「가장 큰 수가 들어가게 정해야 해.」","mis":"M4-1-u5-X21"}],"explanation":["눈금 한 칸을 바꾸면 막대의 칸 수만 달라져요.","지아의 말은 눈금 한 칸의 뜻과 맞지 않아요.","가장 큰 수를 담고 차이가 보이게 알맞은 크기로 정해요."],"variant_rule":{"alt":[{"stem":"눈금 한 칸의 크기에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「눈금은 아무렇게나 정해도 그래프는 똑같아.」","correct":true,"mis_target":"M4-1-u5-X07"},{"t":"민서 — 「눈금을 바꿔도 수는 그대로야.」","mis":"M4-1-u5-X21"},{"t":"도윤 — 「가장 큰 수가 들어가게 정해야 해.」","mis":"M4-1-u5-X21"},{"t":"서윤 — 「너무 크면 차이가 잘 안 보여.」","mis":"M4-1-u5-X21"}],"explanation":["눈금 한 칸을 바꾸면 막대의 칸 수만 달라져요.","준서의 말은 눈금 한 칸의 뜻과 맞지 않아요.","가장 큰 수를 담고 차이가 보이게 알맞은 크기로 정해요."],"asset":null},{"stem":"눈금 한 칸의 크기에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「한 칸이 10이면 70은 70칸이야.」","correct":true,"mis_target":"M4-1-u5-X08"},{"t":"도윤 — 「가장 큰 수가 들어가게 정해야 해.」","mis":"M4-1-u5-X21"},{"t":"서윤 — 「너무 크면 차이가 잘 안 보여.」","mis":"M4-1-u5-X21"},{"t":"시우 — 「눈금 한 칸이 크면 막대가 짧아져.」","mis":"M4-1-u5-X21"}],"explanation":["눈금 한 칸을 바꾸면 막대의 칸 수만 달라져요.","민서의 말은 눈금 한 칸의 뜻과 맞지 않아요.","가장 큰 수를 담고 차이가 보이게 알맞은 크기로 정해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_challenge#5','math',4,1,'u5','L04','g4_1_math_u5_L04_challenge','lesson_challenge','M4-1-u5-C6',3,'mc','auto','「농장별 토마토 생산량」을 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 320 kg으로 그렸어요, 나 그래프는 눈금 한 칸을 20 kg으로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X07']::text[],true,'{"seq":5,"concept":"M4-1-u5-C6","difficulty":3,"kind":"mc","stem":"「농장별 토마토 생산량」을 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 320 kg으로 그렸어요, 나 그래프는 눈금 한 칸을 20 kg으로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"가 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 320 kg면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 20 kg인 나 그래프가 차이를 알아보기 좋아요."],"variant_rule":{"alt":[{"stem":"「마을별 나무 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 5그루로 그렸어요, 나 그래프는 눈금 한 칸을 120그루로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"가 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"나 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 120그루면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 5그루인 가 그래프가 차이를 알아보기 좋아요."],"asset":null},{"stem":"「학년별 우유 신청 학생 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 100명으로 그렸어요, 나 그래프는 눈금 한 칸을 5명으로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"가 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 100명면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 5명인 나 그래프가 차이를 알아보기 좋아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_challenge#6','math',4,1,'u5','L04','g4_1_math_u5_L04_challenge','lesson_challenge','M4-1-u5-C6',3,'sa','auto','표를 보고 눈금 한 칸을 2개로 막대그래프를 그리려고 해요. 3모둠의 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u5-C6","difficulty":3,"kind":"sa","stem":"표를 보고 눈금 한 칸을 2개로 막대그래프를 그리려고 해요. 3모둠의 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["11"],"explanation":["3모둠이 모은 빈 병은 22개예요.","한 칸이 2개이니 칸 수는 22 ÷ 2로 구해요.","22 ÷ 2 = 11 — 11칸이에요."],"asset":{"type":"picg","only":"table","head":"모둠","cols":["1모둠","2모둠","3모둠","4모둠","5모둠"],"counts":[10,16,22,28,6],"vh":"빈 병 수","unit":"개","title":"모둠별 모은 빈 병 수"},"variant_rule":{"alt":[{"stem":"표를 보고 눈금 한 칸을 25점으로 막대그래프를 그리려고 해요. 나 지역의 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["나 지역의 문화유산은 75점이에요.","한 칸이 25점이니 칸 수는 75 ÷ 25로 구해요.","75 ÷ 25 = 3 — 3칸이에요."],"asset":{"type":"picg","only":"table","head":"지역","cols":["가 지역","나 지역","다 지역","라 지역","마 지역"],"counts":[25,75,150,175,50],"vh":"문화유산 수","unit":"점","title":"지역별 문화유산 수"}},{"stem":"표를 보고 눈금 한 칸을 10권으로 막대그래프를 그리려고 해요. 5반의 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["13"],"explanation":["5반이 빌린 책은 130권이에요.","한 칸이 10권이니 칸 수는 130 ÷ 10으로 구해요.","130 ÷ 10 = 13 — 13칸이에요."],"asset":{"type":"picg","only":"table","head":"반","cols":["1반","2반","3반","4반","5반","6반"],"counts":[120,80,150,30,130,70],"vh":"빌린 책 수","unit":"권","title":"반별 빌린 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_challenge#7','math',4,1,'u5','L04','g4_1_math_u5_L04_challenge','lesson_challenge','M4-1-u5-C6',3,'sa','auto','눈금 한 칸이 2명인 막대그래프에서 20칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 5명인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u5-C6","difficulty":3,"kind":"sa","stem":"눈금 한 칸이 2명인 막대그래프에서 20칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 5명인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["8"],"explanation":["먼저 막대가 나타내는 수를 구해요: 20 × 2 = 40.","나타내는 수 40명은 눈금이 바뀌어도 그대로예요.","40 ÷ 5 = 8 — 8칸이 돼요."],"variant_rule":{"alt":[{"stem":"눈금 한 칸이 10권인 막대그래프에서 9칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 30권인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 막대가 나타내는 수를 구해요: 9 × 10 = 90.","나타내는 수 90권은 눈금이 바뀌어도 그대로예요.","90 ÷ 30 = 3 — 3칸이 돼요."],"asset":null},{"stem":"눈금 한 칸이 1명인 막대그래프에서 10칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 2명인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["5"],"explanation":["먼저 막대가 나타내는 수를 구해요: 10 × 1 = 10.","나타내는 수 10명은 눈금이 바뀌어도 그대로예요.","10 ÷ 2 = 5 — 5칸이 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_challenge#8','math',4,1,'u5','L04','g4_1_math_u5_L04_challenge','lesson_challenge','M4-1-u5-C6',4,'mc','auto','자료가 4명, 14명, 16명, 18명이에요. 모든 막대의 끝이 눈금에 딱 맞으면서 칸 수가 가장 적게 되도록 눈금 한 칸의 크기를 정하면 얼마인가요?',ARRAY['M4-1-u5-X07']::text[],true,'{"seq":8,"concept":"M4-1-u5-C6","difficulty":4,"kind":"mc","stem":"자료가 4명, 14명, 16명, 18명이에요. 모든 막대의 끝이 눈금에 딱 맞으면서 칸 수가 가장 적게 되도록 눈금 한 칸의 크기를 정하면 얼마인가요?","options":[{"t":"2명","correct":true},{"t":"5명","mis":"M4-1-u5-X07"},{"t":"10명","mis":"M4-1-u5-X07"},{"t":"1명","mis":"M4-1-u5-X07"}],"explanation":["수가 모두 2의 배수인지 살펴봐요.","2보다 큰 칸으로 하면 막대 끝이 눈금 사이에 오는 수가 생기고, 더 작은 칸으로 하면 칸이 많아져요.","그래서 눈금 한 칸은 2명로 해요."],"variant_rule":{"alt":[{"stem":"자료가 35그루, 40그루, 45그루, 50그루예요. 모든 막대의 끝이 눈금에 딱 맞으면서 칸 수가 가장 적게 되도록 눈금 한 칸의 크기를 정하면 얼마인가요?","options":[{"t":"5그루","correct":true},{"t":"10그루","mis":"M4-1-u5-X07"},{"t":"20그루","mis":"M4-1-u5-X07"},{"t":"1그루","mis":"M4-1-u5-X07"}],"explanation":["수가 모두 5의 배수인지 살펴봐요.","5보다 큰 칸으로 하면 막대 끝이 눈금 사이에 오는 수가 생기고, 더 작은 칸으로 하면 칸이 많아져요.","그래서 눈금 한 칸은 5그루로 해요."],"asset":null},{"stem":"자료가 50권, 60권, 80권, 90권이에요. 모든 막대의 끝이 눈금에 딱 맞으면서 칸 수가 가장 적게 되도록 눈금 한 칸의 크기를 정하면 얼마인가요?","options":[{"t":"10권","correct":true},{"t":"20권","mis":"M4-1-u5-X07"},{"t":"25권","mis":"M4-1-u5-X07"},{"t":"2권","mis":"M4-1-u5-X07"}],"explanation":["수가 모두 10의 배수인지 살펴봐요.","10보다 큰 칸으로 하면 막대 끝이 눈금 사이에 오는 수가 생기고, 더 작은 칸으로 하면 칸이 많아져요.","그래서 눈금 한 칸은 10권로 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_challenge#9','math',4,1,'u5','L04','g4_1_math_u5_L04_challenge','lesson_challenge','M4-1-u5-C6',4,'sa','auto','60그루를 나타내는 막대를 눈금 한 칸이 5그루인 그래프와 10그루인 그래프에 각각 그렸어요. 두 막대의 칸 수의 차는 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u5-C6","difficulty":4,"kind":"sa","stem":"60그루를 나타내는 막대를 눈금 한 칸이 5그루인 그래프와 10그루인 그래프에 각각 그렸어요. 두 막대의 칸 수의 차는 몇 칸인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 칸이 5그루면 60 ÷ 5 = 12칸이에요.","한 칸이 10그루면 60 ÷ 10 = 6칸이에요.","12 − 6 = 6칸 — 수는 같고 칸 수만 달라요."],"variant_rule":{"alt":[{"stem":"80권을 나타내는 막대를 눈금 한 칸이 10권인 그래프와 20권인 그래프에 각각 그렸어요. 두 막대의 칸 수의 차는 몇 칸인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 칸이 10권면 80 ÷ 10 = 8칸이에요.","한 칸이 20권면 80 ÷ 20 = 4칸이에요.","8 − 4 = 4칸 — 수는 같고 칸 수만 달라요."],"asset":null},{"stem":"120 kg을 나타내는 막대를 눈금 한 칸이 10 kg인 그래프와 20 kg인 그래프에 각각 그렸어요. 두 막대의 칸 수의 차는 몇 칸인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 칸이 10 kg면 120 ÷ 10 = 12칸이에요.","한 칸이 20 kg면 120 ÷ 20 = 6칸이에요.","12 − 6 = 6칸 — 수는 같고 칸 수만 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L04_challenge#10','math',4,1,'u5','L04','g4_1_math_u5_L04_challenge','lesson_challenge','M4-1-u5-C6',4,'essay','teacher','「지역별 문화유산 수」는 가 지역 125점, 나 지역 50점, 다 지역 75점, 라 지역 100점이에요. 눈금 한 칸을 1점, 25점, 500점으로 할 때를 각각 생각해 보고, 가장 알맞은 눈금 한 칸과 그 까닭을 두 가지 기준으로 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-1-u5-C6","difficulty":4,"kind":"essay","stem":"「지역별 문화유산 수」는 가 지역 125점, 나 지역 50점, 다 지역 75점, 라 지역 100점이에요. 눈금 한 칸을 1점, 25점, 500점으로 할 때를 각각 생각해 보고, 가장 알맞은 눈금 한 칸과 그 까닭을 두 가지 기준으로 써 보세요.","answer_guide":{"answer":"예: 1점으로 하면 칸을 125개나 그려야 해서 다 들어가지 않는다. 500점으로 하면 모두 한 칸 안에 들어가 막대들이 다 비슷해 보인다. 25점으로 하면 5칸이면 가장 큰 125점까지 들어가고 지역끼리의 차이도 한눈에 보이므로 25점이 가장 알맞다.","scoring_points":["1점은 칸이 너무 많다고 썼는가","500점은 차이가 안 보인다고 썼는가","25점을 고르고 「가장 큰 수 담기·차이 드러나기」 두 기준을 썼는가"]},"explanation":["한 칸이 너무 작으면 칸이 넘쳐요.","한 칸이 너무 크면 막대가 다 비슷해 보여요.","가장 큰 수를 담으면서 차이가 보이는 25점이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_basic#1','math',4,1,'u5','L05','g4_1_math_u5_L05_basic','lesson_basic','M4-1-u5-C7',1,'sa','auto','가 지역의 문화유산은 몇 점인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u5-C7","difficulty":1,"kind":"sa","stem":"가 지역의 문화유산은 몇 점인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["세로 눈금 한 칸은 25점이에요.","가 지역의 막대는 0에서 3칸이에요.","3 × 25 = 75 — 가 지역의 문화유산은 75점이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 지역","나 지역","다 지역","라 지역","마 지역"],"series":[{"vals":[75,100,50,150,125]}],"step":25,"ymax":175,"ylab":"(점)","title":"지역별 문화유산 수"},"variant_rule":{"alt":[{"stem":"사과를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["세로 눈금 한 칸은 1명이에요.","사과의 막대 끝을 따라 세로 눈금을 읽어요.","사과를 좋아하는 학생은 12명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["사과","포도","딸기","귤","배"],"series":[{"vals":[12,10,7,5,2]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 과일별 학생 수"}},{"stem":"배구를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["세로 눈금 한 칸은 1명이에요.","배구의 막대 끝을 따라 세로 눈금을 읽어요.","배구를 좋아하는 학생은 11명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["축구","피구","수영","야구","배구"],"series":[{"vals":[8,6,12,10,11]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 운동별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_basic#2','math',4,1,'u5','L05','g4_1_math_u5_L05_basic','lesson_basic','M4-1-u5-C7',1,'mc','auto','「좋아하는 급식 메뉴별 학생 수」에서 가장 적은 항목은 무엇인가요?',ARRAY['M4-1-u5-X21','M4-1-u5-X02']::text[],true,'{"seq":2,"concept":"M4-1-u5-C7","difficulty":1,"kind":"mc","stem":"「좋아하는 급식 메뉴별 학생 수」에서 가장 적은 항목은 무엇인가요?","options":[{"t":"불고기","correct":true},{"t":"카레","mis":"M4-1-u5-X21"},{"t":"잡채","mis":"M4-1-u5-X02"},{"t":"국수","mis":"M4-1-u5-X02"}],"explanation":["한 그래프 안에서는 막대가 길수록 수가 많아요.","가장 짧은 막대는 불고기의 막대예요.","그래서 가장 적은 항목은 불고기예요."],"asset":{"type":"lgraph","mode":"bar","xs":["카레","잡채","불고기","국수","김밥"],"series":[{"vals":[11,6,3,8,9]}],"step":1,"ymax":12,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"「좋아하는 간식별 학생 수」에서 가장 많은 항목은 무엇인가요?","options":[{"t":"만두","correct":true},{"t":"떡볶이","mis":"M4-1-u5-X21"},{"t":"김밥","mis":"M4-1-u5-X02"},{"t":"과일","mis":"M4-1-u5-X02"}],"explanation":["한 그래프 안에서는 막대가 길수록 수가 많아요.","가장 긴 막대는 만두의 막대예요.","그래서 가장 많은 항목은 만두예요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","만두"],"series":[{"vals":[2,5,6,4,11]}],"step":1,"ymax":12,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}},{"stem":"「기르고 싶은 동물별 학생 수」에서 가장 적은 항목은 무엇인가요?","options":[{"t":"토끼","correct":true},{"t":"강아지","mis":"M4-1-u5-X21"},{"t":"고양이","mis":"M4-1-u5-X02"},{"t":"햄스터","mis":"M4-1-u5-X02"}],"explanation":["한 그래프 안에서는 막대가 길수록 수가 많아요.","가장 짧은 막대는 토끼의 막대예요.","그래서 가장 적은 항목은 토끼예요."],"asset":{"type":"lgraph","mode":"bar","xs":["강아지","고양이","토끼","햄스터","금붕어"],"series":[{"vals":[9,4,2,6,5]}],"step":1,"ymax":10,"ylab":"(명)","title":"기르고 싶은 동물별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_basic#3','math',4,1,'u5','L05','g4_1_math_u5_L05_basic','lesson_basic','M4-1-u5-C7',1,'sa','auto','4학년 우유 신청 학생과 6학년 우유 신청 학생 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u5-C7","difficulty":1,"kind":"sa","stem":"4학년 우유 신청 학생과 6학년 우유 신청 학생 모두 몇 명인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["4학년은 70명, 6학년은 50명이에요.","모두 몇인지는 두 수를 더해요.","70 + 50 = 120 — 120명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["1학년","2학년","3학년","4학년","5학년","6학년"],"series":[{"vals":[80,30,90,70,25,50]}],"step":5,"ymax":95,"ylab":"(명)","title":"학년별 우유 신청 학생 수"},"variant_rule":{"alt":[{"stem":"3모둠이 모은 빈 병과 4모둠이 모은 빈 병 모두 몇 개인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["3모둠은 16개, 4모둠은 14개예요.","모두 몇인지는 두 수를 더해요.","16 + 14 = 30 — 30개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠","5모둠"],"series":[{"vals":[6,24,16,14,10]}],"step":2,"ymax":26,"ylab":"(개)","title":"모둠별 모은 빈 병 수"}},{"stem":"가 지역의 문화유산과 마 지역의 문화유산 모두 몇 점인가요? 숫자로 쓰세요.","answer":["175"],"explanation":["가 지역은 75점, 마 지역은 100점이에요.","모두 몇인지는 두 수를 더해요.","75 + 100 = 175 — 175점이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 지역","나 지역","다 지역","라 지역","마 지역"],"series":[{"vals":[75,150,125,175,100]}],"step":25,"ymax":200,"ylab":"(점)","title":"지역별 문화유산 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_basic#4','math',4,1,'u5','L05','g4_1_math_u5_L05_basic','lesson_basic','M4-1-u5-C8',1,'ox','auto','막대그래프를 보면 학생들이 그 항목을 고른 까닭도 알 수 있어요.',ARRAY['M4-1-u5-X11']::text[],true,'{"seq":4,"concept":"M4-1-u5-C8","difficulty":1,"kind":"ox","stem":"막대그래프를 보면 학생들이 그 항목을 고른 까닭도 알 수 있어요.","answer":"X","reason_options":[{"t":"그래프에는 수만 있고 까닭은 나와 있지 않아서","correct":true},{"t":"가장 긴 막대가 까닭을 알려 줘서","mis":"M4-1-u5-X11"}],"mis":"M4-1-u5-X11","explanation":["막대그래프는 ① 바로 답 찾기 ② 견주어 알기 ③ 판단하기 세 걸음으로 읽어요.","까닭·앞날처럼 그래프에 없는 것은 지어내지 않아요.","다른 그래프끼리는 눈금부터 확인해요."],"variant_rule":{"alt":[{"stem":"눈금 한 칸이 다른 두 그래프는 막대의 길이만으로 수를 견줄 수 없어요.","answer":"O","reason_options":[{"t":"같은 길이라도 한 칸이 크면 더 큰 수라서","correct":true},{"t":"길이가 길면 언제나 수가 많아서","mis":"M4-1-u5-X10"}],"explanation":["막대그래프는 ① 바로 답 찾기 ② 견주어 알기 ③ 판단하기 세 걸음으로 읽어요.","까닭·앞날처럼 그래프에 없는 것은 지어내지 않아요.","다른 그래프끼리는 눈금부터 확인해요."],"asset":null},{"stem":"그래프를 보고 판단할 때는 그래프의 수를 근거로 해요.","answer":"O","reason_options":[{"t":"그래프에 있는 사실로 판단해야 믿을 수 있어서","correct":true},{"t":"내가 좋아하는 것을 고르면 되어서","mis":"M4-1-u5-X12"}],"explanation":["막대그래프는 ① 바로 답 찾기 ② 견주어 알기 ③ 판단하기 세 걸음으로 읽어요.","까닭·앞날처럼 그래프에 없는 것은 지어내지 않아요.","다른 그래프끼리는 눈금부터 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_basic#5','math',4,1,'u5','L05','g4_1_math_u5_L05_basic','lesson_basic','M4-1-u5-C7',2,'mc','auto','봄을 좋아하는 학생은 여름을 좋아하는 학생의 몇 배인가요?',ARRAY['M4-1-u5-X09']::text[],true,'{"seq":5,"concept":"M4-1-u5-C7","difficulty":2,"kind":"mc","stem":"봄을 좋아하는 학생은 여름을 좋아하는 학생의 몇 배인가요?","options":[{"t":"3배","correct":true},{"t":"4배","mis":"M4-1-u5-X09"},{"t":"2배","mis":"M4-1-u5-X09"},{"t":"8배","mis":"M4-1-u5-X09"}],"explanation":["봄은 6명, 여름은 2명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 2 × 3 = 6.","그래서 3배예요 — 차(4)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"vals":[6,2,11,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 계절별 학생 수"},"variant_rule":{"alt":[{"stem":"방송 체험을 고른 학생은 소방 체험을 고른 학생의 몇 배인가요?","options":[{"t":"4배","correct":true},{"t":"9배","mis":"M4-1-u5-X09"},{"t":"5배","mis":"M4-1-u5-X09"},{"t":"3배","mis":"M4-1-u5-X09"}],"explanation":["방송은 12명, 소방은 3명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 3 × 4 = 12.","그래서 4배예요 — 차(9)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["로봇","요리","방송","소방","과학"],"series":[{"vals":[9,4,12,3,6]}],"step":1,"ymax":13,"ylab":"(명)","title":"가고 싶은 체험별 학생 수"}},{"stem":"의사를 희망하는 학생은 가수를 희망하는 학생의 몇 배인가요?","options":[{"t":"2배","correct":true},{"t":"3배","mis":"M4-1-u5-X09"},{"t":"1배","mis":"M4-1-u5-X09"},{"t":"6배","mis":"M4-1-u5-X09"}],"explanation":["의사는 4명, 가수는 2명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 2 × 2 = 4.","그래서 2배예요 — 차(2)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["요리사","경찰관","과학자","가수","의사"],"series":[{"vals":[3,5,6,2,4]}],"step":1,"ymax":7,"ylab":"(명)","title":"희망 직업별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_basic#6','math',4,1,'u5','L05','g4_1_math_u5_L05_basic','lesson_basic','M4-1-u5-C7',2,'mc','auto','피구의 학생 수보다 학생 수가 더 많은 항목은 어느 것인가요?',ARRAY['M4-1-u5-X21']::text[],true,'{"seq":6,"concept":"M4-1-u5-C7","difficulty":2,"kind":"mc","stem":"피구의 학생 수보다 학생 수가 더 많은 항목은 어느 것인가요?","options":[{"t":"야구","correct":true},{"t":"피구","mis":"M4-1-u5-X21"},{"t":"축구","mis":"M4-1-u5-X21"},{"t":"수영","mis":"M4-1-u5-X21"}],"explanation":["피구는 11명이에요.","피구의 막대보다 더 긴 막대를 찾아요.","야구(12명)만 더 길어요."],"asset":{"type":"lgraph","mode":"bar","xs":["축구","피구","수영","야구","배구"],"series":[{"vals":[8,11,4,12,3]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 운동별 학생 수"},"variant_rule":{"alt":[{"stem":"여름의 학생 수보다 학생 수가 더 많은 항목은 어느 것인가요?","options":[{"t":"겨울","correct":true},{"t":"여름","mis":"M4-1-u5-X21"},{"t":"봄","mis":"M4-1-u5-X21"},{"t":"가을","mis":"M4-1-u5-X21"}],"explanation":["여름은 10명이에요.","여름의 막대보다 더 긴 막대를 찾아요.","겨울(12명)만 더 길어요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"vals":[7,10,3,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 계절별 학생 수"}},{"stem":"요리의 학생 수보다 학생 수가 더 많은 항목은 어느 것인가요?","options":[{"t":"로봇","correct":true},{"t":"요리","mis":"M4-1-u5-X21"},{"t":"방송","mis":"M4-1-u5-X21"},{"t":"과학","mis":"M4-1-u5-X21"}],"explanation":["요리는 10명이에요.","요리의 막대보다 더 긴 막대를 찾아요.","로봇(12명)만 더 길어요."],"asset":{"type":"lgraph","mode":"bar","xs":["로봇","요리","방송","소방","과학"],"series":[{"vals":[12,10,9,6,7]}],"step":1,"ymax":13,"ylab":"(명)","title":"가고 싶은 체험별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_basic#7','math',4,1,'u5','L05','g4_1_math_u5_L05_basic','lesson_basic','M4-1-u5-C7',2,'sa','auto','라 마을의 나무는 마 마을의 나무보다 몇 그루 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u5-C7","difficulty":2,"kind":"sa","stem":"라 마을의 나무는 마 마을의 나무보다 몇 그루 더 많은가요? 숫자로 쓰세요.","answer":["20"],"explanation":["라 마을은 80그루, 마 마을은 60그루예요.","몇 더 많은지는 큰 수에서 작은 수를 빼요.","80 − 60 = 20 — 20그루 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을","마 마을"],"series":[{"vals":[40,65,25,80,60]}],"step":5,"ymax":85,"ylab":"(그루)","title":"마을별 나무 수"},"variant_rule":{"alt":[{"stem":"2학년 우유 신청 학생은 6학년 우유 신청 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["35"],"explanation":["2학년은 90명, 6학년은 55명이에요.","몇 더 많은지는 큰 수에서 작은 수를 빼요.","90 − 55 = 35 — 35명 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["1학년","2학년","3학년","4학년","5학년","6학년"],"series":[{"vals":[60,90,75,20,25,55]}],"step":5,"ymax":95,"ylab":"(명)","title":"학년별 우유 신청 학생 수"}},{"stem":"1모둠이 모은 빈 병은 4모둠이 모은 빈 병보다 몇 개 더 많은가요? 숫자로 쓰세요.","answer":["8"],"explanation":["1모둠은 24개, 4모둠은 16개예요.","몇 더 많은지는 큰 수에서 작은 수를 빼요.","24 − 16 = 8 — 8개 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠","5모둠"],"series":[{"vals":[24,12,30,16,10]}],"step":2,"ymax":32,"ylab":"(개)","title":"모둠별 모은 빈 병 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_basic#8','math',4,1,'u5','L05','g4_1_math_u5_L05_basic','lesson_basic','M4-1-u5-C8',2,'mc','auto','아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?',ARRAY['M4-1-u5-X21']::text[],true,'{"seq":8,"concept":"M4-1-u5-C8","difficulty":2,"kind":"mc","stem":"아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"학생들이 그 항목을 고른 까닭","correct":true},{"t":"가장 많은 학생이 고른 항목","mis":"M4-1-u5-X21"},{"t":"축구의 학생 수","mis":"M4-1-u5-X21"},{"t":"축구와 피구의 학생 수의 차","mis":"M4-1-u5-X21"}],"explanation":["막대그래프에서는 항목별 수, 가장 많은 것, 두 항목의 차를 알 수 있어요.","「학생들이 그 항목을 고른 까닭」은 그래프에 나와 있지 않아요.","그래프에 없는 것은 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["축구","피구","수영","야구","배구"],"series":[{"vals":[3,6,12,11,7]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 운동별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"다음 달에 가장 인기 있을 항목","correct":true},{"t":"가장 많은 학생이 고른 항목","mis":"M4-1-u5-X21"},{"t":"봄의 학생 수","mis":"M4-1-u5-X21"},{"t":"봄과 가을의 학생 수의 차","mis":"M4-1-u5-X21"}],"explanation":["막대그래프에서는 항목별 수, 가장 많은 것, 두 항목의 차를 알 수 있어요.","「다음 달에 가장 인기 있을 항목」은 그래프에 나와 있지 않아요.","그래프에 없는 것은 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"vals":[2,3,4,11]}],"step":1,"ymax":12,"ylab":"(명)","title":"좋아하는 계절별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"조사한 날의 날씨","correct":true},{"t":"가장 많은 학생이 고른 항목","mis":"M4-1-u5-X21"},{"t":"로봇의 학생 수","mis":"M4-1-u5-X21"},{"t":"로봇과 과학의 학생 수의 차","mis":"M4-1-u5-X21"}],"explanation":["막대그래프에서는 항목별 수, 가장 많은 것, 두 항목의 차를 알 수 있어요.","「조사한 날의 날씨」는 그래프에 나와 있지 않아요.","그래프에 없는 것은 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["로봇","요리","방송","소방","과학"],"series":[{"vals":[2,5,13,3,11]}],"step":1,"ymax":14,"ylab":"(명)","title":"가고 싶은 체험별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_basic#9','math',4,1,'u5','L05','g4_1_math_u5_L05_basic','lesson_basic','M4-1-u5-C8',2,'sa','auto','학교 4학년 전체를 조사한 막대그래프는 눈금 한 칸이 5명이에요. 이 그래프에서 어느 직업의 막대가 4칸이라면 그 직업을 희망하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u5-C8","difficulty":2,"kind":"sa","stem":"학교 4학년 전체를 조사한 막대그래프는 눈금 한 칸이 5명이에요. 이 그래프에서 어느 직업의 막대가 4칸이라면 그 직업을 희망하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["반 그래프와 학교 그래프는 눈금 한 칸이 다를 수 있어요.","이 그래프는 한 칸이 5명이에요.","4 × 5 = 20 — 20명이에요."],"variant_rule":{"alt":[{"stem":"학교 4학년 전체를 조사한 막대그래프는 눈금 한 칸이 5명이에요. 이 그래프에서 어느 직업의 막대가 7칸이라면 그 직업을 희망하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["반 그래프와 학교 그래프는 눈금 한 칸이 다를 수 있어요.","이 그래프는 한 칸이 5명이에요.","7 × 5 = 35 — 35명이에요."],"asset":null},{"stem":"학교 4학년 전체를 조사한 막대그래프는 눈금 한 칸이 10명이에요. 이 그래프에서 어느 직업의 막대가 3칸이라면 그 직업을 희망하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["반 그래프와 학교 그래프는 눈금 한 칸이 다를 수 있어요.","이 그래프는 한 칸이 10명이에요.","3 × 10 = 30 — 30명이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_basic#10','math',4,1,'u5','L05','g4_1_math_u5_L05_basic','lesson_basic','M4-1-u5-C8',3,'mc','auto','진로 체험의 날에 직업인 한 분을 초대하려고 해요. 아래 막대그래프를 보고 판단할 때, 고를 것과 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X12']::text[],true,'{"seq":10,"concept":"M4-1-u5-C8","difficulty":3,"kind":"mc","stem":"진로 체험의 날에 직업인 한 분을 초대하려고 해요. 아래 막대그래프를 보고 판단할 때, 고를 것과 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"요리사 — 가장 많은 학생이 골랐으니까요.","correct":true},{"t":"경찰관 — 막대가 가장 짧아서요.","mis":"M4-1-u5-X12"},{"t":"과학자 — 내가 좋아하는 것이니까요.","mis":"M4-1-u5-X12"},{"t":"가수 — 이름이 가장 멋있어서요.","mis":"M4-1-u5-X12"}],"explanation":["그래프를 바탕으로 판단할 때는 그래프의 수를 근거로 해요.","가장 긴 막대는 요리사의 막대로 9명이에요.","가장 많은 학생이 고른 요리사를 고르는 것이 알맞아요."],"asset":{"type":"lgraph","mode":"bar","xs":["요리사","경찰관","과학자","가수","의사"],"series":[{"vals":[9,1,8,2,5]}],"step":1,"ymax":10,"ylab":"(명)","title":"희망 직업별 학생 수"},"variant_rule":{"alt":[{"stem":"체험 부스를 하나 더 열려고 해요. 아래 막대그래프를 보고 판단할 때, 고를 것과 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"방송 — 가장 많은 학생이 골랐으니까요.","correct":true},{"t":"로봇 — 막대가 가장 짧아서요.","mis":"M4-1-u5-X12"},{"t":"요리 — 내가 좋아하는 것이니까요.","mis":"M4-1-u5-X12"},{"t":"소방 — 이름이 가장 멋있어서요.","mis":"M4-1-u5-X12"}],"explanation":["그래프를 바탕으로 판단할 때는 그래프의 수를 근거로 해요.","가장 긴 막대는 방송의 막대로 13명이에요.","가장 많은 학생이 고른 방송을 고르는 것이 알맞아요."],"asset":{"type":"lgraph","mode":"bar","xs":["로봇","요리","방송","소방","과학"],"series":[{"vals":[2,4,13,3,8]}],"step":1,"ymax":14,"ylab":"(명)","title":"가고 싶은 체험별 학생 수"}},{"stem":"학급 잔치에 간식 한 가지를 준비하려고 해요. 아래 막대그래프를 보고 판단할 때, 고를 것과 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"만두 — 가장 많은 학생이 골랐으니까요.","correct":true},{"t":"떡볶이 — 막대가 가장 짧아서요.","mis":"M4-1-u5-X12"},{"t":"김밥 — 내가 좋아하는 것이니까요.","mis":"M4-1-u5-X12"},{"t":"과일 — 이름이 가장 멋있어서요.","mis":"M4-1-u5-X12"}],"explanation":["그래프를 바탕으로 판단할 때는 그래프의 수를 근거로 해요.","가장 긴 막대는 만두의 막대로 12명이에요.","가장 많은 학생이 고른 만두를 고르는 것이 알맞아요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","만두"],"series":[{"vals":[2,11,4,5,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_challenge#1','math',4,1,'u5','L05','g4_1_math_u5_L05_challenge','lesson_challenge','M4-1-u5-C7',2,'mc','auto','국수를 좋아하는 학생은 카레를 좋아하는 학생의 몇 배인가요?',ARRAY['M4-1-u5-X09']::text[],true,'{"seq":1,"concept":"M4-1-u5-C7","difficulty":2,"kind":"mc","stem":"국수를 좋아하는 학생은 카레를 좋아하는 학생의 몇 배인가요?","options":[{"t":"2배","correct":true},{"t":"4배","mis":"M4-1-u5-X09"},{"t":"3배","mis":"M4-1-u5-X09"},{"t":"1배","mis":"M4-1-u5-X09"}],"explanation":["국수는 8명, 카레는 4명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 4 × 2 = 8.","그래서 2배예요 — 차(4)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["카레","잡채","불고기","국수","김밥"],"series":[{"vals":[4,11,5,8,7]}],"step":1,"ymax":12,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"김밥을 좋아하는 학생은 떡볶이를 좋아하는 학생의 몇 배인가요?","options":[{"t":"2배","correct":true},{"t":"4배","mis":"M4-1-u5-X09"},{"t":"3배","mis":"M4-1-u5-X09"},{"t":"1배","mis":"M4-1-u5-X09"}],"explanation":["김밥은 8명, 떡볶이는 4명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 4 × 2 = 8.","그래서 2배예요 — 차(4)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","만두"],"series":[{"vals":[4,8,6,7,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}},{"stem":"금붕어를 기르고 싶은 학생은 강아지를 기르고 싶은 학생의 몇 배인가요?","options":[{"t":"3배","correct":true},{"t":"4배","mis":"M4-1-u5-X09"},{"t":"2배","mis":"M4-1-u5-X09"},{"t":"8배","mis":"M4-1-u5-X09"}],"explanation":["금붕어는 6명, 강아지는 2명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 2 × 3 = 6.","그래서 3배예요 — 차(4)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["강아지","고양이","토끼","햄스터","금붕어"],"series":[{"vals":[2,4,8,3,6]}],"step":1,"ymax":9,"ylab":"(명)","title":"기르고 싶은 동물별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
