학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_challenge#3','math',4,1,'u5','L05','g4_1_math_u5_L05_challenge','lesson_challenge','M4-1-u5-C8',3,'mc','auto','가 그래프는 눈금 한 칸이 1명이고 범죄 수사관의 막대가 8칸이에요. 나 그래프는 눈금 한 칸이 5명이고 수의사의 막대가 2칸이에요. 범죄 수사관의 막대가 더 길어 보이는데, 범죄 수사관을 고른 학생이 더 많은 걸까요?',ARRAY['M4-1-u5-X10','M4-1-u5-X02','M4-1-u5-X12']::text[],true,'{"seq":3,"concept":"M4-1-u5-C8","difficulty":3,"kind":"mc","stem":"가 그래프는 눈금 한 칸이 1명이고 범죄 수사관의 막대가 8칸이에요. 나 그래프는 눈금 한 칸이 5명이고 수의사의 막대가 2칸이에요. 범죄 수사관의 막대가 더 길어 보이는데, 범죄 수사관을 고른 학생이 더 많은 걸까요?","options":[{"t":"아니요 — 눈금이 달라요. 범죄 수사관은 8명, 수의사는 10명이에요.","correct":true},{"t":"네 — 막대가 길면 언제나 수가 많아요.","mis":"M4-1-u5-X10"},{"t":"두 막대가 나타내는 수는 똑같아요.","mis":"M4-1-u5-X02"},{"t":"네 — 가 그래프가 먼저 나왔으니까요.","mis":"M4-1-u5-X12"}],"explanation":["다른 그래프끼리 견줄 때는 눈금부터 확인해요.","범죄 수사관은 8 × 1 = 8명, 수의사는 2 × 5 = 10명이에요.","막대는 범죄 수사관이 더 길어도 수는 수의사가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 그래프는 눈금 한 칸이 1명이고 로봇의 막대가 9칸이에요. 나 그래프는 눈금 한 칸이 5명이고 요리의 막대가 3칸이에요. 로봇의 막대가 더 길어 보이는데, 로봇을 고른 학생이 더 많은 걸까요?","options":[{"t":"아니요 — 눈금이 달라요. 로봇은 9명, 요리는 15명이에요.","correct":true},{"t":"네 — 막대가 길면 언제나 수가 많아요.","mis":"M4-1-u5-X10"},{"t":"두 막대가 나타내는 수는 똑같아요.","mis":"M4-1-u5-X02"},{"t":"네 — 가 그래프가 먼저 나왔으니까요.","mis":"M4-1-u5-X12"}],"explanation":["다른 그래프끼리 견줄 때는 눈금부터 확인해요.","로봇은 9 × 1 = 9명, 요리는 3 × 5 = 15명이에요.","막대는 로봇이 더 길어도 수는 요리가 더 많아요."],"asset":null},{"stem":"가 그래프는 눈금 한 칸이 2명이고 축구의 막대가 7칸이에요. 나 그래프는 눈금 한 칸이 10명이고 피구의 막대가 2칸이에요. 축구의 막대가 더 길어 보이는데, 축구를 고른 학생이 더 많은 걸까요?","options":[{"t":"아니요 — 눈금이 달라요. 축구는 14명, 피구는 20명이에요.","correct":true},{"t":"네 — 막대가 길면 언제나 수가 많아요.","mis":"M4-1-u5-X10"},{"t":"두 막대가 나타내는 수는 똑같아요.","mis":"M4-1-u5-X02"},{"t":"네 — 가 그래프가 먼저 나왔으니까요.","mis":"M4-1-u5-X12"}],"explanation":["다른 그래프끼리 견줄 때는 눈금부터 확인해요.","축구는 7 × 2 = 14명, 피구는 2 × 10 = 20명이에요.","막대는 축구가 더 길어도 수는 피구가 더 많아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_challenge#4','math',4,1,'u5','L05','g4_1_math_u5_L05_challenge','lesson_challenge','M4-1-u5-C8',3,'error','auto','막대그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u5-X11','M4-1-u5-X21']::text[],true,'{"seq":4,"concept":"M4-1-u5-C8","difficulty":3,"kind":"error","stem":"막대그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「요리사 막대가 가장 기니까 다들 맛있는 걸 좋아해서 그래.」","correct":true,"mis_target":"M4-1-u5-X11"},{"t":"은우 — 「가장 긴 막대가 가장 많은 거야.」","mis":"M4-1-u5-X21"},{"t":"하랑 — 「두 막대의 수를 빼면 차를 알 수 있어.」","mis":"M4-1-u5-X21"},{"t":"지아 — 「다른 그래프는 눈금부터 확인하자.」","mis":"M4-1-u5-X21"}],"explanation":["그래프에 있는 것과 없는 것을 가려 읽어요.","시우의 말은 그래프에 없는 것을 지어내거나 그래프가 아닌 것으로 판단했어요.","판단은 그래프의 수로, 다른 그래프는 눈금부터 확인해요."],"variant_rule":{"alt":[{"stem":"막대그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「반 그래프의 막대가 학교 그래프보다 기니까 반이 더 많아.」","correct":true,"mis_target":"M4-1-u5-X10"},{"t":"하랑 — 「두 막대의 수를 빼면 차를 알 수 있어.」","mis":"M4-1-u5-X21"},{"t":"지아 — 「다른 그래프는 눈금부터 확인하자.」","mis":"M4-1-u5-X21"},{"t":"준서 — 「까닭은 그래프에 나와 있지 않아.」","mis":"M4-1-u5-X21"}],"explanation":["그래프에 있는 것과 없는 것을 가려 읽어요.","은우의 말은 그래프에 없는 것을 지어내거나 그래프가 아닌 것으로 판단했어요.","판단은 그래프의 수로, 다른 그래프는 눈금부터 확인해요."],"asset":null},{"stem":"막대그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「나는 가수가 좋으니까 가수를 초대하자.」","correct":true,"mis_target":"M4-1-u5-X12"},{"t":"지아 — 「다른 그래프는 눈금부터 확인하자.」","mis":"M4-1-u5-X21"},{"t":"준서 — 「까닭은 그래프에 나와 있지 않아.」","mis":"M4-1-u5-X21"},{"t":"민서 — 「가장 긴 막대가 가장 많은 거야.」","mis":"M4-1-u5-X21"}],"explanation":["그래프에 있는 것과 없는 것을 가려 읽어요.","하랑의 말은 그래프에 없는 것을 지어내거나 그래프가 아닌 것으로 판단했어요.","판단은 그래프의 수로, 다른 그래프는 눈금부터 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_challenge#5','math',4,1,'u5','L05','g4_1_math_u5_L05_challenge','lesson_challenge','M4-1-u5-C7',3,'sa','auto','사과의 학생 수보다 학생 수가 더 많은 항목은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u5-C7","difficulty":3,"kind":"sa","stem":"사과의 학생 수보다 학생 수가 더 많은 항목은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["사과는 9명이에요.","사과의 막대보다 긴 막대를 찾아요: 귤.","모두 1개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["사과","포도","딸기","귤","배"],"series":[{"vals":[9,5,7,10,6]}],"step":1,"ymax":11,"ylab":"(명)","title":"좋아하는 과일별 학생 수"},"variant_rule":{"alt":[{"stem":"야구의 학생 수보다 학생 수가 더 많은 항목은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["야구는 4명이에요.","야구의 막대보다 긴 막대를 찾아요: 축구, 수영, 배구.","모두 3개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["축구","피구","수영","야구","배구"],"series":[{"vals":[7,2,5,4,6]}],"step":1,"ymax":8,"ylab":"(명)","title":"좋아하는 운동별 학생 수"}},{"stem":"로봇의 학생 수보다 학생 수가 더 많은 항목은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["로봇은 6명이에요.","로봇의 막대보다 긴 막대를 찾아요: 요리, 방송.","모두 2개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["로봇","요리","방송","소방","과학"],"series":[{"vals":[6,11,8,4,5]}],"step":1,"ymax":12,"ylab":"(명)","title":"가고 싶은 체험별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_challenge#6','math',4,1,'u5','L05','g4_1_math_u5_L05_challenge','lesson_challenge','M4-1-u5-C8',3,'mc','auto','급식에 우리 반 추천 메뉴 한 가지를 내려고 해요. 아래 막대그래프를 보고 판단할 때, 고를 것과 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X12']::text[],true,'{"seq":6,"concept":"M4-1-u5-C8","difficulty":3,"kind":"mc","stem":"급식에 우리 반 추천 메뉴 한 가지를 내려고 해요. 아래 막대그래프를 보고 판단할 때, 고를 것과 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국수 — 가장 많은 학생이 골랐으니까요.","correct":true},{"t":"김밥 — 막대가 가장 짧아서요.","mis":"M4-1-u5-X12"},{"t":"카레 — 내가 좋아하는 것이니까요.","mis":"M4-1-u5-X12"},{"t":"잡채 — 이름이 가장 멋있어서요.","mis":"M4-1-u5-X12"}],"explanation":["그래프를 바탕으로 판단할 때는 그래프의 수를 근거로 해요.","가장 긴 막대는 국수의 막대로 11명이에요.","가장 많은 학생이 고른 국수를 고르는 것이 알맞아요."],"asset":{"type":"lgraph","mode":"bar","xs":["카레","잡채","불고기","국수","김밥"],"series":[{"vals":[5,4,7,11,2]}],"step":1,"ymax":12,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"반에서 기를 동물 한 가지를 정하려고 해요. 아래 막대그래프를 보고 판단할 때, 고를 것과 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"토끼 — 가장 많은 학생이 골랐으니까요.","correct":true},{"t":"강아지 — 막대가 가장 짧아서요.","mis":"M4-1-u5-X12"},{"t":"고양이 — 내가 좋아하는 것이니까요.","mis":"M4-1-u5-X12"},{"t":"햄스터 — 이름이 가장 멋있어서요.","mis":"M4-1-u5-X12"}],"explanation":["그래프를 바탕으로 판단할 때는 그래프의 수를 근거로 해요.","가장 긴 막대는 토끼의 막대로 9명이에요.","가장 많은 학생이 고른 토끼를 고르는 것이 알맞아요."],"asset":{"type":"lgraph","mode":"bar","xs":["강아지","고양이","토끼","햄스터","금붕어"],"series":[{"vals":[2,3,9,5,8]}],"step":1,"ymax":10,"ylab":"(명)","title":"기르고 싶은 동물별 학생 수"}},{"stem":"운동회 반 대항 종목 한 가지를 고르려고 해요. 아래 막대그래프를 보고 판단할 때, 고를 것과 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"야구 — 가장 많은 학생이 골랐으니까요.","correct":true},{"t":"축구 — 막대가 가장 짧아서요.","mis":"M4-1-u5-X12"},{"t":"피구 — 내가 좋아하는 것이니까요.","mis":"M4-1-u5-X12"},{"t":"수영 — 이름이 가장 멋있어서요.","mis":"M4-1-u5-X12"}],"explanation":["그래프를 바탕으로 판단할 때는 그래프의 수를 근거로 해요.","가장 긴 막대는 야구의 막대로 12명이에요.","가장 많은 학생이 고른 야구를 고르는 것이 알맞아요."],"asset":{"type":"lgraph","mode":"bar","xs":["축구","피구","수영","야구","배구"],"series":[{"vals":[3,7,4,12,9]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 운동별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_challenge#7','math',4,1,'u5','L05','g4_1_math_u5_L05_challenge','lesson_challenge','M4-1-u5-C7',3,'mc','auto','경찰관의 학생 수보다 학생 수가 더 많은 항목은 어느 것인가요?',ARRAY['M4-1-u5-X21']::text[],true,'{"seq":7,"concept":"M4-1-u5-C7","difficulty":3,"kind":"mc","stem":"경찰관의 학생 수보다 학생 수가 더 많은 항목은 어느 것인가요?","options":[{"t":"과학자","correct":true},{"t":"경찰관","mis":"M4-1-u5-X21"},{"t":"요리사","mis":"M4-1-u5-X21"},{"t":"의사","mis":"M4-1-u5-X21"}],"explanation":["경찰관은 8명이에요.","경찰관의 막대보다 더 긴 막대를 찾아요.","과학자(10명)만 더 길어요."],"asset":{"type":"lgraph","mode":"bar","xs":["요리사","경찰관","과학자","가수","의사"],"series":[{"vals":[7,8,10,1,5]}],"step":1,"ymax":11,"ylab":"(명)","title":"희망 직업별 학생 수"},"variant_rule":{"alt":[{"stem":"국수의 학생 수보다 학생 수가 더 많은 항목은 어느 것인가요?","options":[{"t":"불고기","correct":true},{"t":"국수","mis":"M4-1-u5-X21"},{"t":"잡채","mis":"M4-1-u5-X21"},{"t":"김밥","mis":"M4-1-u5-X21"}],"explanation":["국수는 7명이에요.","국수의 막대보다 더 긴 막대를 찾아요.","불고기(8명)만 더 길어요."],"asset":{"type":"lgraph","mode":"bar","xs":["카레","잡채","불고기","국수","김밥"],"series":[{"vals":[3,6,8,7,5]}],"step":1,"ymax":9,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"}},{"stem":"떡볶이의 학생 수보다 학생 수가 더 많은 항목은 어느 것인가요?","options":[{"t":"과일","correct":true},{"t":"떡볶이","mis":"M4-1-u5-X21"},{"t":"만두","mis":"M4-1-u5-X21"},{"t":"김밥","mis":"M4-1-u5-X21"}],"explanation":["떡볶이는 8명이에요.","떡볶이의 막대보다 더 긴 막대를 찾아요.","과일(10명)만 더 길어요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","만두"],"series":[{"vals":[8,4,10,2,5]}],"step":1,"ymax":11,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_challenge#8','math',4,1,'u5','L05','g4_1_math_u5_L05_challenge','lesson_challenge','M4-1-u5-C7',4,'mc','auto','가장 많은 항목의 학생 수는 가장 적은 항목의 몇 배인가요?',ARRAY['M4-1-u5-X09']::text[],true,'{"seq":8,"concept":"M4-1-u5-C7","difficulty":4,"kind":"mc","stem":"가장 많은 항목의 학생 수는 가장 적은 항목의 몇 배인가요?","options":[{"t":"2배","correct":true},{"t":"6배","mis":"M4-1-u5-X09"},{"t":"3배","mis":"M4-1-u5-X09"},{"t":"1배","mis":"M4-1-u5-X09"}],"explanation":["가을은 12명, 봄은 6명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 6 × 2 = 12.","그래서 2배예요 — 차(6)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"vals":[6,10,12,9]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 계절별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 가장 많은 항목의 학생 수는 가장 적은 항목의 몇 배인가요?","options":[{"t":"3배","correct":true},{"t":"8배","mis":"M4-1-u5-X09"},{"t":"4배","mis":"M4-1-u5-X09"},{"t":"2배","mis":"M4-1-u5-X09"}],"explanation":["방송은 12명, 소방은 4명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 4 × 3 = 12.","그래서 3배예요 — 차(8)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["로봇","요리","방송","소방","과학"],"series":[{"vals":[9,8,12,4,11]}],"step":1,"ymax":13,"ylab":"(명)","title":"가고 싶은 체험별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 가장 많은 항목의 학생 수는 가장 적은 항목의 몇 배인가요?","options":[{"t":"3배","correct":true},{"t":"6배","mis":"M4-1-u5-X09"},{"t":"4배","mis":"M4-1-u5-X09"},{"t":"2배","mis":"M4-1-u5-X09"}],"explanation":["의사는 9명, 과학자는 3명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 3 × 3 = 9.","그래서 3배예요 — 차(6)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["요리사","경찰관","과학자","가수","의사"],"series":[{"vals":[4,7,3,8,9]}],"step":1,"ymax":10,"ylab":"(명)","title":"희망 직업별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_challenge#9','math',4,1,'u5','L05','g4_1_math_u5_L05_challenge','lesson_challenge','M4-1-u5-C7',4,'sa','auto','소방과 과학을 더하면 가장 많은 항목보다 몇 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u5-C7","difficulty":4,"kind":"sa","stem":"소방과 과학을 더하면 가장 많은 항목보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["4"],"explanation":["소방 9명 + 과학 8명 = 17명.","가장 많은 항목인 방송은 13명이에요.","17 − 13 = 4 — 4명 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["로봇","요리","방송","소방","과학"],"series":[{"vals":[4,6,13,9,8]}],"step":1,"ymax":14,"ylab":"(명)","title":"가고 싶은 체험별 학생 수"},"variant_rule":{"alt":[{"stem":"야구와 피구를 더하면 가장 많은 항목보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["5"],"explanation":["야구 8명 + 피구 7명 = 15명.","가장 많은 항목인 배구는 10명이에요.","15 − 10 = 5 — 5명 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["축구","피구","수영","야구","배구"],"series":[{"vals":[2,7,3,8,10]}],"step":1,"ymax":11,"ylab":"(명)","title":"좋아하는 운동별 학생 수"}},{"stem":"사과와 귤을 더하면 가장 많은 항목보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["7"],"explanation":["사과 9명 + 귤 8명 = 17명.","가장 많은 항목인 포도는 10명이에요.","17 − 10 = 7 — 7명 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["사과","포도","딸기","귤","배"],"series":[{"vals":[9,10,2,8,3]}],"step":1,"ymax":11,"ylab":"(명)","title":"좋아하는 과일별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L05_challenge#10','math',4,1,'u5','L05','g4_1_math_u5_L05_challenge','lesson_challenge','M4-1-u5-C8',4,'essay','teacher','반 그래프는 눈금 한 칸이 1명이고 범죄 수사관의 막대가 8칸이에요. 학교 그래프는 눈금 한 칸이 5명이고 수의사의 막대가 2칸이에요. 한 친구가 「수사관 막대가 더 기니까 수사관을 희망하는 학생이 더 많아. 수사관이 멋있어서 그런 거야.」라고 했어요. 친구의 말에서 잘못된 점 두 가지를 찾아 바르게 고쳐 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-1-u5-C8","difficulty":4,"kind":"essay","stem":"반 그래프는 눈금 한 칸이 1명이고 범죄 수사관의 막대가 8칸이에요. 학교 그래프는 눈금 한 칸이 5명이고 수의사의 막대가 2칸이에요. 한 친구가 「수사관 막대가 더 기니까 수사관을 희망하는 학생이 더 많아. 수사관이 멋있어서 그런 거야.」라고 했어요. 친구의 말에서 잘못된 점 두 가지를 찾아 바르게 고쳐 써 보세요.","answer_guide":{"answer":"예: 첫째, 두 그래프는 눈금 한 칸의 크기가 달라 길이만으로 견줄 수 없다. 수사관은 8 × 1 = 8명, 수의사는 2 × 5 = 10명이므로 수의사를 희망하는 학생이 더 많다. 둘째, 왜 희망하는지 그 까닭은 그래프에 나와 있지 않으므로 「멋있어서」라고 지어내면 안 된다.","scoring_points":["눈금이 달라 길이로 견줄 수 없다고 썼는가","8명과 10명으로 바르게 구했는가","까닭은 그래프에 없어 지어내면 안 된다고 썼는가"]},"explanation":["다른 그래프는 눈금부터 확인해요.","수사관 8명, 수의사 10명이에요.","까닭은 그래프에 없으니 지어내지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_basic#1','math',4,1,'u5','L06','g4_1_math_u5_L06_basic','lesson_basic','M4-1-u5-C9',1,'mc','auto','자료를 조사할 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M4-1-u5-X18']::text[],true,'{"seq":1,"concept":"M4-1-u5-C9","difficulty":1,"kind":"mc","stem":"자료를 조사할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"조사할 주제 정하기","correct":true},{"t":"막대그래프 그리기","mis":"M4-1-u5-X18"},{"t":"조사 방법 정하기","mis":"M4-1-u5-X18"},{"t":"합계 확인하기","mis":"M4-1-u5-X18"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"variant_rule":{"alt":[{"stem":"조사할 주제를 정한 다음에 할 일은 무엇인가요?","options":[{"t":"항목 정하기","correct":true},{"t":"합계 확인하기","mis":"M4-1-u5-X18"},{"t":"막대그래프 그리기","mis":"M4-1-u5-X18"},{"t":"신문 기사 쓰기","mis":"M4-1-u5-X18"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"asset":null},{"stem":"자료를 조사하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주제 → 항목 → 방법 → 조사","correct":true},{"t":"방법 → 조사 → 주제 → 항목","mis":"M4-1-u5-X18"},{"t":"조사 → 주제 → 항목 → 방법","mis":"M4-1-u5-X18"},{"t":"항목 → 방법 → 조사 → 주제","mis":"M4-1-u5-X18"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_basic#2','math',4,1,'u5','L06','g4_1_math_u5_L06_basic','lesson_basic','M4-1-u5-C9',1,'mc','auto','「우리 반이 좋아하는 급식 메뉴」 조사의 항목을 정하려고 해요. 항목으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M4-1-u5-X21']::text[],true,'{"seq":2,"concept":"M4-1-u5-C9","difficulty":1,"kind":"mc","stem":"「우리 반이 좋아하는 급식 메뉴」 조사의 항목을 정하려고 해요. 항목으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"고기 반찬 — 불고기와 겹쳐요.","correct":true},{"t":"잡채","mis":"M4-1-u5-X21"},{"t":"카레","mis":"M4-1-u5-X21"},{"t":"기타","mis":"M4-1-u5-X21"}],"explanation":["항목끼리 겹치면 어디에 답할지 헷갈려요.","「고기 반찬」에는 불고기가 들어가요.","그래서 「고기 반찬」은 항목으로 알맞지 않아요."],"variant_rule":{"alt":[{"stem":"「우리 반이 좋아하는 과일」 조사의 항목을 정하려고 해요. 항목으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"빨간 과일 — 사과와 겹쳐요.","correct":true},{"t":"포도","mis":"M4-1-u5-X21"},{"t":"딸기","mis":"M4-1-u5-X21"},{"t":"기타","mis":"M4-1-u5-X21"}],"explanation":["항목끼리 겹치면 어디에 답할지 헷갈려요.","「빨간 과일」에는 사과가 들어가요.","그래서 「빨간 과일」은 항목으로 알맞지 않아요."],"asset":null},{"stem":"「우리 반이 좋아하는 운동」 조사의 항목을 정하려고 해요. 항목으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"공놀이 — 축구와 겹쳐요.","correct":true},{"t":"피구","mis":"M4-1-u5-X21"},{"t":"수영","mis":"M4-1-u5-X21"},{"t":"기타","mis":"M4-1-u5-X21"}],"explanation":["항목끼리 겹치면 어디에 답할지 헷갈려요.","「공놀이」에는 축구가 들어가요.","그래서 「공놀이」는 항목으로 알맞지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_basic#3','math',4,1,'u5','L06','g4_1_math_u5_L06_basic','lesson_basic','M4-1-u5-C9',1,'sa','auto','우리 반 조사 결과예요. 항목별 수를 모두 더하면 합계는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u5-C9","difficulty":1,"kind":"sa","stem":"우리 반 조사 결과예요. 항목별 수를 모두 더하면 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["합계는 항목별 수를 모두 더해요.","8 + 3 + 2 + 12 + 7 = 32.","합계는 32명이에요 — 우리 반 인원과 같은지 확인해요."],"asset":{"type":"picg","only":"table","head":"운동","cols":["축구","피구","수영","야구","배구"],"counts":[8,3,2,12,7],"vh":"학생 수","unit":"명","total":null,"title":"좋아하는 운동별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 우리 반 조사 결과예요. 항목별 수를 모두 더하면 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["합계는 항목별 수를 모두 더해요.","8 + 2 + 5 + 3 = 18.","합계는 18명이에요 — 우리 반 인원과 같은지 확인해요."],"asset":{"type":"picg","only":"table","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[8,2,5,3],"vh":"학생 수","unit":"명","total":null,"title":"좋아하는 계절별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 우리 반 조사 결과예요. 항목별 수를 모두 더하면 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["합계는 항목별 수를 모두 더해요.","13 + 6 + 11 + 5 + 3 = 38.","합계는 38명이에요 — 우리 반 인원과 같은지 확인해요."],"asset":{"type":"picg","only":"table","head":"체험","cols":["로봇","요리","방송","소방","과학"],"counts":[13,6,11,5,3],"vh":"학생 수","unit":"명","total":null,"title":"가고 싶은 체험별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_basic#4','math',4,1,'u5','L06','g4_1_math_u5_L06_basic','lesson_basic','M4-1-u5-C9',1,'mc','auto','손 들기로 자료를 모을 때의 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X16']::text[],true,'{"seq":4,"concept":"M4-1-u5-C9","difficulty":1,"kind":"mc","stem":"손 들기로 자료를 모을 때의 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"그 자리에서 빠르게 조사할 수 있어요.","correct":true},{"t":"붙인 쪽지가 한눈에 모여요.","mis":"M4-1-u5-X16"},{"t":"차분히 생각해서 답할 수 있어요.","mis":"M4-1-u5-X16"},{"t":"많은 사람의 답도 자동으로 집계돼요.","mis":"M4-1-u5-X16"}],"explanation":["손 들기는 빠르고, 붙임쪽지는 한눈에 모이고, 종이는 차분하고, 온라인 설문은 자동으로 집계돼요.","손 들기 — 그 자리에서 빠르게 조사할 수 있어요.","상황에 맞게 방법을 골라요."],"variant_rule":{"alt":[{"stem":"붙임쪽지로 자료를 모을 때의 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"붙인 쪽지가 한눈에 모여요.","correct":true},{"t":"그 자리에서 빠르게 조사할 수 있어요.","mis":"M4-1-u5-X16"},{"t":"차분히 생각해서 답할 수 있어요.","mis":"M4-1-u5-X16"},{"t":"많은 사람의 답도 자동으로 집계돼요.","mis":"M4-1-u5-X16"}],"explanation":["손 들기는 빠르고, 붙임쪽지는 한눈에 모이고, 종이는 차분하고, 온라인 설문은 자동으로 집계돼요.","붙임쪽지 — 붙인 쪽지가 한눈에 모여요.","상황에 맞게 방법을 골라요."],"asset":null},{"stem":"종이에 적어 내기로 자료를 모을 때의 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"차분히 생각해서 답할 수 있어요.","correct":true},{"t":"그 자리에서 빠르게 조사할 수 있어요.","mis":"M4-1-u5-X16"},{"t":"붙인 쪽지가 한눈에 모여요.","mis":"M4-1-u5-X16"},{"t":"많은 사람의 답도 자동으로 집계돼요.","mis":"M4-1-u5-X16"}],"explanation":["손 들기는 빠르고, 붙임쪽지는 한눈에 모이고, 종이는 차분하고, 온라인 설문은 자동으로 집계돼요.","종이에 적어 내기 — 차분히 생각해서 답할 수 있어요.","상황에 맞게 방법을 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_basic#5','math',4,1,'u5','L06','g4_1_math_u5_L06_basic','lesson_basic','M4-1-u5-C9',2,'mc','auto','학교 4학년 전체 100명을 조사하려고 해요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?',ARRAY['M4-1-u5-X16']::text[],true,'{"seq":5,"concept":"M4-1-u5-C9","difficulty":2,"kind":"mc","stem":"학교 4학년 전체 100명을 조사하려고 해요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"온라인 설문 — 여러 반의 답이 자동으로 집계되니까요.","correct":true},{"t":"손 들기 — 100명이 한곳에 모이기 쉬우니까요.","mis":"M4-1-u5-X16"},{"t":"붙임쪽지 — 쪽지 100장이면 충분하니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 결과가 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 여러 반의 답이 자동으로 집계되니까요.","그래서 온라인 설문이 알맞아요."],"variant_rule":{"alt":[{"stem":"쉬는 시간이 거의 끝나서 우리 반에 아주 빠르게 물어봐야 해요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"손 들기 — 그 자리에서 빠르게 셀 수 있으니까요.","correct":true},{"t":"온라인 설문 — 기기를 나눠 주고 기다리면 되니까요.","mis":"M4-1-u5-X16"},{"t":"종이에 적어 내기 — 걷어서 세면 되니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 걸리는 시간이 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 그 자리에서 빠르게 셀 수 있으니까요.","그래서 손 들기가 알맞아요."],"asset":null},{"stem":"친구들이 다른 친구 눈치를 보지 않고 차분히 답하게 하고 싶어요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"종이에 적어 내기 — 혼자 차분히 생각해서 쓸 수 있으니까요.","correct":true},{"t":"손 들기 — 누가 어디에 드는지 다 보이니까요.","mis":"M4-1-u5-X16"},{"t":"붙임쪽지 — 모두 앞에 나와 붙이니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 혼자 차분히 생각해서 쓸 수 있으니까요.","그래서 종이에 적어 내기가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_basic#6','math',4,1,'u5','L06','g4_1_math_u5_L06_basic','lesson_basic','M4-1-u5-C9',2,'sa','auto','조사 결과 일부가 지워졌어요. 우리 반 42명이 모두 답했고 합계가 42명일 때, 떡볶이를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u5-C9","difficulty":2,"kind":"sa","stem":"조사 결과 일부가 지워졌어요. 우리 반 42명이 모두 답했고 합계가 42명일 때, 떡볶이를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["합계에서 나머지 항목의 수를 빼요.","나머지의 합: 11 + 9 + 7 + 3 = 30.","42 − 30 = 12 — 12명이에요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","만두"],"counts":[null,11,9,7,3],"vh":"학생 수","unit":"명","total":42,"title":"좋아하는 간식별 학생 수"},"variant_rule":{"alt":[{"stem":"조사 결과 일부가 지워졌어요. 우리 반 32명이 모두 답했고 합계가 32명일 때, 고양이를 기르고 싶은 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["합계에서 나머지 항목의 수를 빼요.","나머지의 합: 11 + 6 + 1 + 4 = 22.","32 − 22 = 10 — 10명이에요."],"asset":{"type":"picg","only":"table","head":"동물","cols":["강아지","고양이","토끼","햄스터","금붕어"],"counts":[11,null,6,1,4],"vh":"학생 수","unit":"명","total":32,"title":"기르고 싶은 동물별 학생 수"}},{"stem":"조사 결과 일부가 지워졌어요. 우리 반 37명이 모두 답했고 합계가 37명일 때, 딸기를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["합계에서 나머지 항목의 수를 빼요.","나머지의 합: 3 + 8 + 7 + 9 = 27.","37 − 27 = 10 — 10명이에요."],"asset":{"type":"picg","only":"table","head":"과일","cols":["사과","포도","딸기","귤","배"],"counts":[3,8,null,7,9],"vh":"학생 수","unit":"명","total":37,"title":"좋아하는 과일별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_basic#7','math',4,1,'u5','L06','g4_1_math_u5_L06_basic','lesson_basic','M4-1-u5-C9',2,'mc','auto','주제가 「우리 반이 좋아하는 계절」일 때 항목 묶음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X13']::text[],true,'{"seq":7,"concept":"M4-1-u5-C9","difficulty":2,"kind":"mc","stem":"주제가 「우리 반이 좋아하는 계절」일 때 항목 묶음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"봄 · 여름 · 가을 · 겨울","correct":true},{"t":"축구 · 야구 · 수영 · 달리기","mis":"M4-1-u5-X13"},{"t":"1월 · 2월 · 3월 · 4월","mis":"M4-1-u5-X13"},{"t":"좋아요 · 싫어요","mis":"M4-1-u5-X13"}],"explanation":["항목은 주제에 맞게, 답을 몇 가지 갈래로 나눈 것이에요.","항목끼리 겹치면 안 되고, 고르지 못한 친구를 위해 기타를 둘 수 있어요.","그래서 「봄 · 여름 · 가을 · 겨울」이 알맞아요."],"variant_rule":{"alt":[{"stem":"주제가 「우리 반이 좋아하는 운동」일 때 항목 묶음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"축구 · 피구 · 수영 · 기타","correct":true},{"t":"축구 · 공놀이 · 피구 · 기타","mis":"M4-1-u5-X14"},{"t":"봄 · 여름 · 가을 · 겨울","mis":"M4-1-u5-X13"},{"t":"잘해요 · 못해요","mis":"M4-1-u5-X13"}],"explanation":["항목은 주제에 맞게, 답을 몇 가지 갈래로 나눈 것이에요.","항목끼리 겹치면 안 되고, 고르지 못한 친구를 위해 기타를 둘 수 있어요.","그래서 「축구 · 피구 · 수영 · 기타」가 알맞아요."],"asset":null},{"stem":"주제가 「우리 반이 기르고 싶은 동물」일 때 항목 묶음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"강아지 · 고양이 · 토끼 · 기타","correct":true},{"t":"강아지 · 털 있는 동물 · 토끼 · 기타","mis":"M4-1-u5-X14"},{"t":"사과 · 포도 · 귤 · 배","mis":"M4-1-u5-X13"},{"t":"많이 · 조금","mis":"M4-1-u5-X13"}],"explanation":["항목은 주제에 맞게, 답을 몇 가지 갈래로 나눈 것이에요.","항목끼리 겹치면 안 되고, 고르지 못한 친구를 위해 기타를 둘 수 있어요.","그래서 「강아지 · 고양이 · 토끼 · 기타」가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_basic#8','math',4,1,'u5','L06','g4_1_math_u5_L06_basic','lesson_basic','M4-1-u5-C9',2,'mc','auto','우리 반 친구들에게 물어서 막대그래프로 나타낼 조사 주제로 가장 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X13']::text[],true,'{"seq":8,"concept":"M4-1-u5-C9","difficulty":2,"kind":"mc","stem":"우리 반 친구들에게 물어서 막대그래프로 나타낼 조사 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리 반이 좋아하는 급식 메뉴","correct":true},{"t":"우주의 크기","mis":"M4-1-u5-X13"},{"t":"바닷물의 양","mis":"M4-1-u5-X13"},{"t":"내년 여름의 날씨","mis":"M4-1-u5-X13"}],"explanation":["좋은 주제는 우리 반 친구들에게 직접 물어볼 수 있어요.","답을 몇 가지 갈래로 나눌 수 있어야 해요.","「우리 반이 좋아하는 급식 메뉴」는 물어보고 갈래로 나눌 수 있어요."],"variant_rule":{"alt":[{"stem":"우리 반 친구들에게 물어서 막대그래프로 나타낼 조사 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리 반이 가고 싶은 체험학습 장소","correct":true},{"t":"바닷물의 양","mis":"M4-1-u5-X13"},{"t":"내년 여름의 날씨","mis":"M4-1-u5-X13"},{"t":"개미가 사는 햇수","mis":"M4-1-u5-X13"}],"explanation":["좋은 주제는 우리 반 친구들에게 직접 물어볼 수 있어요.","답을 몇 가지 갈래로 나눌 수 있어야 해요.","「우리 반이 가고 싶은 체험학습 장소」는 물어보고 갈래로 나눌 수 있어요."],"asset":null},{"stem":"우리 반 친구들에게 물어서 막대그래프로 나타낼 조사 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리 반이 즐겨 하는 놀이","correct":true},{"t":"내년 여름의 날씨","mis":"M4-1-u5-X13"},{"t":"개미가 사는 햇수","mis":"M4-1-u5-X13"},{"t":"하늘에 떠 있는 구름의 수","mis":"M4-1-u5-X13"}],"explanation":["좋은 주제는 우리 반 친구들에게 직접 물어볼 수 있어요.","답을 몇 가지 갈래로 나눌 수 있어야 해요.","「우리 반이 즐겨 하는 놀이」는 물어보고 갈래로 나눌 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_basic#9','math',4,1,'u5','L06','g4_1_math_u5_L06_basic','lesson_basic','M4-1-u5-C9',2,'ox','auto','항목끼리 겹쳐도 조사하는 데에는 문제가 없어요.',ARRAY['M4-1-u5-X14']::text[],true,'{"seq":9,"concept":"M4-1-u5-C9","difficulty":2,"kind":"ox","stem":"항목끼리 겹쳐도 조사하는 데에는 문제가 없어요.","answer":"X","reason_options":[{"t":"겹치면 어디에 답할지 헷갈려서","correct":true},{"t":"항목이 많을수록 좋아서","mis":"M4-1-u5-X14"}],"mis":"M4-1-u5-X14","explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 방법은 상황에 맞게 골라요.","한 사람이 한 번만 답하고, 합계가 인원과 같은지 확인해요."],"variant_rule":{"alt":[{"stem":"조사가 끝나면 합계가 우리 반 인원과 같은지 확인해요.","answer":"O","reason_options":[{"t":"두 번 답하거나 빠진 친구가 없는지 알 수 있어서","correct":true},{"t":"합계는 인원과 달라도 괜찮아서","mis":"M4-1-u5-X15"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 방법은 상황에 맞게 골라요.","한 사람이 한 번만 답하고, 합계가 인원과 같은지 확인해요."],"asset":null},{"stem":"온라인 설문은 많은 사람의 답도 자동으로 집계할 수 있어요.","answer":"O","reason_options":[{"t":"답이 기기에서 저절로 모여서","correct":true},{"t":"손으로 하나하나 세야 해서","mis":"M4-1-u5-X16"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 방법은 상황에 맞게 골라요.","한 사람이 한 번만 답하고, 합계가 인원과 같은지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_basic#10','math',4,1,'u5','L06','g4_1_math_u5_L06_basic','lesson_basic','M4-1-u5-C9',3,'mc','auto','조사를 했더니 합계가 26명이 나왔어요. 우리 반은 24명인데요! 무슨 일이 생긴 걸까요?',ARRAY['M4-1-u5-X21','M4-1-u5-X14','M4-1-u5-X15']::text[],true,'{"seq":10,"concept":"M4-1-u5-C9","difficulty":3,"kind":"mc","stem":"조사를 했더니 합계가 26명이 나왔어요. 우리 반은 24명인데요! 무슨 일이 생긴 걸까요?","options":[{"t":"두 번 답한 친구가 있어요 — 한 사람은 한 번만 답해야 해요.","correct":true},{"t":"빠진 친구가 있어요 — 모두 한 번씩 답해야 해요.","mis":"M4-1-u5-X21"},{"t":"항목을 너무 많이 만들었어요.","mis":"M4-1-u5-X14"},{"t":"합계는 인원과 달라도 괜찮아요.","mis":"M4-1-u5-X15"}],"explanation":["합계는 우리 반 인원과 같아야 해요.","합계 26명이 인원 24명보다 많아요.","많으면 두 번 답한 친구가, 적으면 빠진 친구가 있는 거예요."],"variant_rule":{"alt":[{"stem":"조사를 했더니 합계가 24명이 나왔어요. 우리 반은 25명인데요! 무슨 일이 생긴 걸까요?","options":[{"t":"빠진 친구가 있어요 — 모두 한 번씩 답해야 해요.","correct":true},{"t":"두 번 답한 친구가 있어요 — 한 사람은 한 번만 답해야 해요.","mis":"M4-1-u5-X21"},{"t":"항목을 너무 많이 만들었어요.","mis":"M4-1-u5-X14"},{"t":"합계는 인원과 달라도 괜찮아요.","mis":"M4-1-u5-X15"}],"explanation":["합계는 우리 반 인원과 같아야 해요.","합계 24명이 인원 25명보다 적어요.","많으면 두 번 답한 친구가, 적으면 빠진 친구가 있는 거예요."],"asset":null},{"stem":"조사를 했더니 합계가 27명이 나왔어요. 우리 반은 26명인데요! 무슨 일이 생긴 걸까요?","options":[{"t":"두 번 답한 친구가 있어요 — 한 사람은 한 번만 답해야 해요.","correct":true},{"t":"빠진 친구가 있어요 — 모두 한 번씩 답해야 해요.","mis":"M4-1-u5-X21"},{"t":"항목을 너무 많이 만들었어요.","mis":"M4-1-u5-X14"},{"t":"합계는 인원과 달라도 괜찮아요.","mis":"M4-1-u5-X15"}],"explanation":["합계는 우리 반 인원과 같아야 해요.","합계 27명이 인원 26명보다 많아요.","많으면 두 번 답한 친구가, 적으면 빠진 친구가 있는 거예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_challenge#1','math',4,1,'u5','L06','g4_1_math_u5_L06_challenge','lesson_challenge','M4-1-u5-C9',2,'mc','auto','손 들기로 자료를 모을 때의 아쉬운 점으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X16']::text[],true,'{"seq":1,"concept":"M4-1-u5-C9","difficulty":2,"kind":"mc","stem":"손 들기로 자료를 모을 때의 아쉬운 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 번에 한 항목씩만 셀 수 있어요.","correct":true},{"t":"쪽지를 미리 준비해야 해요.","mis":"M4-1-u5-X16"},{"t":"모아서 세는 데 시간이 걸려요.","mis":"M4-1-u5-X16"},{"t":"스마트 기기가 있어야 해요.","mis":"M4-1-u5-X16"}],"explanation":["손 들기는 빠르고, 붙임쪽지는 한눈에 모이고, 종이는 차분하고, 온라인 설문은 자동으로 집계돼요.","손 들기 — 한 번에 한 항목씩만 셀 수 있어요.","상황에 맞게 방법을 골라요."],"variant_rule":{"alt":[{"stem":"붙임쪽지로 자료를 모을 때의 아쉬운 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"쪽지를 미리 준비해야 해요.","correct":true},{"t":"한 번에 한 항목씩만 셀 수 있어요.","mis":"M4-1-u5-X16"},{"t":"모아서 세는 데 시간이 걸려요.","mis":"M4-1-u5-X16"},{"t":"스마트 기기가 있어야 해요.","mis":"M4-1-u5-X16"}],"explanation":["손 들기는 빠르고, 붙임쪽지는 한눈에 모이고, 종이는 차분하고, 온라인 설문은 자동으로 집계돼요.","붙임쪽지 — 쪽지를 미리 준비해야 해요.","상황에 맞게 방법을 골라요."],"asset":null},{"stem":"종이에 적어 내기로 자료를 모을 때의 아쉬운 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"모아서 세는 데 시간이 걸려요.","correct":true},{"t":"한 번에 한 항목씩만 셀 수 있어요.","mis":"M4-1-u5-X16"},{"t":"쪽지를 미리 준비해야 해요.","mis":"M4-1-u5-X16"},{"t":"스마트 기기가 있어야 해요.","mis":"M4-1-u5-X16"}],"explanation":["손 들기는 빠르고, 붙임쪽지는 한눈에 모이고, 종이는 차분하고, 온라인 설문은 자동으로 집계돼요.","종이에 적어 내기 — 모아서 세는 데 시간이 걸려요.","상황에 맞게 방법을 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_challenge#2','math',4,1,'u5','L06','g4_1_math_u5_L06_challenge','lesson_challenge','M4-1-u5-C9',2,'mc','auto','조사가 끝나면 꼭 확인할 것은 무엇인가요?',ARRAY['M4-1-u5-X15','M4-1-u5-X13','M4-1-u5-X16']::text[],true,'{"seq":2,"concept":"M4-1-u5-C9","difficulty":2,"kind":"mc","stem":"조사가 끝나면 꼭 확인할 것은 무엇인가요?","options":[{"t":"합계가 인원과 같은지","correct":true},{"t":"가장 많은 항목이 무엇인지만","mis":"M4-1-u5-X15"},{"t":"항목의 이름이 멋있는지","mis":"M4-1-u5-X13"},{"t":"조사 방법이 가장 빨랐는지","mis":"M4-1-u5-X16"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"variant_rule":{"alt":[{"stem":"항목을 정할 때 고르지 못한 친구를 위해 두면 좋은 칸은 무엇인가요?","options":[{"t":"기타","correct":true},{"t":"합계","mis":"M4-1-u5-X14"},{"t":"제목","mis":"M4-1-u5-X14"},{"t":"단위","mis":"M4-1-u5-X14"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"asset":null},{"stem":"조사할 때 한 사람은 몇 번 답해야 하나요?","options":[{"t":"한 번만 답해요.","correct":true},{"t":"두 번씩 답해요.","mis":"M4-1-u5-X15"},{"t":"원하는 만큼 답해요.","mis":"M4-1-u5-X15"},{"t":"답하지 않아도 돼요.","mis":"M4-1-u5-X15"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
