INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_challenge#4','math',4,1,'u5','L06','g4_1_math_u5_L06_challenge','lesson_challenge','M4-1-u5-C9',3,'error','auto','모둠 친구들이 자료를 모으며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u5-X14','M4-1-u5-X21']::text[],true,'{"seq":4,"concept":"M4-1-u5-C9","difficulty":3,"kind":"error","stem":"모둠 친구들이 자료를 모으며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「항목에 불고기와 고기 반찬을 둘 다 넣자.」","correct":true,"mis_target":"M4-1-u5-X14"},{"t":"지아 — 「먼저 조사할 주제를 정하자.」","mis":"M4-1-u5-X21"},{"t":"준서 — 「고르지 못한 친구를 위해 기타 칸을 두자.」","mis":"M4-1-u5-X21"},{"t":"민서 — 「한 사람은 한 번만 답하게 하자.」","mis":"M4-1-u5-X21"}],"explanation":["주제 → 항목 → 방법 → 조사의 차례로 모아요.","하랑의 말은 자료를 바르게 모으는 방법과 맞지 않아요.","항목은 겹치지 않게, 방법은 상황에 맞게, 합계는 인원과 같게 해요."],"variant_rule":{"alt":[{"stem":"모둠 친구들이 자료를 모으며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「합계가 인원보다 많아도 괜찮아.」","correct":true,"mis_target":"M4-1-u5-X15"},{"t":"준서 — 「고르지 못한 친구를 위해 기타 칸을 두자.」","mis":"M4-1-u5-X21"},{"t":"민서 — 「한 사람은 한 번만 답하게 하자.」","mis":"M4-1-u5-X21"},{"t":"도윤 — 「끝나면 합계를 꼭 확인하자.」","mis":"M4-1-u5-X21"}],"explanation":["주제 → 항목 → 방법 → 조사의 차례로 모아요.","지아의 말은 자료를 바르게 모으는 방법과 맞지 않아요.","항목은 겹치지 않게, 방법은 상황에 맞게, 합계는 인원과 같게 해요."],"asset":null},{"stem":"모둠 친구들이 자료를 모으며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「100명은 손 들기로 한꺼번에 세면 돼.」","correct":true,"mis_target":"M4-1-u5-X16"},{"t":"민서 — 「한 사람은 한 번만 답하게 하자.」","mis":"M4-1-u5-X21"},{"t":"도윤 — 「끝나면 합계를 꼭 확인하자.」","mis":"M4-1-u5-X21"},{"t":"서윤 — 「먼저 조사할 주제를 정하자.」","mis":"M4-1-u5-X21"}],"explanation":["주제 → 항목 → 방법 → 조사의 차례로 모아요.","준서의 말은 자료를 바르게 모으는 방법과 맞지 않아요.","항목은 겹치지 않게, 방법은 상황에 맞게, 합계는 인원과 같게 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_challenge#5','math',4,1,'u5','L06','g4_1_math_u5_L06_challenge','lesson_challenge','M4-1-u5-C9',3,'mc','auto','교실 게시판에 결과가 한눈에 모이는 모습을 보여 주고 싶어요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?',ARRAY['M4-1-u5-X16']::text[],true,'{"seq":5,"concept":"M4-1-u5-C9","difficulty":3,"kind":"mc","stem":"교실 게시판에 결과가 한눈에 모이는 모습을 보여 주고 싶어요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"붙임쪽지 — 붙이면 한눈에 모이니까요.","correct":true},{"t":"종이에 적어 내기 — 걷어서 따로 세니까요.","mis":"M4-1-u5-X16"},{"t":"손 들기 — 손을 내리면 사라지니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 붙이면 한눈에 모이니까요.","그래서 붙임쪽지가 알맞아요."],"variant_rule":{"alt":[{"stem":"멀리 떨어진 다른 학교 친구들과 함께 조사하려고 해요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"온라인 설문 — 멀리 있는 사람도 답할 수 있으니까요.","correct":true},{"t":"손 들기 — 그 자리에서 셀 수 있으니까요.","mis":"M4-1-u5-X16"},{"t":"붙임쪽지 — 우리 교실 게시판에 붙이면 되니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 멀리 있는 사람도 답할 수 있으니까요.","그래서 온라인 설문이 알맞아요."],"asset":null},{"stem":"스마트 기기가 없는 교실에서 우리 반 친구들이 좋아하는 것을 차분히 조사하려고 해요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"종이에 적어 내기 — 기기 없이도 차분히 답할 수 있으니까요.","correct":true},{"t":"온라인 설문 — 기기가 없어도 집계되니까요.","mis":"M4-1-u5-X16"},{"t":"손 들기 — 차분히 생각할 시간을 주니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 기기 없이도 차분히 답할 수 있으니까요.","그래서 종이에 적어 내기가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_challenge#6','math',4,1,'u5','L06','g4_1_math_u5_L06_challenge','lesson_challenge','M4-1-u5-C9',3,'sa','auto','우리 반은 25명인데 조사 결과의 합계가 23명이에요. 답하지 않고 빠진 친구는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u5-C9","difficulty":3,"kind":"sa","stem":"우리 반은 25명인데 조사 결과의 합계가 23명이에요. 답하지 않고 빠진 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["합계가 인원보다 적으면 빠진 친구가 있어요.","25 − 23 = 2.","2명이 빠졌어요 — 모두 한 번씩 답해야 해요."],"variant_rule":{"alt":[{"stem":"우리 반은 24명인데 조사 결과의 합계가 27명이에요. 몇 명이 한 번씩 더 답했다면, 두 번 답한 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["합계가 인원보다 많으면 두 번 답한 친구가 있어요.","27 − 24 = 3.","3명이 두 번 답했어요 — 한 사람은 한 번만 답해야 해요."],"asset":null},{"stem":"우리 반은 26명인데 조사 결과의 합계가 24명이에요. 답하지 않고 빠진 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["합계가 인원보다 적으면 빠진 친구가 있어요.","26 − 24 = 2.","2명이 빠졌어요 — 모두 한 번씩 답해야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_challenge#7','math',4,1,'u5','L06','g4_1_math_u5_L06_challenge','lesson_challenge','M4-1-u5-C9',3,'mc','auto','「우리 반이 좋아하는 간식」 조사의 항목을 정하려고 해요. 항목으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M4-1-u5-X21']::text[],true,'{"seq":7,"concept":"M4-1-u5-C9","difficulty":3,"kind":"mc","stem":"「우리 반이 좋아하는 간식」 조사의 항목을 정하려고 해요. 항목으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"분식 — 떡볶이와 겹쳐요.","correct":true},{"t":"김밥","mis":"M4-1-u5-X21"},{"t":"빵","mis":"M4-1-u5-X21"},{"t":"기타","mis":"M4-1-u5-X21"}],"explanation":["항목끼리 겹치면 어디에 답할지 헷갈려요.","「분식」에는 떡볶이가 들어가요.","그래서 「분식」은 항목으로 알맞지 않아요."],"variant_rule":{"alt":[{"stem":"「우리 반이 기르고 싶은 동물」 조사의 항목을 정하려고 해요. 항목으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"털 있는 동물 — 강아지와 겹쳐요.","correct":true},{"t":"고양이","mis":"M4-1-u5-X21"},{"t":"토끼","mis":"M4-1-u5-X21"},{"t":"기타","mis":"M4-1-u5-X21"}],"explanation":["항목끼리 겹치면 어디에 답할지 헷갈려요.","「털 있는 동물」에는 강아지가 들어가요.","그래서 「털 있는 동물」은 항목으로 알맞지 않아요."],"asset":null},{"stem":"「우리 반이 가고 싶은 체험학습 장소」 조사의 항목을 정하려고 해요. 항목으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"전시관 — 과학관과 겹쳐요.","correct":true},{"t":"박물관","mis":"M4-1-u5-X21"},{"t":"동물원","mis":"M4-1-u5-X21"},{"t":"기타","mis":"M4-1-u5-X21"}],"explanation":["항목끼리 겹치면 어디에 답할지 헷갈려요.","「전시관」에는 과학관이 들어가요.","그래서 「전시관」은 항목으로 알맞지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_challenge#8','math',4,1,'u5','L06','g4_1_math_u5_L06_challenge','lesson_challenge','M4-1-u5-C9',4,'sa','auto','조사 결과 일부가 지워졌어요. 우리 반 45명이 모두 답했고 합계가 45명일 때, 배구를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u5-C9","difficulty":4,"kind":"sa","stem":"조사 결과 일부가 지워졌어요. 우리 반 45명이 모두 답했고 합계가 45명일 때, 배구를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["합계에서 나머지 항목의 수를 빼요.","나머지의 합: 9 + 12 + 11 + 5 = 37.","45 − 37 = 8 — 8명이에요."],"asset":{"type":"picg","only":"table","head":"운동","cols":["축구","피구","수영","야구","배구"],"counts":[9,12,11,5,null],"vh":"학생 수","unit":"명","total":45,"title":"좋아하는 운동별 학생 수"},"variant_rule":{"alt":[{"stem":"조사 결과 일부가 지워졌어요. 우리 반 28명이 모두 답했고 합계가 28명일 때, 가을을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["합계에서 나머지 항목의 수를 빼요.","나머지의 합: 12 + 3 + 2 = 17.","28 − 17 = 11 — 11명이에요."],"asset":{"type":"picg","only":"table","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[12,3,null,2],"vh":"학생 수","unit":"명","total":28,"title":"좋아하는 계절별 학생 수"}},{"stem":"조사 결과 일부가 지워졌어요. 우리 반 47명이 모두 답했고 합계가 47명일 때, 방송 체험을 고른 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["합계에서 나머지 항목의 수를 빼요.","나머지의 합: 5 + 10 + 11 + 12 = 38.","47 − 38 = 9 — 9명이에요."],"asset":{"type":"picg","only":"table","head":"체험","cols":["로봇","요리","방송","소방","과학"],"counts":[5,10,null,11,12],"vh":"학생 수","unit":"명","total":47,"title":"가고 싶은 체험별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_challenge#9','math',4,1,'u5','L06','g4_1_math_u5_L06_challenge','lesson_challenge','M4-1-u5-C9',4,'sa','auto','우리 반은 22명인데 조사 결과의 합계가 25명이에요. 몇 명이 한 번씩 더 답했다면, 두 번 답한 친구는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u5-C9","difficulty":4,"kind":"sa","stem":"우리 반은 22명인데 조사 결과의 합계가 25명이에요. 몇 명이 한 번씩 더 답했다면, 두 번 답한 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["합계가 인원보다 많으면 두 번 답한 친구가 있어요.","25 − 22 = 3.","3명이 두 번 답했어요 — 한 사람은 한 번만 답해야 해요."],"variant_rule":{"alt":[{"stem":"우리 반은 28명인데 조사 결과의 합계가 26명이에요. 답하지 않고 빠진 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["합계가 인원보다 적으면 빠진 친구가 있어요.","28 − 26 = 2.","2명이 빠졌어요 — 모두 한 번씩 답해야 해요."],"asset":null},{"stem":"우리 반은 23명인데 조사 결과의 합계가 24명이에요. 몇 명이 한 번씩 더 답했다면, 두 번 답한 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["합계가 인원보다 많으면 두 번 답한 친구가 있어요.","24 − 23 = 1.","1명이 두 번 답했어요 — 한 사람은 한 번만 답해야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L06_challenge#10','math',4,1,'u5','L06','g4_1_math_u5_L06_challenge','lesson_challenge','M4-1-u5-C9',4,'essay','teacher','「우리 반이 좋아하는 운동」을 조사하려고 해요. 한 친구가 항목을 「축구 · 공놀이 · 수영」으로 정하고, 손 들기로 조사했더니 합계가 우리 반 인원 25명보다 많은 28명이 나왔어요. 무엇이 잘못되었는지 두 가지를 찾고, 어떻게 고치면 좋을지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-1-u5-C9","difficulty":4,"kind":"essay","stem":"「우리 반이 좋아하는 운동」을 조사하려고 해요. 한 친구가 항목을 「축구 · 공놀이 · 수영」으로 정하고, 손 들기로 조사했더니 합계가 우리 반 인원 25명보다 많은 28명이 나왔어요. 무엇이 잘못되었는지 두 가지를 찾고, 어떻게 고치면 좋을지 써 보세요.","answer_guide":{"answer":"예: 첫째, 「공놀이」에 「축구」가 들어가 항목이 겹친다. 겹치지 않게 「축구 · 피구 · 수영 · 기타」처럼 고친다. 둘째, 합계가 인원보다 많으니 두 번 손을 든 친구가 있다. 한 사람이 한 번만 답하게 하고, 끝나면 합계가 25명인지 확인한다.","scoring_points":["항목이 겹친 잘못을 찾고 고쳤는가","합계가 많아 두 번 답한 친구가 있다고 썼는가","한 번만 답하기·합계 확인을 썼는가"]},"explanation":["항목끼리 겹치면 헷갈려요.","합계가 인원보다 많으면 두 번 답한 거예요.","겹치지 않게 정하고, 한 번만 답하고, 합계를 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_basic#1','math',4,1,'u5','L07','g4_1_math_u5_L07_basic','lesson_basic','M4-1-u5-C10',1,'mc','auto','모은 쪽지를 표로 정리하면 무엇이 좋을까요?',ARRAY['M4-1-u5-X04','M4-1-u5-X11','M4-1-u5-X03']::text[],true,'{"seq":1,"concept":"M4-1-u5-C10","difficulty":1,"kind":"mc","stem":"모은 쪽지를 표로 정리하면 무엇이 좋을까요?","options":[{"t":"항목별 수와 합계를 한눈에 알 수 있어요.","correct":true},{"t":"쪽지가 더 많아 보여요.","mis":"M4-1-u5-X04"},{"t":"조사를 다시 하지 않아도 앞날을 알 수 있어요.","mis":"M4-1-u5-X11"},{"t":"막대의 굵기로 견줄 수 있어요.","mis":"M4-1-u5-X03"}],"explanation":["모은 자료는 표 → 막대그래프 → 해석의 길을 걸어요.","표는 수와 합계를, 그래프는 많고 적음을 보여 줘요.","표와 그래프의 값은 언제나 같고, 기사에는 그래프에 있는 사실만 써요."],"variant_rule":{"alt":[{"stem":"표를 막대그래프로 바꾸면 표보다 좋은 점은 무엇일까요?","options":[{"t":"많고 적음을 길이로 한눈에 견줄 수 있어요.","correct":true},{"t":"합계가 저절로 계산돼요.","mis":"M4-1-u5-X04"},{"t":"항목이 저절로 늘어나요.","mis":"M4-1-u5-X04"},{"t":"조사한 수가 더 커져요.","mis":"M4-1-u5-X17"}],"explanation":["모은 자료는 표 → 막대그래프 → 해석의 길을 걸어요.","표는 수와 합계를, 그래프는 많고 적음을 보여 줘요.","표와 그래프의 값은 언제나 같고, 기사에는 그래프에 있는 사실만 써요."],"asset":null},{"stem":"같은 자료를 나타낸 표와 막대그래프의 값은 어떤 관계인가요?","options":[{"t":"언제나 같아야 해요.","correct":true},{"t":"그래프의 값이 표보다 커야 해요.","mis":"M4-1-u5-X17"},{"t":"달라도 괜찮아요.","mis":"M4-1-u5-X17"},{"t":"표의 값을 그래프에 맞춰 고쳐요.","mis":"M4-1-u5-X17"}],"explanation":["모은 자료는 표 → 막대그래프 → 해석의 길을 걸어요.","표는 수와 합계를, 그래프는 많고 적음을 보여 줘요.","표와 그래프의 값은 언제나 같고, 기사에는 그래프에 있는 사실만 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_basic#2','math',4,1,'u5','L07','g4_1_math_u5_L07_basic','lesson_basic','M4-1-u5-C10',1,'sa','auto','표를 보고 답하세요. 카레와 국수를 모두 고른 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u5-C10","difficulty":1,"kind":"sa","stem":"표를 보고 답하세요. 카레와 국수를 모두 고른 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["표에서 카레는 9명, 국수는 7명이에요.","모두 몇 명인지는 더해요.","9 + 7 = 16 — 16명이에요."],"asset":{"type":"picg","only":"table","head":"급식 메뉴","cols":["불고기","잡채","카레","국수","기타"],"counts":[2,5,9,7,4],"vh":"학생 수","unit":"명","total":27,"title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"표를 보고 답하세요. 떡볶이와 빵을 모두 고른 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["표에서 떡볶이는 12명, 빵은 4명이에요.","모두 몇 명인지는 더해요.","12 + 4 = 16 — 16명이에요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","기타"],"counts":[12,8,6,4,2],"vh":"학생 수","unit":"명","total":32,"title":"좋아하는 간식별 학생 수"}},{"stem":"표를 보고 답하세요. 술래잡기와 공기를 모두 고른 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["표에서 술래잡기는 10명, 공기는 9명이에요.","모두 몇 명인지는 더해요.","10 + 9 = 19 — 19명이에요."],"asset":{"type":"picg","only":"table","head":"놀이","cols":["술래잡기","공기","줄넘기","피구","기타"],"counts":[10,9,5,6,3],"vh":"학생 수","unit":"명","total":33,"title":"즐겨 하는 놀이별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_basic#3','math',4,1,'u5','L07','g4_1_math_u5_L07_basic','lesson_basic','M4-1-u5-C10',1,'mc','auto','막대그래프를 보고 신문 기사를 쓸 때 지킬 것은 무엇인가요?',ARRAY['M4-1-u5-X11','M4-1-u5-X17','M4-1-u5-X21']::text[],true,'{"seq":3,"concept":"M4-1-u5-C10","difficulty":1,"kind":"mc","stem":"막대그래프를 보고 신문 기사를 쓸 때 지킬 것은 무엇인가요?","options":[{"t":"그래프에서 알 수 있는 사실만 써요.","correct":true},{"t":"재미있게 지어내도 돼요.","mis":"M4-1-u5-X11"},{"t":"그래프와 다른 수를 써도 돼요.","mis":"M4-1-u5-X17"},{"t":"가장 많은 것은 빼고 써요.","mis":"M4-1-u5-X21"}],"explanation":["모은 자료는 표 → 막대그래프 → 해석의 길을 걸어요.","표는 수와 합계를, 그래프는 많고 적음을 보여 줘요.","표와 그래프의 값은 언제나 같고, 기사에는 그래프에 있는 사실만 써요."],"variant_rule":{"alt":[{"stem":"쪽지를 세어 표에 적었더니 합계가 우리 반 인원과 같았어요. 무엇을 알 수 있나요?","options":[{"t":"빠짐없이, 겹침없이 조사되었다는 것","correct":true},{"t":"가장 인기 있는 항목을 고른 까닭","mis":"M4-1-u5-X11"},{"t":"그래프를 그리지 않아도 된다는 것","mis":"M4-1-u5-X18"},{"t":"눈금 한 칸이 1이라는 것","mis":"M4-1-u5-X02"}],"explanation":["모은 자료는 표 → 막대그래프 → 해석의 길을 걸어요.","표는 수와 합계를, 그래프는 많고 적음을 보여 줘요.","표와 그래프의 값은 언제나 같고, 기사에는 그래프에 있는 사실만 써요."],"asset":null},{"stem":"모둠 신문을 만드는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"자료 모으기 → 표 → 그래프 → 해석해서 쓰기","correct":true},{"t":"그래프 → 자료 모으기 → 표 → 해석해서 쓰기","mis":"M4-1-u5-X18"},{"t":"해석해서 쓰기 → 그래프 → 표 → 자료 모으기","mis":"M4-1-u5-X18"},{"t":"표 → 자료 모으기 → 해석해서 쓰기 → 그래프","mis":"M4-1-u5-X18"}],"explanation":["모은 자료는 표 → 막대그래프 → 해석의 길을 걸어요.","표는 수와 합계를, 그래프는 많고 적음을 보여 줘요.","표와 그래프의 값은 언제나 같고, 기사에는 그래프에 있는 사실만 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_basic#4','math',4,1,'u5','L07','g4_1_math_u5_L07_basic','lesson_basic','M4-1-u5-C10',1,'sa','auto','완성한 막대그래프예요. 눈금 한 칸이 1명일 때 불고기의 막대는 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u5-C10","difficulty":1,"kind":"sa","stem":"완성한 막대그래프예요. 눈금 한 칸이 1명일 때 불고기의 막대는 몇 칸인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["표에서 불고기는 9명이에요.","눈금 한 칸이 1명이니 9 ÷ 1로 구해요.","9칸이에요 — 표와 그래프는 같은 수를 나타내요."],"asset":{"type":"lgraph","mode":"bar","xs":["불고기","잡채","카레","국수","기타"],"series":[{"vals":[9,7,5,4,3]}],"step":1,"ymax":10,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"완성한 막대그래프예요. 눈금 한 칸이 2명일 때 빵의 막대는 몇 칸인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["표에서 빵은 10명이에요.","눈금 한 칸이 2명이니 10 ÷ 2로 구해요.","5칸이에요 — 표와 그래프는 같은 수를 나타내요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","기타"],"series":[{"vals":[2,4,12,10,8]}],"step":2,"ymax":14,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}},{"stem":"완성한 막대그래프예요. 눈금 한 칸이 1명일 때 피구의 막대는 몇 칸인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["표에서 피구는 4명이에요.","눈금 한 칸이 1명이니 4 ÷ 1로 구해요.","4칸이에요 — 표와 그래프는 같은 수를 나타내요."],"asset":{"type":"lgraph","mode":"bar","xs":["술래잡기","공기","줄넘기","피구","기타"],"series":[{"vals":[8,3,7,4,5]}],"step":1,"ymax":9,"ylab":"(명)","title":"즐겨 하는 놀이별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_basic#5','math',4,1,'u5','L07','g4_1_math_u5_L07_basic','lesson_basic','M4-1-u5-C10',2,'sa','auto','표에서 기타는 2명이에요. 아래 막대그래프에 아직 기타 막대를 그리지 못했어요. 몇 칸으로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u5-C10","difficulty":2,"kind":"sa","stem":"표에서 기타는 2명이에요. 아래 막대그래프에 아직 기타 막대를 그리지 못했어요. 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["눈금 한 칸은 1명이에요.","2 ÷ 1 = 2.","기타 막대는 2칸으로 그려요 — 표의 수를 그대로 따라요."],"asset":{"type":"lgraph","mode":"bar","xs":["불고기","잡채","카레","국수","기타"],"series":[{"vals":[7,5,4,6,2]}],"step":1,"ymax":8,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수","hide":[[0,4]]},"variant_rule":{"alt":[{"stem":"표에서 기타는 6명이에요. 아래 막대그래프에 아직 기타 막대를 그리지 못했어요. 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["눈금 한 칸은 2명이에요.","6 ÷ 2 = 3.","기타 막대는 3칸으로 그려요 — 표의 수를 그대로 따라요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","기타"],"series":[{"vals":[2,12,10,14,6]}],"step":2,"ymax":16,"ylab":"(명)","title":"좋아하는 간식별 학생 수","hide":[[0,4]]}},{"stem":"표에서 기타는 7명이에요. 아래 막대그래프에 아직 기타 막대를 그리지 못했어요. 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["눈금 한 칸은 1명이에요.","7 ÷ 1 = 7.","기타 막대는 7칸으로 그려요 — 표의 수를 그대로 따라요."],"asset":{"type":"lgraph","mode":"bar","xs":["술래잡기","공기","줄넘기","피구","기타"],"series":[{"vals":[10,9,3,4,7]}],"step":1,"ymax":11,"ylab":"(명)","title":"즐겨 하는 놀이별 학생 수","hide":[[0,4]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_basic#6','math',4,1,'u5','L07','g4_1_math_u5_L07_basic','lesson_basic','M4-1-u5-C10',2,'mc','auto','이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X11','M4-1-u5-X21']::text[],true,'{"seq":6,"concept":"M4-1-u5-C10","difficulty":2,"kind":"mc","stem":"이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 메뉴는 국수다.」","correct":true},{"t":"「내일은 카레가 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「국수는 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「카레가 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 국수의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["불고기","잡채","카레","국수","기타"],"series":[{"vals":[7,5,4,9,2]}],"step":1,"ymax":10,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 간식은 빵이다.」","correct":true},{"t":"「내일은 과일이 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「빵은 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「과일이 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 빵의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","기타"],"series":[{"vals":[6,10,4,12,2]}],"step":2,"ymax":14,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 놀이는 공기다.」","correct":true},{"t":"「내일은 줄넘기가 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「공기는 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「줄넘기가 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 공기의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["술래잡기","공기","줄넘기","피구","기타"],"series":[{"vals":[7,9,3,8,4]}],"step":1,"ymax":10,"ylab":"(명)","title":"즐겨 하는 놀이별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_basic#7','math',4,1,'u5','L07','g4_1_math_u5_L07_basic','lesson_basic','M4-1-u5-C10',2,'mc','auto','눈금 한 칸이 1명인 막대그래프에서 불고기 막대가 9칸인데, 표에는 7명이라고 적혀 있어요. 어떻게 해야 할까요?',ARRAY['M4-1-u5-X17']::text[],true,'{"seq":7,"concept":"M4-1-u5-C10","difficulty":2,"kind":"mc","stem":"눈금 한 칸이 1명인 막대그래프에서 불고기 막대가 9칸인데, 표에는 7명이라고 적혀 있어요. 어떻게 해야 할까요?","options":[{"t":"표와 그래프는 같은 자료니까 7칸으로 고쳐요.","correct":true},{"t":"막대가 길수록 보기 좋으니 그대로 둬요.","mis":"M4-1-u5-X17"},{"t":"표의 수를 9로 바꿔요.","mis":"M4-1-u5-X17"},{"t":"불고기 항목을 지워 버려요.","mis":"M4-1-u5-X17"}],"explanation":["그래프는 표에 적힌 수를 그대로 따라야 해요.","표에서 불고기는 7명이니 막대는 7칸이어야 해요.","그래서 그래프의 막대를 7칸으로 고쳐요."],"variant_rule":{"alt":[{"stem":"눈금 한 칸이 1명인 막대그래프에서 잡채 막대가 5칸인데, 표에는 6명이라고 적혀 있어요. 어떻게 해야 할까요?","options":[{"t":"표와 그래프는 같은 자료니까 6칸으로 고쳐요.","correct":true},{"t":"막대가 짧아도 괜찮으니 그대로 둬요.","mis":"M4-1-u5-X17"},{"t":"표의 수를 5로 바꿔요.","mis":"M4-1-u5-X17"},{"t":"잡채 항목을 지워 버려요.","mis":"M4-1-u5-X17"}],"explanation":["그래프는 표에 적힌 수를 그대로 따라야 해요.","표에서 잡채는 6명이니 막대는 6칸이어야 해요.","그래서 그래프의 막대를 6칸으로 고쳐요."],"asset":null},{"stem":"눈금 한 칸이 1명인 막대그래프에서 카레 막대가 10칸인데, 표에는 8명이라고 적혀 있어요. 어떻게 해야 할까요?","options":[{"t":"표와 그래프는 같은 자료니까 8칸으로 고쳐요.","correct":true},{"t":"막대가 길수록 보기 좋으니 그대로 둬요.","mis":"M4-1-u5-X17"},{"t":"표의 수를 10으로 바꿔요.","mis":"M4-1-u5-X17"},{"t":"카레 항목을 지워 버려요.","mis":"M4-1-u5-X17"}],"explanation":["그래프는 표에 적힌 수를 그대로 따라야 해요.","표에서 카레는 8명이니 막대는 8칸이어야 해요.","그래서 그래프의 막대를 8칸으로 고쳐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_basic#8','math',4,1,'u5','L07','g4_1_math_u5_L07_basic','lesson_basic','M4-1-u5-C10',2,'sa','auto','기사 문장 「국수가 1위, 잡채가 국수를 □명 차이로 뒤쫓아요.」에서 □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u5-C10","difficulty":2,"kind":"sa","stem":"기사 문장 「국수가 1위, 잡채가 국수를 □명 차이로 뒤쫓아요.」에서 □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["가장 긴 막대는 국수 8명, 둘째로 긴 막대는 잡채 5명이에요.","차는 큰 수에서 작은 수를 빼요.","8 − 5 = 3 — □는 3이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["불고기","잡채","카레","국수","기타"],"series":[{"vals":[4,5,3,8,2]}],"step":1,"ymax":9,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"기사 문장 「빵이 1위, 떡볶이가 빵을 □명 차이로 뒤쫓아요.」에서 □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["가장 긴 막대는 빵 14명, 둘째로 긴 막대는 떡볶이 12명이에요.","차는 큰 수에서 작은 수를 빼요.","14 − 12 = 2 — □는 2예요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","기타"],"series":[{"vals":[12,10,8,14,2]}],"step":2,"ymax":16,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}},{"stem":"기사 문장 「피구가 1위, 공기가 피구를 □명 차이로 뒤쫓아요.」에서 □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["가장 긴 막대는 피구 9명, 둘째로 긴 막대는 공기 6명이에요.","차는 큰 수에서 작은 수를 빼요.","9 − 6 = 3 — □는 3이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["술래잡기","공기","줄넘기","피구","기타"],"series":[{"vals":[5,6,4,9,2]}],"step":1,"ymax":10,"ylab":"(명)","title":"즐겨 하는 놀이별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_basic#9','math',4,1,'u5','L07','g4_1_math_u5_L07_basic','lesson_basic','M4-1-u5-C10',2,'ox','auto','표와 막대그래프의 값이 조금 달라도 괜찮아요.',ARRAY['M4-1-u5-X17']::text[],true,'{"seq":9,"concept":"M4-1-u5-C10","difficulty":2,"kind":"ox","stem":"표와 막대그래프의 값이 조금 달라도 괜찮아요.","answer":"X","reason_options":[{"t":"같은 자료를 나타내므로 값이 언제나 같아야 해서","correct":true},{"t":"그래프는 대강 그려도 되어서","mis":"M4-1-u5-X17"}],"mis":"M4-1-u5-X17","explanation":["모은 자료 → 표 → 막대그래프 → 해석의 차례예요.","표와 그래프의 값은 언제나 같아야 해요.","기사에는 그래프에 있는 사실만 써요."],"variant_rule":{"alt":[{"stem":"기사에는 그래프에서 알 수 있는 사실만 써요.","answer":"O","reason_options":[{"t":"그래프에 없는 것을 지어내면 소문이 되어서","correct":true},{"t":"재미있게 지어내야 읽히니까","mis":"M4-1-u5-X11"}],"explanation":["모은 자료 → 표 → 막대그래프 → 해석의 차례예요.","표와 그래프의 값은 언제나 같아야 해요.","기사에는 그래프에 있는 사실만 써요."],"asset":null},{"stem":"막대그래프를 보면 표보다 많고 적음을 한눈에 견주기 좋아요.","answer":"O","reason_options":[{"t":"막대의 길이로 견줄 수 있어서","correct":true},{"t":"그래프에는 수가 없어서","mis":"M4-1-u5-X04"}],"explanation":["모은 자료 → 표 → 막대그래프 → 해석의 차례예요.","표와 그래프의 값은 언제나 같아야 해요.","기사에는 그래프에 있는 사실만 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_basic#10','math',4,1,'u5','L07','g4_1_math_u5_L07_basic','lesson_basic','M4-1-u5-C10',3,'mc','auto','표의 내용은 「불고기 6명, 잡채 5명, 카레 7명, 국수 9명, 기타 2명」이에요. 친구가 그린 막대그래프에서 표와 다르게 그린 막대는 어느 것인가요?',ARRAY['M4-1-u5-X17']::text[],true,'{"seq":10,"concept":"M4-1-u5-C10","difficulty":3,"kind":"mc","stem":"표의 내용은 「불고기 6명, 잡채 5명, 카레 7명, 국수 9명, 기타 2명」이에요. 친구가 그린 막대그래프에서 표와 다르게 그린 막대는 어느 것인가요?","options":[{"t":"기타","correct":true},{"t":"불고기","mis":"M4-1-u5-X17"},{"t":"잡채","mis":"M4-1-u5-X17"},{"t":"카레","mis":"M4-1-u5-X17"}],"explanation":["표와 그래프의 값은 언제나 같아야 해요.","눈금 한 칸은 1명이에요 — 막대마다 표의 수와 견주어 봐요.","기타 막대는 3명인데 표에는 2명 — 이 막대를 고쳐야 해요."],"asset":{"type":"lgraph","mode":"bar","xs":["불고기","잡채","카레","국수","기타"],"series":[{"vals":[6,5,7,9,3]}],"step":1,"ymax":10,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"표의 내용은 「떡볶이 10명, 김밥 8명, 과일 12명, 빵 6명, 기타 4명」이에요. 친구가 그린 막대그래프에서 표와 다르게 그린 막대는 어느 것인가요?","options":[{"t":"과일","correct":true},{"t":"떡볶이","mis":"M4-1-u5-X17"},{"t":"김밥","mis":"M4-1-u5-X17"},{"t":"빵","mis":"M4-1-u5-X17"}],"explanation":["표와 그래프의 값은 언제나 같아야 해요.","눈금 한 칸은 2명이에요 — 막대마다 표의 수와 견주어 봐요.","과일 막대는 14명인데 표에는 12명 — 이 막대를 고쳐야 해요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","기타"],"series":[{"vals":[10,8,14,6,4]}],"step":2,"ymax":16,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}},{"stem":"표의 내용은 「술래잡기 8명, 공기 9명, 줄넘기 6명, 피구 4명, 기타 7명」이에요. 친구가 그린 막대그래프에서 표와 다르게 그린 막대는 어느 것인가요?","options":[{"t":"술래잡기","correct":true},{"t":"공기","mis":"M4-1-u5-X17"},{"t":"줄넘기","mis":"M4-1-u5-X17"},{"t":"피구","mis":"M4-1-u5-X17"}],"explanation":["표와 그래프의 값은 언제나 같아야 해요.","눈금 한 칸은 1명이에요 — 막대마다 표의 수와 견주어 봐요.","술래잡기 막대는 10명인데 표에는 8명 — 이 막대를 고쳐야 해요."],"asset":{"type":"lgraph","mode":"bar","xs":["술래잡기","공기","줄넘기","피구","기타"],"series":[{"vals":[10,9,6,4,7]}],"step":1,"ymax":11,"ylab":"(명)","title":"즐겨 하는 놀이별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_challenge#1','math',4,1,'u5','L07','g4_1_math_u5_L07_challenge','lesson_challenge','M4-1-u5-C10',2,'sa','auto','완성한 막대그래프예요. 눈금 한 칸이 1명일 때 카레의 막대는 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u5-C10","difficulty":2,"kind":"sa","stem":"완성한 막대그래프예요. 눈금 한 칸이 1명일 때 카레의 막대는 몇 칸인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["표에서 카레는 4명이에요.","눈금 한 칸이 1명이니 4 ÷ 1로 구해요.","4칸이에요 — 표와 그래프는 같은 수를 나타내요."],"asset":{"type":"lgraph","mode":"bar","xs":["불고기","잡채","카레","국수","기타"],"series":[{"vals":[7,5,4,9,6]}],"step":1,"ymax":10,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"완성한 막대그래프예요. 눈금 한 칸이 2명일 때 빵의 막대는 몇 칸인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["표에서 빵은 4명이에요.","눈금 한 칸이 2명이니 4 ÷ 2로 구해요.","2칸이에요 — 표와 그래프는 같은 수를 나타내요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","기타"],"series":[{"vals":[12,10,2,4,8]}],"step":2,"ymax":14,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}},{"stem":"완성한 막대그래프예요. 눈금 한 칸이 1명일 때 피구의 막대는 몇 칸인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["표에서 피구는 9명이에요.","눈금 한 칸이 1명이니 9 ÷ 1로 구해요.","9칸이에요 — 표와 그래프는 같은 수를 나타내요."],"asset":{"type":"lgraph","mode":"bar","xs":["술래잡기","공기","줄넘기","피구","기타"],"series":[{"vals":[3,10,5,9,2]}],"step":1,"ymax":11,"ylab":"(명)","title":"즐겨 하는 놀이별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_challenge#2','math',4,1,'u5','L07','g4_1_math_u5_L07_challenge','lesson_challenge','M4-1-u5-C10',2,'ox','auto','그래프를 먼저 그리고 나중에 자료를 모아도 돼요.',ARRAY['M4-1-u5-X18']::text[],true,'{"seq":2,"concept":"M4-1-u5-C10","difficulty":2,"kind":"ox","stem":"그래프를 먼저 그리고 나중에 자료를 모아도 돼요.","answer":"X","reason_options":[{"t":"자료를 모아 표로 정리한 뒤 그래프로 나타내야 해서","correct":true},{"t":"차례는 상관없어서","mis":"M4-1-u5-X18"}],"mis":"M4-1-u5-X18","explanation":["모은 자료 → 표 → 막대그래프 → 해석의 차례예요.","표와 그래프의 값은 언제나 같아야 해요.","기사에는 그래프에 있는 사실만 써요."],"variant_rule":{"alt":[{"stem":"그래프의 막대가 표와 다르면 표의 수를 그래프에 맞춰 고쳐요.","answer":"X","reason_options":[{"t":"표는 조사한 자료이니 그래프를 표에 맞춰 고쳐야 해서","correct":true},{"t":"그래프가 더 정확해서","mis":"M4-1-u5-X17"}],"explanation":["모은 자료 → 표 → 막대그래프 → 해석의 차례예요.","표와 그래프의 값은 언제나 같아야 해요.","기사에는 그래프에 있는 사실만 써요."],"asset":null},{"stem":"표의 합계가 우리 반 인원과 같으면 빠짐없이 조사된 거예요.","answer":"O","reason_options":[{"t":"모두 한 번씩 답했다는 뜻이라서","correct":true},{"t":"합계는 인원과 상관없어서","mis":"M4-1-u5-X15"}],"explanation":["모은 자료 → 표 → 막대그래프 → 해석의 차례예요.","표와 그래프의 값은 언제나 같아야 해요.","기사에는 그래프에 있는 사실만 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_challenge#3','math',4,1,'u5','L07','g4_1_math_u5_L07_challenge','lesson_challenge','M4-1-u5-C10',3,'mc','auto','이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X11','M4-1-u5-X21']::text[],true,'{"seq":3,"concept":"M4-1-u5-C10","difficulty":3,"kind":"mc","stem":"이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 메뉴는 카레다.」","correct":true},{"t":"「내일은 국수가 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「카레는 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「국수가 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 카레의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["불고기","잡채","카레","국수","기타"],"series":[{"vals":[5,6,8,3,2]}],"step":1,"ymax":9,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 간식은 과일이다.」","correct":true},{"t":"「내일은 김밥이 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「과일은 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「김밥이 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 과일의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","기타"],"series":[{"vals":[6,4,12,8,2]}],"step":2,"ymax":14,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 놀이는 피구다.」","correct":true},{"t":"「내일은 줄넘기가 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「피구는 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「줄넘기가 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 피구의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["술래잡기","공기","줄넘기","피구","기타"],"series":[{"vals":[7,6,3,8,2]}],"step":1,"ymax":9,"ylab":"(명)","title":"즐겨 하는 놀이별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_challenge#4','math',4,1,'u5','L07','g4_1_math_u5_L07_challenge','lesson_challenge','M4-1-u5-C10',3,'error','auto','모둠 신문을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u5-X11','M4-1-u5-X21']::text[],true,'{"seq":4,"concept":"M4-1-u5-C10","difficulty":3,"kind":"error","stem":"모둠 신문을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「카레가 1위니까 내일 급식도 카레가 나올 거야.」","correct":true,"mis_target":"M4-1-u5-X11"},{"t":"민서 — 「표의 수만큼 막대를 그리자.」","mis":"M4-1-u5-X21"},{"t":"도윤 — 「기사에는 그래프에 있는 사실만 쓰자.」","mis":"M4-1-u5-X21"},{"t":"서윤 — 「합계가 우리 반 인원과 같은지 보자.」","mis":"M4-1-u5-X21"}],"explanation":["자료 모으기 → 표 → 그래프 → 해석해서 쓰기의 차례예요.","준서의 말은 표·그래프·기사를 바르게 만드는 방법과 맞지 않아요.","그래프는 표를 그대로 따르고, 기사에는 사실만 써요."],"variant_rule":{"alt":[{"stem":"모둠 신문을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「표에는 7명인데 막대는 9칸으로 길게 그렸어. 멋있잖아.」","correct":true,"mis_target":"M4-1-u5-X17"},{"t":"도윤 — 「기사에는 그래프에 있는 사실만 쓰자.」","mis":"M4-1-u5-X21"},{"t":"서윤 — 「합계가 우리 반 인원과 같은지 보자.」","mis":"M4-1-u5-X21"},{"t":"시우 — 「가장 긴 막대가 1위야.」","mis":"M4-1-u5-X21"}],"explanation":["자료 모으기 → 표 → 그래프 → 해석해서 쓰기의 차례예요.","민서의 말은 표·그래프·기사를 바르게 만드는 방법과 맞지 않아요.","그래프는 표를 그대로 따르고, 기사에는 사실만 써요."],"asset":null},{"stem":"모둠 신문을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「그래프부터 그리고 표는 나중에 만들자.」","correct":true,"mis_target":"M4-1-u5-X18"},{"t":"서윤 — 「합계가 우리 반 인원과 같은지 보자.」","mis":"M4-1-u5-X21"},{"t":"시우 — 「가장 긴 막대가 1위야.」","mis":"M4-1-u5-X21"},{"t":"은우 — 「표의 수만큼 막대를 그리자.」","mis":"M4-1-u5-X21"}],"explanation":["자료 모으기 → 표 → 그래프 → 해석해서 쓰기의 차례예요.","도윤의 말은 표·그래프·기사를 바르게 만드는 방법과 맞지 않아요.","그래프는 표를 그대로 따르고, 기사에는 사실만 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_challenge#5','math',4,1,'u5','L07','g4_1_math_u5_L07_challenge','lesson_challenge','M4-1-u5-C10',3,'mc','auto','눈금 한 칸이 1명인 막대그래프에서 국수 막대가 3칸인데, 표에는 5명이라고 적혀 있어요. 어떻게 해야 할까요?',ARRAY['M4-1-u5-X17']::text[],true,'{"seq":5,"concept":"M4-1-u5-C10","difficulty":3,"kind":"mc","stem":"눈금 한 칸이 1명인 막대그래프에서 국수 막대가 3칸인데, 표에는 5명이라고 적혀 있어요. 어떻게 해야 할까요?","options":[{"t":"표와 그래프는 같은 자료니까 5칸으로 고쳐요.","correct":true},{"t":"막대가 짧아도 괜찮으니 그대로 둬요.","mis":"M4-1-u5-X17"},{"t":"표의 수를 3으로 바꿔요.","mis":"M4-1-u5-X17"},{"t":"국수 항목을 지워 버려요.","mis":"M4-1-u5-X17"}],"explanation":["그래프는 표에 적힌 수를 그대로 따라야 해요.","표에서 국수는 5명이니 막대는 5칸이어야 해요.","그래서 그래프의 막대를 5칸으로 고쳐요."],"variant_rule":{"alt":[{"stem":"눈금 한 칸이 1명인 막대그래프에서 떡볶이 막대가 8칸인데, 표에는 6명이라고 적혀 있어요. 어떻게 해야 할까요?","options":[{"t":"표와 그래프는 같은 자료니까 6칸으로 고쳐요.","correct":true},{"t":"막대가 길수록 보기 좋으니 그대로 둬요.","mis":"M4-1-u5-X17"},{"t":"표의 수를 8로 바꿔요.","mis":"M4-1-u5-X17"},{"t":"떡볶이 항목을 지워 버려요.","mis":"M4-1-u5-X17"}],"explanation":["그래프는 표에 적힌 수를 그대로 따라야 해요.","표에서 떡볶이는 6명이니 막대는 6칸이어야 해요.","그래서 그래프의 막대를 6칸으로 고쳐요."],"asset":null},{"stem":"눈금 한 칸이 1명인 막대그래프에서 김밥 막대가 4칸인데, 표에는 7명이라고 적혀 있어요. 어떻게 해야 할까요?","options":[{"t":"표와 그래프는 같은 자료니까 7칸으로 고쳐요.","correct":true},{"t":"막대가 짧아도 괜찮으니 그대로 둬요.","mis":"M4-1-u5-X17"},{"t":"표의 수를 4로 바꿔요.","mis":"M4-1-u5-X17"},{"t":"김밥 항목을 지워 버려요.","mis":"M4-1-u5-X17"}],"explanation":["그래프는 표에 적힌 수를 그대로 따라야 해요.","표에서 김밥은 7명이니 막대는 7칸이어야 해요.","그래서 그래프의 막대를 7칸으로 고쳐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_challenge#6','math',4,1,'u5','L07','g4_1_math_u5_L07_challenge','lesson_challenge','M4-1-u5-C10',3,'mc','auto','표의 내용은 「불고기 9명, 잡채 8명, 카레 6명, 국수 5명, 기타 7명」이에요. 친구가 그린 막대그래프에서 표와 다르게 그린 막대는 어느 것인가요?',ARRAY['M4-1-u5-X17']::text[],true,'{"seq":6,"concept":"M4-1-u5-C10","difficulty":3,"kind":"mc","stem":"표의 내용은 「불고기 9명, 잡채 8명, 카레 6명, 국수 5명, 기타 7명」이에요. 친구가 그린 막대그래프에서 표와 다르게 그린 막대는 어느 것인가요?","options":[{"t":"국수","correct":true},{"t":"불고기","mis":"M4-1-u5-X17"},{"t":"잡채","mis":"M4-1-u5-X17"},{"t":"카레","mis":"M4-1-u5-X17"}],"explanation":["표와 그래프의 값은 언제나 같아야 해요.","눈금 한 칸은 1명이에요 — 막대마다 표의 수와 견주어 봐요.","국수 막대는 4명인데 표에는 5명 — 이 막대를 고쳐야 해요."],"asset":{"type":"lgraph","mode":"bar","xs":["불고기","잡채","카레","국수","기타"],"series":[{"vals":[9,8,6,4,7]}],"step":1,"ymax":10,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"표의 내용은 「떡볶이 12명, 김밥 14명, 과일 8명, 빵 4명, 기타 2명」이에요. 친구가 그린 막대그래프에서 표와 다르게 그린 막대는 어느 것인가요?","options":[{"t":"과일","correct":true},{"t":"떡볶이","mis":"M4-1-u5-X17"},{"t":"김밥","mis":"M4-1-u5-X17"},{"t":"빵","mis":"M4-1-u5-X17"}],"explanation":["표와 그래프의 값은 언제나 같아야 해요.","눈금 한 칸은 2명이에요 — 막대마다 표의 수와 견주어 봐요.","과일 막대는 10명인데 표에는 8명 — 이 막대를 고쳐야 해요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","기타"],"series":[{"vals":[12,14,10,4,2]}],"step":2,"ymax":16,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}},{"stem":"표의 내용은 「술래잡기 7명, 공기 9명, 줄넘기 10명, 피구 6명, 기타 5명」이에요. 친구가 그린 막대그래프에서 표와 다르게 그린 막대는 어느 것인가요?","options":[{"t":"줄넘기","correct":true},{"t":"술래잡기","mis":"M4-1-u5-X17"},{"t":"공기","mis":"M4-1-u5-X17"},{"t":"피구","mis":"M4-1-u5-X17"}],"explanation":["표와 그래프의 값은 언제나 같아야 해요.","눈금 한 칸은 1명이에요 — 막대마다 표의 수와 견주어 봐요.","줄넘기 막대는 11명인데 표에는 10명 — 이 막대를 고쳐야 해요."],"asset":{"type":"lgraph","mode":"bar","xs":["술래잡기","공기","줄넘기","피구","기타"],"series":[{"vals":[7,9,11,6,5]}],"step":1,"ymax":12,"ylab":"(명)","title":"즐겨 하는 놀이별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_challenge#7','math',4,1,'u5','L07','g4_1_math_u5_L07_challenge','lesson_challenge','M4-1-u5-C10',3,'sa','auto','표에서 기타는 3명이에요. 아래 막대그래프에 아직 기타 막대를 그리지 못했어요. 몇 칸으로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u5-C10","difficulty":3,"kind":"sa","stem":"표에서 기타는 3명이에요. 아래 막대그래프에 아직 기타 막대를 그리지 못했어요. 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["눈금 한 칸은 1명이에요.","3 ÷ 1 = 3.","기타 막대는 3칸으로 그려요 — 표의 수를 그대로 따라요."],"asset":{"type":"lgraph","mode":"bar","xs":["불고기","잡채","카레","국수","기타"],"series":[{"vals":[8,7,2,4,3]}],"step":1,"ymax":9,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수","hide":[[0,4]]},"variant_rule":{"alt":[{"stem":"표에서 기타는 4명이에요. 아래 막대그래프에 아직 기타 막대를 그리지 못했어요. 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["눈금 한 칸은 2명이에요.","4 ÷ 2 = 2.","기타 막대는 2칸으로 그려요 — 표의 수를 그대로 따라요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","기타"],"series":[{"vals":[6,10,8,12,4]}],"step":2,"ymax":14,"ylab":"(명)","title":"좋아하는 간식별 학생 수","hide":[[0,4]]}},{"stem":"이번에는 다른 그림이에요. 표에서 기타는 3명이에요. 아래 막대그래프에 아직 기타 막대를 그리지 못했어요. 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["눈금 한 칸은 1명이에요.","3 ÷ 1 = 3.","기타 막대는 3칸으로 그려요 — 표의 수를 그대로 따라요."],"asset":{"type":"lgraph","mode":"bar","xs":["술래잡기","공기","줄넘기","피구","기타"],"series":[{"vals":[10,8,2,6,3]}],"step":1,"ymax":11,"ylab":"(명)","title":"즐겨 하는 놀이별 학생 수","hide":[[0,4]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_challenge#8','math',4,1,'u5','L07','g4_1_math_u5_L07_challenge','lesson_challenge','M4-1-u5-C10',4,'sa','auto','우리 반 34명이 모두 답한 간식 조사의 표에서 김밥의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 김밥 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u5-C10","difficulty":4,"kind":"sa","stem":"우리 반 34명이 모두 답한 간식 조사의 표에서 김밥의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 김밥 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["김밥의 수는 34 − (2 + 14 + 4 + 6) = 8명이에요.","눈금 한 칸이 2명이니 8 ÷ 2로 구해요.","4칸으로 그려요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","기타"],"counts":[2,null,14,4,6],"vh":"학생 수","unit":"명","total":34,"title":"좋아하는 간식별 학생 수"},"variant_rule":{"alt":[{"stem":"우리 반 42명이 모두 답한 간식 조사의 표에서 기타의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 기타 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["기타의 수는 42 − (14 + 6 + 2 + 8) = 12명이에요.","눈금 한 칸이 2명이니 12 ÷ 2로 구해요.","6칸으로 그려요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","기타"],"counts":[14,6,2,8,null],"vh":"학생 수","unit":"명","total":42,"title":"좋아하는 간식별 학생 수"}},{"stem":"우리 반 32명이 모두 답한 간식 조사의 표에서 기타의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 기타 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["기타의 수는 32 − (2 + 6 + 12 + 4) = 8명이에요.","눈금 한 칸이 2명이니 8 ÷ 2로 구해요.","4칸으로 그려요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","기타"],"counts":[2,6,12,4,null],"vh":"학생 수","unit":"명","total":32,"title":"좋아하는 간식별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_challenge#9','math',4,1,'u5','L07','g4_1_math_u5_L07_challenge','lesson_challenge','M4-1-u5-C10',4,'sa','auto','그래프를 보고 기사를 써요. 「우리 반 25명 가운데 1위와 2위 메뉴를 고른 학생이 □명이에요.」 □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u5-C10","difficulty":4,"kind":"sa","stem":"그래프를 보고 기사를 써요. 「우리 반 25명 가운데 1위와 2위 메뉴를 고른 학생이 □명이에요.」 □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["1위는 잡채 7명, 2위는 불고기 6명이에요.","두 수를 더해요.","7 + 6 = 13 — □는 13이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["불고기","잡채","카레","국수","기타"],"series":[{"vals":[6,7,3,5,4]}],"step":1,"ymax":8,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"그래프를 보고 기사를 써요. 「우리 반 38명 가운데 1위와 2위 간식을 고른 학생이 □명이에요.」 □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["1위는 빵 14명, 2위는 김밥 10명이에요.","두 수를 더해요.","14 + 10 = 24 — □는 24예요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","기타"],"series":[{"vals":[4,10,8,14,2]}],"step":2,"ymax":16,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}},{"stem":"그래프를 보고 기사를 써요. 「우리 반 30명 가운데 1위와 2위 놀이를 고른 학생이 □명이에요.」 □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["1위는 피구 10명, 2위는 줄넘기 8명이에요.","두 수를 더해요.","10 + 8 = 18 — □는 18이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["술래잡기","공기","줄넘기","피구","기타"],"series":[{"vals":[5,3,8,10,4]}],"step":1,"ymax":11,"ylab":"(명)","title":"즐겨 하는 놀이별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L07_challenge#10','math',4,1,'u5','L07','g4_1_math_u5_L07_challenge','lesson_challenge','M4-1-u5-C10',4,'essay','teacher','모둠이 붙임쪽지 25장으로 급식 조사를 했어요. 표는 불고기 7명, 잡채 4명, 카레 8명, 국수 2명, 기타 4명이에요. 그런데 그래프에는 불고기 막대가 9칸(눈금 한 칸 1명)으로 그려져 있고, 기사에는 「카레는 몸에 가장 좋은 음식이다.」라고 썼어요. 잘못된 곳 두 가지를 찾아 바르게 고치고, 그래프에서 알 수 있는 사실로 기사 문장을 하나 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-1-u5-C10","difficulty":4,"kind":"essay","stem":"모둠이 붙임쪽지 25장으로 급식 조사를 했어요. 표는 불고기 7명, 잡채 4명, 카레 8명, 국수 2명, 기타 4명이에요. 그런데 그래프에는 불고기 막대가 9칸(눈금 한 칸 1명)으로 그려져 있고, 기사에는 「카레는 몸에 가장 좋은 음식이다.」라고 썼어요. 잘못된 곳 두 가지를 찾아 바르게 고치고, 그래프에서 알 수 있는 사실로 기사 문장을 하나 써 보세요.","answer_guide":{"answer":"예: 첫째, 표에는 불고기가 7명이므로 그래프의 불고기 막대를 7칸으로 고쳐야 한다. 둘째, 몸에 좋은지는 그래프에 없으므로 기사에 쓰면 안 된다. 기사 문장: 「우리 반에서 가장 인기 있는 급식 메뉴는 8명이 고른 카레이다.」","scoring_points":["불고기 막대를 7칸으로 고쳤는가","몸에 좋다는 문장이 그래프에 없는 내용이라고 썼는가","그래프에 있는 사실로 기사 문장을 썼는가"]},"explanation":["표와 그래프의 값은 언제나 같아야 해요.","몸에 좋은지는 그래프에 없어요.","가장 긴 막대 카레(8명)가 1위라는 것은 그래프에 있는 사실이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_basic#1','math',4,1,'u5','L08','g4_1_math_u5_L08_basic','lesson_basic','M4-1-u5-C11',1,'mc','auto','두 자료를 하나의 막대그래프에 나타낼 때 두 자료는 무엇으로 구분하나요?',ARRAY['M4-1-u5-X03','M4-1-u5-X02','M4-1-u5-X19']::text[],true,'{"seq":1,"concept":"M4-1-u5-C11","difficulty":1,"kind":"mc","stem":"두 자료를 하나의 막대그래프에 나타낼 때 두 자료는 무엇으로 구분하나요?","options":[{"t":"막대의 색 — 이름표(범례)가 알려 줘요.","correct":true},{"t":"막대의 굵기 — 굵은 쪽이 새 자료예요.","mis":"M4-1-u5-X03"},{"t":"눈금 한 칸의 크기","mis":"M4-1-u5-X02"},{"t":"막대 위에 붙인 별표","mis":"M4-1-u5-X19"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"variant_rule":{"alt":[{"stem":"두 자료를 나타낸 막대그래프에서 어느 색이 어느 자료인지 알려 주는 것은 무엇인가요?","options":[{"t":"이름표(범례)","correct":true},{"t":"제목","mis":"M4-1-u5-X19"},{"t":"세로 눈금","mis":"M4-1-u5-X19"},{"t":"가로 눈금 이름","mis":"M4-1-u5-X19"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"asset":null},{"stem":"두 자료를 하나의 막대그래프에 나타내면 좋은 점은 무엇인가요?","options":[{"t":"항목마다 두 자료를 한눈에 견줄 수 있어요.","correct":true},{"t":"두 그래프 사이를 오가며 봐야 해요.","mis":"M4-1-u5-X21"},{"t":"나타내는 수가 저절로 커져요.","mis":"M4-1-u5-X20"},{"t":"그렇게 된 까닭까지 알 수 있어요.","mis":"M4-1-u5-X11"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_basic#2','math',4,1,'u5','L08','g4_1_math_u5_L08_basic','lesson_basic','M4-1-u5-C11',1,'sa','auto','2반 떡볶이의 학생 수는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u5-C11","difficulty":1,"kind":"sa","stem":"2반 떡볶이의 학생 수는 몇 명인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["이름표에서 2반의 막대 색을 먼저 찾아요.","떡볶이 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 1명).","2반 떡볶이의 학생 수는 4명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵"],"series":[{"name":"1반","vals":[8,4,9,11]},{"name":"2반","vals":[4,7,11,9]}],"step":1,"ymax":12,"ylab":"(명)","title":"반별 좋아하는 간식"},"variant_rule":{"alt":[{"stem":"작년 역사의 빌린 책 수는 몇 권인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["이름표에서 작년의 막대 색을 먼저 찾아요.","역사 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 10권).","작년 역사의 빌린 책 수는 60권이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["동화","과학","역사","만화"],"series":[{"name":"작년","vals":[90,40,60,20]},{"name":"올해","vals":[110,90,130,80]}],"step":10,"ymax":140,"ylab":"(권)","title":"작년과 올해 빌린 책 수"}},{"stem":"지난달 1모둠의 빈 병 수는 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["이름표에서 지난달의 막대 색을 먼저 찾아요.","1모둠 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 5개).","지난달 1모둠의 빈 병 수는 10개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"지난달","vals":[10,25,15,20]},{"name":"이번 달","vals":[35,70,80,40]}],"step":5,"ymax":85,"ylab":"(개)","title":"지난달과 이번 달 모은 빈 병 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_basic#3','math',4,1,'u5','L08','g4_1_math_u5_L08_basic','lesson_basic','M4-1-u5-C11',1,'mc','auto','항목별로 두 막대씩 묶어 그리면 무엇을 한눈에 알 수 있나요?',ARRAY['M4-1-u5-X11','M4-1-u5-X03']::text[],true,'{"seq":3,"concept":"M4-1-u5-C11","difficulty":1,"kind":"mc","stem":"항목별로 두 막대씩 묶어 그리면 무엇을 한눈에 알 수 있나요?","options":[{"t":"항목마다 두 자료가 얼마나 다른지","correct":true},{"t":"항목마다 그렇게 된 까닭","mis":"M4-1-u5-X11"},{"t":"앞으로 늘어날 수","mis":"M4-1-u5-X11"},{"t":"막대마다 다른 굵기","mis":"M4-1-u5-X03"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"variant_rule":{"alt":[{"stem":"같은 두 자료를 묶는 방법만 바꾸어 다시 그리면 무엇이 달라지나요?","options":[{"t":"막대를 늘어놓는 차례만 달라지고 나타내는 수는 그대로예요.","correct":true},{"t":"막대가 나타내는 수가 달라져요.","mis":"M4-1-u5-X20"},{"t":"눈금 한 칸이 저절로 달라져요.","mis":"M4-1-u5-X20"},{"t":"자료가 더 많아져요.","mis":"M4-1-u5-X20"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"asset":null},{"stem":"자료별(작년끼리·올해끼리)로 묶어 그리면 무엇을 견주기 좋나요?","options":[{"t":"같은 해 안에서 항목끼리 견주기","correct":true},{"t":"항목마다 늘어난 까닭","mis":"M4-1-u5-X11"},{"t":"다음 해의 수","mis":"M4-1-u5-X11"},{"t":"막대의 굵기","mis":"M4-1-u5-X03"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_basic#4','math',4,1,'u5','L08','g4_1_math_u5_L08_basic','lesson_basic','M4-1-u5-C11',1,'sa','auto','작년 다 마을의 나무 수는 몇 그루인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u5-C11","difficulty":1,"kind":"sa","stem":"작년 다 마을의 나무 수는 몇 그루인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["이름표에서 작년의 막대 색을 먼저 찾아요.","다 마을 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 5그루).","작년 다 마을의 나무 수는 40그루예요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을"],"series":[{"name":"작년","vals":[55,25,40,20]},{"name":"올해","vals":[60,70,55,45]}],"step":5,"ymax":75,"ylab":"(그루)","title":"작년과 올해 심은 나무 수"},"variant_rule":{"alt":[{"stem":"2학기 3모둠의 붙임딱지 수는 몇 개인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["이름표에서 2학기의 막대 색을 먼저 찾아요.","3모둠 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 2개).","2학기 3모둠의 붙임딱지 수는 30개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"1학기","vals":[10,8,24,12]},{"name":"2학기","vals":[24,16,30,22]}],"step":2,"ymax":32,"ylab":"(개)","title":"1학기와 2학기 칭찬 붙임딱지 수"}},{"stem":"남학생 가을의 학생 수는 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["이름표에서 남학생의 막대 색을 먼저 찾아요.","가을 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 1명).","남학생 가을의 학생 수는 3명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"name":"남학생","vals":[4,5,3,9]},{"name":"여학생","vals":[6,9,7,3]}],"step":1,"ymax":10,"ylab":"(명)","title":"남학생과 여학생이 좋아하는 계절"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_basic#5','math',4,1,'u5','L08','g4_1_math_u5_L08_basic','lesson_basic','M4-1-u5-C11',2,'sa','auto','과일을 고른 1반과 2반의 학생 수의 차는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u5-C11","difficulty":2,"kind":"sa","stem":"과일을 고른 1반과 2반의 학생 수의 차는 몇 명인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["과일 묶음에서 1반은 11명, 2반은 2명이에요.","차는 큰 수에서 작은 수를 빼요.","11 − 2 = 9 — 9명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵"],"series":[{"name":"1반","vals":[12,4,11,2]},{"name":"2반","vals":[4,7,2,11]}],"step":1,"ymax":13,"ylab":"(명)","title":"반별 좋아하는 간식"},"variant_rule":{"alt":[{"stem":"역사의 빌린 책 수는 작년보다 올해에 몇 권 더 늘었나요? 숫자로 쓰세요.","answer":["70"],"explanation":["역사 작년의 막대는 80권, 올해의 막대는 150권이에요.","늘어난 수는 뒤의 수에서 앞의 수를 빼요.","150 − 80 = 70 — 70권 늘었어요."],"asset":{"type":"lgraph","mode":"bar","xs":["동화","과학","역사","만화"],"series":[{"name":"작년","vals":[20,110,80,70]},{"name":"올해","vals":[100,140,150,120]}],"step":10,"ymax":160,"ylab":"(권)","title":"작년과 올해 빌린 책 수"}},{"stem":"4모둠의 빈 병 수는 지난달보다 이번 달에 몇 개 더 늘었나요? 숫자로 쓰세요.","answer":["10"],"explanation":["4모둠 지난달의 막대는 25개, 이번 달의 막대는 35개예요.","늘어난 수는 뒤의 수에서 앞의 수를 빼요.","35 − 25 = 10 — 10개 늘었어요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"지난달","vals":[35,55,10,25]},{"name":"이번 달","vals":[60,75,70,35]}],"step":5,"ymax":80,"ylab":"(개)","title":"지난달과 이번 달 모은 빈 병 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_basic#6','math',4,1,'u5','L08','g4_1_math_u5_L08_basic','lesson_basic','M4-1-u5-C11',2,'mc','auto','1반이 2반보다 학생 수가 많은 항목은 어느 것인가요?',ARRAY['M4-1-u5-X19']::text[],true,'{"seq":6,"concept":"M4-1-u5-C11","difficulty":2,"kind":"mc","stem":"1반이 2반보다 학생 수가 많은 항목은 어느 것인가요?","options":[{"t":"빵","correct":true},{"t":"떡볶이","mis":"M4-1-u5-X19"},{"t":"김밥","mis":"M4-1-u5-X19"},{"t":"과일","mis":"M4-1-u5-X19"}],"explanation":["이름표로 1반의 막대 색과 2반의 막대 색을 먼저 가려요.","항목마다 두 막대를 견주어 1반 막대가 더 긴 곳을 찾아요.","빵 묶음만 1반이 6명, 2반이 3명로 1반이 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵"],"series":[{"name":"1반","vals":[4,3,10,6]},{"name":"2반","vals":[6,10,12,3]}],"step":1,"ymax":13,"ylab":"(명)","title":"반별 좋아하는 간식"},"variant_rule":{"alt":[{"stem":"남학생이 여학생보다 학생 수가 많은 항목은 어느 것인가요?","options":[{"t":"겨울","correct":true},{"t":"봄","mis":"M4-1-u5-X19"},{"t":"여름","mis":"M4-1-u5-X19"},{"t":"가을","mis":"M4-1-u5-X19"}],"explanation":["이름표로 남학생의 막대 색과 여학생의 막대 색을 먼저 가려요.","항목마다 두 막대를 견주어 남학생 막대가 더 긴 곳을 찾아요.","겨울 묶음만 남학생이 10명, 여학생이 3명로 남학생이 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"name":"남학생","vals":[6,2,4,10]},{"name":"여학생","vals":[8,6,9,3]}],"step":1,"ymax":11,"ylab":"(명)","title":"남학생과 여학생이 좋아하는 계절"}},{"stem":"이번에는 다른 그림이에요. 1반이 2반보다 학생 수가 많은 항목은 어느 것인가요?","options":[{"t":"떡볶이","correct":true},{"t":"김밥","mis":"M4-1-u5-X19"},{"t":"과일","mis":"M4-1-u5-X19"},{"t":"빵","mis":"M4-1-u5-X19"}],"explanation":["이름표로 1반의 막대 색과 2반의 막대 색을 먼저 가려요.","항목마다 두 막대를 견주어 1반 막대가 더 긴 곳을 찾아요.","떡볶이 묶음만 1반이 5명, 2반이 3명로 1반이 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵"],"series":[{"name":"1반","vals":[5,3,7,4]},{"name":"2반","vals":[3,10,11,7]}],"step":1,"ymax":12,"ylab":"(명)","title":"반별 좋아하는 간식"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_basic#7','math',4,1,'u5','L08','g4_1_math_u5_L08_basic','lesson_basic','M4-1-u5-C11',2,'sa','auto','1반의 학생 수를 모두 더하면 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u5-C11","difficulty":2,"kind":"sa","stem":"1반의 학생 수를 모두 더하면 몇 명인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["이름표에서 1반의 막대 색을 찾아요.","그 색 막대: 3명, 6명, 7명, 4명.","3 + 6 + 7 + 4 = 20 — 20명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵"],"series":[{"name":"1반","vals":[3,6,7,4]},{"name":"2반","vals":[6,3,12,2]}],"step":1,"ymax":13,"ylab":"(명)","title":"반별 좋아하는 간식"},"variant_rule":{"alt":[{"stem":"올해의 빌린 책 수를 모두 더하면 몇 권인가요? 숫자로 쓰세요.","answer":["480"],"explanation":["이름표에서 올해의 막대 색을 찾아요.","그 색 막대: 130권, 120권, 80권, 150권.","130 + 120 + 80 + 150 = 480 — 480권이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["동화","과학","역사","만화"],"series":[{"name":"작년","vals":[30,80,20,70]},{"name":"올해","vals":[130,120,80,150]}],"step":10,"ymax":160,"ylab":"(권)","title":"작년과 올해 빌린 책 수"}},{"stem":"지난달의 빈 병 수를 모두 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["이름표에서 지난달의 막대 색을 찾아요.","그 색 막대: 10개, 60개, 35개, 15개.","10 + 60 + 35 + 15 = 120 — 120개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"지난달","vals":[10,60,35,15]},{"name":"이번 달","vals":[60,75,65,80]}],"step":5,"ymax":85,"ylab":"(개)","title":"지난달과 이번 달 모은 빈 병 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_basic#8','math',4,1,'u5','L08','g4_1_math_u5_L08_basic','lesson_basic','M4-1-u5-C11',2,'ox','auto','두 자료를 하나의 막대그래프에 나타낼 때는 막대의 색으로 구분해요.',ARRAY['M4-1-u5-X03']::text[],true,'{"seq":8,"concept":"M4-1-u5-C11","difficulty":2,"kind":"ox","stem":"두 자료를 하나의 막대그래프에 나타낼 때는 막대의 색으로 구분해요.","answer":"O","reason_options":[{"t":"색으로 구분하고 이름표가 어느 자료인지 알려 줘서","correct":true},{"t":"굵기로 구분해야 해서","mis":"M4-1-u5-X03"}],"mis":"M4-1-u5-X03","explanation":["두 자료는 막대의 색으로 구분하고 이름표로 읽어요.","묶는 방법을 바꿔도 수는 그대로예요.","늘어난 수는 두 막대의 차로 구하고, 까닭은 그래프에 없어요."],"variant_rule":{"alt":[{"stem":"두 자료를 묶는 방법을 바꾸면 막대가 나타내는 수도 바뀌어요.","answer":"X","reason_options":[{"t":"늘어놓는 차례만 바뀌고 수는 그대로라서","correct":true},{"t":"막대의 자리가 바뀌니 수도 바뀌어서","mis":"M4-1-u5-X20"}],"explanation":["두 자료는 막대의 색으로 구분하고 이름표로 읽어요.","묶는 방법을 바꿔도 수는 그대로예요.","늘어난 수는 두 막대의 차로 구하고, 까닭은 그래프에 없어요."],"asset":null},{"stem":"두 자료를 나타낸 막대그래프에서는 이름표(범례)를 먼저 봐야 해요.","answer":"O","reason_options":[{"t":"어느 색이 어느 자료인지 알아야 바르게 읽을 수 있어서","correct":true},{"t":"이름표는 꾸미는 것이라서","mis":"M4-1-u5-X19"}],"explanation":["두 자료는 막대의 색으로 구분하고 이름표로 읽어요.","묶는 방법을 바꿔도 수는 그대로예요.","늘어난 수는 두 막대의 차로 구하고, 까닭은 그래프에 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_basic#9','math',4,1,'u5','L08','g4_1_math_u5_L08_basic','lesson_basic','M4-1-u5-C11',2,'sa','auto','떡볶이 묶음의 두 막대가 나타내는 수를 더하면 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u5-C11","difficulty":2,"kind":"sa","stem":"떡볶이 묶음의 두 막대가 나타내는 수를 더하면 몇 명인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["떡볶이 묶음에서 1반은 4명, 2반은 7명이에요.","두 수를 더해요.","4 + 7 = 11 — 11명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵"],"series":[{"name":"1반","vals":[4,2,10,3]},{"name":"2반","vals":[7,5,4,10]}],"step":1,"ymax":11,"ylab":"(명)","title":"반별 좋아하는 간식"},"variant_rule":{"alt":[{"stem":"과학 묶음의 두 막대가 나타내는 수를 더하면 몇 권인가요? 숫자로 쓰세요.","answer":["160"],"explanation":["과학 묶음에서 작년은 40권, 올해는 120권이에요.","두 수를 더해요.","40 + 120 = 160 — 160권이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["동화","과학","역사","만화"],"series":[{"name":"작년","vals":[80,40,90,30]},{"name":"올해","vals":[110,120,100,70]}],"step":10,"ymax":130,"ylab":"(권)","title":"작년과 올해 빌린 책 수"}},{"stem":"3모둠 묶음의 두 막대가 나타내는 수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["3모둠 묶음에서 지난달은 25개, 이번 달은 40개예요.","두 수를 더해요.","25 + 40 = 65 — 65개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"지난달","vals":[10,45,25,20]},{"name":"이번 달","vals":[60,65,40,45]}],"step":5,"ymax":70,"ylab":"(개)","title":"지난달과 이번 달 모은 빈 병 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_basic#10','math',4,1,'u5','L08','g4_1_math_u5_L08_basic','lesson_basic','M4-1-u5-C11',3,'mc','auto','작년보다 올해에 빌린 책 수가 가장 많이 늘어난 항목은 어느 것인가요?',ARRAY['M4-1-u5-X09']::text[],true,'{"seq":10,"concept":"M4-1-u5-C11","difficulty":3,"kind":"mc","stem":"작년보다 올해에 빌린 책 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"역사","correct":true},{"t":"만화","mis":"M4-1-u5-X09"},{"t":"동화","mis":"M4-1-u5-X09"},{"t":"과학","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 동화 20, 과학 10, 역사 80, 만화 40.","올해의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 역사예요."],"asset":{"type":"lgraph","mode":"bar","xs":["동화","과학","역사","만화"],"series":[{"name":"작년","vals":[20,80,30,110]},{"name":"올해","vals":[40,90,110,150]}],"step":10,"ymax":160,"ylab":"(권)","title":"작년과 올해 빌린 책 수"},"variant_rule":{"alt":[{"stem":"지난달보다 이번 달에 빈 병 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"2모둠","correct":true},{"t":"3모둠","mis":"M4-1-u5-X09"},{"t":"1모둠","mis":"M4-1-u5-X09"},{"t":"4모둠","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 1모둠 5, 2모둠 25, 3모둠 15, 4모둠 10.","이번 달의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 2모둠이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"지난달","vals":[40,35,65,20]},{"name":"이번 달","vals":[45,60,80,30]}],"step":5,"ymax":85,"ylab":"(개)","title":"지난달과 이번 달 모은 빈 병 수"}},{"stem":"작년보다 올해에 나무 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"라 마을","correct":true},{"t":"가 마을","mis":"M4-1-u5-X09"},{"t":"나 마을","mis":"M4-1-u5-X09"},{"t":"다 마을","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 가 마을 35, 나 마을 15, 다 마을 20, 라 마을 45.","올해의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 라 마을이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을"],"series":[{"name":"작년","vals":[30,40,10,15]},{"name":"올해","vals":[65,55,30,60]}],"step":5,"ymax":70,"ylab":"(그루)","title":"작년과 올해 심은 나무 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_challenge#1','math',4,1,'u5','L08','g4_1_math_u5_L08_challenge','lesson_challenge','M4-1-u5-C11',2,'sa','auto','나 마을의 나무 수는 작년보다 올해에 몇 그루 더 늘었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u5-C11","difficulty":2,"kind":"sa","stem":"나 마을의 나무 수는 작년보다 올해에 몇 그루 더 늘었나요? 숫자로 쓰세요.","answer":["20"],"explanation":["나 마을 작년의 막대는 20그루, 올해의 막대는 40그루예요.","늘어난 수는 뒤의 수에서 앞의 수를 빼요.","40 − 20 = 20 — 20그루 늘었어요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을"],"series":[{"name":"작년","vals":[15,20,60,30]},{"name":"올해","vals":[55,40,65,60]}],"step":5,"ymax":70,"ylab":"(그루)","title":"작년과 올해 심은 나무 수"},"variant_rule":{"alt":[{"stem":"3모둠의 붙임딱지 수는 1학기보다 2학기에 몇 개 더 늘었나요? 숫자로 쓰세요.","answer":["4"],"explanation":["3모둠 1학기의 막대는 22개, 2학기의 막대는 26개예요.","늘어난 수는 뒤의 수에서 앞의 수를 빼요.","26 − 22 = 4 — 4개 늘었어요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"1학기","vals":[10,18,22,6]},{"name":"2학기","vals":[28,20,26,30]}],"step":2,"ymax":32,"ylab":"(개)","title":"1학기와 2학기 칭찬 붙임딱지 수"}},{"stem":"가을을 고른 남학생과 여학생의 학생 수의 차는 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["가을 묶음에서 남학생은 9명, 여학생은 1명이에요.","차는 큰 수에서 작은 수를 빼요.","9 − 1 = 8 — 8명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"name":"남학생","vals":[7,2,9,8]},{"name":"여학생","vals":[10,7,1,2]}],"step":1,"ymax":11,"ylab":"(명)","title":"남학생과 여학생이 좋아하는 계절"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_challenge#2','math',4,1,'u5','L08','g4_1_math_u5_L08_challenge','lesson_challenge','M4-1-u5-C11',2,'ox','auto','두 자료 가운데 막대가 가장 긴 항목이 언제나 가장 많이 늘어난 항목이에요.',ARRAY['M4-1-u5-X09']::text[],true,'{"seq":2,"concept":"M4-1-u5-C11","difficulty":2,"kind":"ox","stem":"두 자료 가운데 막대가 가장 긴 항목이 언제나 가장 많이 늘어난 항목이에요.","answer":"X","reason_options":[{"t":"늘어난 수는 두 막대의 차로 구해야 해서","correct":true},{"t":"가장 긴 막대가 가장 많이 늘어서","mis":"M4-1-u5-X09"}],"mis":"M4-1-u5-X09","explanation":["두 자료는 막대의 색으로 구분하고 이름표로 읽어요.","묶는 방법을 바꿔도 수는 그대로예요.","늘어난 수는 두 막대의 차로 구하고, 까닭은 그래프에 없어요."],"variant_rule":{"alt":[{"stem":"두 자료를 하나의 그래프에 나타내면 항목마다 두 자료를 한눈에 견줄 수 있어요.","answer":"O","reason_options":[{"t":"두 막대가 나란히 서 있어서","correct":true},{"t":"두 그래프를 오가며 봐야 해서","mis":"M4-1-u5-X21"}],"explanation":["두 자료는 막대의 색으로 구분하고 이름표로 읽어요.","묶는 방법을 바꿔도 수는 그대로예요.","늘어난 수는 두 막대의 차로 구하고, 까닭은 그래프에 없어요."],"asset":null},{"stem":"두 자료의 그래프를 보면 그렇게 달라진 까닭도 알 수 있어요.","answer":"X","reason_options":[{"t":"그래프에는 수만 있고 까닭은 없어서","correct":true},{"t":"두 막대를 견주면 까닭이 보여서","mis":"M4-1-u5-X11"}],"explanation":["두 자료는 막대의 색으로 구분하고 이름표로 읽어요.","묶는 방법을 바꿔도 수는 그대로예요.","늘어난 수는 두 막대의 차로 구하고, 까닭은 그래프에 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_challenge#3','math',4,1,'u5','L08','g4_1_math_u5_L08_challenge','lesson_challenge','M4-1-u5-C11',3,'mc','auto','만화의 빌린 책 수는 올해에 작년의 몇 배가 되었나요?',ARRAY['M4-1-u5-X09']::text[],true,'{"seq":3,"concept":"M4-1-u5-C11","difficulty":3,"kind":"mc","stem":"만화의 빌린 책 수는 올해에 작년의 몇 배가 되었나요?","options":[{"t":"2배","correct":true},{"t":"70배","mis":"M4-1-u5-X09"},{"t":"3배","mis":"M4-1-u5-X09"},{"t":"4배","mis":"M4-1-u5-X09"}],"explanation":["만화 묶음에서 작년은 70권, 올해는 140권이에요.","70 × 2 = 140.","그래서 2배가 되었어요 — 늘어난 수(70)와는 달라요."],"asset":{"type":"lgraph","mode":"bar","xs":["동화","과학","역사","만화"],"series":[{"name":"작년","vals":[60,110,20,70]},{"name":"올해","vals":[90,150,110,140]}],"step":10,"ymax":160,"ylab":"(권)","title":"작년과 올해 빌린 책 수"},"variant_rule":{"alt":[{"stem":"3모둠의 빈 병 수는 이번 달에 지난달의 몇 배가 되었나요?","options":[{"t":"2배","correct":true},{"t":"30배","mis":"M4-1-u5-X09"},{"t":"3배","mis":"M4-1-u5-X09"},{"t":"4배","mis":"M4-1-u5-X09"}],"explanation":["3모둠 묶음에서 지난달은 30개, 이번 달은 60개예요.","30 × 2 = 60.","그래서 2배가 되었어요 — 늘어난 수(30)와는 달라요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"지난달","vals":[45,10,30,35]},{"name":"이번 달","vals":[65,80,60,45]}],"step":5,"ymax":85,"ylab":"(개)","title":"지난달과 이번 달 모은 빈 병 수"}},{"stem":"나 마을의 나무 수는 올해에 작년의 몇 배가 되었나요?","options":[{"t":"2배","correct":true},{"t":"15배","mis":"M4-1-u5-X09"},{"t":"3배","mis":"M4-1-u5-X09"},{"t":"4배","mis":"M4-1-u5-X09"}],"explanation":["나 마을 묶음에서 작년은 15그루, 올해는 30그루예요.","15 × 2 = 30.","그래서 2배가 되었어요 — 늘어난 수(15)와는 달라요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을"],"series":[{"name":"작년","vals":[40,15,10,50]},{"name":"올해","vals":[50,30,35,70]}],"step":5,"ymax":75,"ylab":"(그루)","title":"작년과 올해 심은 나무 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_challenge#4','math',4,1,'u5','L08','g4_1_math_u5_L08_challenge','lesson_challenge','M4-1-u5-C11',3,'error','auto','두 자료를 나타낸 막대그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u5-X19','M4-1-u5-X21']::text[],true,'{"seq":4,"concept":"M4-1-u5-C11","difficulty":3,"kind":"error","stem":"두 자료를 나타낸 막대그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「주황 막대가 작년이겠지 뭐. 이름표는 안 봐도 돼.」","correct":true,"mis_target":"M4-1-u5-X19"},{"t":"도윤 — 「이름표로 색을 먼저 확인하자.」","mis":"M4-1-u5-X21"},{"t":"서윤 — 「늘어난 수는 두 막대의 차야.」","mis":"M4-1-u5-X21"},{"t":"시우 — 「묶는 방법을 바꿔도 수는 그대로야.」","mis":"M4-1-u5-X21"}],"explanation":["두 자료는 색으로 구분하고 이름표로 읽어요.","민서의 말은 두 자료 그래프를 읽는 방법과 맞지 않아요.","늘어난 수는 차로, 묶음을 바꿔도 수는 그대로예요."],"variant_rule":{"alt":[{"stem":"두 자료를 나타낸 막대그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「올해끼리 묶어 다시 그리면 수가 달라져.」","correct":true,"mis_target":"M4-1-u5-X20"},{"t":"서윤 — 「늘어난 수는 두 막대의 차야.」","mis":"M4-1-u5-X21"},{"t":"시우 — 「묶는 방법을 바꿔도 수는 그대로야.」","mis":"M4-1-u5-X21"},{"t":"은우 — 「까닭은 그래프에 나와 있지 않아.」","mis":"M4-1-u5-X21"}],"explanation":["두 자료는 색으로 구분하고 이름표로 읽어요.","도윤의 말은 두 자료 그래프를 읽는 방법과 맞지 않아요.","늘어난 수는 차로, 묶음을 바꿔도 수는 그대로예요."],"asset":null},{"stem":"두 자료를 나타낸 막대그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「올해 막대가 가장 긴 항목이 가장 많이 늘어난 거야.」","correct":true,"mis_target":"M4-1-u5-X09"},{"t":"시우 — 「묶는 방법을 바꿔도 수는 그대로야.」","mis":"M4-1-u5-X21"},{"t":"은우 — 「까닭은 그래프에 나와 있지 않아.」","mis":"M4-1-u5-X21"},{"t":"하랑 — 「이름표로 색을 먼저 확인하자.」","mis":"M4-1-u5-X21"}],"explanation":["두 자료는 색으로 구분하고 이름표로 읽어요.","서윤의 말은 두 자료 그래프를 읽는 방법과 맞지 않아요.","늘어난 수는 차로, 묶음을 바꿔도 수는 그대로예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_challenge#5','math',4,1,'u5','L08','g4_1_math_u5_L08_challenge','lesson_challenge','M4-1-u5-C11',3,'mc','auto','그래프를 보고 기사를 써요. 그래프에서 알 수 있는 사실만 쓴 것은 어느 것인가요?',ARRAY['M4-1-u5-X09','M4-1-u5-X11']::text[],true,'{"seq":5,"concept":"M4-1-u5-C11","difficulty":3,"kind":"mc","stem":"그래프를 보고 기사를 써요. 그래프에서 알 수 있는 사실만 쓴 것은 어느 것인가요?","options":[{"t":"네 항목 모두 작년보다 올해에 빌린 책 수가 늘었어요.","correct":true},{"t":"가장 많이 늘어난 것은 과학이에요.","mis":"M4-1-u5-X09"},{"t":"다음에는 역사가 200권을 넘을 거예요.","mis":"M4-1-u5-X11"},{"t":"과학이 가장 인기 있는 까닭은 재미있어서예요.","mis":"M4-1-u5-X11"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","네 묶음 모두 올해 막대가 작년 막대보다 길어요.","앞날이나 까닭은 그래프에 없으니 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["동화","과학","역사","만화"],"series":[{"name":"작년","vals":[40,100,30,20]},{"name":"올해","vals":[110,150,120,30]}],"step":10,"ymax":160,"ylab":"(권)","title":"작년과 올해 빌린 책 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 그래프를 보고 기사를 써요. 그래프에서 알 수 있는 사실만 쓴 것은 어느 것인가요?","options":[{"t":"네 항목 모두 지난달보다 이번 달에 빈 병 수가 늘었어요.","correct":true},{"t":"가장 많이 늘어난 것은 2모둠이에요.","mis":"M4-1-u5-X09"},{"t":"다음에는 1모둠이 130개를 넘을 거예요.","mis":"M4-1-u5-X11"},{"t":"2모둠이 가장 인기 있는 까닭은 재미있어서예요.","mis":"M4-1-u5-X11"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","네 묶음 모두 이번 달 막대가 지난달 막대보다 길어요.","앞날이나 까닭은 그래프에 없으니 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"지난달","vals":[10,65,25,20]},{"name":"이번 달","vals":[65,70,55,45]}],"step":5,"ymax":75,"ylab":"(개)","title":"지난달과 이번 달 모은 빈 병 수"}},{"stem":"이번에는 다른 그림이에요. 그래프를 보고 기사를 써요. 그래프에서 알 수 있는 사실만 쓴 것은 어느 것인가요?","options":[{"t":"네 항목 모두 작년보다 올해에 나무 수가 늘었어요.","correct":true},{"t":"가장 많이 늘어난 것은 가 마을이에요.","mis":"M4-1-u5-X09"},{"t":"다음에는 나 마을이 120그루를 넘을 거예요.","mis":"M4-1-u5-X11"},{"t":"가 마을이 가장 인기 있는 까닭은 재미있어서예요.","mis":"M4-1-u5-X11"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","네 묶음 모두 올해 막대가 작년 막대보다 길어요.","앞날이나 까닭은 그래프에 없으니 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을"],"series":[{"name":"작년","vals":[45,35,30,20]},{"name":"올해","vals":[70,65,35,40]}],"step":5,"ymax":75,"ylab":"(그루)","title":"작년과 올해 심은 나무 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_challenge#6','math',4,1,'u5','L08','g4_1_math_u5_L08_challenge','lesson_challenge','M4-1-u5-C11',3,'sa','auto','같은 자료를 자료별(1반끼리·2반끼리)로 묶어 다시 그렸어요. 새 그래프의 1반 묶음에서 빵 막대가 나타내는 수는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u5-C11","difficulty":3,"kind":"sa","stem":"같은 자료를 자료별(1반끼리·2반끼리)로 묶어 다시 그렸어요. 새 그래프의 1반 묶음에서 빵 막대가 나타내는 수는 몇 명인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["묶는 방법을 바꾸면 막대를 늘어놓는 차례만 달라져요.","나타내는 수는 그대로예요.","아래 그래프에서 1반 빵의 막대를 읽으면 4명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵"],"series":[{"name":"1반","vals":[2,3,11,4]},{"name":"2반","vals":[4,8,3,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"반별 좋아하는 간식"},"variant_rule":{"alt":[{"stem":"같은 자료를 자료별(작년끼리·올해끼리)로 묶어 다시 그렸어요. 새 그래프의 올해 묶음에서 동화 막대가 나타내는 수는 몇 권인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["묶는 방법을 바꾸면 막대를 늘어놓는 차례만 달라져요.","나타내는 수는 그대로예요.","아래 그래프에서 올해 동화의 막대를 읽으면 110권이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["동화","과학","역사","만화"],"series":[{"name":"작년","vals":[20,50,70,110]},{"name":"올해","vals":[110,90,100,130]}],"step":10,"ymax":140,"ylab":"(권)","title":"작년과 올해 빌린 책 수"}},{"stem":"같은 자료를 자료별(지난달끼리·이번 달끼리)로 묶어 다시 그렸어요. 새 그래프의 이번 달 묶음에서 2모둠 막대가 나타내는 수는 몇 개인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["묶는 방법을 바꾸면 막대를 늘어놓는 차례만 달라져요.","나타내는 수는 그대로예요.","아래 그래프에서 이번 달 2모둠의 막대를 읽으면 65개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"지난달","vals":[10,25,45,30]},{"name":"이번 달","vals":[70,65,80,45]}],"step":5,"ymax":85,"ylab":"(개)","title":"지난달과 이번 달 모은 빈 병 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_challenge#7','math',4,1,'u5','L08','g4_1_math_u5_L08_challenge','lesson_challenge','M4-1-u5-C11',3,'mc','auto','1학기보다 2학기에 붙임딱지 수가 가장 많이 늘어난 항목은 어느 것인가요?',ARRAY['M4-1-u5-X09']::text[],true,'{"seq":7,"concept":"M4-1-u5-C11","difficulty":3,"kind":"mc","stem":"1학기보다 2학기에 붙임딱지 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"1모둠","correct":true},{"t":"2모둠","mis":"M4-1-u5-X09"},{"t":"3모둠","mis":"M4-1-u5-X09"},{"t":"4모둠","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 1모둠 18, 2모둠 8, 3모둠 2, 4모둠 6.","2학기의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 1모둠이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"1학기","vals":[4,18,6,10]},{"name":"2학기","vals":[22,26,8,16]}],"step":2,"ymax":28,"ylab":"(개)","title":"1학기와 2학기 칭찬 붙임딱지 수"},"variant_rule":{"alt":[{"stem":"작년보다 올해에 빌린 책 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"동화","correct":true},{"t":"과학","mis":"M4-1-u5-X09"},{"t":"역사","mis":"M4-1-u5-X09"},{"t":"만화","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 동화 100, 과학 50, 역사 40, 만화 80.","올해의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 동화예요."],"asset":{"type":"lgraph","mode":"bar","xs":["동화","과학","역사","만화"],"series":[{"name":"작년","vals":[20,90,70,50]},{"name":"올해","vals":[120,140,110,130]}],"step":10,"ymax":150,"ylab":"(권)","title":"작년과 올해 빌린 책 수"}},{"stem":"지난달보다 이번 달에 빈 병 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"1모둠","correct":true},{"t":"3모둠","mis":"M4-1-u5-X09"},{"t":"2모둠","mis":"M4-1-u5-X09"},{"t":"4모둠","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 1모둠 40, 2모둠 5, 3모둠 10, 4모둠 25.","이번 달의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 1모둠이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"지난달","vals":[15,20,60,35]},{"name":"이번 달","vals":[55,25,70,60]}],"step":5,"ymax":75,"ylab":"(개)","title":"지난달과 이번 달 모은 빈 병 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_challenge#8','math',4,1,'u5','L08','g4_1_math_u5_L08_challenge','lesson_challenge','M4-1-u5-C11',4,'sa','auto','1반과 2반의 차가 가장 큰 항목에서, 두 수의 차는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u5-C11","difficulty":4,"kind":"sa","stem":"1반과 2반의 차가 가장 큰 항목에서, 두 수의 차는 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["항목마다 두 막대의 차를 구해요: 떡볶이 3, 김밥 1, 과일 4, 빵 6.","차가 가장 큰 항목은 빵이에요.","그 차는 6명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵"],"series":[{"name":"1반","vals":[4,3,12,11]},{"name":"2반","vals":[7,4,8,5]}],"step":1,"ymax":13,"ylab":"(명)","title":"반별 좋아하는 간식"},"variant_rule":{"alt":[{"stem":"작년과 올해의 차가 가장 큰 항목에서, 두 수의 차는 몇 권인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["항목마다 두 막대의 차를 구해요: 동화 70, 과학 40, 역사 10, 만화 20.","차가 가장 큰 항목은 동화예요.","그 차는 70권이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["동화","과학","역사","만화"],"series":[{"name":"작년","vals":[50,40,30,120]},{"name":"올해","vals":[120,80,40,140]}],"step":10,"ymax":150,"ylab":"(권)","title":"작년과 올해 빌린 책 수"}},{"stem":"지난달과 이번 달의 차가 가장 큰 항목에서, 두 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["항목마다 두 막대의 차를 구해요: 1모둠 5, 2모둠 10, 3모둠 55, 4모둠 45.","차가 가장 큰 항목은 3모둠이에요.","그 차는 55개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"지난달","vals":[50,20,10,25]},{"name":"이번 달","vals":[55,30,65,70]}],"step":5,"ymax":75,"ylab":"(개)","title":"지난달과 이번 달 모은 빈 병 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_challenge#9','math',4,1,'u5','L08','g4_1_math_u5_L08_challenge','lesson_challenge','M4-1-u5-C11',4,'mc','auto','2모둠의 붙임딱지 수는 2학기에 1학기의 몇 배가 되었나요?',ARRAY['M4-1-u5-X09']::text[],true,'{"seq":9,"concept":"M4-1-u5-C11","difficulty":4,"kind":"mc","stem":"2모둠의 붙임딱지 수는 2학기에 1학기의 몇 배가 되었나요?","options":[{"t":"2배","correct":true},{"t":"6배","mis":"M4-1-u5-X09"},{"t":"3배","mis":"M4-1-u5-X09"},{"t":"4배","mis":"M4-1-u5-X09"}],"explanation":["2모둠 묶음에서 1학기는 6개, 2학기는 12개예요.","6 × 2 = 12.","그래서 2배가 되었어요 — 늘어난 수(6)와는 달라요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"1학기","vals":[12,6,16,10]},{"name":"2학기","vals":[16,12,28,26]}],"step":2,"ymax":30,"ylab":"(개)","title":"1학기와 2학기 칭찬 붙임딱지 수"},"variant_rule":{"alt":[{"stem":"역사의 빌린 책 수는 올해에 작년의 몇 배가 되었나요?","options":[{"t":"2배","correct":true},{"t":"40배","mis":"M4-1-u5-X09"},{"t":"3배","mis":"M4-1-u5-X09"},{"t":"4배","mis":"M4-1-u5-X09"}],"explanation":["역사 묶음에서 작년은 40권, 올해는 80권이에요.","40 × 2 = 80.","그래서 2배가 되었어요 — 늘어난 수(40)와는 달라요."],"asset":{"type":"lgraph","mode":"bar","xs":["동화","과학","역사","만화"],"series":[{"name":"작년","vals":[110,130,40,30]},{"name":"올해","vals":[120,150,80,140]}],"step":10,"ymax":160,"ylab":"(권)","title":"작년과 올해 빌린 책 수"}},{"stem":"1모둠의 빈 병 수는 이번 달에 지난달의 몇 배가 되었나요?","options":[{"t":"3배","correct":true},{"t":"20배","mis":"M4-1-u5-X09"},{"t":"4배","mis":"M4-1-u5-X09"},{"t":"2배","mis":"M4-1-u5-X09"}],"explanation":["1모둠 묶음에서 지난달은 10개, 이번 달은 30개예요.","10 × 3 = 30.","그래서 3배가 되었어요 — 늘어난 수(20)와는 달라요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"지난달","vals":[10,45,65,30]},{"name":"이번 달","vals":[30,50,80,55]}],"step":5,"ymax":85,"ylab":"(개)","title":"지난달과 이번 달 모은 빈 병 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_L08_challenge#10','math',4,1,'u5','L08','g4_1_math_u5_L08_challenge','lesson_challenge','M4-1-u5-C11',4,'essay','teacher','「작년과 올해 빌린 책 수」를 하나의 막대그래프에 나타냈어요. 동화는 작년 40권·올해 70권, 과학은 작년 30권·올해 90권이에요. 한 친구가 「올해 과학 막대가 가장 기니까 과학이 2배로 늘었어. 다들 과학을 좋아하게 된 거야.」라고 했어요. 친구의 말에서 잘못된 점을 찾아 바르게 고치고, 그래프에서 알 수 있는 사실로 기사 제목을 하나 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-1-u5-C11","difficulty":4,"kind":"essay","stem":"「작년과 올해 빌린 책 수」를 하나의 막대그래프에 나타냈어요. 동화는 작년 40권·올해 70권, 과학은 작년 30권·올해 90권이에요. 한 친구가 「올해 과학 막대가 가장 기니까 과학이 2배로 늘었어. 다들 과학을 좋아하게 된 거야.」라고 했어요. 친구의 말에서 잘못된 점을 찾아 바르게 고치고, 그래프에서 알 수 있는 사실로 기사 제목을 하나 써 보세요.","answer_guide":{"answer":"예: 과학은 30권에서 90권이 되었으므로 2배가 아니라 3배가 되었다(60권 늘었다). 과학을 좋아하게 된 까닭은 그래프에 나와 있지 않으므로 지어내면 안 된다. 기사 제목: 「올해 빌린 동화와 과학 책, 작년보다 모두 늘었다」","scoring_points":["3배(60권 늘어남)로 바르게 고쳤는가","까닭은 그래프에 없어 지어내면 안 된다고 썼는가","그래프에 있는 사실로 기사 제목을 썼는가"]},"explanation":["30 × 3 = 90 — 3배가 되었어요.","좋아하게 된 까닭은 그래프에 없어요.","두 항목 모두 늘었다는 것은 그래프에 있는 사실이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["동화","과학"],"series":[{"name":"작년","vals":[40,30]},{"name":"올해","vals":[70,90]}],"step":10,"ymax":100,"ylab":"(권)","title":"작년과 올해 빌린 책 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#1','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C2',1,'mc','auto','막대그래프의 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X04','M4-1-u5-X11']::text[],true,'{"seq":1,"concept":"M4-1-u5-C2","difficulty":1,"kind":"mc","stem":"막대그래프의 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"막대의 길이만 보고 많고 적음을 한눈에 견줄 수 있어요.","correct":true},{"t":"정확한 수를 조사하지 않아도 돼요.","mis":"M4-1-u5-X04"},{"t":"그림을 예쁘게 그릴 수 있어요.","mis":"M4-1-u5-X04"},{"t":"조사하지 않아도 결과를 알 수 있어요.","mis":"M4-1-u5-X11"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"variant_rule":{"alt":[{"stem":"그림그래프와 막대그래프의 다른 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"수량을 그림그래프는 그림으로, 막대그래프는 막대의 길이로 나타내요.","correct":true},{"t":"그림그래프는 항목을 나타내지 않아요.","mis":"M4-1-u5-X04"},{"t":"막대그래프에는 제목이 없어요.","mis":"M4-1-u5-X04"},{"t":"두 그래프는 서로 다른 자료만 나타내요.","mis":"M4-1-u5-X04"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"asset":null},{"stem":"그림그래프와 막대그래프의 같은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 항목별 수량을 나타내요.","correct":true},{"t":"둘 다 그림의 개수로 나타내요.","mis":"M4-1-u5-X04"},{"t":"둘 다 막대의 굵기로 나타내요.","mis":"M4-1-u5-X03"},{"t":"둘 다 합계만 나타내요.","mis":"M4-1-u5-X04"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#2','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C3',1,'mc','auto','아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?',ARRAY['M4-1-u5-X01']::text[],true,'{"seq":2,"concept":"M4-1-u5-C3","difficulty":1,"kind":"mc","stem":"아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 농장, 세로: 토마토 생산량","correct":true},{"t":"가로: 토마토 생산량, 세로: 농장","mis":"M4-1-u5-X01"},{"t":"가로: 농장, 세로: 농장","mis":"M4-1-u5-X01"},{"t":"가로: 토마토 생산량, 세로: 토마토 생산량","mis":"M4-1-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 농장, 세로에는 토마토 생산량을 kg 단위로 나타냈어요.","가로: 농장, 세로: 토마토 생산량이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["해 농장","달 농장","별 농장","숲 농장","강 농장"],"series":[{"vals":[100,260,80,200,180]}],"step":20,"ymax":280,"ylab":"(kg)","title":"농장별 토마토 생산량"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 마을, 세로: 나무 수","correct":true},{"t":"가로: 나무 수, 세로: 마을","mis":"M4-1-u5-X01"},{"t":"가로: 마을, 세로: 마을","mis":"M4-1-u5-X01"},{"t":"가로: 나무 수, 세로: 나무 수","mis":"M4-1-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 마을, 세로에는 나무 수를 그루 단위로 나타냈어요.","가로: 마을, 세로: 나무 수예요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을","마 마을"],"series":[{"vals":[70,80,55,25,75]}],"step":5,"ymax":85,"ylab":"(그루)","title":"마을별 나무 수"}},{"stem":"이번에는 다른 그림이에요. 아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 학년, 세로: 학생 수","correct":true},{"t":"가로: 학생 수, 세로: 학년","mis":"M4-1-u5-X01"},{"t":"가로: 학년, 세로: 학년","mis":"M4-1-u5-X01"},{"t":"가로: 학생 수, 세로: 학생 수","mis":"M4-1-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 학년, 세로에는 학생 수를 명 단위로 나타냈어요.","가로: 학년, 세로: 학생 수예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1학년","2학년","3학년","4학년","5학년","6학년"],"series":[{"vals":[30,25,65,85,45,75]}],"step":5,"ymax":90,"ylab":"(명)","title":"학년별 우유 신청 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#3','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C1',1,'sa','auto','조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u5-C1","difficulty":1,"kind":"sa","stem":"조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["합계는 항목별 수를 모두 더한 것이에요.","5 + 7 + 4 + 1 + 3. = 20","합계는 20명이에요 — 모두 답했는지 확인할 수 있어요."],"asset":{"type":"picg","only":"table","head":"직업","cols":["요리사","경찰관","과학자","가수","의사"],"counts":[5,7,4,1,3],"vh":"학생 수","unit":"명","total":null,"title":"희망 직업별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["합계는 항목별 수를 모두 더한 것이에요.","8 + 7 + 6 + 3 + 11. = 35","합계는 35명이에요 — 모두 답했는지 확인할 수 있어요."],"asset":{"type":"picg","only":"table","head":"급식 메뉴","cols":["카레","잡채","불고기","국수","김밥"],"counts":[8,7,6,3,11],"vh":"학생 수","unit":"명","total":null,"title":"좋아하는 급식 메뉴별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["37"],"explanation":["합계는 항목별 수를 모두 더한 것이에요.","3 + 8 + 12 + 9 + 5. = 37","합계는 37명이에요 — 모두 답했는지 확인할 수 있어요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","만두"],"counts":[3,8,12,9,5],"vh":"학생 수","unit":"명","total":null,"title":"좋아하는 간식별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#4','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C4',1,'mc','auto','막대그래프의 제목에 대해 알맞게 말한 것은 어느 것인가요?',ARRAY['M4-1-u5-X18','M4-1-u5-X04','M4-1-u5-X03']::text[],true,'{"seq":4,"concept":"M4-1-u5-C4","difficulty":1,"kind":"mc","stem":"막대그래프의 제목에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"맨 처음에 써도 되고 맨 마지막에 써도 돼요.","correct":true},{"t":"맨 처음에만 써야 해요.","mis":"M4-1-u5-X18"},{"t":"제목은 쓰지 않아도 돼요.","mis":"M4-1-u5-X04"},{"t":"막대마다 하나씩 써요.","mis":"M4-1-u5-X03"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"variant_rule":{"alt":[{"stem":"막대를 그릴 때 지켜야 할 것은 어느 것인가요?","options":[{"t":"막대의 굵기를 모두 같게 그려요.","correct":true},{"t":"수가 많은 막대를 더 굵게 그려요.","mis":"M4-1-u5-X03"},{"t":"막대마다 눈금 한 칸을 다르게 해요.","mis":"M4-1-u5-X02"},{"t":"수가 적은 막대는 그리지 않아요.","mis":"M4-1-u5-X05"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"asset":null},{"stem":"학생 수를 나타내는 막대그래프에서 세로 눈금의 단위로 알맞은 것은 어느 것인가요?","options":[{"t":"명","correct":true},{"t":"개","mis":"M4-1-u5-X01"},{"t":"권","mis":"M4-1-u5-X01"},{"t":"kg","mis":"M4-1-u5-X01"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#5','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C5',1,'sa','auto','표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 명까지 나타내어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u5-C5","difficulty":1,"kind":"sa","stem":"표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 명까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["세로 눈금은 모든 막대를 그릴 수 있어야 해요.","표에서 가장 큰 수는 9명이에요.","그래서 세로 눈금은 적어도 9명까지 나타내요."],"asset":{"type":"picg","only":"table","head":"급식 메뉴","cols":["카레","잡채","불고기","국수","김밥"],"counts":[4,2,9,7,3],"vh":"학생 수","unit":"명","title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 명까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["세로 눈금은 모든 막대를 그릴 수 있어야 해요.","표에서 가장 큰 수는 12명이에요.","그래서 세로 눈금은 적어도 12명까지 나타내요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","만두"],"counts":[8,5,12,6,2],"vh":"학생 수","unit":"명","title":"좋아하는 간식별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 명까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["세로 눈금은 모든 막대를 그릴 수 있어야 해요.","표에서 가장 큰 수는 9명이에요.","그래서 세로 눈금은 적어도 9명까지 나타내요."],"asset":{"type":"picg","only":"table","head":"동물","cols":["강아지","고양이","토끼","햄스터","금붕어"],"counts":[7,6,2,9,4],"vh":"학생 수","unit":"명","title":"기르고 싶은 동물별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#6','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C6',1,'mc','auto','같은 자료에서 눈금 한 칸을 작게 하면 막대는 어떻게 되나요?',ARRAY['M4-1-u5-X21','M4-1-u5-X06']::text[],true,'{"seq":6,"concept":"M4-1-u5-C6","difficulty":1,"kind":"mc","stem":"같은 자료에서 눈금 한 칸을 작게 하면 막대는 어떻게 되나요?","options":[{"t":"막대가 길어져요.","correct":true},{"t":"막대가 짧아져요.","mis":"M4-1-u5-X21"},{"t":"막대가 나타내는 수가 작아져요.","mis":"M4-1-u5-X06"},{"t":"항목의 개수가 늘어나요.","mis":"M4-1-u5-X06"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"variant_rule":{"alt":[{"stem":"눈금 한 칸의 크기를 고르는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"가장 큰 수를 담으면서 차이가 잘 드러나게 해요.","correct":true},{"t":"언제나 한 칸을 1로 해요.","mis":"M4-1-u5-X07"},{"t":"한 칸을 될 수 있는 대로 크게 해요.","mis":"M4-1-u5-X07"},{"t":"아무렇게나 정해도 돼요.","mis":"M4-1-u5-X07"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"asset":null},{"stem":"눈금 한 칸을 너무 크게 정하면 어떤 점이 불편한가요?","options":[{"t":"막대들이 다 비슷해 보여서 차이를 알아보기 어려워요.","correct":true},{"t":"가장 큰 수가 그래프 밖으로 넘쳐요.","mis":"M4-1-u5-X21"},{"t":"항목을 모두 쓸 수 없어요.","mis":"M4-1-u5-X07"},{"t":"제목을 쓸 자리가 없어져요.","mis":"M4-1-u5-X07"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#7','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C9',1,'mc','auto','자료를 조사하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X18']::text[],true,'{"seq":7,"concept":"M4-1-u5-C9","difficulty":1,"kind":"mc","stem":"자료를 조사하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주제 → 항목 → 방법 → 조사","correct":true},{"t":"방법 → 조사 → 주제 → 항목","mis":"M4-1-u5-X18"},{"t":"조사 → 주제 → 항목 → 방법","mis":"M4-1-u5-X18"},{"t":"항목 → 방법 → 조사 → 주제","mis":"M4-1-u5-X18"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"variant_rule":{"alt":[{"stem":"조사가 끝나면 꼭 확인할 것은 무엇인가요?","options":[{"t":"합계가 인원과 같은지","correct":true},{"t":"가장 많은 항목이 무엇인지만","mis":"M4-1-u5-X15"},{"t":"항목의 이름이 멋있는지","mis":"M4-1-u5-X13"},{"t":"조사 방법이 가장 빨랐는지","mis":"M4-1-u5-X16"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"asset":null},{"stem":"항목을 정할 때 고르지 못한 친구를 위해 두면 좋은 칸은 무엇인가요?","options":[{"t":"기타","correct":true},{"t":"합계","mis":"M4-1-u5-X14"},{"t":"제목","mis":"M4-1-u5-X14"},{"t":"단위","mis":"M4-1-u5-X14"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#8','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C11',1,'mc','auto','두 자료를 하나의 막대그래프에 나타내면 좋은 점은 무엇인가요?',ARRAY['M4-1-u5-X21','M4-1-u5-X20','M4-1-u5-X11']::text[],true,'{"seq":8,"concept":"M4-1-u5-C11","difficulty":1,"kind":"mc","stem":"두 자료를 하나의 막대그래프에 나타내면 좋은 점은 무엇인가요?","options":[{"t":"항목마다 두 자료를 한눈에 견줄 수 있어요.","correct":true},{"t":"두 그래프 사이를 오가며 봐야 해요.","mis":"M4-1-u5-X21"},{"t":"나타내는 수가 저절로 커져요.","mis":"M4-1-u5-X20"},{"t":"그렇게 된 까닭까지 알 수 있어요.","mis":"M4-1-u5-X11"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"variant_rule":{"alt":[{"stem":"항목별로 두 막대씩 묶어 그리면 무엇을 한눈에 알 수 있나요?","options":[{"t":"항목마다 두 자료가 얼마나 다른지","correct":true},{"t":"항목마다 그렇게 된 까닭","mis":"M4-1-u5-X11"},{"t":"앞으로 늘어날 수","mis":"M4-1-u5-X11"},{"t":"막대마다 다른 굵기","mis":"M4-1-u5-X03"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"asset":null},{"stem":"같은 두 자료를 묶는 방법만 바꾸어 다시 그리면 무엇이 달라지나요?","options":[{"t":"막대를 늘어놓는 차례만 달라지고 나타내는 수는 그대로예요.","correct":true},{"t":"막대가 나타내는 수가 달라져요.","mis":"M4-1-u5-X20"},{"t":"눈금 한 칸이 저절로 달라져요.","mis":"M4-1-u5-X20"},{"t":"자료가 더 많아져요.","mis":"M4-1-u5-X20"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#9','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C3',2,'sa','auto','2모둠이 모은 빈 병은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u5-C3","difficulty":2,"kind":"sa","stem":"2모둠이 모은 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["세로 눈금 한 칸은 2개예요.","2모둠의 막대는 0에서 2칸이에요.","2 × 2 = 4 — 2모둠이 모은 빈 병은 4개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠","5모둠"],"series":[{"vals":[28,4,18,30,12]}],"step":2,"ymax":32,"ylab":"(개)","title":"모둠별 모은 빈 병 수"},"variant_rule":{"alt":[{"stem":"마 지역의 문화유산은 몇 점인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["세로 눈금 한 칸은 25점이에요.","마 지역의 막대는 0에서 2칸이에요.","2 × 25 = 50 — 마 지역의 문화유산은 50점이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 지역","나 지역","다 지역","라 지역","마 지역"],"series":[{"vals":[25,125,150,100,50]}],"step":25,"ymax":175,"ylab":"(점)","title":"지역별 문화유산 수"}},{"stem":"사과를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["세로 눈금 한 칸은 1명이에요.","사과의 막대 끝을 따라 세로 눈금을 읽어요.","사과를 좋아하는 학생은 2명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["사과","포도","딸기","귤","배"],"series":[{"vals":[2,9,6,7,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 과일별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#10','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C5',2,'sa','auto','세로 눈금 한 칸이 20 kg인 막대그래프에 160 kg을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u5-C5","difficulty":2,"kind":"sa","stem":"세로 눈금 한 칸이 20 kg인 막대그래프에 160 kg을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 칸이 20 kg이니 한 칸 올라갈 때마다 20씩 커져요.","막대의 칸 수는 160 ÷ 20으로 구해요.","160 ÷ 20 = 8 — 8칸으로 그려요."],"variant_rule":{"alt":[{"stem":"세로 눈금 한 칸이 25점인 막대그래프에 125점을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 칸이 25점이니 한 칸 올라갈 때마다 25씩 커져요.","막대의 칸 수는 125 ÷ 25로 구해요.","125 ÷ 25 = 5 — 5칸으로 그려요."],"asset":null},{"stem":"세로 눈금 한 칸이 2개인 막대그래프에 18개를 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 칸이 2개이니 한 칸 올라갈 때마다 2씩 커져요.","막대의 칸 수는 18 ÷ 2로 구해요.","18 ÷ 2 = 9 — 9칸으로 그려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#11','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C6',2,'sa','auto','눈금 한 칸이 20 kg인 막대그래프에서 10칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 40 kg인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M4-1-u5-C6","difficulty":2,"kind":"sa","stem":"눈금 한 칸이 20 kg인 막대그래프에서 10칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 40 kg인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["5"],"explanation":["먼저 막대가 나타내는 수를 구해요: 10 × 20 = 200.","나타내는 수 200 kg은 눈금이 바뀌어도 그대로예요.","200 ÷ 40 = 5 — 5칸이 돼요."],"variant_rule":{"alt":[{"stem":"눈금 한 칸이 25점인 막대그래프에서 6칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 50점인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 막대가 나타내는 수를 구해요: 6 × 25 = 150.","나타내는 수 150점은 눈금이 바뀌어도 그대로예요.","150 ÷ 50 = 3 — 3칸이 돼요."],"asset":null},{"stem":"눈금 한 칸이 2명인 막대그래프에서 20칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 5명인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["8"],"explanation":["먼저 막대가 나타내는 수를 구해요: 20 × 2 = 40.","나타내는 수 40명은 눈금이 바뀌어도 그대로예요.","40 ÷ 5 = 8 — 8칸이 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#12','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C7',2,'sa','auto','가을을 좋아하는 학생은 봄을 좋아하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M4-1-u5-C7","difficulty":2,"kind":"sa","stem":"가을을 좋아하는 학생은 봄을 좋아하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가을은 7명, 봄은 3명이에요.","몇 더 많은지는 큰 수에서 작은 수를 빼요.","7 − 3 = 4 — 4명 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"vals":[3,5,7,10]}],"step":1,"ymax":11,"ylab":"(명)","title":"좋아하는 계절별 학생 수"},"variant_rule":{"alt":[{"stem":"방송 체험을 고른 학생은 요리 체험을 고른 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["7"],"explanation":["방송은 10명, 요리는 3명이에요.","몇 더 많은지는 큰 수에서 작은 수를 빼요.","10 − 3 = 7 — 7명 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["로봇","요리","방송","소방","과학"],"series":[{"vals":[12,3,10,5,7]}],"step":1,"ymax":13,"ylab":"(명)","title":"가고 싶은 체험별 학생 수"}},{"stem":"가수를 희망하는 학생은 경찰관을 희망하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["7"],"explanation":["가수는 10명, 경찰관은 3명이에요.","몇 더 많은지는 큰 수에서 작은 수를 빼요.","10 − 3 = 7 — 7명 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["요리사","경찰관","과학자","가수","의사"],"series":[{"vals":[9,3,8,10,7]}],"step":1,"ymax":11,"ylab":"(명)","title":"희망 직업별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#13','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C8',2,'mc','auto','아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?',ARRAY['M4-1-u5-X21']::text[],true,'{"seq":13,"concept":"M4-1-u5-C8","difficulty":2,"kind":"mc","stem":"아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"학생들이 그 항목을 고른 까닭","correct":true},{"t":"가장 많은 학생이 고른 항목","mis":"M4-1-u5-X21"},{"t":"김밥의 학생 수","mis":"M4-1-u5-X21"},{"t":"김밥과 불고기의 학생 수의 차","mis":"M4-1-u5-X21"}],"explanation":["막대그래프에서는 항목별 수, 가장 많은 것, 두 항목의 차를 알 수 있어요.","「학생들이 그 항목을 고른 까닭」은 그래프에 나와 있지 않아요.","그래프에 없는 것은 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["카레","잡채","불고기","국수","김밥"],"series":[{"vals":[10,8,7,9,4]}],"step":1,"ymax":11,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"다음 달에 가장 인기 있을 항목","correct":true},{"t":"가장 많은 학생이 고른 항목","mis":"M4-1-u5-X21"},{"t":"김밥의 학생 수","mis":"M4-1-u5-X21"},{"t":"김밥과 떡볶이의 학생 수의 차","mis":"M4-1-u5-X21"}],"explanation":["막대그래프에서는 항목별 수, 가장 많은 것, 두 항목의 차를 알 수 있어요.","「다음 달에 가장 인기 있을 항목」은 그래프에 나와 있지 않아요.","그래프에 없는 것은 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","만두"],"series":[{"vals":[5,3,11,2,9]}],"step":1,"ymax":12,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"조사한 날의 날씨","correct":true},{"t":"가장 많은 학생이 고른 항목","mis":"M4-1-u5-X21"},{"t":"고양이의 학생 수","mis":"M4-1-u5-X21"},{"t":"고양이와 강아지의 학생 수의 차","mis":"M4-1-u5-X21"}],"explanation":["막대그래프에서는 항목별 수, 가장 많은 것, 두 항목의 차를 알 수 있어요.","「조사한 날의 날씨」는 그래프에 나와 있지 않아요.","그래프에 없는 것은 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["강아지","고양이","토끼","햄스터","금붕어"],"series":[{"vals":[4,1,5,6,11]}],"step":1,"ymax":12,"ylab":"(명)","title":"기르고 싶은 동물별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#14','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C9',2,'mc','auto','친구들이 다른 친구 눈치를 보지 않고 차분히 답하게 하고 싶어요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?',ARRAY['M4-1-u5-X16']::text[],true,'{"seq":14,"concept":"M4-1-u5-C9","difficulty":2,"kind":"mc","stem":"친구들이 다른 친구 눈치를 보지 않고 차분히 답하게 하고 싶어요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"종이에 적어 내기 — 혼자 차분히 생각해서 쓸 수 있으니까요.","correct":true},{"t":"손 들기 — 누가 어디에 드는지 다 보이니까요.","mis":"M4-1-u5-X16"},{"t":"붙임쪽지 — 모두 앞에 나와 붙이니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 혼자 차분히 생각해서 쓸 수 있으니까요.","그래서 종이에 적어 내기가 알맞아요."],"variant_rule":{"alt":[{"stem":"교실 게시판에 결과가 한눈에 모이는 모습을 보여 주고 싶어요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"붙임쪽지 — 붙이면 한눈에 모이니까요.","correct":true},{"t":"종이에 적어 내기 — 걷어서 따로 세니까요.","mis":"M4-1-u5-X16"},{"t":"손 들기 — 손을 내리면 사라지니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 붙이면 한눈에 모이니까요.","그래서 붙임쪽지가 알맞아요."],"asset":null},{"stem":"멀리 떨어진 다른 학교 친구들과 함께 조사하려고 해요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"온라인 설문 — 멀리 있는 사람도 답할 수 있으니까요.","correct":true},{"t":"손 들기 — 그 자리에서 셀 수 있으니까요.","mis":"M4-1-u5-X16"},{"t":"붙임쪽지 — 우리 교실 게시판에 붙이면 되니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 멀리 있는 사람도 답할 수 있으니까요.","그래서 온라인 설문이 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#15','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C10',2,'mc','auto','이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X11','M4-1-u5-X21']::text[],true,'{"seq":15,"concept":"M4-1-u5-C10","difficulty":2,"kind":"mc","stem":"이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 놀이는 공기다.」","correct":true},{"t":"「내일은 줄넘기가 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「공기는 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「줄넘기가 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 공기의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["술래잡기","공기","줄넘기","피구","기타"],"series":[{"vals":[7,10,6,8,4]}],"step":1,"ymax":11,"ylab":"(명)","title":"즐겨 하는 놀이별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 메뉴는 카레다.」","correct":true},{"t":"「내일은 잡채가 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「카레는 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「잡채가 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 카레의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["불고기","잡채","카레","국수","기타"],"series":[{"vals":[7,4,8,5,6]}],"step":1,"ymax":9,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 간식은 과일이다.」","correct":true},{"t":"「내일은 떡볶이가 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「과일은 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「떡볶이가 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 과일의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","기타"],"series":[{"vals":[6,10,12,8,4]}],"step":2,"ymax":14,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#16','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C11',2,'sa','auto','지난달 2모둠의 빈 병 수는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-1-u5-C11","difficulty":2,"kind":"sa","stem":"지난달 2모둠의 빈 병 수는 몇 개인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["이름표에서 지난달의 막대 색을 먼저 찾아요.","2모둠 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 5개).","지난달 2모둠의 빈 병 수는 35개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"지난달","vals":[10,35,65,30]},{"name":"이번 달","vals":[30,60,80,40]}],"step":5,"ymax":85,"ylab":"(개)","title":"지난달과 이번 달 모은 빈 병 수"},"variant_rule":{"alt":[{"stem":"올해 나 마을의 나무 수는 몇 그루인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["이름표에서 올해의 막대 색을 먼저 찾아요.","나 마을 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 5그루).","올해 나 마을의 나무 수는 50그루예요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을"],"series":[{"name":"작년","vals":[35,10,20,15]},{"name":"올해","vals":[45,50,25,35]}],"step":5,"ymax":55,"ylab":"(그루)","title":"작년과 올해 심은 나무 수"}},{"stem":"2학기 3모둠의 붙임딱지 수는 몇 개인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["이름표에서 2학기의 막대 색을 먼저 찾아요.","3모둠 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 2개).","2학기 3모둠의 붙임딱지 수는 20개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"1학기","vals":[18,16,14,4]},{"name":"2학기","vals":[22,30,20,16]}],"step":2,"ymax":32,"ylab":"(개)","title":"1학기와 2학기 칭찬 붙임딱지 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#17','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C5',3,'mc','auto','표의 내용은 「사과 8명, 포도 11명, 딸기 9명, 귤 4명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?',ARRAY['M4-1-u5-X02']::text[],true,'{"seq":17,"concept":"M4-1-u5-C5","difficulty":3,"kind":"mc","stem":"표의 내용은 「사과 8명, 포도 11명, 딸기 9명, 귤 4명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"사과","correct":true},{"t":"포도","mis":"M4-1-u5-X02"},{"t":"딸기","mis":"M4-1-u5-X02"},{"t":"귤","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 1명이에요.","막대마다 표의 수와 견주어 봐요.","사과의 막대는 7명인데 표에서는 8명이에요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["사과","포도","딸기","귤"],"series":[{"vals":[7,11,9,4]}],"step":1,"ymax":12,"ylab":"(명)","title":"좋아하는 과일별 학생 수"},"variant_rule":{"alt":[{"stem":"표의 내용은 「축구 4명, 피구 5명, 수영 12명, 야구 2명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"피구","correct":true},{"t":"축구","mis":"M4-1-u5-X02"},{"t":"수영","mis":"M4-1-u5-X02"},{"t":"야구","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 1명이에요.","막대마다 표의 수와 견주어 봐요.","피구의 막대는 6명인데 표에서는 5명이에요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["축구","피구","수영","야구"],"series":[{"vals":[4,6,12,2]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 운동별 학생 수"}},{"stem":"표의 내용은 「봄 12명, 여름 5명, 가을 8명, 겨울 7명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"겨울","correct":true},{"t":"봄","mis":"M4-1-u5-X02"},{"t":"여름","mis":"M4-1-u5-X02"},{"t":"가을","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 1명이에요.","막대마다 표의 수와 견주어 봐요.","겨울의 막대는 6명인데 표에서는 7명이에요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"vals":[12,5,8,6]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 계절별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#18','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C6',3,'mc','auto','「반별 빌린 책 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 10권으로 그렸어요, 나 그래프는 눈금 한 칸을 200권으로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X07']::text[],true,'{"seq":18,"concept":"M4-1-u5-C6","difficulty":3,"kind":"mc","stem":"「반별 빌린 책 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 10권으로 그렸어요, 나 그래프는 눈금 한 칸을 200권으로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"가 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"나 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 200권면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 10권인 가 그래프가 차이를 알아보기 좋아요."],"variant_rule":{"alt":[{"stem":"「농장별 토마토 생산량」을 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 320 kg으로 그렸어요, 나 그래프는 눈금 한 칸을 20 kg으로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"가 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 320 kg면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 20 kg인 나 그래프가 차이를 알아보기 좋아요."],"asset":null},{"stem":"「마을별 나무 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 5그루로 그렸어요, 나 그래프는 눈금 한 칸을 120그루로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"가 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"나 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 120그루면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 5그루인 가 그래프가 차이를 알아보기 좋아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#19','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C7',3,'mc','auto','김밥을 좋아하는 학생은 빵을 좋아하는 학생의 몇 배인가요?',ARRAY['M4-1-u5-X09']::text[],true,'{"seq":19,"concept":"M4-1-u5-C7","difficulty":3,"kind":"mc","stem":"김밥을 좋아하는 학생은 빵을 좋아하는 학생의 몇 배인가요?","options":[{"t":"3배","correct":true},{"t":"6배","mis":"M4-1-u5-X09"},{"t":"4배","mis":"M4-1-u5-X09"},{"t":"2배","mis":"M4-1-u5-X09"}],"explanation":["김밥은 9명, 빵은 3명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 3 × 3 = 9.","그래서 3배예요 — 차(6)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","만두"],"series":[{"vals":[7,9,11,3,10]}],"step":1,"ymax":12,"ylab":"(명)","title":"좋아하는 간식별 학생 수"},"variant_rule":{"alt":[{"stem":"고양이를 기르고 싶은 학생은 강아지를 기르고 싶은 학생의 몇 배인가요?","options":[{"t":"2배","correct":true},{"t":"4배","mis":"M4-1-u5-X09"},{"t":"3배","mis":"M4-1-u5-X09"},{"t":"1배","mis":"M4-1-u5-X09"}],"explanation":["고양이는 8명, 강아지는 4명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 4 × 2 = 8.","그래서 2배예요 — 차(4)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["강아지","고양이","토끼","햄스터","금붕어"],"series":[{"vals":[4,8,1,9,7]}],"step":1,"ymax":10,"ylab":"(명)","title":"기르고 싶은 동물별 학생 수"}},{"stem":"배를 좋아하는 학생은 사과를 좋아하는 학생의 몇 배인가요?","options":[{"t":"3배","correct":true},{"t":"8배","mis":"M4-1-u5-X09"},{"t":"4배","mis":"M4-1-u5-X09"},{"t":"2배","mis":"M4-1-u5-X09"}],"explanation":["배는 12명, 사과는 4명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 4 × 3 = 12.","그래서 3배예요 — 차(8)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["사과","포도","딸기","귤","배"],"series":[{"vals":[4,2,9,6,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 과일별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#20','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C8',3,'mc','auto','가 그래프는 눈금 한 칸이 2명이고 축구의 막대가 7칸이에요. 나 그래프는 눈금 한 칸이 10명이고 피구의 막대가 2칸이에요. 축구의 막대가 더 길어 보이는데, 축구를 고른 학생이 더 많은 걸까요?',ARRAY['M4-1-u5-X10','M4-1-u5-X02','M4-1-u5-X12']::text[],true,'{"seq":20,"concept":"M4-1-u5-C8","difficulty":3,"kind":"mc","stem":"가 그래프는 눈금 한 칸이 2명이고 축구의 막대가 7칸이에요. 나 그래프는 눈금 한 칸이 10명이고 피구의 막대가 2칸이에요. 축구의 막대가 더 길어 보이는데, 축구를 고른 학생이 더 많은 걸까요?","options":[{"t":"아니요 — 눈금이 달라요. 축구는 14명, 피구는 20명이에요.","correct":true},{"t":"네 — 막대가 길면 언제나 수가 많아요.","mis":"M4-1-u5-X10"},{"t":"두 막대가 나타내는 수는 똑같아요.","mis":"M4-1-u5-X02"},{"t":"네 — 가 그래프가 먼저 나왔으니까요.","mis":"M4-1-u5-X12"}],"explanation":["다른 그래프끼리 견줄 때는 눈금부터 확인해요.","축구는 7 × 2 = 14명, 피구는 2 × 10 = 20명이에요.","막대는 축구가 더 길어도 수는 피구가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 그래프는 눈금 한 칸이 1명이고 사과의 막대가 6칸이에요. 나 그래프는 눈금 한 칸이 2명이고 배의 막대가 4칸이에요. 사과의 막대가 더 길어 보이는데, 사과를 고른 학생이 더 많은 걸까요?","options":[{"t":"아니요 — 눈금이 달라요. 사과는 6명, 배는 8명이에요.","correct":true},{"t":"네 — 막대가 길면 언제나 수가 많아요.","mis":"M4-1-u5-X10"},{"t":"두 막대가 나타내는 수는 똑같아요.","mis":"M4-1-u5-X02"},{"t":"네 — 가 그래프가 먼저 나왔으니까요.","mis":"M4-1-u5-X12"}],"explanation":["다른 그래프끼리 견줄 때는 눈금부터 확인해요.","사과는 6 × 1 = 6명, 배는 4 × 2 = 8명이에요.","막대는 사과가 더 길어도 수는 배가 더 많아요."],"asset":null},{"stem":"가 그래프는 눈금 한 칸이 1명이고 떡볶이의 막대가 10칸이에요. 나 그래프는 눈금 한 칸이 5명이고 만두의 막대가 3칸이에요. 떡볶이의 막대가 더 길어 보이는데, 떡볶이를 고른 학생이 더 많은 걸까요?","options":[{"t":"아니요 — 눈금이 달라요. 떡볶이는 10명, 만두는 15명이에요.","correct":true},{"t":"네 — 막대가 길면 언제나 수가 많아요.","mis":"M4-1-u5-X10"},{"t":"두 막대가 나타내는 수는 똑같아요.","mis":"M4-1-u5-X02"},{"t":"네 — 가 그래프가 먼저 나왔으니까요.","mis":"M4-1-u5-X12"}],"explanation":["다른 그래프끼리 견줄 때는 눈금부터 확인해요.","떡볶이는 10 × 1 = 10명, 만두는 3 × 5 = 15명이에요.","막대는 떡볶이가 더 길어도 수는 만두가 더 많아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#21','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C9',3,'mc','auto','조사를 했더니 합계가 27명이 나왔어요. 우리 반은 26명인데요! 무슨 일이 생긴 걸까요?',ARRAY['M4-1-u5-X21','M4-1-u5-X14','M4-1-u5-X15']::text[],true,'{"seq":21,"concept":"M4-1-u5-C9","difficulty":3,"kind":"mc","stem":"조사를 했더니 합계가 27명이 나왔어요. 우리 반은 26명인데요! 무슨 일이 생긴 걸까요?","options":[{"t":"두 번 답한 친구가 있어요 — 한 사람은 한 번만 답해야 해요.","correct":true},{"t":"빠진 친구가 있어요 — 모두 한 번씩 답해야 해요.","mis":"M4-1-u5-X21"},{"t":"항목을 너무 많이 만들었어요.","mis":"M4-1-u5-X14"},{"t":"합계는 인원과 달라도 괜찮아요.","mis":"M4-1-u5-X15"}],"explanation":["합계는 우리 반 인원과 같아야 해요.","합계 27명이 인원 26명보다 많아요.","많으면 두 번 답한 친구가, 적으면 빠진 친구가 있는 거예요."],"variant_rule":{"alt":[{"stem":"조사를 했더니 합계가 21명이 나왔어요. 우리 반은 23명인데요! 무슨 일이 생긴 걸까요?","options":[{"t":"빠진 친구가 있어요 — 모두 한 번씩 답해야 해요.","correct":true},{"t":"두 번 답한 친구가 있어요 — 한 사람은 한 번만 답해야 해요.","mis":"M4-1-u5-X21"},{"t":"항목을 너무 많이 만들었어요.","mis":"M4-1-u5-X14"},{"t":"합계는 인원과 달라도 괜찮아요.","mis":"M4-1-u5-X15"}],"explanation":["합계는 우리 반 인원과 같아야 해요.","합계 21명이 인원 23명보다 적어요.","많으면 두 번 답한 친구가, 적으면 빠진 친구가 있는 거예요."],"asset":null},{"stem":"조사를 했더니 합계가 30명이 나왔어요. 우리 반은 27명인데요! 무슨 일이 생긴 걸까요?","options":[{"t":"두 번 답한 친구가 있어요 — 한 사람은 한 번만 답해야 해요.","correct":true},{"t":"빠진 친구가 있어요 — 모두 한 번씩 답해야 해요.","mis":"M4-1-u5-X21"},{"t":"항목을 너무 많이 만들었어요.","mis":"M4-1-u5-X14"},{"t":"합계는 인원과 달라도 괜찮아요.","mis":"M4-1-u5-X15"}],"explanation":["합계는 우리 반 인원과 같아야 해요.","합계 30명이 인원 27명보다 많아요.","많으면 두 번 답한 친구가, 적으면 빠진 친구가 있는 거예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#22','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C11',3,'mc','auto','작년보다 올해에 빌린 책 수가 가장 많이 늘어난 항목은 어느 것인가요?',ARRAY['M4-1-u5-X09']::text[],true,'{"seq":22,"concept":"M4-1-u5-C11","difficulty":3,"kind":"mc","stem":"작년보다 올해에 빌린 책 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"과학","correct":true},{"t":"만화","mis":"M4-1-u5-X09"},{"t":"동화","mis":"M4-1-u5-X09"},{"t":"역사","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 동화 10, 과학 60, 역사 30, 만화 40.","올해의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 과학이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["동화","과학","역사","만화"],"series":[{"name":"작년","vals":[100,20,40,90]},{"name":"올해","vals":[110,80,70,130]}],"step":10,"ymax":140,"ylab":"(권)","title":"작년과 올해 빌린 책 수"},"variant_rule":{"alt":[{"stem":"지난달보다 이번 달에 빈 병 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"3모둠","correct":true},{"t":"2모둠","mis":"M4-1-u5-X09"},{"t":"1모둠","mis":"M4-1-u5-X09"},{"t":"4모둠","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 1모둠 30, 2모둠 35, 3모둠 40, 4모둠 10.","이번 달의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 3모둠이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"지난달","vals":[10,45,25,50]},{"name":"이번 달","vals":[40,80,65,60]}],"step":5,"ymax":85,"ylab":"(개)","title":"지난달과 이번 달 모은 빈 병 수"}},{"stem":"작년보다 올해에 나무 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"가 마을","correct":true},{"t":"라 마을","mis":"M4-1-u5-X09"},{"t":"나 마을","mis":"M4-1-u5-X09"},{"t":"다 마을","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 가 마을 35, 나 마을 20, 다 마을 15, 라 마을 25.","올해의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 가 마을이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을"],"series":[{"name":"작년","vals":[25,15,30,40]},{"name":"올해","vals":[60,35,45,65]}],"step":5,"ymax":70,"ylab":"(그루)","title":"작년과 올해 심은 나무 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#23','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C10',4,'sa','auto','우리 반 36명이 모두 답한 간식 조사의 표에서 떡볶이의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 떡볶이 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-1-u5-C10","difficulty":4,"kind":"sa","stem":"우리 반 36명이 모두 답한 간식 조사의 표에서 떡볶이의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 떡볶이 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["떡볶이의 수는 36 − (8 + 4 + 12 + 10) = 2명이에요.","눈금 한 칸이 2명이니 2 ÷ 2로 구해요.","1칸으로 그려요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","기타"],"counts":[null,8,4,12,10],"vh":"학생 수","unit":"명","total":36,"title":"좋아하는 간식별 학생 수"},"variant_rule":{"alt":[{"stem":"우리 반 34명이 모두 답한 간식 조사의 표에서 빵의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 빵 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["빵의 수는 34 − (12 + 10 + 6 + 4) = 2명이에요.","눈금 한 칸이 2명이니 2 ÷ 2로 구해요.","1칸으로 그려요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","기타"],"counts":[12,10,6,null,4],"vh":"학생 수","unit":"명","total":34,"title":"좋아하는 간식별 학생 수"}},{"stem":"우리 반 40명이 모두 답한 간식 조사의 표에서 과일의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 과일 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["과일의 수는 40 − (8 + 4 + 14 + 12) = 2명이에요.","눈금 한 칸이 2명이니 2 ÷ 2로 구해요.","1칸으로 그려요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","기타"],"counts":[8,4,null,14,12],"vh":"학생 수","unit":"명","total":40,"title":"좋아하는 간식별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#24','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C11',4,'sa','auto','지난달과 이번 달의 차가 가장 큰 항목에서, 두 수의 차는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-1-u5-C11","difficulty":4,"kind":"sa","stem":"지난달과 이번 달의 차가 가장 큰 항목에서, 두 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["항목마다 두 막대의 차를 구해요: 1모둠 55, 2모둠 35, 3모둠 5, 4모둠 50.","차가 가장 큰 항목은 1모둠이에요.","그 차는 55개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"지난달","vals":[10,35,75,25]},{"name":"이번 달","vals":[65,70,80,75]}],"step":5,"ymax":85,"ylab":"(개)","title":"지난달과 이번 달 모은 빈 병 수"},"variant_rule":{"alt":[{"stem":"작년과 올해의 차가 가장 큰 항목에서, 두 수의 차는 몇 그루인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["항목마다 두 막대의 차를 구해요: 가 마을 50, 나 마을 15, 다 마을 20, 라 마을 40.","차가 가장 큰 항목은 가 마을이에요.","그 차는 50그루예요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을"],"series":[{"name":"작년","vals":[10,25,15,30]},{"name":"올해","vals":[60,40,35,70]}],"step":5,"ymax":75,"ylab":"(그루)","title":"작년과 올해 심은 나무 수"}},{"stem":"1학기와 2학기의 차가 가장 큰 항목에서, 두 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["항목마다 두 막대의 차를 구해요: 1모둠 22, 2모둠 2, 3모둠 20, 4모둠 6.","차가 가장 큰 항목은 1모둠이에요.","그 차는 22개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"1학기","vals":[8,22,6,14]},{"name":"2학기","vals":[30,24,26,20]}],"step":2,"ymax":32,"ylab":"(개)","title":"1학기와 2학기 칭찬 붙임딱지 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_a#25','math',4,1,'u5','','g4_1_math_u5_review_a','unit_review','M4-1-u5-C3',4,'essay','teacher','「반별 빌린 책 수」 막대그래프에서 세로 눈금 한 칸은 10권이에요. 3반의 막대가 0에서 7칸일 때 한 친구는 「3반은 7권을 빌렸어. 그리고 3반 막대가 가장 굵으니 가장 많이 빌린 거야.」라고 했어요. 친구의 말에서 잘못된 점 두 가지를 찾아 바르게 고쳐 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u5-C3","difficulty":4,"kind":"essay","stem":"「반별 빌린 책 수」 막대그래프에서 세로 눈금 한 칸은 10권이에요. 3반의 막대가 0에서 7칸일 때 한 친구는 「3반은 7권을 빌렸어. 그리고 3반 막대가 가장 굵으니 가장 많이 빌린 거야.」라고 했어요. 친구의 말에서 잘못된 점 두 가지를 찾아 바르게 고쳐 써 보세요.","answer_guide":{"answer":"예: 첫째, 눈금 한 칸의 크기를 확인하지 않고 칸 수를 그대로 읽었다. 한 칸이 10권이므로 7칸은 7 × 10 = 70권이다. 둘째, 막대그래프에서 수량은 막대의 길이로 나타내고 굵기와는 관계없으므로, 가장 많이 빌린 반은 가장 긴 막대를 찾아야 한다.","scoring_points":["칸 수를 그대로 읽은 잘못을 찾고 70권으로 고쳤는가","굵기가 아니라 길이로 수량을 나타낸다고 썼는가","가장 긴 막대로 찾는다고 썼는가"]},"explanation":["세로 눈금 한 칸은 10권이에요.","7칸 × 10권 = 70권.","수량은 막대의 길이로만 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#1','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C2',1,'mc','auto','그림그래프와 막대그래프의 다른 점으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X04']::text[],true,'{"seq":1,"concept":"M4-1-u5-C2","difficulty":1,"kind":"mc","stem":"그림그래프와 막대그래프의 다른 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"수량을 그림그래프는 그림으로, 막대그래프는 막대의 길이로 나타내요.","correct":true},{"t":"그림그래프는 항목을 나타내지 않아요.","mis":"M4-1-u5-X04"},{"t":"막대그래프에는 제목이 없어요.","mis":"M4-1-u5-X04"},{"t":"두 그래프는 서로 다른 자료만 나타내요.","mis":"M4-1-u5-X04"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"variant_rule":{"alt":[{"stem":"그림그래프와 막대그래프의 같은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 항목별 수량을 나타내요.","correct":true},{"t":"둘 다 그림의 개수로 나타내요.","mis":"M4-1-u5-X04"},{"t":"둘 다 막대의 굵기로 나타내요.","mis":"M4-1-u5-X03"},{"t":"둘 다 합계만 나타내요.","mis":"M4-1-u5-X04"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"asset":null},{"stem":"그림을 세지 않고도 길이만 보고 많고 적음을 견줄 수 있는 것은 어느 것인가요?","options":[{"t":"막대그래프","correct":true},{"t":"그림그래프","mis":"M4-1-u5-X04"},{"t":"표","mis":"M4-1-u5-X04"},{"t":"말로 들은 조사 결과","mis":"M4-1-u5-X04"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#2','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C3',1,'mc','auto','아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?',ARRAY['M4-1-u5-X01']::text[],true,'{"seq":2,"concept":"M4-1-u5-C3","difficulty":1,"kind":"mc","stem":"아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 마을, 세로: 나무 수","correct":true},{"t":"가로: 나무 수, 세로: 마을","mis":"M4-1-u5-X01"},{"t":"가로: 마을, 세로: 마을","mis":"M4-1-u5-X01"},{"t":"가로: 나무 수, 세로: 나무 수","mis":"M4-1-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 마을, 세로에는 나무 수를 그루 단위로 나타냈어요.","가로: 마을, 세로: 나무 수예요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을","마 마을"],"series":[{"vals":[70,80,55,25,75]}],"step":5,"ymax":85,"ylab":"(그루)","title":"마을별 나무 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 학년, 세로: 학생 수","correct":true},{"t":"가로: 학생 수, 세로: 학년","mis":"M4-1-u5-X01"},{"t":"가로: 학년, 세로: 학년","mis":"M4-1-u5-X01"},{"t":"가로: 학생 수, 세로: 학생 수","mis":"M4-1-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 학년, 세로에는 학생 수를 명 단위로 나타냈어요.","가로: 학년, 세로: 학생 수예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1학년","2학년","3학년","4학년","5학년","6학년"],"series":[{"vals":[30,25,65,85,45,75]}],"step":5,"ymax":90,"ylab":"(명)","title":"학년별 우유 신청 학생 수"}},{"stem":"이번에는 다른 그림이에요. 아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 모둠, 세로: 빈 병 수","correct":true},{"t":"가로: 빈 병 수, 세로: 모둠","mis":"M4-1-u5-X01"},{"t":"가로: 모둠, 세로: 모둠","mis":"M4-1-u5-X01"},{"t":"가로: 빈 병 수, 세로: 빈 병 수","mis":"M4-1-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 모둠, 세로에는 빈 병 수를 개 단위로 나타냈어요.","가로: 모둠, 세로: 빈 병 수예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠","5모둠"],"series":[{"vals":[12,8,14,16,20]}],"step":2,"ymax":22,"ylab":"(개)","title":"모둠별 모은 빈 병 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#3','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C1',1,'sa','auto','조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u5-C1","difficulty":1,"kind":"sa","stem":"조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["합계는 항목별 수를 모두 더한 것이에요.","8 + 7 + 6 + 3 + 11. = 35","합계는 35명이에요 — 모두 답했는지 확인할 수 있어요."],"asset":{"type":"picg","only":"table","head":"급식 메뉴","cols":["카레","잡채","불고기","국수","김밥"],"counts":[8,7,6,3,11],"vh":"학생 수","unit":"명","total":null,"title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["37"],"explanation":["합계는 항목별 수를 모두 더한 것이에요.","3 + 8 + 12 + 9 + 5. = 37","합계는 37명이에요 — 모두 답했는지 확인할 수 있어요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","만두"],"counts":[3,8,12,9,5],"vh":"학생 수","unit":"명","total":null,"title":"좋아하는 간식별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["43"],"explanation":["합계는 항목별 수를 모두 더한 것이에요.","11 + 6 + 9 + 10 + 7. = 43","합계는 43명이에요 — 모두 답했는지 확인할 수 있어요."],"asset":{"type":"picg","only":"table","head":"동물","cols":["강아지","고양이","토끼","햄스터","금붕어"],"counts":[11,6,9,10,7],"vh":"학생 수","unit":"명","total":null,"title":"기르고 싶은 동물별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#4','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C4',1,'mc','auto','막대를 그릴 때 지켜야 할 것은 어느 것인가요?',ARRAY['M4-1-u5-X03','M4-1-u5-X02','M4-1-u5-X05']::text[],true,'{"seq":4,"concept":"M4-1-u5-C4","difficulty":1,"kind":"mc","stem":"막대를 그릴 때 지켜야 할 것은 어느 것인가요?","options":[{"t":"막대의 굵기를 모두 같게 그려요.","correct":true},{"t":"수가 많은 막대를 더 굵게 그려요.","mis":"M4-1-u5-X03"},{"t":"막대마다 눈금 한 칸을 다르게 해요.","mis":"M4-1-u5-X02"},{"t":"수가 적은 막대는 그리지 않아요.","mis":"M4-1-u5-X05"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"variant_rule":{"alt":[{"stem":"학생 수를 나타내는 막대그래프에서 세로 눈금의 단위로 알맞은 것은 어느 것인가요?","options":[{"t":"명","correct":true},{"t":"개","mis":"M4-1-u5-X01"},{"t":"권","mis":"M4-1-u5-X01"},{"t":"kg","mis":"M4-1-u5-X01"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"asset":null},{"stem":"가로에는 항목, 세로에는 학생 수를 나타내기로 정했어요. 그다음에 정할 것은 무엇인가요?","options":[{"t":"세로 눈금의 단위","correct":true},{"t":"막대마다 다른 굵기","mis":"M4-1-u5-X03"},{"t":"막대마다 다른 색","mis":"M4-1-u5-X03"},{"t":"신문 기사 제목","mis":"M4-1-u5-X18"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#5','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C5',1,'sa','auto','표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 명까지 나타내어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u5-C5","difficulty":1,"kind":"sa","stem":"표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 명까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["세로 눈금은 모든 막대를 그릴 수 있어야 해요.","표에서 가장 큰 수는 12명이에요.","그래서 세로 눈금은 적어도 12명까지 나타내요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","만두"],"counts":[8,5,12,6,2],"vh":"학생 수","unit":"명","title":"좋아하는 간식별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 명까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["세로 눈금은 모든 막대를 그릴 수 있어야 해요.","표에서 가장 큰 수는 9명이에요.","그래서 세로 눈금은 적어도 9명까지 나타내요."],"asset":{"type":"picg","only":"table","head":"동물","cols":["강아지","고양이","토끼","햄스터","금붕어"],"counts":[7,6,2,9,4],"vh":"학생 수","unit":"명","title":"기르고 싶은 동물별 학생 수"}},{"stem":"표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 권까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["140"],"explanation":["세로 눈금은 모든 막대를 그릴 수 있어야 해요.","표에서 가장 큰 수는 140권이에요.","그래서 세로 눈금은 적어도 140권까지 나타내요."],"asset":{"type":"picg","only":"table","head":"반","cols":["1반","2반","3반","4반","5반","6반"],"counts":[110,60,40,140,50,130],"vh":"빌린 책 수","unit":"권","title":"반별 빌린 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#6','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C6',1,'mc','auto','눈금 한 칸의 크기를 고르는 기준으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X07']::text[],true,'{"seq":6,"concept":"M4-1-u5-C6","difficulty":1,"kind":"mc","stem":"눈금 한 칸의 크기를 고르는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"가장 큰 수를 담으면서 차이가 잘 드러나게 해요.","correct":true},{"t":"언제나 한 칸을 1로 해요.","mis":"M4-1-u5-X07"},{"t":"한 칸을 될 수 있는 대로 크게 해요.","mis":"M4-1-u5-X07"},{"t":"아무렇게나 정해도 돼요.","mis":"M4-1-u5-X07"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"variant_rule":{"alt":[{"stem":"눈금 한 칸을 너무 크게 정하면 어떤 점이 불편한가요?","options":[{"t":"막대들이 다 비슷해 보여서 차이를 알아보기 어려워요.","correct":true},{"t":"가장 큰 수가 그래프 밖으로 넘쳐요.","mis":"M4-1-u5-X21"},{"t":"항목을 모두 쓸 수 없어요.","mis":"M4-1-u5-X07"},{"t":"제목을 쓸 자리가 없어져요.","mis":"M4-1-u5-X07"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"asset":null},{"stem":"가장 큰 수가 126인 자료를 눈금 한 칸 1로 그리면 어떤 점이 불편한가요?","options":[{"t":"칸을 126개나 그려야 해서 종이에 다 들어가지 않아요.","correct":true},{"t":"막대들이 다 비슷해 보여요.","mis":"M4-1-u5-X21"},{"t":"막대가 나타내는 수가 달라져요.","mis":"M4-1-u5-X06"},{"t":"불편한 점이 없어요.","mis":"M4-1-u5-X07"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#7','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C9',1,'mc','auto','조사가 끝나면 꼭 확인할 것은 무엇인가요?',ARRAY['M4-1-u5-X15','M4-1-u5-X13','M4-1-u5-X16']::text[],true,'{"seq":7,"concept":"M4-1-u5-C9","difficulty":1,"kind":"mc","stem":"조사가 끝나면 꼭 확인할 것은 무엇인가요?","options":[{"t":"합계가 인원과 같은지","correct":true},{"t":"가장 많은 항목이 무엇인지만","mis":"M4-1-u5-X15"},{"t":"항목의 이름이 멋있는지","mis":"M4-1-u5-X13"},{"t":"조사 방법이 가장 빨랐는지","mis":"M4-1-u5-X16"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"variant_rule":{"alt":[{"stem":"항목을 정할 때 고르지 못한 친구를 위해 두면 좋은 칸은 무엇인가요?","options":[{"t":"기타","correct":true},{"t":"합계","mis":"M4-1-u5-X14"},{"t":"제목","mis":"M4-1-u5-X14"},{"t":"단위","mis":"M4-1-u5-X14"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"asset":null},{"stem":"조사할 때 한 사람은 몇 번 답해야 하나요?","options":[{"t":"한 번만 답해요.","correct":true},{"t":"두 번씩 답해요.","mis":"M4-1-u5-X15"},{"t":"원하는 만큼 답해요.","mis":"M4-1-u5-X15"},{"t":"답하지 않아도 돼요.","mis":"M4-1-u5-X15"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#8','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C11',1,'mc','auto','항목별로 두 막대씩 묶어 그리면 무엇을 한눈에 알 수 있나요?',ARRAY['M4-1-u5-X11','M4-1-u5-X03']::text[],true,'{"seq":8,"concept":"M4-1-u5-C11","difficulty":1,"kind":"mc","stem":"항목별로 두 막대씩 묶어 그리면 무엇을 한눈에 알 수 있나요?","options":[{"t":"항목마다 두 자료가 얼마나 다른지","correct":true},{"t":"항목마다 그렇게 된 까닭","mis":"M4-1-u5-X11"},{"t":"앞으로 늘어날 수","mis":"M4-1-u5-X11"},{"t":"막대마다 다른 굵기","mis":"M4-1-u5-X03"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"variant_rule":{"alt":[{"stem":"같은 두 자료를 묶는 방법만 바꾸어 다시 그리면 무엇이 달라지나요?","options":[{"t":"막대를 늘어놓는 차례만 달라지고 나타내는 수는 그대로예요.","correct":true},{"t":"막대가 나타내는 수가 달라져요.","mis":"M4-1-u5-X20"},{"t":"눈금 한 칸이 저절로 달라져요.","mis":"M4-1-u5-X20"},{"t":"자료가 더 많아져요.","mis":"M4-1-u5-X20"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"asset":null},{"stem":"자료별(작년끼리·올해끼리)로 묶어 그리면 무엇을 견주기 좋나요?","options":[{"t":"같은 해 안에서 항목끼리 견주기","correct":true},{"t":"항목마다 늘어난 까닭","mis":"M4-1-u5-X11"},{"t":"다음 해의 수","mis":"M4-1-u5-X11"},{"t":"막대의 굵기","mis":"M4-1-u5-X03"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#9','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C3',2,'sa','auto','마 지역의 문화유산은 몇 점인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u5-C3","difficulty":2,"kind":"sa","stem":"마 지역의 문화유산은 몇 점인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["세로 눈금 한 칸은 25점이에요.","마 지역의 막대는 0에서 2칸이에요.","2 × 25 = 50 — 마 지역의 문화유산은 50점이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 지역","나 지역","다 지역","라 지역","마 지역"],"series":[{"vals":[25,125,150,100,50]}],"step":25,"ymax":175,"ylab":"(점)","title":"지역별 문화유산 수"},"variant_rule":{"alt":[{"stem":"사과를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["세로 눈금 한 칸은 1명이에요.","사과의 막대 끝을 따라 세로 눈금을 읽어요.","사과를 좋아하는 학생은 2명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["사과","포도","딸기","귤","배"],"series":[{"vals":[2,9,6,7,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 과일별 학생 수"}},{"stem":"배구를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["세로 눈금 한 칸은 1명이에요.","배구의 막대 끝을 따라 세로 눈금을 읽어요.","배구를 좋아하는 학생은 3명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["축구","피구","수영","야구","배구"],"series":[{"vals":[7,5,2,9,3]}],"step":1,"ymax":10,"ylab":"(명)","title":"좋아하는 운동별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#10','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C5',2,'sa','auto','세로 눈금 한 칸이 25점인 막대그래프에 125점을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u5-C5","difficulty":2,"kind":"sa","stem":"세로 눈금 한 칸이 25점인 막대그래프에 125점을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 칸이 25점이니 한 칸 올라갈 때마다 25씩 커져요.","막대의 칸 수는 125 ÷ 25로 구해요.","125 ÷ 25 = 5 — 5칸으로 그려요."],"variant_rule":{"alt":[{"stem":"세로 눈금 한 칸이 2개인 막대그래프에 18개를 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 칸이 2개이니 한 칸 올라갈 때마다 2씩 커져요.","막대의 칸 수는 18 ÷ 2로 구해요.","18 ÷ 2 = 9 — 9칸으로 그려요."],"asset":null},{"stem":"세로 눈금 한 칸이 5명인 막대그래프에 45명을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 칸이 5명이니 한 칸 올라갈 때마다 5씩 커져요.","막대의 칸 수는 45 ÷ 5로 구해요.","45 ÷ 5 = 9 — 9칸으로 그려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#11','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C6',2,'sa','auto','눈금 한 칸이 25점인 막대그래프에서 6칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 50점인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M4-1-u5-C6","difficulty":2,"kind":"sa","stem":"눈금 한 칸이 25점인 막대그래프에서 6칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 50점인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 막대가 나타내는 수를 구해요: 6 × 25 = 150.","나타내는 수 150점은 눈금이 바뀌어도 그대로예요.","150 ÷ 50 = 3 — 3칸이 돼요."],"variant_rule":{"alt":[{"stem":"눈금 한 칸이 2명인 막대그래프에서 20칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 5명인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["8"],"explanation":["먼저 막대가 나타내는 수를 구해요: 20 × 2 = 40.","나타내는 수 40명은 눈금이 바뀌어도 그대로예요.","40 ÷ 5 = 8 — 8칸이 돼요."],"asset":null},{"stem":"눈금 한 칸이 10권인 막대그래프에서 9칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 30권인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 막대가 나타내는 수를 구해요: 9 × 10 = 90.","나타내는 수 90권은 눈금이 바뀌어도 그대로예요.","90 ÷ 30 = 3 — 3칸이 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#12','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C7',2,'sa','auto','방송 체험을 고른 학생은 요리 체험을 고른 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M4-1-u5-C7","difficulty":2,"kind":"sa","stem":"방송 체험을 고른 학생은 요리 체험을 고른 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["7"],"explanation":["방송은 10명, 요리는 3명이에요.","몇 더 많은지는 큰 수에서 작은 수를 빼요.","10 − 3 = 7 — 7명 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["로봇","요리","방송","소방","과학"],"series":[{"vals":[12,3,10,5,7]}],"step":1,"ymax":13,"ylab":"(명)","title":"가고 싶은 체험별 학생 수"},"variant_rule":{"alt":[{"stem":"가수를 희망하는 학생은 경찰관을 희망하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["7"],"explanation":["가수는 10명, 경찰관은 3명이에요.","몇 더 많은지는 큰 수에서 작은 수를 빼요.","10 − 3 = 7 — 7명 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["요리사","경찰관","과학자","가수","의사"],"series":[{"vals":[9,3,8,10,7]}],"step":1,"ymax":11,"ylab":"(명)","title":"희망 직업별 학생 수"}},{"stem":"국수를 좋아하는 학생은 잡채를 좋아하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["4"],"explanation":["국수는 9명, 잡채는 5명이에요.","몇 더 많은지는 큰 수에서 작은 수를 빼요.","9 − 5 = 4 — 4명 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["카레","잡채","불고기","국수","김밥"],"series":[{"vals":[10,5,4,9,2]}],"step":1,"ymax":11,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#13','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C8',2,'mc','auto','아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?',ARRAY['M4-1-u5-X21']::text[],true,'{"seq":13,"concept":"M4-1-u5-C8","difficulty":2,"kind":"mc","stem":"아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"다음 달에 가장 인기 있을 항목","correct":true},{"t":"가장 많은 학생이 고른 항목","mis":"M4-1-u5-X21"},{"t":"김밥의 학생 수","mis":"M4-1-u5-X21"},{"t":"김밥과 떡볶이의 학생 수의 차","mis":"M4-1-u5-X21"}],"explanation":["막대그래프에서는 항목별 수, 가장 많은 것, 두 항목의 차를 알 수 있어요.","「다음 달에 가장 인기 있을 항목」은 그래프에 나와 있지 않아요.","그래프에 없는 것은 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","만두"],"series":[{"vals":[5,3,11,2,9]}],"step":1,"ymax":12,"ylab":"(명)","title":"좋아하는 간식별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"조사한 날의 날씨","correct":true},{"t":"가장 많은 학생이 고른 항목","mis":"M4-1-u5-X21"},{"t":"고양이의 학생 수","mis":"M4-1-u5-X21"},{"t":"고양이와 강아지의 학생 수의 차","mis":"M4-1-u5-X21"}],"explanation":["막대그래프에서는 항목별 수, 가장 많은 것, 두 항목의 차를 알 수 있어요.","「조사한 날의 날씨」는 그래프에 나와 있지 않아요.","그래프에 없는 것은 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["강아지","고양이","토끼","햄스터","금붕어"],"series":[{"vals":[4,1,5,6,11]}],"step":1,"ymax":12,"ylab":"(명)","title":"기르고 싶은 동물별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"학생마다 고른 항목의 이름","correct":true},{"t":"가장 많은 학생이 고른 항목","mis":"M4-1-u5-X21"},{"t":"포도의 학생 수","mis":"M4-1-u5-X21"},{"t":"포도와 딸기의 학생 수의 차","mis":"M4-1-u5-X21"}],"explanation":["막대그래프에서는 항목별 수, 가장 많은 것, 두 항목의 차를 알 수 있어요.","「학생마다 고른 항목의 이름」은 그래프에 나와 있지 않아요.","그래프에 없는 것은 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["사과","포도","딸기","귤","배"],"series":[{"vals":[5,2,7,11,6]}],"step":1,"ymax":12,"ylab":"(명)","title":"좋아하는 과일별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#14','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C9',2,'mc','auto','교실 게시판에 결과가 한눈에 모이는 모습을 보여 주고 싶어요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?',ARRAY['M4-1-u5-X16']::text[],true,'{"seq":14,"concept":"M4-1-u5-C9","difficulty":2,"kind":"mc","stem":"교실 게시판에 결과가 한눈에 모이는 모습을 보여 주고 싶어요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"붙임쪽지 — 붙이면 한눈에 모이니까요.","correct":true},{"t":"종이에 적어 내기 — 걷어서 따로 세니까요.","mis":"M4-1-u5-X16"},{"t":"손 들기 — 손을 내리면 사라지니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 붙이면 한눈에 모이니까요.","그래서 붙임쪽지가 알맞아요."],"variant_rule":{"alt":[{"stem":"멀리 떨어진 다른 학교 친구들과 함께 조사하려고 해요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"온라인 설문 — 멀리 있는 사람도 답할 수 있으니까요.","correct":true},{"t":"손 들기 — 그 자리에서 셀 수 있으니까요.","mis":"M4-1-u5-X16"},{"t":"붙임쪽지 — 우리 교실 게시판에 붙이면 되니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 멀리 있는 사람도 답할 수 있으니까요.","그래서 온라인 설문이 알맞아요."],"asset":null},{"stem":"스마트 기기가 없는 교실에서 우리 반 친구들이 좋아하는 것을 차분히 조사하려고 해요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"종이에 적어 내기 — 기기 없이도 차분히 답할 수 있으니까요.","correct":true},{"t":"온라인 설문 — 기기가 없어도 집계되니까요.","mis":"M4-1-u5-X16"},{"t":"손 들기 — 차분히 생각할 시간을 주니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 기기 없이도 차분히 답할 수 있으니까요.","그래서 종이에 적어 내기가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#15','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C10',2,'mc','auto','이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X11','M4-1-u5-X21']::text[],true,'{"seq":15,"concept":"M4-1-u5-C10","difficulty":2,"kind":"mc","stem":"이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 메뉴는 카레다.」","correct":true},{"t":"「내일은 잡채가 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「카레는 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「잡채가 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 카레의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["불고기","잡채","카레","국수","기타"],"series":[{"vals":[7,4,8,5,6]}],"step":1,"ymax":9,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 간식은 과일이다.」","correct":true},{"t":"「내일은 떡볶이가 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「과일은 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「떡볶이가 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 과일의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","기타"],"series":[{"vals":[6,10,12,8,4]}],"step":2,"ymax":14,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 놀이는 술래잡기다.」","correct":true},{"t":"「내일은 피구가 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「술래잡기는 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「피구가 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 술래잡기의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["술래잡기","공기","줄넘기","피구","기타"],"series":[{"vals":[9,4,8,3,7]}],"step":1,"ymax":10,"ylab":"(명)","title":"즐겨 하는 놀이별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#16','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C11',2,'sa','auto','올해 나 마을의 나무 수는 몇 그루인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-1-u5-C11","difficulty":2,"kind":"sa","stem":"올해 나 마을의 나무 수는 몇 그루인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["이름표에서 올해의 막대 색을 먼저 찾아요.","나 마을 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 5그루).","올해 나 마을의 나무 수는 50그루예요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을"],"series":[{"name":"작년","vals":[35,10,20,15]},{"name":"올해","vals":[45,50,25,35]}],"step":5,"ymax":55,"ylab":"(그루)","title":"작년과 올해 심은 나무 수"},"variant_rule":{"alt":[{"stem":"2학기 3모둠의 붙임딱지 수는 몇 개인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["이름표에서 2학기의 막대 색을 먼저 찾아요.","3모둠 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 2개).","2학기 3모둠의 붙임딱지 수는 20개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"1학기","vals":[18,16,14,4]},{"name":"2학기","vals":[22,30,20,16]}],"step":2,"ymax":32,"ylab":"(개)","title":"1학기와 2학기 칭찬 붙임딱지 수"}},{"stem":"남학생 겨울의 학생 수는 몇 명인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["이름표에서 남학생의 막대 색을 먼저 찾아요.","겨울 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 1명).","남학생 겨울의 학생 수는 4명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"name":"남학생","vals":[6,1,8,4]},{"name":"여학생","vals":[5,10,2,7]}],"step":1,"ymax":11,"ylab":"(명)","title":"남학생과 여학생이 좋아하는 계절"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#17','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C5',3,'mc','auto','표의 내용은 「축구 4명, 피구 5명, 수영 12명, 야구 2명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?',ARRAY['M4-1-u5-X02']::text[],true,'{"seq":17,"concept":"M4-1-u5-C5","difficulty":3,"kind":"mc","stem":"표의 내용은 「축구 4명, 피구 5명, 수영 12명, 야구 2명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"피구","correct":true},{"t":"축구","mis":"M4-1-u5-X02"},{"t":"수영","mis":"M4-1-u5-X02"},{"t":"야구","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 1명이에요.","막대마다 표의 수와 견주어 봐요.","피구의 막대는 6명인데 표에서는 5명이에요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["축구","피구","수영","야구"],"series":[{"vals":[4,6,12,2]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 운동별 학생 수"},"variant_rule":{"alt":[{"stem":"표의 내용은 「봄 12명, 여름 5명, 가을 8명, 겨울 7명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"겨울","correct":true},{"t":"봄","mis":"M4-1-u5-X02"},{"t":"여름","mis":"M4-1-u5-X02"},{"t":"가을","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 1명이에요.","막대마다 표의 수와 견주어 봐요.","겨울의 막대는 6명인데 표에서는 7명이에요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"vals":[12,5,8,6]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 계절별 학생 수"}},{"stem":"표의 내용은 「로봇 9명, 요리 12명, 방송 7명, 소방 4명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"방송","correct":true},{"t":"로봇","mis":"M4-1-u5-X02"},{"t":"요리","mis":"M4-1-u5-X02"},{"t":"소방","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 1명이에요.","막대마다 표의 수와 견주어 봐요.","방송의 막대는 8명인데 표에서는 7명이에요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["로봇","요리","방송","소방"],"series":[{"vals":[9,12,8,4]}],"step":1,"ymax":13,"ylab":"(명)","title":"가고 싶은 체험별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#18','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C6',3,'mc','auto','「농장별 토마토 생산량」을 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 320 kg으로 그렸어요, 나 그래프는 눈금 한 칸을 20 kg으로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X07']::text[],true,'{"seq":18,"concept":"M4-1-u5-C6","difficulty":3,"kind":"mc","stem":"「농장별 토마토 생산량」을 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 320 kg으로 그렸어요, 나 그래프는 눈금 한 칸을 20 kg으로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"가 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 320 kg면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 20 kg인 나 그래프가 차이를 알아보기 좋아요."],"variant_rule":{"alt":[{"stem":"「마을별 나무 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 5그루로 그렸어요, 나 그래프는 눈금 한 칸을 120그루로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"가 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"나 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 120그루면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 5그루인 가 그래프가 차이를 알아보기 좋아요."],"asset":null},{"stem":"「학년별 우유 신청 학생 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 100명으로 그렸어요, 나 그래프는 눈금 한 칸을 5명으로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"가 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 100명면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 5명인 나 그래프가 차이를 알아보기 좋아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#19','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C7',3,'mc','auto','고양이를 기르고 싶은 학생은 강아지를 기르고 싶은 학생의 몇 배인가요?',ARRAY['M4-1-u5-X09']::text[],true,'{"seq":19,"concept":"M4-1-u5-C7","difficulty":3,"kind":"mc","stem":"고양이를 기르고 싶은 학생은 강아지를 기르고 싶은 학생의 몇 배인가요?","options":[{"t":"2배","correct":true},{"t":"4배","mis":"M4-1-u5-X09"},{"t":"3배","mis":"M4-1-u5-X09"},{"t":"1배","mis":"M4-1-u5-X09"}],"explanation":["고양이는 8명, 강아지는 4명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 4 × 2 = 8.","그래서 2배예요 — 차(4)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["강아지","고양이","토끼","햄스터","금붕어"],"series":[{"vals":[4,8,1,9,7]}],"step":1,"ymax":10,"ylab":"(명)","title":"기르고 싶은 동물별 학생 수"},"variant_rule":{"alt":[{"stem":"배를 좋아하는 학생은 사과를 좋아하는 학생의 몇 배인가요?","options":[{"t":"3배","correct":true},{"t":"8배","mis":"M4-1-u5-X09"},{"t":"4배","mis":"M4-1-u5-X09"},{"t":"2배","mis":"M4-1-u5-X09"}],"explanation":["배는 12명, 사과는 4명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 4 × 3 = 12.","그래서 3배예요 — 차(8)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["사과","포도","딸기","귤","배"],"series":[{"vals":[4,2,9,6,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 과일별 학생 수"}},{"stem":"피구를 좋아하는 학생은 축구를 좋아하는 학생의 몇 배인가요?","options":[{"t":"2배","correct":true},{"t":"5배","mis":"M4-1-u5-X09"},{"t":"3배","mis":"M4-1-u5-X09"},{"t":"1배","mis":"M4-1-u5-X09"}],"explanation":["피구는 10명, 축구는 5명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 5 × 2 = 10.","그래서 2배예요 — 차(5)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["축구","피구","수영","야구","배구"],"series":[{"vals":[5,10,2,6,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 운동별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#20','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C8',3,'mc','auto','가 그래프는 눈금 한 칸이 1명이고 사과의 막대가 6칸이에요. 나 그래프는 눈금 한 칸이 2명이고 배의 막대가 4칸이에요. 사과의 막대가 더 길어 보이는데, 사과를 고른 학생이 더 많은 걸까요?',ARRAY['M4-1-u5-X10','M4-1-u5-X02','M4-1-u5-X12']::text[],true,'{"seq":20,"concept":"M4-1-u5-C8","difficulty":3,"kind":"mc","stem":"가 그래프는 눈금 한 칸이 1명이고 사과의 막대가 6칸이에요. 나 그래프는 눈금 한 칸이 2명이고 배의 막대가 4칸이에요. 사과의 막대가 더 길어 보이는데, 사과를 고른 학생이 더 많은 걸까요?","options":[{"t":"아니요 — 눈금이 달라요. 사과는 6명, 배는 8명이에요.","correct":true},{"t":"네 — 막대가 길면 언제나 수가 많아요.","mis":"M4-1-u5-X10"},{"t":"두 막대가 나타내는 수는 똑같아요.","mis":"M4-1-u5-X02"},{"t":"네 — 가 그래프가 먼저 나왔으니까요.","mis":"M4-1-u5-X12"}],"explanation":["다른 그래프끼리 견줄 때는 눈금부터 확인해요.","사과는 6 × 1 = 6명, 배는 4 × 2 = 8명이에요.","막대는 사과가 더 길어도 수는 배가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 그래프는 눈금 한 칸이 1명이고 떡볶이의 막대가 10칸이에요. 나 그래프는 눈금 한 칸이 5명이고 만두의 막대가 3칸이에요. 떡볶이의 막대가 더 길어 보이는데, 떡볶이를 고른 학생이 더 많은 걸까요?","options":[{"t":"아니요 — 눈금이 달라요. 떡볶이는 10명, 만두는 15명이에요.","correct":true},{"t":"네 — 막대가 길면 언제나 수가 많아요.","mis":"M4-1-u5-X10"},{"t":"두 막대가 나타내는 수는 똑같아요.","mis":"M4-1-u5-X02"},{"t":"네 — 가 그래프가 먼저 나왔으니까요.","mis":"M4-1-u5-X12"}],"explanation":["다른 그래프끼리 견줄 때는 눈금부터 확인해요.","떡볶이는 10 × 1 = 10명, 만두는 3 × 5 = 15명이에요.","막대는 떡볶이가 더 길어도 수는 만두가 더 많아요."],"asset":null},{"stem":"가 그래프는 눈금 한 칸이 2명이고 봄의 막대가 6칸이에요. 나 그래프는 눈금 한 칸이 5명이고 가을의 막대가 3칸이에요. 봄의 막대가 더 길어 보이는데, 봄을 고른 학생이 더 많은 걸까요?","options":[{"t":"아니요 — 눈금이 달라요. 봄은 12명, 가을은 15명이에요.","correct":true},{"t":"네 — 막대가 길면 언제나 수가 많아요.","mis":"M4-1-u5-X10"},{"t":"두 막대가 나타내는 수는 똑같아요.","mis":"M4-1-u5-X02"},{"t":"네 — 가 그래프가 먼저 나왔으니까요.","mis":"M4-1-u5-X12"}],"explanation":["다른 그래프끼리 견줄 때는 눈금부터 확인해요.","봄은 6 × 2 = 12명, 가을은 3 × 5 = 15명이에요.","막대는 봄이 더 길어도 수는 가을이 더 많아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#21','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C9',3,'mc','auto','조사를 했더니 합계가 21명이 나왔어요. 우리 반은 23명인데요! 무슨 일이 생긴 걸까요?',ARRAY['M4-1-u5-X21','M4-1-u5-X14','M4-1-u5-X15']::text[],true,'{"seq":21,"concept":"M4-1-u5-C9","difficulty":3,"kind":"mc","stem":"조사를 했더니 합계가 21명이 나왔어요. 우리 반은 23명인데요! 무슨 일이 생긴 걸까요?","options":[{"t":"빠진 친구가 있어요 — 모두 한 번씩 답해야 해요.","correct":true},{"t":"두 번 답한 친구가 있어요 — 한 사람은 한 번만 답해야 해요.","mis":"M4-1-u5-X21"},{"t":"항목을 너무 많이 만들었어요.","mis":"M4-1-u5-X14"},{"t":"합계는 인원과 달라도 괜찮아요.","mis":"M4-1-u5-X15"}],"explanation":["합계는 우리 반 인원과 같아야 해요.","합계 21명이 인원 23명보다 적어요.","많으면 두 번 답한 친구가, 적으면 빠진 친구가 있는 거예요."],"variant_rule":{"alt":[{"stem":"조사를 했더니 합계가 30명이 나왔어요. 우리 반은 27명인데요! 무슨 일이 생긴 걸까요?","options":[{"t":"두 번 답한 친구가 있어요 — 한 사람은 한 번만 답해야 해요.","correct":true},{"t":"빠진 친구가 있어요 — 모두 한 번씩 답해야 해요.","mis":"M4-1-u5-X21"},{"t":"항목을 너무 많이 만들었어요.","mis":"M4-1-u5-X14"},{"t":"합계는 인원과 달라도 괜찮아요.","mis":"M4-1-u5-X15"}],"explanation":["합계는 우리 반 인원과 같아야 해요.","합계 30명이 인원 27명보다 많아요.","많으면 두 번 답한 친구가, 적으면 빠진 친구가 있는 거예요."],"asset":null},{"stem":"조사를 했더니 합계가 19명이 나왔어요. 우리 반은 22명인데요! 무슨 일이 생긴 걸까요?","options":[{"t":"빠진 친구가 있어요 — 모두 한 번씩 답해야 해요.","correct":true},{"t":"두 번 답한 친구가 있어요 — 한 사람은 한 번만 답해야 해요.","mis":"M4-1-u5-X21"},{"t":"항목을 너무 많이 만들었어요.","mis":"M4-1-u5-X14"},{"t":"합계는 인원과 달라도 괜찮아요.","mis":"M4-1-u5-X15"}],"explanation":["합계는 우리 반 인원과 같아야 해요.","합계 19명이 인원 22명보다 적어요.","많으면 두 번 답한 친구가, 적으면 빠진 친구가 있는 거예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#22','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C11',3,'mc','auto','지난달보다 이번 달에 빈 병 수가 가장 많이 늘어난 항목은 어느 것인가요?',ARRAY['M4-1-u5-X09']::text[],true,'{"seq":22,"concept":"M4-1-u5-C11","difficulty":3,"kind":"mc","stem":"지난달보다 이번 달에 빈 병 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"3모둠","correct":true},{"t":"2모둠","mis":"M4-1-u5-X09"},{"t":"1모둠","mis":"M4-1-u5-X09"},{"t":"4모둠","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 1모둠 30, 2모둠 35, 3모둠 40, 4모둠 10.","이번 달의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 3모둠이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"지난달","vals":[10,45,25,50]},{"name":"이번 달","vals":[40,80,65,60]}],"step":5,"ymax":85,"ylab":"(개)","title":"지난달과 이번 달 모은 빈 병 수"},"variant_rule":{"alt":[{"stem":"작년보다 올해에 나무 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"가 마을","correct":true},{"t":"라 마을","mis":"M4-1-u5-X09"},{"t":"나 마을","mis":"M4-1-u5-X09"},{"t":"다 마을","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 가 마을 35, 나 마을 20, 다 마을 15, 라 마을 25.","올해의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 가 마을이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을"],"series":[{"name":"작년","vals":[25,15,30,40]},{"name":"올해","vals":[60,35,45,65]}],"step":5,"ymax":70,"ylab":"(그루)","title":"작년과 올해 심은 나무 수"}},{"stem":"1학기보다 2학기에 붙임딱지 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"3모둠","correct":true},{"t":"4모둠","mis":"M4-1-u5-X09"},{"t":"1모둠","mis":"M4-1-u5-X09"},{"t":"2모둠","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 1모둠 2, 2모둠 10, 3모둠 12, 4모둠 6.","2학기의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 3모둠이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"1학기","vals":[6,12,8,20]},{"name":"2학기","vals":[8,22,20,26]}],"step":2,"ymax":28,"ylab":"(개)","title":"1학기와 2학기 칭찬 붙임딱지 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#23','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C10',4,'sa','auto','우리 반 34명이 모두 답한 간식 조사의 표에서 빵의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 빵 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-1-u5-C10","difficulty":4,"kind":"sa","stem":"우리 반 34명이 모두 답한 간식 조사의 표에서 빵의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 빵 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["빵의 수는 34 − (12 + 10 + 6 + 4) = 2명이에요.","눈금 한 칸이 2명이니 2 ÷ 2로 구해요.","1칸으로 그려요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","기타"],"counts":[12,10,6,null,4],"vh":"학생 수","unit":"명","total":34,"title":"좋아하는 간식별 학생 수"},"variant_rule":{"alt":[{"stem":"우리 반 40명이 모두 답한 간식 조사의 표에서 과일의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 과일 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["과일의 수는 40 − (8 + 4 + 14 + 12) = 2명이에요.","눈금 한 칸이 2명이니 2 ÷ 2로 구해요.","1칸으로 그려요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","기타"],"counts":[8,4,null,14,12],"vh":"학생 수","unit":"명","total":40,"title":"좋아하는 간식별 학생 수"}},{"stem":"우리 반 34명이 모두 답한 간식 조사의 표에서 과일의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 과일 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["과일의 수는 34 − (6 + 10 + 12 + 4) = 2명이에요.","눈금 한 칸이 2명이니 2 ÷ 2로 구해요.","1칸으로 그려요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","기타"],"counts":[6,10,null,12,4],"vh":"학생 수","unit":"명","total":34,"title":"좋아하는 간식별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#24','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C11',4,'sa','auto','작년과 올해의 차가 가장 큰 항목에서, 두 수의 차는 몇 그루인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-1-u5-C11","difficulty":4,"kind":"sa","stem":"작년과 올해의 차가 가장 큰 항목에서, 두 수의 차는 몇 그루인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["항목마다 두 막대의 차를 구해요: 가 마을 50, 나 마을 15, 다 마을 20, 라 마을 40.","차가 가장 큰 항목은 가 마을이에요.","그 차는 50그루예요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을"],"series":[{"name":"작년","vals":[10,25,15,30]},{"name":"올해","vals":[60,40,35,70]}],"step":5,"ymax":75,"ylab":"(그루)","title":"작년과 올해 심은 나무 수"},"variant_rule":{"alt":[{"stem":"1학기와 2학기의 차가 가장 큰 항목에서, 두 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["항목마다 두 막대의 차를 구해요: 1모둠 22, 2모둠 2, 3모둠 20, 4모둠 6.","차가 가장 큰 항목은 1모둠이에요.","그 차는 22개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"1학기","vals":[8,22,6,14]},{"name":"2학기","vals":[30,24,26,20]}],"step":2,"ymax":32,"ylab":"(개)","title":"1학기와 2학기 칭찬 붙임딱지 수"}},{"stem":"남학생과 여학생의 차가 가장 큰 항목에서, 두 수의 차는 몇 명인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["항목마다 두 막대의 차를 구해요: 봄 6, 여름 4, 가을 7, 겨울 3.","차가 가장 큰 항목은 가을이에요.","그 차는 7명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"name":"남학생","vals":[10,5,9,2]},{"name":"여학생","vals":[4,9,2,5]}],"step":1,"ymax":11,"ylab":"(명)","title":"남학생과 여학생이 좋아하는 계절"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_b#25','math',4,1,'u5','','g4_1_math_u5_review_b','unit_review','M4-1-u5-C6',4,'essay','teacher','「농장별 토마토 생산량」은 해 농장 240 kg, 달 농장 180 kg, 별 농장 100 kg, 숲 농장 220 kg이에요. 눈금 한 칸을 1 kg으로 하자는 친구와 500 kg으로 하자는 친구가 있어요. 두 의견의 불편한 점을 각각 쓰고, 알맞은 눈금 한 칸을 정해 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u5-C6","difficulty":4,"kind":"essay","stem":"「농장별 토마토 생산량」은 해 농장 240 kg, 달 농장 180 kg, 별 농장 100 kg, 숲 농장 220 kg이에요. 눈금 한 칸을 1 kg으로 하자는 친구와 500 kg으로 하자는 친구가 있어요. 두 의견의 불편한 점을 각각 쓰고, 알맞은 눈금 한 칸을 정해 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 1 kg으로 하면 칸을 240개나 그려야 해서 다 들어가지 않는다. 500 kg으로 하면 모두 한 칸 안에 들어가 막대들이 다 비슷해 보여 차이를 알기 어렵다. 20 kg으로 하면 12칸이면 가장 큰 240 kg까지 들어가고 농장끼리 차이도 잘 보이므로 알맞다. 눈금을 바꿔도 나타내는 수는 그대로이다.","scoring_points":["1 kg은 칸이 너무 많다고 썼는가","500 kg은 차이가 안 보인다고 썼는가","알맞은 눈금(예: 20 kg)을 가장 큰 수 담기·차이 드러나기로 설명했는가"]},"explanation":["너무 작은 칸은 넘쳐요.","너무 큰 칸은 차이가 안 보여요.","가장 큰 수를 담으면서 차이가 보이게 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#1','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C2',1,'mc','auto','그림그래프와 막대그래프의 같은 점으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X04','M4-1-u5-X03']::text[],true,'{"seq":1,"concept":"M4-1-u5-C2","difficulty":1,"kind":"mc","stem":"그림그래프와 막대그래프의 같은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 항목별 수량을 나타내요.","correct":true},{"t":"둘 다 그림의 개수로 나타내요.","mis":"M4-1-u5-X04"},{"t":"둘 다 막대의 굵기로 나타내요.","mis":"M4-1-u5-X03"},{"t":"둘 다 합계만 나타내요.","mis":"M4-1-u5-X04"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"variant_rule":{"alt":[{"stem":"그림을 세지 않고도 길이만 보고 많고 적음을 견줄 수 있는 것은 어느 것인가요?","options":[{"t":"막대그래프","correct":true},{"t":"그림그래프","mis":"M4-1-u5-X04"},{"t":"표","mis":"M4-1-u5-X04"},{"t":"말로 들은 조사 결과","mis":"M4-1-u5-X04"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"asset":null},{"stem":"조사한 수량을 막대 모양으로 나타낸 그래프를 무엇이라고 하나요?","options":[{"t":"막대그래프","correct":true},{"t":"그림그래프","mis":"M4-1-u5-X04"},{"t":"표","mis":"M4-1-u5-X04"},{"t":"수직선","mis":"M4-1-u5-X04"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#2','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C3',1,'mc','auto','아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?',ARRAY['M4-1-u5-X01']::text[],true,'{"seq":2,"concept":"M4-1-u5-C3","difficulty":1,"kind":"mc","stem":"아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 학년, 세로: 학생 수","correct":true},{"t":"가로: 학생 수, 세로: 학년","mis":"M4-1-u5-X01"},{"t":"가로: 학년, 세로: 학년","mis":"M4-1-u5-X01"},{"t":"가로: 학생 수, 세로: 학생 수","mis":"M4-1-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 학년, 세로에는 학생 수를 명 단위로 나타냈어요.","가로: 학년, 세로: 학생 수예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1학년","2학년","3학년","4학년","5학년","6학년"],"series":[{"vals":[30,25,65,85,45,75]}],"step":5,"ymax":90,"ylab":"(명)","title":"학년별 우유 신청 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 모둠, 세로: 빈 병 수","correct":true},{"t":"가로: 빈 병 수, 세로: 모둠","mis":"M4-1-u5-X01"},{"t":"가로: 모둠, 세로: 모둠","mis":"M4-1-u5-X01"},{"t":"가로: 빈 병 수, 세로: 빈 병 수","mis":"M4-1-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 모둠, 세로에는 빈 병 수를 개 단위로 나타냈어요.","가로: 모둠, 세로: 빈 병 수예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠","5모둠"],"series":[{"vals":[12,8,14,16,20]}],"step":2,"ymax":22,"ylab":"(개)","title":"모둠별 모은 빈 병 수"}},{"stem":"이번에는 다른 그림이에요. 아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 지역, 세로: 문화유산 수","correct":true},{"t":"가로: 문화유산 수, 세로: 지역","mis":"M4-1-u5-X01"},{"t":"가로: 지역, 세로: 지역","mis":"M4-1-u5-X01"},{"t":"가로: 문화유산 수, 세로: 문화유산 수","mis":"M4-1-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 지역, 세로에는 문화유산 수를 점 단위로 나타냈어요.","가로: 지역, 세로: 문화유산 수예요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 지역","나 지역","다 지역","라 지역","마 지역"],"series":[{"vals":[125,75,150,175,25]}],"step":25,"ymax":200,"ylab":"(점)","title":"지역별 문화유산 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#3','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C1',1,'sa','auto','조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u5-C1","difficulty":1,"kind":"sa","stem":"조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["37"],"explanation":["합계는 항목별 수를 모두 더한 것이에요.","3 + 8 + 12 + 9 + 5. = 37","합계는 37명이에요 — 모두 답했는지 확인할 수 있어요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","만두"],"counts":[3,8,12,9,5],"vh":"학생 수","unit":"명","total":null,"title":"좋아하는 간식별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["43"],"explanation":["합계는 항목별 수를 모두 더한 것이에요.","11 + 6 + 9 + 10 + 7. = 43","합계는 43명이에요 — 모두 답했는지 확인할 수 있어요."],"asset":{"type":"picg","only":"table","head":"동물","cols":["강아지","고양이","토끼","햄스터","금붕어"],"counts":[11,6,9,10,7],"vh":"학생 수","unit":"명","total":null,"title":"기르고 싶은 동물별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["합계는 항목별 수를 모두 더한 것이에요.","2 + 3 + 4 + 11 + 7. = 27","합계는 27명이에요 — 모두 답했는지 확인할 수 있어요."],"asset":{"type":"picg","only":"table","head":"과일","cols":["사과","포도","딸기","귤","배"],"counts":[2,3,4,11,7],"vh":"학생 수","unit":"명","total":null,"title":"좋아하는 과일별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#4','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C4',1,'mc','auto','학생 수를 나타내는 막대그래프에서 세로 눈금의 단위로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X01']::text[],true,'{"seq":4,"concept":"M4-1-u5-C4","difficulty":1,"kind":"mc","stem":"학생 수를 나타내는 막대그래프에서 세로 눈금의 단위로 알맞은 것은 어느 것인가요?","options":[{"t":"명","correct":true},{"t":"개","mis":"M4-1-u5-X01"},{"t":"권","mis":"M4-1-u5-X01"},{"t":"kg","mis":"M4-1-u5-X01"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"variant_rule":{"alt":[{"stem":"가로에는 항목, 세로에는 학생 수를 나타내기로 정했어요. 그다음에 정할 것은 무엇인가요?","options":[{"t":"세로 눈금의 단위","correct":true},{"t":"막대마다 다른 굵기","mis":"M4-1-u5-X03"},{"t":"막대마다 다른 색","mis":"M4-1-u5-X03"},{"t":"신문 기사 제목","mis":"M4-1-u5-X18"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"asset":null},{"stem":"막대그래프를 그리는 차례에서 눈금 한 칸의 크기를 정한 다음에 하는 일은 무엇인가요?","options":[{"t":"수량만큼 막대를 그려요.","correct":true},{"t":"가로와 세로에 나타낼 것을 정해요.","mis":"M4-1-u5-X18"},{"t":"세로 눈금의 단위를 정해요.","mis":"M4-1-u5-X18"},{"t":"조사를 처음부터 다시 해요.","mis":"M4-1-u5-X18"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#5','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C5',1,'sa','auto','표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 명까지 나타내어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u5-C5","difficulty":1,"kind":"sa","stem":"표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 명까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["세로 눈금은 모든 막대를 그릴 수 있어야 해요.","표에서 가장 큰 수는 9명이에요.","그래서 세로 눈금은 적어도 9명까지 나타내요."],"asset":{"type":"picg","only":"table","head":"동물","cols":["강아지","고양이","토끼","햄스터","금붕어"],"counts":[7,6,2,9,4],"vh":"학생 수","unit":"명","title":"기르고 싶은 동물별 학생 수"},"variant_rule":{"alt":[{"stem":"표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 권까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["140"],"explanation":["세로 눈금은 모든 막대를 그릴 수 있어야 해요.","표에서 가장 큰 수는 140권이에요.","그래서 세로 눈금은 적어도 140권까지 나타내요."],"asset":{"type":"picg","only":"table","head":"반","cols":["1반","2반","3반","4반","5반","6반"],"counts":[110,60,40,140,50,130],"vh":"빌린 책 수","unit":"권","title":"반별 빌린 책 수"}},{"stem":"표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 kg까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["260"],"explanation":["세로 눈금은 모든 막대를 그릴 수 있어야 해요.","표에서 가장 큰 수는 260 kg이에요.","그래서 세로 눈금은 적어도 260 kg까지 나타내요."],"asset":{"type":"picg","only":"table","head":"농장","cols":["해 농장","달 농장","별 농장","숲 농장","강 농장"],"counts":[260,200,180,240,100],"vh":"토마토 생산량","unit":"kg","title":"농장별 토마토 생산량"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#6','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C6',1,'mc','auto','눈금 한 칸을 너무 크게 정하면 어떤 점이 불편한가요?',ARRAY['M4-1-u5-X21','M4-1-u5-X07']::text[],true,'{"seq":6,"concept":"M4-1-u5-C6","difficulty":1,"kind":"mc","stem":"눈금 한 칸을 너무 크게 정하면 어떤 점이 불편한가요?","options":[{"t":"막대들이 다 비슷해 보여서 차이를 알아보기 어려워요.","correct":true},{"t":"가장 큰 수가 그래프 밖으로 넘쳐요.","mis":"M4-1-u5-X21"},{"t":"항목을 모두 쓸 수 없어요.","mis":"M4-1-u5-X07"},{"t":"제목을 쓸 자리가 없어져요.","mis":"M4-1-u5-X07"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"variant_rule":{"alt":[{"stem":"가장 큰 수가 126인 자료를 눈금 한 칸 1로 그리면 어떤 점이 불편한가요?","options":[{"t":"칸을 126개나 그려야 해서 종이에 다 들어가지 않아요.","correct":true},{"t":"막대들이 다 비슷해 보여요.","mis":"M4-1-u5-X21"},{"t":"막대가 나타내는 수가 달라져요.","mis":"M4-1-u5-X06"},{"t":"불편한 점이 없어요.","mis":"M4-1-u5-X07"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"asset":null},{"stem":"눈금 한 칸의 크기를 바꾸면 무엇이 달라지나요?","options":[{"t":"막대의 칸 수는 달라지지만 나타내는 수는 그대로예요.","correct":true},{"t":"막대가 나타내는 수가 달라져요.","mis":"M4-1-u5-X06"},{"t":"항목의 개수가 달라져요.","mis":"M4-1-u5-X06"},{"t":"아무것도 달라지지 않아요.","mis":"M4-1-u5-X06"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#7','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C9',1,'mc','auto','항목을 정할 때 고르지 못한 친구를 위해 두면 좋은 칸은 무엇인가요?',ARRAY['M4-1-u5-X14']::text[],true,'{"seq":7,"concept":"M4-1-u5-C9","difficulty":1,"kind":"mc","stem":"항목을 정할 때 고르지 못한 친구를 위해 두면 좋은 칸은 무엇인가요?","options":[{"t":"기타","correct":true},{"t":"합계","mis":"M4-1-u5-X14"},{"t":"제목","mis":"M4-1-u5-X14"},{"t":"단위","mis":"M4-1-u5-X14"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"variant_rule":{"alt":[{"stem":"조사할 때 한 사람은 몇 번 답해야 하나요?","options":[{"t":"한 번만 답해요.","correct":true},{"t":"두 번씩 답해요.","mis":"M4-1-u5-X15"},{"t":"원하는 만큼 답해요.","mis":"M4-1-u5-X15"},{"t":"답하지 않아도 돼요.","mis":"M4-1-u5-X15"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"asset":null},{"stem":"자료를 조사할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"조사할 주제 정하기","correct":true},{"t":"막대그래프 그리기","mis":"M4-1-u5-X18"},{"t":"조사 방법 정하기","mis":"M4-1-u5-X18"},{"t":"합계 확인하기","mis":"M4-1-u5-X18"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#8','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C11',1,'mc','auto','같은 두 자료를 묶는 방법만 바꾸어 다시 그리면 무엇이 달라지나요?',ARRAY['M4-1-u5-X20']::text[],true,'{"seq":8,"concept":"M4-1-u5-C11","difficulty":1,"kind":"mc","stem":"같은 두 자료를 묶는 방법만 바꾸어 다시 그리면 무엇이 달라지나요?","options":[{"t":"막대를 늘어놓는 차례만 달라지고 나타내는 수는 그대로예요.","correct":true},{"t":"막대가 나타내는 수가 달라져요.","mis":"M4-1-u5-X20"},{"t":"눈금 한 칸이 저절로 달라져요.","mis":"M4-1-u5-X20"},{"t":"자료가 더 많아져요.","mis":"M4-1-u5-X20"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"variant_rule":{"alt":[{"stem":"자료별(작년끼리·올해끼리)로 묶어 그리면 무엇을 견주기 좋나요?","options":[{"t":"같은 해 안에서 항목끼리 견주기","correct":true},{"t":"항목마다 늘어난 까닭","mis":"M4-1-u5-X11"},{"t":"다음 해의 수","mis":"M4-1-u5-X11"},{"t":"막대의 굵기","mis":"M4-1-u5-X03"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"asset":null},{"stem":"두 자료를 하나의 막대그래프에 나타낼 때 두 자료는 무엇으로 구분하나요?","options":[{"t":"막대의 색 — 이름표(범례)가 알려 줘요.","correct":true},{"t":"막대의 굵기 — 굵은 쪽이 새 자료예요.","mis":"M4-1-u5-X03"},{"t":"눈금 한 칸의 크기","mis":"M4-1-u5-X02"},{"t":"막대 위에 붙인 별표","mis":"M4-1-u5-X19"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#9','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C3',2,'sa','auto','사과를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u5-C3","difficulty":2,"kind":"sa","stem":"사과를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["세로 눈금 한 칸은 1명이에요.","사과의 막대 끝을 따라 세로 눈금을 읽어요.","사과를 좋아하는 학생은 2명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["사과","포도","딸기","귤","배"],"series":[{"vals":[2,9,6,7,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 과일별 학생 수"},"variant_rule":{"alt":[{"stem":"배구를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["세로 눈금 한 칸은 1명이에요.","배구의 막대 끝을 따라 세로 눈금을 읽어요.","배구를 좋아하는 학생은 3명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["축구","피구","수영","야구","배구"],"series":[{"vals":[7,5,2,9,3]}],"step":1,"ymax":10,"ylab":"(명)","title":"좋아하는 운동별 학생 수"}},{"stem":"겨울을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["세로 눈금 한 칸은 1명이에요.","겨울의 막대 끝을 따라 세로 눈금을 읽어요.","겨울을 좋아하는 학생은 6명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"vals":[4,10,2,6]}],"step":1,"ymax":11,"ylab":"(명)","title":"좋아하는 계절별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#10','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C5',2,'sa','auto','세로 눈금 한 칸이 2개인 막대그래프에 18개를 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u5-C5","difficulty":2,"kind":"sa","stem":"세로 눈금 한 칸이 2개인 막대그래프에 18개를 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 칸이 2개이니 한 칸 올라갈 때마다 2씩 커져요.","막대의 칸 수는 18 ÷ 2로 구해요.","18 ÷ 2 = 9 — 9칸으로 그려요."],"variant_rule":{"alt":[{"stem":"세로 눈금 한 칸이 5명인 막대그래프에 45명을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 칸이 5명이니 한 칸 올라갈 때마다 5씩 커져요.","막대의 칸 수는 45 ÷ 5로 구해요.","45 ÷ 5 = 9 — 9칸으로 그려요."],"asset":null},{"stem":"세로 눈금 한 칸이 1명인 막대그래프에 7명을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 칸이 1명이니 한 칸 올라갈 때마다 1씩 커져요.","막대의 칸 수는 7 ÷ 1로 구해요.","7 ÷ 1 = 7 — 7칸으로 그려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#11','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C6',2,'sa','auto','눈금 한 칸이 2명인 막대그래프에서 20칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 5명인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M4-1-u5-C6","difficulty":2,"kind":"sa","stem":"눈금 한 칸이 2명인 막대그래프에서 20칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 5명인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["8"],"explanation":["먼저 막대가 나타내는 수를 구해요: 20 × 2 = 40.","나타내는 수 40명은 눈금이 바뀌어도 그대로예요.","40 ÷ 5 = 8 — 8칸이 돼요."],"variant_rule":{"alt":[{"stem":"눈금 한 칸이 10권인 막대그래프에서 9칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 30권인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 막대가 나타내는 수를 구해요: 9 × 10 = 90.","나타내는 수 90권은 눈금이 바뀌어도 그대로예요.","90 ÷ 30 = 3 — 3칸이 돼요."],"asset":null},{"stem":"눈금 한 칸이 1명인 막대그래프에서 10칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 2명인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["5"],"explanation":["먼저 막대가 나타내는 수를 구해요: 10 × 1 = 10.","나타내는 수 10명은 눈금이 바뀌어도 그대로예요.","10 ÷ 2 = 5 — 5칸이 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#12','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C7',2,'sa','auto','가수를 희망하는 학생은 경찰관을 희망하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M4-1-u5-C7","difficulty":2,"kind":"sa","stem":"가수를 희망하는 학생은 경찰관을 희망하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["7"],"explanation":["가수는 10명, 경찰관은 3명이에요.","몇 더 많은지는 큰 수에서 작은 수를 빼요.","10 − 3 = 7 — 7명 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["요리사","경찰관","과학자","가수","의사"],"series":[{"vals":[9,3,8,10,7]}],"step":1,"ymax":11,"ylab":"(명)","title":"희망 직업별 학생 수"},"variant_rule":{"alt":[{"stem":"국수를 좋아하는 학생은 잡채를 좋아하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["4"],"explanation":["국수는 9명, 잡채는 5명이에요.","몇 더 많은지는 큰 수에서 작은 수를 빼요.","9 − 5 = 4 — 4명 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["카레","잡채","불고기","국수","김밥"],"series":[{"vals":[10,5,4,9,2]}],"step":1,"ymax":11,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"}},{"stem":"빵을 좋아하는 학생은 만두를 좋아하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["1"],"explanation":["빵은 10명, 만두는 9명이에요.","몇 더 많은지는 큰 수에서 작은 수를 빼요.","10 − 9 = 1 — 1명 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","만두"],"series":[{"vals":[11,5,6,10,9]}],"step":1,"ymax":12,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#13','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C8',2,'mc','auto','아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?',ARRAY['M4-1-u5-X21']::text[],true,'{"seq":13,"concept":"M4-1-u5-C8","difficulty":2,"kind":"mc","stem":"아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"조사한 날의 날씨","correct":true},{"t":"가장 많은 학생이 고른 항목","mis":"M4-1-u5-X21"},{"t":"고양이의 학생 수","mis":"M4-1-u5-X21"},{"t":"고양이와 강아지의 학생 수의 차","mis":"M4-1-u5-X21"}],"explanation":["막대그래프에서는 항목별 수, 가장 많은 것, 두 항목의 차를 알 수 있어요.","「조사한 날의 날씨」는 그래프에 나와 있지 않아요.","그래프에 없는 것은 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["강아지","고양이","토끼","햄스터","금붕어"],"series":[{"vals":[4,1,5,6,11]}],"step":1,"ymax":12,"ylab":"(명)","title":"기르고 싶은 동물별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"학생마다 고른 항목의 이름","correct":true},{"t":"가장 많은 학생이 고른 항목","mis":"M4-1-u5-X21"},{"t":"포도의 학생 수","mis":"M4-1-u5-X21"},{"t":"포도와 딸기의 학생 수의 차","mis":"M4-1-u5-X21"}],"explanation":["막대그래프에서는 항목별 수, 가장 많은 것, 두 항목의 차를 알 수 있어요.","「학생마다 고른 항목의 이름」은 그래프에 나와 있지 않아요.","그래프에 없는 것은 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["사과","포도","딸기","귤","배"],"series":[{"vals":[5,2,7,11,6]}],"step":1,"ymax":12,"ylab":"(명)","title":"좋아하는 과일별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"학생들이 그 항목을 고른 까닭","correct":true},{"t":"가장 많은 학생이 고른 항목","mis":"M4-1-u5-X21"},{"t":"축구의 학생 수","mis":"M4-1-u5-X21"},{"t":"축구와 피구의 학생 수의 차","mis":"M4-1-u5-X21"}],"explanation":["막대그래프에서는 항목별 수, 가장 많은 것, 두 항목의 차를 알 수 있어요.","「학생들이 그 항목을 고른 까닭」은 그래프에 나와 있지 않아요.","그래프에 없는 것은 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["축구","피구","수영","야구","배구"],"series":[{"vals":[11,2,7,12,9]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 운동별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#14','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C9',2,'mc','auto','멀리 떨어진 다른 학교 친구들과 함께 조사하려고 해요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?',ARRAY['M4-1-u5-X16']::text[],true,'{"seq":14,"concept":"M4-1-u5-C9","difficulty":2,"kind":"mc","stem":"멀리 떨어진 다른 학교 친구들과 함께 조사하려고 해요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"온라인 설문 — 멀리 있는 사람도 답할 수 있으니까요.","correct":true},{"t":"손 들기 — 그 자리에서 셀 수 있으니까요.","mis":"M4-1-u5-X16"},{"t":"붙임쪽지 — 우리 교실 게시판에 붙이면 되니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 멀리 있는 사람도 답할 수 있으니까요.","그래서 온라인 설문이 알맞아요."],"variant_rule":{"alt":[{"stem":"스마트 기기가 없는 교실에서 우리 반 친구들이 좋아하는 것을 차분히 조사하려고 해요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"종이에 적어 내기 — 기기 없이도 차분히 답할 수 있으니까요.","correct":true},{"t":"온라인 설문 — 기기가 없어도 집계되니까요.","mis":"M4-1-u5-X16"},{"t":"손 들기 — 차분히 생각할 시간을 주니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 기기 없이도 차분히 답할 수 있으니까요.","그래서 종이에 적어 내기가 알맞아요."],"asset":null},{"stem":"학교 4학년 전체 100명을 조사하려고 해요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"온라인 설문 — 여러 반의 답이 자동으로 집계되니까요.","correct":true},{"t":"손 들기 — 100명이 한곳에 모이기 쉬우니까요.","mis":"M4-1-u5-X16"},{"t":"붙임쪽지 — 쪽지 100장이면 충분하니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 결과가 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 여러 반의 답이 자동으로 집계되니까요.","그래서 온라인 설문이 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#15','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C10',2,'mc','auto','이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X11','M4-1-u5-X21']::text[],true,'{"seq":15,"concept":"M4-1-u5-C10","difficulty":2,"kind":"mc","stem":"이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 간식은 과일이다.」","correct":true},{"t":"「내일은 떡볶이가 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「과일은 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「떡볶이가 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 과일의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","기타"],"series":[{"vals":[6,10,12,8,4]}],"step":2,"ymax":14,"ylab":"(명)","title":"좋아하는 간식별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 놀이는 술래잡기다.」","correct":true},{"t":"「내일은 피구가 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「술래잡기는 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「피구가 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 술래잡기의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["술래잡기","공기","줄넘기","피구","기타"],"series":[{"vals":[9,4,8,3,7]}],"step":1,"ymax":10,"ylab":"(명)","title":"즐겨 하는 놀이별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 메뉴는 불고기다.」","correct":true},{"t":"「내일은 카레가 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「불고기는 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「카레가 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 불고기의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["불고기","잡채","카레","국수","기타"],"series":[{"vals":[9,6,3,5,2]}],"step":1,"ymax":10,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#16','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C11',2,'sa','auto','2학기 3모둠의 붙임딱지 수는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-1-u5-C11","difficulty":2,"kind":"sa","stem":"2학기 3모둠의 붙임딱지 수는 몇 개인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["이름표에서 2학기의 막대 색을 먼저 찾아요.","3모둠 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 2개).","2학기 3모둠의 붙임딱지 수는 20개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"1학기","vals":[18,16,14,4]},{"name":"2학기","vals":[22,30,20,16]}],"step":2,"ymax":32,"ylab":"(개)","title":"1학기와 2학기 칭찬 붙임딱지 수"},"variant_rule":{"alt":[{"stem":"남학생 겨울의 학생 수는 몇 명인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["이름표에서 남학생의 막대 색을 먼저 찾아요.","겨울 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 1명).","남학생 겨울의 학생 수는 4명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"name":"남학생","vals":[6,1,8,4]},{"name":"여학생","vals":[5,10,2,7]}],"step":1,"ymax":11,"ylab":"(명)","title":"남학생과 여학생이 좋아하는 계절"}},{"stem":"2반 김밥의 학생 수는 몇 명인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["이름표에서 2반의 막대 색을 먼저 찾아요.","김밥 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 1명).","2반 김밥의 학생 수는 5명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵"],"series":[{"name":"1반","vals":[4,3,5,6]},{"name":"2반","vals":[8,5,3,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"반별 좋아하는 간식"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#17','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C5',3,'mc','auto','표의 내용은 「봄 12명, 여름 5명, 가을 8명, 겨울 7명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?',ARRAY['M4-1-u5-X02']::text[],true,'{"seq":17,"concept":"M4-1-u5-C5","difficulty":3,"kind":"mc","stem":"표의 내용은 「봄 12명, 여름 5명, 가을 8명, 겨울 7명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"겨울","correct":true},{"t":"봄","mis":"M4-1-u5-X02"},{"t":"여름","mis":"M4-1-u5-X02"},{"t":"가을","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 1명이에요.","막대마다 표의 수와 견주어 봐요.","겨울의 막대는 6명인데 표에서는 7명이에요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"vals":[12,5,8,6]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 계절별 학생 수"},"variant_rule":{"alt":[{"stem":"표의 내용은 「로봇 9명, 요리 12명, 방송 7명, 소방 4명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"방송","correct":true},{"t":"로봇","mis":"M4-1-u5-X02"},{"t":"요리","mis":"M4-1-u5-X02"},{"t":"소방","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 1명이에요.","막대마다 표의 수와 견주어 봐요.","방송의 막대는 8명인데 표에서는 7명이에요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["로봇","요리","방송","소방"],"series":[{"vals":[9,12,8,4]}],"step":1,"ymax":13,"ylab":"(명)","title":"가고 싶은 체험별 학생 수"}},{"stem":"표의 내용은 「요리사 9명, 경찰관 7명, 과학자 10명, 가수 3명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"경찰관","correct":true},{"t":"요리사","mis":"M4-1-u5-X02"},{"t":"과학자","mis":"M4-1-u5-X02"},{"t":"가수","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 1명이에요.","막대마다 표의 수와 견주어 봐요.","경찰관의 막대는 8명인데 표에서는 7명이에요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["요리사","경찰관","과학자","가수"],"series":[{"vals":[9,8,10,3]}],"step":1,"ymax":11,"ylab":"(명)","title":"희망 직업별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#18','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C6',3,'mc','auto','「마을별 나무 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 5그루로 그렸어요, 나 그래프는 눈금 한 칸을 120그루로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X07']::text[],true,'{"seq":18,"concept":"M4-1-u5-C6","difficulty":3,"kind":"mc","stem":"「마을별 나무 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 5그루로 그렸어요, 나 그래프는 눈금 한 칸을 120그루로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"가 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"나 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 120그루면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 5그루인 가 그래프가 차이를 알아보기 좋아요."],"variant_rule":{"alt":[{"stem":"「학년별 우유 신청 학생 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 100명으로 그렸어요, 나 그래프는 눈금 한 칸을 5명으로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"가 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 100명면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 5명인 나 그래프가 차이를 알아보기 좋아요."],"asset":null},{"stem":"「모둠별 모은 빈 병 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 2개로 그렸어요, 나 그래프는 눈금 한 칸을 40개로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"가 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"나 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 40개면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 2개인 가 그래프가 차이를 알아보기 좋아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#19','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C7',3,'mc','auto','배를 좋아하는 학생은 사과를 좋아하는 학생의 몇 배인가요?',ARRAY['M4-1-u5-X09']::text[],true,'{"seq":19,"concept":"M4-1-u5-C7","difficulty":3,"kind":"mc","stem":"배를 좋아하는 학생은 사과를 좋아하는 학생의 몇 배인가요?","options":[{"t":"3배","correct":true},{"t":"8배","mis":"M4-1-u5-X09"},{"t":"4배","mis":"M4-1-u5-X09"},{"t":"2배","mis":"M4-1-u5-X09"}],"explanation":["배는 12명, 사과는 4명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 4 × 3 = 12.","그래서 3배예요 — 차(8)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["사과","포도","딸기","귤","배"],"series":[{"vals":[4,2,9,6,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 과일별 학생 수"},"variant_rule":{"alt":[{"stem":"피구를 좋아하는 학생은 축구를 좋아하는 학생의 몇 배인가요?","options":[{"t":"2배","correct":true},{"t":"5배","mis":"M4-1-u5-X09"},{"t":"3배","mis":"M4-1-u5-X09"},{"t":"1배","mis":"M4-1-u5-X09"}],"explanation":["피구는 10명, 축구는 5명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 5 × 2 = 10.","그래서 2배예요 — 차(5)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["축구","피구","수영","야구","배구"],"series":[{"vals":[5,10,2,6,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 운동별 학생 수"}},{"stem":"여름을 좋아하는 학생은 봄을 좋아하는 학생의 몇 배인가요?","options":[{"t":"4배","correct":true},{"t":"6배","mis":"M4-1-u5-X09"},{"t":"5배","mis":"M4-1-u5-X09"},{"t":"3배","mis":"M4-1-u5-X09"}],"explanation":["여름은 8명, 봄은 2명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 2 × 4 = 8.","그래서 4배예요 — 차(6)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"vals":[2,8,6,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 계절별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#20','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C8',3,'mc','auto','가 그래프는 눈금 한 칸이 1명이고 떡볶이의 막대가 10칸이에요. 나 그래프는 눈금 한 칸이 5명이고 만두의 막대가 3칸이에요. 떡볶이의 막대가 더 길어 보이는데, 떡볶이를 고른 학생이 더 많은 걸까요?',ARRAY['M4-1-u5-X10','M4-1-u5-X02','M4-1-u5-X12']::text[],true,'{"seq":20,"concept":"M4-1-u5-C8","difficulty":3,"kind":"mc","stem":"가 그래프는 눈금 한 칸이 1명이고 떡볶이의 막대가 10칸이에요. 나 그래프는 눈금 한 칸이 5명이고 만두의 막대가 3칸이에요. 떡볶이의 막대가 더 길어 보이는데, 떡볶이를 고른 학생이 더 많은 걸까요?","options":[{"t":"아니요 — 눈금이 달라요. 떡볶이는 10명, 만두는 15명이에요.","correct":true},{"t":"네 — 막대가 길면 언제나 수가 많아요.","mis":"M4-1-u5-X10"},{"t":"두 막대가 나타내는 수는 똑같아요.","mis":"M4-1-u5-X02"},{"t":"네 — 가 그래프가 먼저 나왔으니까요.","mis":"M4-1-u5-X12"}],"explanation":["다른 그래프끼리 견줄 때는 눈금부터 확인해요.","떡볶이는 10 × 1 = 10명, 만두는 3 × 5 = 15명이에요.","막대는 떡볶이가 더 길어도 수는 만두가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 그래프는 눈금 한 칸이 2명이고 봄의 막대가 6칸이에요. 나 그래프는 눈금 한 칸이 5명이고 가을의 막대가 3칸이에요. 봄의 막대가 더 길어 보이는데, 봄을 고른 학생이 더 많은 걸까요?","options":[{"t":"아니요 — 눈금이 달라요. 봄은 12명, 가을은 15명이에요.","correct":true},{"t":"네 — 막대가 길면 언제나 수가 많아요.","mis":"M4-1-u5-X10"},{"t":"두 막대가 나타내는 수는 똑같아요.","mis":"M4-1-u5-X02"},{"t":"네 — 가 그래프가 먼저 나왔으니까요.","mis":"M4-1-u5-X12"}],"explanation":["다른 그래프끼리 견줄 때는 눈금부터 확인해요.","봄은 6 × 2 = 12명, 가을은 3 × 5 = 15명이에요.","막대는 봄이 더 길어도 수는 가을이 더 많아요."],"asset":null},{"stem":"가 그래프는 눈금 한 칸이 1명이고 범죄 수사관의 막대가 8칸이에요. 나 그래프는 눈금 한 칸이 5명이고 수의사의 막대가 2칸이에요. 범죄 수사관의 막대가 더 길어 보이는데, 범죄 수사관을 고른 학생이 더 많은 걸까요?","options":[{"t":"아니요 — 눈금이 달라요. 범죄 수사관은 8명, 수의사는 10명이에요.","correct":true},{"t":"네 — 막대가 길면 언제나 수가 많아요.","mis":"M4-1-u5-X10"},{"t":"두 막대가 나타내는 수는 똑같아요.","mis":"M4-1-u5-X02"},{"t":"네 — 가 그래프가 먼저 나왔으니까요.","mis":"M4-1-u5-X12"}],"explanation":["다른 그래프끼리 견줄 때는 눈금부터 확인해요.","범죄 수사관은 8 × 1 = 8명, 수의사는 2 × 5 = 10명이에요.","막대는 범죄 수사관이 더 길어도 수는 수의사가 더 많아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#21','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C9',3,'mc','auto','조사를 했더니 합계가 30명이 나왔어요. 우리 반은 27명인데요! 무슨 일이 생긴 걸까요?',ARRAY['M4-1-u5-X21','M4-1-u5-X14','M4-1-u5-X15']::text[],true,'{"seq":21,"concept":"M4-1-u5-C9","difficulty":3,"kind":"mc","stem":"조사를 했더니 합계가 30명이 나왔어요. 우리 반은 27명인데요! 무슨 일이 생긴 걸까요?","options":[{"t":"두 번 답한 친구가 있어요 — 한 사람은 한 번만 답해야 해요.","correct":true},{"t":"빠진 친구가 있어요 — 모두 한 번씩 답해야 해요.","mis":"M4-1-u5-X21"},{"t":"항목을 너무 많이 만들었어요.","mis":"M4-1-u5-X14"},{"t":"합계는 인원과 달라도 괜찮아요.","mis":"M4-1-u5-X15"}],"explanation":["합계는 우리 반 인원과 같아야 해요.","합계 30명이 인원 27명보다 많아요.","많으면 두 번 답한 친구가, 적으면 빠진 친구가 있는 거예요."],"variant_rule":{"alt":[{"stem":"조사를 했더니 합계가 19명이 나왔어요. 우리 반은 22명인데요! 무슨 일이 생긴 걸까요?","options":[{"t":"빠진 친구가 있어요 — 모두 한 번씩 답해야 해요.","correct":true},{"t":"두 번 답한 친구가 있어요 — 한 사람은 한 번만 답해야 해요.","mis":"M4-1-u5-X21"},{"t":"항목을 너무 많이 만들었어요.","mis":"M4-1-u5-X14"},{"t":"합계는 인원과 달라도 괜찮아요.","mis":"M4-1-u5-X15"}],"explanation":["합계는 우리 반 인원과 같아야 해요.","합계 19명이 인원 22명보다 적어요.","많으면 두 번 답한 친구가, 적으면 빠진 친구가 있는 거예요."],"asset":null},{"stem":"조사를 했더니 합계가 26명이 나왔어요. 우리 반은 24명인데요! 무슨 일이 생긴 걸까요?","options":[{"t":"두 번 답한 친구가 있어요 — 한 사람은 한 번만 답해야 해요.","correct":true},{"t":"빠진 친구가 있어요 — 모두 한 번씩 답해야 해요.","mis":"M4-1-u5-X21"},{"t":"항목을 너무 많이 만들었어요.","mis":"M4-1-u5-X14"},{"t":"합계는 인원과 달라도 괜찮아요.","mis":"M4-1-u5-X15"}],"explanation":["합계는 우리 반 인원과 같아야 해요.","합계 26명이 인원 24명보다 많아요.","많으면 두 번 답한 친구가, 적으면 빠진 친구가 있는 거예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#22','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C11',3,'mc','auto','작년보다 올해에 나무 수가 가장 많이 늘어난 항목은 어느 것인가요?',ARRAY['M4-1-u5-X09']::text[],true,'{"seq":22,"concept":"M4-1-u5-C11","difficulty":3,"kind":"mc","stem":"작년보다 올해에 나무 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"가 마을","correct":true},{"t":"라 마을","mis":"M4-1-u5-X09"},{"t":"나 마을","mis":"M4-1-u5-X09"},{"t":"다 마을","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 가 마을 35, 나 마을 20, 다 마을 15, 라 마을 25.","올해의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 가 마을이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 마을","나 마을","다 마을","라 마을"],"series":[{"name":"작년","vals":[25,15,30,40]},{"name":"올해","vals":[60,35,45,65]}],"step":5,"ymax":70,"ylab":"(그루)","title":"작년과 올해 심은 나무 수"},"variant_rule":{"alt":[{"stem":"1학기보다 2학기에 붙임딱지 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"3모둠","correct":true},{"t":"4모둠","mis":"M4-1-u5-X09"},{"t":"1모둠","mis":"M4-1-u5-X09"},{"t":"2모둠","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 1모둠 2, 2모둠 10, 3모둠 12, 4모둠 6.","2학기의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 3모둠이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"1학기","vals":[6,12,8,20]},{"name":"2학기","vals":[8,22,20,26]}],"step":2,"ymax":28,"ylab":"(개)","title":"1학기와 2학기 칭찬 붙임딱지 수"}},{"stem":"작년보다 올해에 빌린 책 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"역사","correct":true},{"t":"만화","mis":"M4-1-u5-X09"},{"t":"동화","mis":"M4-1-u5-X09"},{"t":"과학","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 동화 30, 과학 10, 역사 70, 만화 50.","올해의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 역사예요."],"asset":{"type":"lgraph","mode":"bar","xs":["동화","과학","역사","만화"],"series":[{"name":"작년","vals":[50,20,60,100]},{"name":"올해","vals":[80,30,130,150]}],"step":10,"ymax":160,"ylab":"(권)","title":"작년과 올해 빌린 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#23','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C10',4,'sa','auto','우리 반 40명이 모두 답한 간식 조사의 표에서 과일의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 과일 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-1-u5-C10","difficulty":4,"kind":"sa","stem":"우리 반 40명이 모두 답한 간식 조사의 표에서 과일의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 과일 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["과일의 수는 40 − (8 + 4 + 14 + 12) = 2명이에요.","눈금 한 칸이 2명이니 2 ÷ 2로 구해요.","1칸으로 그려요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","기타"],"counts":[8,4,null,14,12],"vh":"학생 수","unit":"명","total":40,"title":"좋아하는 간식별 학생 수"},"variant_rule":{"alt":[{"stem":"우리 반 34명이 모두 답한 간식 조사의 표에서 과일의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 과일 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["과일의 수는 34 − (6 + 10 + 12 + 4) = 2명이에요.","눈금 한 칸이 2명이니 2 ÷ 2로 구해요.","1칸으로 그려요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","기타"],"counts":[6,10,null,12,4],"vh":"학생 수","unit":"명","total":34,"title":"좋아하는 간식별 학생 수"}},{"stem":"우리 반 44명이 모두 답한 간식 조사의 표에서 떡볶이의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 떡볶이 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["떡볶이의 수는 44 − (12 + 14 + 6 + 8) = 4명이에요.","눈금 한 칸이 2명이니 4 ÷ 2로 구해요.","2칸으로 그려요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","기타"],"counts":[null,12,14,6,8],"vh":"학생 수","unit":"명","total":44,"title":"좋아하는 간식별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#24','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C11',4,'sa','auto','1학기와 2학기의 차가 가장 큰 항목에서, 두 수의 차는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-1-u5-C11","difficulty":4,"kind":"sa","stem":"1학기와 2학기의 차가 가장 큰 항목에서, 두 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["항목마다 두 막대의 차를 구해요: 1모둠 22, 2모둠 2, 3모둠 20, 4모둠 6.","차가 가장 큰 항목은 1모둠이에요.","그 차는 22개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"1학기","vals":[8,22,6,14]},{"name":"2학기","vals":[30,24,26,20]}],"step":2,"ymax":32,"ylab":"(개)","title":"1학기와 2학기 칭찬 붙임딱지 수"},"variant_rule":{"alt":[{"stem":"남학생과 여학생의 차가 가장 큰 항목에서, 두 수의 차는 몇 명인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["항목마다 두 막대의 차를 구해요: 봄 6, 여름 4, 가을 7, 겨울 3.","차가 가장 큰 항목은 가을이에요.","그 차는 7명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"name":"남학생","vals":[10,5,9,2]},{"name":"여학생","vals":[4,9,2,5]}],"step":1,"ymax":11,"ylab":"(명)","title":"남학생과 여학생이 좋아하는 계절"}},{"stem":"1반과 2반의 차가 가장 큰 항목에서, 두 수의 차는 몇 명인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["항목마다 두 막대의 차를 구해요: 떡볶이 2, 김밥 9, 과일 5, 빵 3.","차가 가장 큰 항목은 김밥이에요.","그 차는 9명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵"],"series":[{"name":"1반","vals":[8,11,3,10]},{"name":"2반","vals":[6,2,8,7]}],"step":1,"ymax":12,"ylab":"(명)","title":"반별 좋아하는 간식"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_c#25','math',4,1,'u5','','g4_1_math_u5_review_c','unit_review','M4-1-u5-C8',4,'essay','teacher','「희망 직업별 학생 수」 그래프에서 요리사가 9명으로 가장 많고 의사가 3명으로 가장 적어요. 학급 초청 행사에 직업인 한 분을 모시려고 할 때 그래프를 바탕으로 누구를 초대하면 좋을지 쓰고, 이 그래프만으로는 알 수 없는 것을 한 가지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u5-C8","difficulty":4,"kind":"essay","stem":"「희망 직업별 학생 수」 그래프에서 요리사가 9명으로 가장 많고 의사가 3명으로 가장 적어요. 학급 초청 행사에 직업인 한 분을 모시려고 할 때 그래프를 바탕으로 누구를 초대하면 좋을지 쓰고, 이 그래프만으로는 알 수 없는 것을 한 가지 써 보세요.","answer_guide":{"answer":"예: 가장 많은 학생이 희망하는 요리사를 초대하는 것이 좋다. 그래프에서 요리사의 막대가 9명으로 가장 길기 때문이다. 그러나 학생들이 왜 그 직업을 희망하는지 그 까닭은 그래프에 나와 있지 않아 알 수 없다.","scoring_points":["요리사를 골랐는가","가장 긴 막대(9명)를 근거로 썼는가","까닭처럼 그래프에 없는 것을 썼는가"]},"explanation":["판단은 그래프의 수로 해요.","요리사 막대가 9명으로 가장 길어요.","희망하는 까닭은 그래프에 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#1','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C2',1,'mc','auto','그림을 세지 않고도 길이만 보고 많고 적음을 견줄 수 있는 것은 어느 것인가요?',ARRAY['M4-1-u5-X04']::text[],true,'{"seq":1,"concept":"M4-1-u5-C2","difficulty":1,"kind":"mc","stem":"그림을 세지 않고도 길이만 보고 많고 적음을 견줄 수 있는 것은 어느 것인가요?","options":[{"t":"막대그래프","correct":true},{"t":"그림그래프","mis":"M4-1-u5-X04"},{"t":"표","mis":"M4-1-u5-X04"},{"t":"말로 들은 조사 결과","mis":"M4-1-u5-X04"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"variant_rule":{"alt":[{"stem":"조사한 수량을 막대 모양으로 나타낸 그래프를 무엇이라고 하나요?","options":[{"t":"막대그래프","correct":true},{"t":"그림그래프","mis":"M4-1-u5-X04"},{"t":"표","mis":"M4-1-u5-X04"},{"t":"수직선","mis":"M4-1-u5-X04"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"asset":null},{"stem":"막대그래프에서 수량은 무엇으로 나타내나요?","options":[{"t":"막대의 길이","correct":true},{"t":"막대의 굵기","mis":"M4-1-u5-X03"},{"t":"막대의 색깔","mis":"M4-1-u5-X03"},{"t":"그림의 개수","mis":"M4-1-u5-X04"}],"explanation":["조사한 수량을 막대 모양으로 나타낸 그래프가 막대그래프예요.","수량은 막대의 길이로 나타내고, 굵기는 모두 같아요.","그래서 세지 않아도 길이만 보면 많고 적음을 견줄 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#2','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C3',1,'mc','auto','아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?',ARRAY['M4-1-u5-X01']::text[],true,'{"seq":2,"concept":"M4-1-u5-C3","difficulty":1,"kind":"mc","stem":"아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 모둠, 세로: 빈 병 수","correct":true},{"t":"가로: 빈 병 수, 세로: 모둠","mis":"M4-1-u5-X01"},{"t":"가로: 모둠, 세로: 모둠","mis":"M4-1-u5-X01"},{"t":"가로: 빈 병 수, 세로: 빈 병 수","mis":"M4-1-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 모둠, 세로에는 빈 병 수를 개 단위로 나타냈어요.","가로: 모둠, 세로: 빈 병 수예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠","5모둠"],"series":[{"vals":[12,8,14,16,20]}],"step":2,"ymax":22,"ylab":"(개)","title":"모둠별 모은 빈 병 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 지역, 세로: 문화유산 수","correct":true},{"t":"가로: 문화유산 수, 세로: 지역","mis":"M4-1-u5-X01"},{"t":"가로: 지역, 세로: 지역","mis":"M4-1-u5-X01"},{"t":"가로: 문화유산 수, 세로: 문화유산 수","mis":"M4-1-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 지역, 세로에는 문화유산 수를 점 단위로 나타냈어요.","가로: 지역, 세로: 문화유산 수예요."],"asset":{"type":"lgraph","mode":"bar","xs":["가 지역","나 지역","다 지역","라 지역","마 지역"],"series":[{"vals":[125,75,150,175,25]}],"step":25,"ymax":200,"ylab":"(점)","title":"지역별 문화유산 수"}},{"stem":"이번에는 다른 그림이에요. 아래 막대그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 과일, 세로: 학생 수","correct":true},{"t":"가로: 학생 수, 세로: 과일","mis":"M4-1-u5-X01"},{"t":"가로: 과일, 세로: 과일","mis":"M4-1-u5-X01"},{"t":"가로: 학생 수, 세로: 학생 수","mis":"M4-1-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 과일, 세로에는 학생 수를 명 단위로 나타냈어요.","가로: 과일, 세로: 학생 수예요."],"asset":{"type":"lgraph","mode":"bar","xs":["사과","포도","딸기","귤","배"],"series":[{"vals":[2,8,12,9,10]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 과일별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#3','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C1',1,'sa','auto','조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u5-C1","difficulty":1,"kind":"sa","stem":"조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["43"],"explanation":["합계는 항목별 수를 모두 더한 것이에요.","11 + 6 + 9 + 10 + 7. = 43","합계는 43명이에요 — 모두 답했는지 확인할 수 있어요."],"asset":{"type":"picg","only":"table","head":"동물","cols":["강아지","고양이","토끼","햄스터","금붕어"],"counts":[11,6,9,10,7],"vh":"학생 수","unit":"명","total":null,"title":"기르고 싶은 동물별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["합계는 항목별 수를 모두 더한 것이에요.","2 + 3 + 4 + 11 + 7. = 27","합계는 27명이에요 — 모두 답했는지 확인할 수 있어요."],"asset":{"type":"picg","only":"table","head":"과일","cols":["사과","포도","딸기","귤","배"],"counts":[2,3,4,11,7],"vh":"학생 수","unit":"명","total":null,"title":"좋아하는 과일별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 조사한 것을 표로 정리했어요. 합계는 몇 명인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["합계는 항목별 수를 모두 더한 것이에요.","4 + 7 + 10 + 11 + 8. = 40","합계는 40명이에요 — 모두 답했는지 확인할 수 있어요."],"asset":{"type":"picg","only":"table","head":"운동","cols":["축구","피구","수영","야구","배구"],"counts":[4,7,10,11,8],"vh":"학생 수","unit":"명","total":null,"title":"좋아하는 운동별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#4','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C4',1,'mc','auto','가로에는 항목, 세로에는 학생 수를 나타내기로 정했어요. 그다음에 정할 것은 무엇인가요?',ARRAY['M4-1-u5-X03','M4-1-u5-X18']::text[],true,'{"seq":4,"concept":"M4-1-u5-C4","difficulty":1,"kind":"mc","stem":"가로에는 항목, 세로에는 학생 수를 나타내기로 정했어요. 그다음에 정할 것은 무엇인가요?","options":[{"t":"세로 눈금의 단위","correct":true},{"t":"막대마다 다른 굵기","mis":"M4-1-u5-X03"},{"t":"막대마다 다른 색","mis":"M4-1-u5-X03"},{"t":"신문 기사 제목","mis":"M4-1-u5-X18"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"variant_rule":{"alt":[{"stem":"막대그래프를 그리는 차례에서 눈금 한 칸의 크기를 정한 다음에 하는 일은 무엇인가요?","options":[{"t":"수량만큼 막대를 그려요.","correct":true},{"t":"가로와 세로에 나타낼 것을 정해요.","mis":"M4-1-u5-X18"},{"t":"세로 눈금의 단위를 정해요.","mis":"M4-1-u5-X18"},{"t":"조사를 처음부터 다시 해요.","mis":"M4-1-u5-X18"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"asset":null},{"stem":"막대그래프를 그리는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"제목 → 가로와 세로 → 단위 → 눈금의 크기 → 막대","correct":true},{"t":"막대 → 눈금의 크기 → 단위 → 가로와 세로 → 제목","mis":"M4-1-u5-X18"},{"t":"가로와 세로 → 막대 → 단위 → 눈금의 크기 → 제목","mis":"M4-1-u5-X18"},{"t":"눈금의 크기 → 막대 → 가로와 세로 → 단위 → 제목","mis":"M4-1-u5-X18"}],"explanation":["그리는 차례 — ① 제목 ② 가로와 세로 ③ 단위 ④ 눈금 한 칸의 크기 ⑤ 막대.","막대는 수량만큼 그리고, 굵기는 모두 같게 해요.","제목은 맨 마지막에 써도 괜찮아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#5','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C5',1,'sa','auto','표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 권까지 나타내어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u5-C5","difficulty":1,"kind":"sa","stem":"표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 권까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["140"],"explanation":["세로 눈금은 모든 막대를 그릴 수 있어야 해요.","표에서 가장 큰 수는 140권이에요.","그래서 세로 눈금은 적어도 140권까지 나타내요."],"asset":{"type":"picg","only":"table","head":"반","cols":["1반","2반","3반","4반","5반","6반"],"counts":[110,60,40,140,50,130],"vh":"빌린 책 수","unit":"권","title":"반별 빌린 책 수"},"variant_rule":{"alt":[{"stem":"표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 kg까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["260"],"explanation":["세로 눈금은 모든 막대를 그릴 수 있어야 해요.","표에서 가장 큰 수는 260 kg이에요.","그래서 세로 눈금은 적어도 260 kg까지 나타내요."],"asset":{"type":"picg","only":"table","head":"농장","cols":["해 농장","달 농장","별 농장","숲 농장","강 농장"],"counts":[260,200,180,240,100],"vh":"토마토 생산량","unit":"kg","title":"농장별 토마토 생산량"}},{"stem":"표를 보고 막대그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 그루까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["75"],"explanation":["세로 눈금은 모든 막대를 그릴 수 있어야 해요.","표에서 가장 큰 수는 75그루예요.","그래서 세로 눈금은 적어도 75그루까지 나타내요."],"asset":{"type":"picg","only":"table","head":"마을","cols":["가 마을","나 마을","다 마을","라 마을","마 마을"],"counts":[30,15,45,55,75],"vh":"나무 수","unit":"그루","title":"마을별 나무 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#6','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C6',1,'mc','auto','가장 큰 수가 126인 자료를 눈금 한 칸 1로 그리면 어떤 점이 불편한가요?',ARRAY['M4-1-u5-X21','M4-1-u5-X06','M4-1-u5-X07']::text[],true,'{"seq":6,"concept":"M4-1-u5-C6","difficulty":1,"kind":"mc","stem":"가장 큰 수가 126인 자료를 눈금 한 칸 1로 그리면 어떤 점이 불편한가요?","options":[{"t":"칸을 126개나 그려야 해서 종이에 다 들어가지 않아요.","correct":true},{"t":"막대들이 다 비슷해 보여요.","mis":"M4-1-u5-X21"},{"t":"막대가 나타내는 수가 달라져요.","mis":"M4-1-u5-X06"},{"t":"불편한 점이 없어요.","mis":"M4-1-u5-X07"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"variant_rule":{"alt":[{"stem":"눈금 한 칸의 크기를 바꾸면 무엇이 달라지나요?","options":[{"t":"막대의 칸 수는 달라지지만 나타내는 수는 그대로예요.","correct":true},{"t":"막대가 나타내는 수가 달라져요.","mis":"M4-1-u5-X06"},{"t":"항목의 개수가 달라져요.","mis":"M4-1-u5-X06"},{"t":"아무것도 달라지지 않아요.","mis":"M4-1-u5-X06"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"asset":null},{"stem":"같은 자료에서 눈금 한 칸을 크게 하면 막대는 어떻게 되나요?","options":[{"t":"막대가 짧아져요.","correct":true},{"t":"막대가 길어져요.","mis":"M4-1-u5-X21"},{"t":"막대가 나타내는 수가 커져요.","mis":"M4-1-u5-X06"},{"t":"막대가 굵어져요.","mis":"M4-1-u5-X03"}],"explanation":["눈금 한 칸을 크게 하면 막대가 짧아지고, 작게 하면 길어져요.","그래도 막대가 나타내는 수는 조금도 변하지 않아요.","가장 큰 수가 들어가면서 차이가 잘 보이게 한 칸을 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#7','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C9',1,'mc','auto','조사할 때 한 사람은 몇 번 답해야 하나요?',ARRAY['M4-1-u5-X15']::text[],true,'{"seq":7,"concept":"M4-1-u5-C9","difficulty":1,"kind":"mc","stem":"조사할 때 한 사람은 몇 번 답해야 하나요?","options":[{"t":"한 번만 답해요.","correct":true},{"t":"두 번씩 답해요.","mis":"M4-1-u5-X15"},{"t":"원하는 만큼 답해요.","mis":"M4-1-u5-X15"},{"t":"답하지 않아도 돼요.","mis":"M4-1-u5-X15"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"variant_rule":{"alt":[{"stem":"자료를 조사할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"조사할 주제 정하기","correct":true},{"t":"막대그래프 그리기","mis":"M4-1-u5-X18"},{"t":"조사 방법 정하기","mis":"M4-1-u5-X18"},{"t":"합계 확인하기","mis":"M4-1-u5-X18"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"asset":null},{"stem":"조사할 주제를 정한 다음에 할 일은 무엇인가요?","options":[{"t":"항목 정하기","correct":true},{"t":"합계 확인하기","mis":"M4-1-u5-X18"},{"t":"막대그래프 그리기","mis":"M4-1-u5-X18"},{"t":"신문 기사 쓰기","mis":"M4-1-u5-X18"}],"explanation":["조사는 주제 → 항목 → 방법 → 조사의 차례로 해요.","항목은 겹치지 않게, 답은 한 사람이 한 번만 해요.","끝나면 합계가 인원과 같은지 꼭 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#8','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C11',1,'mc','auto','자료별(작년끼리·올해끼리)로 묶어 그리면 무엇을 견주기 좋나요?',ARRAY['M4-1-u5-X11','M4-1-u5-X03']::text[],true,'{"seq":8,"concept":"M4-1-u5-C11","difficulty":1,"kind":"mc","stem":"자료별(작년끼리·올해끼리)로 묶어 그리면 무엇을 견주기 좋나요?","options":[{"t":"같은 해 안에서 항목끼리 견주기","correct":true},{"t":"항목마다 늘어난 까닭","mis":"M4-1-u5-X11"},{"t":"다음 해의 수","mis":"M4-1-u5-X11"},{"t":"막대의 굵기","mis":"M4-1-u5-X03"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"variant_rule":{"alt":[{"stem":"두 자료를 하나의 막대그래프에 나타낼 때 두 자료는 무엇으로 구분하나요?","options":[{"t":"막대의 색 — 이름표(범례)가 알려 줘요.","correct":true},{"t":"막대의 굵기 — 굵은 쪽이 새 자료예요.","mis":"M4-1-u5-X03"},{"t":"눈금 한 칸의 크기","mis":"M4-1-u5-X02"},{"t":"막대 위에 붙인 별표","mis":"M4-1-u5-X19"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"asset":null},{"stem":"두 자료를 나타낸 막대그래프에서 어느 색이 어느 자료인지 알려 주는 것은 무엇인가요?","options":[{"t":"이름표(범례)","correct":true},{"t":"제목","mis":"M4-1-u5-X19"},{"t":"세로 눈금","mis":"M4-1-u5-X19"},{"t":"가로 눈금 이름","mis":"M4-1-u5-X19"}],"explanation":["두 자료는 하나의 그래프에 막대를 나란히 세워 나타낼 수 있어요.","두 자료는 막대의 색으로 구분하고, 이름표(범례)가 어느 자료인지 알려 줘요.","묶는 방법을 바꿔도 나타내는 수는 그대로예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#9','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C3',2,'sa','auto','배구를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u5-C3","difficulty":2,"kind":"sa","stem":"배구를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["세로 눈금 한 칸은 1명이에요.","배구의 막대 끝을 따라 세로 눈금을 읽어요.","배구를 좋아하는 학생은 3명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["축구","피구","수영","야구","배구"],"series":[{"vals":[7,5,2,9,3]}],"step":1,"ymax":10,"ylab":"(명)","title":"좋아하는 운동별 학생 수"},"variant_rule":{"alt":[{"stem":"겨울을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["세로 눈금 한 칸은 1명이에요.","겨울의 막대 끝을 따라 세로 눈금을 읽어요.","겨울을 좋아하는 학생은 6명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"vals":[4,10,2,6]}],"step":1,"ymax":11,"ylab":"(명)","title":"좋아하는 계절별 학생 수"}},{"stem":"로봇 체험을 고른 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["세로 눈금 한 칸은 1명이에요.","로봇의 막대 끝을 따라 세로 눈금을 읽어요.","로봇 체험을 고른 학생은 10명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["로봇","요리","방송","소방","과학"],"series":[{"vals":[10,13,12,4,9]}],"step":1,"ymax":14,"ylab":"(명)","title":"가고 싶은 체험별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#10','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C5',2,'sa','auto','세로 눈금 한 칸이 5명인 막대그래프에 45명을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u5-C5","difficulty":2,"kind":"sa","stem":"세로 눈금 한 칸이 5명인 막대그래프에 45명을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 칸이 5명이니 한 칸 올라갈 때마다 5씩 커져요.","막대의 칸 수는 45 ÷ 5로 구해요.","45 ÷ 5 = 9 — 9칸으로 그려요."],"variant_rule":{"alt":[{"stem":"세로 눈금 한 칸이 1명인 막대그래프에 7명을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 칸이 1명이니 한 칸 올라갈 때마다 1씩 커져요.","막대의 칸 수는 7 ÷ 1로 구해요.","7 ÷ 1 = 7 — 7칸으로 그려요."],"asset":null},{"stem":"세로 눈금 한 칸이 2명인 막대그래프에 12명을 나타내려고 해요. 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 칸이 2명이니 한 칸 올라갈 때마다 2씩 커져요.","막대의 칸 수는 12 ÷ 2로 구해요.","12 ÷ 2 = 6 — 6칸으로 그려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#11','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C6',2,'sa','auto','눈금 한 칸이 10권인 막대그래프에서 9칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 30권인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M4-1-u5-C6","difficulty":2,"kind":"sa","stem":"눈금 한 칸이 10권인 막대그래프에서 9칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 30권인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 막대가 나타내는 수를 구해요: 9 × 10 = 90.","나타내는 수 90권은 눈금이 바뀌어도 그대로예요.","90 ÷ 30 = 3 — 3칸이 돼요."],"variant_rule":{"alt":[{"stem":"눈금 한 칸이 1명인 막대그래프에서 10칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 2명인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["5"],"explanation":["먼저 막대가 나타내는 수를 구해요: 10 × 1 = 10.","나타내는 수 10명은 눈금이 바뀌어도 그대로예요.","10 ÷ 2 = 5 — 5칸이 돼요."],"asset":null},{"stem":"눈금 한 칸이 1명인 막대그래프에서 12칸이던 막대가 있어요. 같은 자료를 눈금 한 칸이 2명인 막대그래프로 다시 그리면 이 막대는 몇 칸이 되나요? 숫자로 쓰세요.","answer":["6"],"explanation":["먼저 막대가 나타내는 수를 구해요: 12 × 1 = 12.","나타내는 수 12명은 눈금이 바뀌어도 그대로예요.","12 ÷ 2 = 6 — 6칸이 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#12','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C7',2,'sa','auto','국수를 좋아하는 학생은 잡채를 좋아하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M4-1-u5-C7","difficulty":2,"kind":"sa","stem":"국수를 좋아하는 학생은 잡채를 좋아하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["4"],"explanation":["국수는 9명, 잡채는 5명이에요.","몇 더 많은지는 큰 수에서 작은 수를 빼요.","9 − 5 = 4 — 4명 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["카레","잡채","불고기","국수","김밥"],"series":[{"vals":[10,5,4,9,2]}],"step":1,"ymax":11,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"},"variant_rule":{"alt":[{"stem":"빵을 좋아하는 학생은 만두를 좋아하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["1"],"explanation":["빵은 10명, 만두는 9명이에요.","몇 더 많은지는 큰 수에서 작은 수를 빼요.","10 − 9 = 1 — 1명 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","만두"],"series":[{"vals":[11,5,6,10,9]}],"step":1,"ymax":12,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}},{"stem":"햄스터를 기르고 싶은 학생은 강아지를 기르고 싶은 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["2"],"explanation":["햄스터는 3명, 강아지는 1명이에요.","몇 더 많은지는 큰 수에서 작은 수를 빼요.","3 − 1 = 2 — 2명 더 많아요."],"asset":{"type":"lgraph","mode":"bar","xs":["강아지","고양이","토끼","햄스터","금붕어"],"series":[{"vals":[1,10,6,3,11]}],"step":1,"ymax":12,"ylab":"(명)","title":"기르고 싶은 동물별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#13','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C8',2,'mc','auto','아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?',ARRAY['M4-1-u5-X21']::text[],true,'{"seq":13,"concept":"M4-1-u5-C8","difficulty":2,"kind":"mc","stem":"아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"학생마다 고른 항목의 이름","correct":true},{"t":"가장 많은 학생이 고른 항목","mis":"M4-1-u5-X21"},{"t":"포도의 학생 수","mis":"M4-1-u5-X21"},{"t":"포도와 딸기의 학생 수의 차","mis":"M4-1-u5-X21"}],"explanation":["막대그래프에서는 항목별 수, 가장 많은 것, 두 항목의 차를 알 수 있어요.","「학생마다 고른 항목의 이름」은 그래프에 나와 있지 않아요.","그래프에 없는 것은 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["사과","포도","딸기","귤","배"],"series":[{"vals":[5,2,7,11,6]}],"step":1,"ymax":12,"ylab":"(명)","title":"좋아하는 과일별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"학생들이 그 항목을 고른 까닭","correct":true},{"t":"가장 많은 학생이 고른 항목","mis":"M4-1-u5-X21"},{"t":"축구의 학생 수","mis":"M4-1-u5-X21"},{"t":"축구와 피구의 학생 수의 차","mis":"M4-1-u5-X21"}],"explanation":["막대그래프에서는 항목별 수, 가장 많은 것, 두 항목의 차를 알 수 있어요.","「학생들이 그 항목을 고른 까닭」은 그래프에 나와 있지 않아요.","그래프에 없는 것은 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["축구","피구","수영","야구","배구"],"series":[{"vals":[11,2,7,12,9]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 운동별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 아래 막대그래프를 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"다음 달에 가장 인기 있을 항목","correct":true},{"t":"가장 많은 학생이 고른 항목","mis":"M4-1-u5-X21"},{"t":"겨울의 학생 수","mis":"M4-1-u5-X21"},{"t":"겨울과 여름의 학생 수의 차","mis":"M4-1-u5-X21"}],"explanation":["막대그래프에서는 항목별 수, 가장 많은 것, 두 항목의 차를 알 수 있어요.","「다음 달에 가장 인기 있을 항목」은 그래프에 나와 있지 않아요.","그래프에 없는 것은 지어내지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"vals":[10,5,3,4]}],"step":1,"ymax":11,"ylab":"(명)","title":"좋아하는 계절별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#14','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C9',2,'mc','auto','스마트 기기가 없는 교실에서 우리 반 친구들이 좋아하는 것을 차분히 조사하려고 해요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?',ARRAY['M4-1-u5-X16']::text[],true,'{"seq":14,"concept":"M4-1-u5-C9","difficulty":2,"kind":"mc","stem":"스마트 기기가 없는 교실에서 우리 반 친구들이 좋아하는 것을 차분히 조사하려고 해요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"종이에 적어 내기 — 기기 없이도 차분히 답할 수 있으니까요.","correct":true},{"t":"온라인 설문 — 기기가 없어도 집계되니까요.","mis":"M4-1-u5-X16"},{"t":"손 들기 — 차분히 생각할 시간을 주니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 기기 없이도 차분히 답할 수 있으니까요.","그래서 종이에 적어 내기가 알맞아요."],"variant_rule":{"alt":[{"stem":"학교 4학년 전체 100명을 조사하려고 해요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"온라인 설문 — 여러 반의 답이 자동으로 집계되니까요.","correct":true},{"t":"손 들기 — 100명이 한곳에 모이기 쉬우니까요.","mis":"M4-1-u5-X16"},{"t":"붙임쪽지 — 쪽지 100장이면 충분하니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 결과가 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 여러 반의 답이 자동으로 집계되니까요.","그래서 온라인 설문이 알맞아요."],"asset":null},{"stem":"쉬는 시간이 거의 끝나서 우리 반에 아주 빠르게 물어봐야 해요. 가장 알맞은 방법과 그 까닭은 어느 것인가요?","options":[{"t":"손 들기 — 그 자리에서 빠르게 셀 수 있으니까요.","correct":true},{"t":"온라인 설문 — 기기를 나눠 주고 기다리면 되니까요.","mis":"M4-1-u5-X16"},{"t":"종이에 적어 내기 — 걷어서 세면 되니까요.","mis":"M4-1-u5-X16"},{"t":"방법은 아무거나 골라도 걸리는 시간이 같아요.","mis":"M4-1-u5-X16"}],"explanation":["방법마다 좋은 점과 아쉬운 점이 있어요.","이 상황에서는 그 자리에서 빠르게 셀 수 있으니까요.","그래서 손 들기가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#15','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C10',2,'mc','auto','이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X11','M4-1-u5-X21']::text[],true,'{"seq":15,"concept":"M4-1-u5-C10","difficulty":2,"kind":"mc","stem":"이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 놀이는 술래잡기다.」","correct":true},{"t":"「내일은 피구가 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「술래잡기는 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「피구가 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 술래잡기의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["술래잡기","공기","줄넘기","피구","기타"],"series":[{"vals":[9,4,8,3,7]}],"step":1,"ymax":10,"ylab":"(명)","title":"즐겨 하는 놀이별 학생 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 메뉴는 불고기다.」","correct":true},{"t":"「내일은 카레가 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「불고기는 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「카레가 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 불고기의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["불고기","잡채","카레","국수","기타"],"series":[{"vals":[9,6,3,5,2]}],"step":1,"ymax":10,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"}},{"stem":"이번에는 다른 그림이에요. 이 그래프로 신문 기사를 써요. 기사 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반에서 가장 인기 있는 간식은 김밥이다.」","correct":true},{"t":"「내일은 과일이 가장 인기 있을 것이다.」","mis":"M4-1-u5-X11"},{"t":"「김밥은 몸에 가장 좋다.」","mis":"M4-1-u5-X11"},{"t":"「과일이 우리 반에서 가장 인기 있다.」","mis":"M4-1-u5-X21"}],"explanation":["기사에는 그래프에서 알 수 있는 사실만 써요.","가장 긴 막대는 김밥의 막대예요.","앞날이나 몸에 좋은지는 그래프에 없으니 지어내면 소문이 돼요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵","기타"],"series":[{"vals":[6,10,4,8,2]}],"step":2,"ymax":12,"ylab":"(명)","title":"좋아하는 간식별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#16','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C11',2,'sa','auto','남학생 겨울의 학생 수는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-1-u5-C11","difficulty":2,"kind":"sa","stem":"남학생 겨울의 학생 수는 몇 명인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["이름표에서 남학생의 막대 색을 먼저 찾아요.","겨울 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 1명).","남학생 겨울의 학생 수는 4명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"name":"남학생","vals":[6,1,8,4]},{"name":"여학생","vals":[5,10,2,7]}],"step":1,"ymax":11,"ylab":"(명)","title":"남학생과 여학생이 좋아하는 계절"},"variant_rule":{"alt":[{"stem":"2반 김밥의 학생 수는 몇 명인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["이름표에서 2반의 막대 색을 먼저 찾아요.","김밥 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 1명).","2반 김밥의 학생 수는 5명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵"],"series":[{"name":"1반","vals":[4,3,5,6]},{"name":"2반","vals":[8,5,3,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"반별 좋아하는 간식"}},{"stem":"올해 동화의 빌린 책 수는 몇 권인가요? 숫자로 쓰세요.","answer":["140"],"explanation":["이름표에서 올해의 막대 색을 먼저 찾아요.","동화 묶음에서 그 색 막대의 끝을 세로 눈금으로 읽어요(한 칸 10권).","올해 동화의 빌린 책 수는 140권이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["동화","과학","역사","만화"],"series":[{"name":"작년","vals":[70,50,60,40]},{"name":"올해","vals":[140,60,80,130]}],"step":10,"ymax":150,"ylab":"(권)","title":"작년과 올해 빌린 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#17','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C5',3,'mc','auto','표의 내용은 「로봇 9명, 요리 12명, 방송 7명, 소방 4명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?',ARRAY['M4-1-u5-X02']::text[],true,'{"seq":17,"concept":"M4-1-u5-C5","difficulty":3,"kind":"mc","stem":"표의 내용은 「로봇 9명, 요리 12명, 방송 7명, 소방 4명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"방송","correct":true},{"t":"로봇","mis":"M4-1-u5-X02"},{"t":"요리","mis":"M4-1-u5-X02"},{"t":"소방","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 1명이에요.","막대마다 표의 수와 견주어 봐요.","방송의 막대는 8명인데 표에서는 7명이에요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["로봇","요리","방송","소방"],"series":[{"vals":[9,12,8,4]}],"step":1,"ymax":13,"ylab":"(명)","title":"가고 싶은 체험별 학생 수"},"variant_rule":{"alt":[{"stem":"표의 내용은 「요리사 9명, 경찰관 7명, 과학자 10명, 가수 3명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"경찰관","correct":true},{"t":"요리사","mis":"M4-1-u5-X02"},{"t":"과학자","mis":"M4-1-u5-X02"},{"t":"가수","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 1명이에요.","막대마다 표의 수와 견주어 봐요.","경찰관의 막대는 8명인데 표에서는 7명이에요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["요리사","경찰관","과학자","가수"],"series":[{"vals":[9,8,10,3]}],"step":1,"ymax":11,"ylab":"(명)","title":"희망 직업별 학생 수"}},{"stem":"표의 내용은 「카레 5명, 잡채 8명, 불고기 10명, 국수 6명」이에요. 이 표를 막대그래프로 옮겼는데 한 곳이 틀렸어요. 어느 항목인가요?","options":[{"t":"카레","correct":true},{"t":"잡채","mis":"M4-1-u5-X02"},{"t":"불고기","mis":"M4-1-u5-X02"},{"t":"국수","mis":"M4-1-u5-X02"}],"explanation":["세로 눈금 한 칸은 1명이에요.","막대마다 표의 수와 견주어 봐요.","카레의 막대는 4명인데 표에서는 5명이에요 — 이 막대가 틀렸어요."],"asset":{"type":"lgraph","mode":"bar","xs":["카레","잡채","불고기","국수"],"series":[{"vals":[4,8,10,6]}],"step":1,"ymax":11,"ylab":"(명)","title":"좋아하는 급식 메뉴별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#18','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C6',3,'mc','auto','「학년별 우유 신청 학생 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 100명으로 그렸어요, 나 그래프는 눈금 한 칸을 5명으로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u5-X07']::text[],true,'{"seq":18,"concept":"M4-1-u5-C6","difficulty":3,"kind":"mc","stem":"「학년별 우유 신청 학생 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 100명으로 그렸어요, 나 그래프는 눈금 한 칸을 5명으로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"가 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 100명면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 5명인 나 그래프가 차이를 알아보기 좋아요."],"variant_rule":{"alt":[{"stem":"「모둠별 모은 빈 병 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 2개로 그렸어요, 나 그래프는 눈금 한 칸을 40개로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"가 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"나 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 40개면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 2개인 가 그래프가 차이를 알아보기 좋아요."],"asset":null},{"stem":"「지역별 문화유산 수」를 두 막대그래프로 나타냈어요. 가 그래프는 눈금 한 칸을 250점으로 그렸어요, 나 그래프는 눈금 한 칸을 25점으로 그렸어요. 항목끼리 차이를 알아보기 좋은 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나 — 눈금이 알맞아 막대의 길이 차이가 잘 보여요.","correct":true},{"t":"가 — 눈금이 커서 그래프가 깔끔해요.","mis":"M4-1-u5-X07"},{"t":"두 그래프가 똑같아 보여요.","mis":"M4-1-u5-X07"},{"t":"눈금이 큰 쪽이 언제나 더 좋아요.","mis":"M4-1-u5-X07"}],"explanation":["두 그래프가 나타내는 수는 같아요.","한 칸이 250점면 가장 큰 수도 한 칸 안에 들어가 막대들이 다 비슷해 보여요.","그래서 한 칸이 25점인 나 그래프가 차이를 알아보기 좋아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#19','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C7',3,'mc','auto','피구를 좋아하는 학생은 축구를 좋아하는 학생의 몇 배인가요?',ARRAY['M4-1-u5-X09']::text[],true,'{"seq":19,"concept":"M4-1-u5-C7","difficulty":3,"kind":"mc","stem":"피구를 좋아하는 학생은 축구를 좋아하는 학생의 몇 배인가요?","options":[{"t":"2배","correct":true},{"t":"5배","mis":"M4-1-u5-X09"},{"t":"3배","mis":"M4-1-u5-X09"},{"t":"1배","mis":"M4-1-u5-X09"}],"explanation":["피구는 10명, 축구는 5명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 5 × 2 = 10.","그래서 2배예요 — 차(5)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["축구","피구","수영","야구","배구"],"series":[{"vals":[5,10,2,6,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 운동별 학생 수"},"variant_rule":{"alt":[{"stem":"여름을 좋아하는 학생은 봄을 좋아하는 학생의 몇 배인가요?","options":[{"t":"4배","correct":true},{"t":"6배","mis":"M4-1-u5-X09"},{"t":"5배","mis":"M4-1-u5-X09"},{"t":"3배","mis":"M4-1-u5-X09"}],"explanation":["여름은 8명, 봄은 2명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 2 × 4 = 8.","그래서 4배예요 — 차(6)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"vals":[2,8,6,12]}],"step":1,"ymax":13,"ylab":"(명)","title":"좋아하는 계절별 학생 수"}},{"stem":"요리 체험을 고른 학생은 과학 체험을 고른 학생의 몇 배인가요?","options":[{"t":"3배","correct":true},{"t":"6배","mis":"M4-1-u5-X09"},{"t":"4배","mis":"M4-1-u5-X09"},{"t":"2배","mis":"M4-1-u5-X09"}],"explanation":["요리는 9명, 과학은 3명이에요.","몇 배인지는 큰 수가 작은 수를 몇 번 더한 것인지 봐요: 3 × 3 = 9.","그래서 3배예요 — 차(6)와 헷갈리지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["로봇","요리","방송","소방","과학"],"series":[{"vals":[6,9,11,2,3]}],"step":1,"ymax":12,"ylab":"(명)","title":"가고 싶은 체험별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#20','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C8',3,'mc','auto','가 그래프는 눈금 한 칸이 2명이고 봄의 막대가 6칸이에요. 나 그래프는 눈금 한 칸이 5명이고 가을의 막대가 3칸이에요. 봄의 막대가 더 길어 보이는데, 봄을 고른 학생이 더 많은 걸까요?',ARRAY['M4-1-u5-X10','M4-1-u5-X02','M4-1-u5-X12']::text[],true,'{"seq":20,"concept":"M4-1-u5-C8","difficulty":3,"kind":"mc","stem":"가 그래프는 눈금 한 칸이 2명이고 봄의 막대가 6칸이에요. 나 그래프는 눈금 한 칸이 5명이고 가을의 막대가 3칸이에요. 봄의 막대가 더 길어 보이는데, 봄을 고른 학생이 더 많은 걸까요?","options":[{"t":"아니요 — 눈금이 달라요. 봄은 12명, 가을은 15명이에요.","correct":true},{"t":"네 — 막대가 길면 언제나 수가 많아요.","mis":"M4-1-u5-X10"},{"t":"두 막대가 나타내는 수는 똑같아요.","mis":"M4-1-u5-X02"},{"t":"네 — 가 그래프가 먼저 나왔으니까요.","mis":"M4-1-u5-X12"}],"explanation":["다른 그래프끼리 견줄 때는 눈금부터 확인해요.","봄은 6 × 2 = 12명, 가을은 3 × 5 = 15명이에요.","막대는 봄이 더 길어도 수는 가을이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 그래프는 눈금 한 칸이 1명이고 범죄 수사관의 막대가 8칸이에요. 나 그래프는 눈금 한 칸이 5명이고 수의사의 막대가 2칸이에요. 범죄 수사관의 막대가 더 길어 보이는데, 범죄 수사관을 고른 학생이 더 많은 걸까요?","options":[{"t":"아니요 — 눈금이 달라요. 범죄 수사관은 8명, 수의사는 10명이에요.","correct":true},{"t":"네 — 막대가 길면 언제나 수가 많아요.","mis":"M4-1-u5-X10"},{"t":"두 막대가 나타내는 수는 똑같아요.","mis":"M4-1-u5-X02"},{"t":"네 — 가 그래프가 먼저 나왔으니까요.","mis":"M4-1-u5-X12"}],"explanation":["다른 그래프끼리 견줄 때는 눈금부터 확인해요.","범죄 수사관은 8 × 1 = 8명, 수의사는 2 × 5 = 10명이에요.","막대는 범죄 수사관이 더 길어도 수는 수의사가 더 많아요."],"asset":null},{"stem":"가 그래프는 눈금 한 칸이 1명이고 로봇의 막대가 9칸이에요. 나 그래프는 눈금 한 칸이 5명이고 요리의 막대가 3칸이에요. 로봇의 막대가 더 길어 보이는데, 로봇을 고른 학생이 더 많은 걸까요?","options":[{"t":"아니요 — 눈금이 달라요. 로봇은 9명, 요리는 15명이에요.","correct":true},{"t":"네 — 막대가 길면 언제나 수가 많아요.","mis":"M4-1-u5-X10"},{"t":"두 막대가 나타내는 수는 똑같아요.","mis":"M4-1-u5-X02"},{"t":"네 — 가 그래프가 먼저 나왔으니까요.","mis":"M4-1-u5-X12"}],"explanation":["다른 그래프끼리 견줄 때는 눈금부터 확인해요.","로봇은 9 × 1 = 9명, 요리는 3 × 5 = 15명이에요.","막대는 로봇이 더 길어도 수는 요리가 더 많아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#21','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C9',3,'mc','auto','조사를 했더니 합계가 19명이 나왔어요. 우리 반은 22명인데요! 무슨 일이 생긴 걸까요?',ARRAY['M4-1-u5-X21','M4-1-u5-X14','M4-1-u5-X15']::text[],true,'{"seq":21,"concept":"M4-1-u5-C9","difficulty":3,"kind":"mc","stem":"조사를 했더니 합계가 19명이 나왔어요. 우리 반은 22명인데요! 무슨 일이 생긴 걸까요?","options":[{"t":"빠진 친구가 있어요 — 모두 한 번씩 답해야 해요.","correct":true},{"t":"두 번 답한 친구가 있어요 — 한 사람은 한 번만 답해야 해요.","mis":"M4-1-u5-X21"},{"t":"항목을 너무 많이 만들었어요.","mis":"M4-1-u5-X14"},{"t":"합계는 인원과 달라도 괜찮아요.","mis":"M4-1-u5-X15"}],"explanation":["합계는 우리 반 인원과 같아야 해요.","합계 19명이 인원 22명보다 적어요.","많으면 두 번 답한 친구가, 적으면 빠진 친구가 있는 거예요."],"variant_rule":{"alt":[{"stem":"조사를 했더니 합계가 26명이 나왔어요. 우리 반은 24명인데요! 무슨 일이 생긴 걸까요?","options":[{"t":"두 번 답한 친구가 있어요 — 한 사람은 한 번만 답해야 해요.","correct":true},{"t":"빠진 친구가 있어요 — 모두 한 번씩 답해야 해요.","mis":"M4-1-u5-X21"},{"t":"항목을 너무 많이 만들었어요.","mis":"M4-1-u5-X14"},{"t":"합계는 인원과 달라도 괜찮아요.","mis":"M4-1-u5-X15"}],"explanation":["합계는 우리 반 인원과 같아야 해요.","합계 26명이 인원 24명보다 많아요.","많으면 두 번 답한 친구가, 적으면 빠진 친구가 있는 거예요."],"asset":null},{"stem":"조사를 했더니 합계가 24명이 나왔어요. 우리 반은 25명인데요! 무슨 일이 생긴 걸까요?","options":[{"t":"빠진 친구가 있어요 — 모두 한 번씩 답해야 해요.","correct":true},{"t":"두 번 답한 친구가 있어요 — 한 사람은 한 번만 답해야 해요.","mis":"M4-1-u5-X21"},{"t":"항목을 너무 많이 만들었어요.","mis":"M4-1-u5-X14"},{"t":"합계는 인원과 달라도 괜찮아요.","mis":"M4-1-u5-X15"}],"explanation":["합계는 우리 반 인원과 같아야 해요.","합계 24명이 인원 25명보다 적어요.","많으면 두 번 답한 친구가, 적으면 빠진 친구가 있는 거예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#22','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C11',3,'mc','auto','1학기보다 2학기에 붙임딱지 수가 가장 많이 늘어난 항목은 어느 것인가요?',ARRAY['M4-1-u5-X09']::text[],true,'{"seq":22,"concept":"M4-1-u5-C11","difficulty":3,"kind":"mc","stem":"1학기보다 2학기에 붙임딱지 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"3모둠","correct":true},{"t":"4모둠","mis":"M4-1-u5-X09"},{"t":"1모둠","mis":"M4-1-u5-X09"},{"t":"2모둠","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 1모둠 2, 2모둠 10, 3모둠 12, 4모둠 6.","2학기의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 3모둠이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"1학기","vals":[6,12,8,20]},{"name":"2학기","vals":[8,22,20,26]}],"step":2,"ymax":28,"ylab":"(개)","title":"1학기와 2학기 칭찬 붙임딱지 수"},"variant_rule":{"alt":[{"stem":"작년보다 올해에 빌린 책 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"역사","correct":true},{"t":"만화","mis":"M4-1-u5-X09"},{"t":"동화","mis":"M4-1-u5-X09"},{"t":"과학","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 동화 30, 과학 10, 역사 70, 만화 50.","올해의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 역사예요."],"asset":{"type":"lgraph","mode":"bar","xs":["동화","과학","역사","만화"],"series":[{"name":"작년","vals":[50,20,60,100]},{"name":"올해","vals":[80,30,130,150]}],"step":10,"ymax":160,"ylab":"(권)","title":"작년과 올해 빌린 책 수"}},{"stem":"지난달보다 이번 달에 빈 병 수가 가장 많이 늘어난 항목은 어느 것인가요?","options":[{"t":"1모둠","correct":true},{"t":"2모둠","mis":"M4-1-u5-X09"},{"t":"3모둠","mis":"M4-1-u5-X09"},{"t":"4모둠","mis":"M4-1-u5-X09"}],"explanation":["항목마다 늘어난 수를 구해요: 1모둠 25, 2모둠 10, 3모둠 20, 4모둠 5.","이번 달의 막대가 가장 길다고 가장 많이 늘어난 것은 아니에요.","가장 많이 늘어난 항목은 1모둠이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["1모둠","2모둠","3모둠","4모둠"],"series":[{"name":"지난달","vals":[35,65,20,15]},{"name":"이번 달","vals":[60,75,40,20]}],"step":5,"ymax":80,"ylab":"(개)","title":"지난달과 이번 달 모은 빈 병 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#23','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C10',4,'sa','auto','우리 반 34명이 모두 답한 간식 조사의 표에서 과일의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 과일 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-1-u5-C10","difficulty":4,"kind":"sa","stem":"우리 반 34명이 모두 답한 간식 조사의 표에서 과일의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 과일 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["과일의 수는 34 − (6 + 10 + 12 + 4) = 2명이에요.","눈금 한 칸이 2명이니 2 ÷ 2로 구해요.","1칸으로 그려요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","기타"],"counts":[6,10,null,12,4],"vh":"학생 수","unit":"명","total":34,"title":"좋아하는 간식별 학생 수"},"variant_rule":{"alt":[{"stem":"우리 반 44명이 모두 답한 간식 조사의 표에서 떡볶이의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 떡볶이 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["떡볶이의 수는 44 − (12 + 14 + 6 + 8) = 4명이에요.","눈금 한 칸이 2명이니 4 ÷ 2로 구해요.","2칸으로 그려요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","기타"],"counts":[null,12,14,6,8],"vh":"학생 수","unit":"명","total":44,"title":"좋아하는 간식별 학생 수"}},{"stem":"우리 반 40명이 모두 답한 간식 조사의 표에서 기타의 수가 지워졌어요. 눈금 한 칸이 2명인 막대그래프로 나타낼 때 기타 막대는 몇 칸으로 그려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["기타의 수는 40 − (10 + 6 + 12 + 8) = 4명이에요.","눈금 한 칸이 2명이니 4 ÷ 2로 구해요.","2칸으로 그려요."],"asset":{"type":"picg","only":"table","head":"간식","cols":["떡볶이","김밥","과일","빵","기타"],"counts":[10,6,12,8,null],"vh":"학생 수","unit":"명","total":40,"title":"좋아하는 간식별 학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#24','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C11',4,'sa','auto','남학생과 여학생의 차가 가장 큰 항목에서, 두 수의 차는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-1-u5-C11","difficulty":4,"kind":"sa","stem":"남학생과 여학생의 차가 가장 큰 항목에서, 두 수의 차는 몇 명인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["항목마다 두 막대의 차를 구해요: 봄 6, 여름 4, 가을 7, 겨울 3.","차가 가장 큰 항목은 가을이에요.","그 차는 7명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["봄","여름","가을","겨울"],"series":[{"name":"남학생","vals":[10,5,9,2]},{"name":"여학생","vals":[4,9,2,5]}],"step":1,"ymax":11,"ylab":"(명)","title":"남학생과 여학생이 좋아하는 계절"},"variant_rule":{"alt":[{"stem":"1반과 2반의 차가 가장 큰 항목에서, 두 수의 차는 몇 명인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["항목마다 두 막대의 차를 구해요: 떡볶이 2, 김밥 9, 과일 5, 빵 3.","차가 가장 큰 항목은 김밥이에요.","그 차는 9명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["떡볶이","김밥","과일","빵"],"series":[{"name":"1반","vals":[8,11,3,10]},{"name":"2반","vals":[6,2,8,7]}],"step":1,"ymax":12,"ylab":"(명)","title":"반별 좋아하는 간식"}},{"stem":"작년과 올해의 차가 가장 큰 항목에서, 두 수의 차는 몇 권인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["항목마다 두 막대의 차를 구해요: 동화 80, 과학 30, 역사 40, 만화 50.","차가 가장 큰 항목은 동화예요.","그 차는 80권이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["동화","과학","역사","만화"],"series":[{"name":"작년","vals":[20,60,80,100]},{"name":"올해","vals":[100,90,120,150]}],"step":10,"ymax":160,"ylab":"(권)","title":"작년과 올해 빌린 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u5_review_d#25','math',4,1,'u5','','g4_1_math_u5_review_d','unit_review','M4-1-u5-C10',4,'essay','teacher','우리 반 25명에게 좋아하는 간식을 붙임쪽지로 조사했어요. 쪽지를 세어 표로 정리하고 막대그래프로 나타낸 뒤 기사를 쓰려고 해요. 표의 합계로 무엇을 확인해야 하는지, 표와 그래프는 어떤 관계여야 하는지, 기사에는 무엇을 써야 하는지 차례대로 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u5-C10","difficulty":4,"kind":"essay","stem":"우리 반 25명에게 좋아하는 간식을 붙임쪽지로 조사했어요. 쪽지를 세어 표로 정리하고 막대그래프로 나타낸 뒤 기사를 쓰려고 해요. 표의 합계로 무엇을 확인해야 하는지, 표와 그래프는 어떤 관계여야 하는지, 기사에는 무엇을 써야 하는지 차례대로 써 보세요.","answer_guide":{"answer":"예: 표의 합계가 우리 반 인원 25명과 같은지 확인해서 두 번 답하거나 빠진 친구가 없는지 본다. 그래프의 막대는 표에 적힌 수를 그대로 따라야 하므로 표와 그래프의 값은 언제나 같아야 한다. 기사에는 「가장 인기 있는 간식은 ○○이다」처럼 그래프에서 알 수 있는 사실만 쓰고 그래프에 없는 것은 지어내지 않는다.","scoring_points":["합계가 25명과 같은지 확인한다고 썼는가","표와 그래프의 값이 같아야 한다고 썼는가","기사에는 그래프의 사실만 쓴다고 썼는가"]},"explanation":["합계 = 인원인지 확인해요.","그래프는 표를 그대로 따라요.","기사에는 그래프에 있는 사실만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
